-- DEV-only additive official PSOC 2022 API reference import.
-- Source counts are API 10/43/130/466; the 456-unit documentation conflict is retained in metadata.
-- No existing occupation/source/mapping is relabeled or deleted. No ACL/RLS/function change.
-- Repeated PSOC group names at different levels are distinct canonical nodes.
DO $import$
DECLARE
 v_raw text := $psoc2022_3de3889be8c9ca74$[{"code":"0","parent_code":null,"title":"ARMED FORCES OCCUPATIONS","description":"Armed forces occupations include all jobs held by members of the armed forces. Members of the armed forces are those personnel who are currently serving in the armed forces, including auxiliary services, whether on a voluntary or compulsory basis, and who are not free to accept civilian employment and are subject to military discipline. Included are regular members of the army, navy, air force and other military services, as well as conscripts enrolled for military training or other service for a specified period. \nExcluded from this group are:\nJobs held by persons in civilian employment of government establishments concerned with defense issues; police (other than military police); customs inspectors and members of border or other armed civilian services. Many jobs performed by members of the armed forces are similar, in terms of the nature of the work performed, to civilian occupations such as medical doctors, radio operators, cooks, secretaries and heavy truck drivers. Conceptually, it may be appropriate therefore, to classify such jobs in the armed forces with similar civilian jobs. This approach is adopted in several national occupation classifications. Typically such classifications also identify a number of military specific occupational groups. In many countries, however, it is not possible to produce information about the nature of the work performed by members of the armed forces. In adapting ISCO-08 for national purposes countries may wish, therefore, to consider what approach best suits their circumstances and user needs. For purposes of international comparability, however, where data pertaining to members of the armed forces are reported and classified by occupation, they should be included where possible in ISCO-08 major group 0, Armed forces occupations.","version":"2022","source_id":923,"level":1,"normalized_name":"armed forces occupations"},{"code":"1","parent_code":null,"title":"MANAGERS","description":"Managers plan, direct, coordinate and evaluate the overall activities of enterprises, governments and other organizations, or of organizational units within them, and formulate and review their policies, laws, rules and regulations.\nTasks performed by managers usually include: formulating and advising on the policy, budgets, laws and regulations of enterprises, governments and other organizational units; establishing objectives and standards and formulating and evaluating programs and policies and procedures for their implementation; ensuring appropriate systems and procedures are developed and implemented to provide budgetary control; authorizing material, human and financial resources to implement policies and programs; monitoring and evaluating performance of the organization or enterprise and of its staff; selecting, or approving the selection of staff; ensuring compliance with health and safety requirements; planning and directing daily operations; representing and negotiating on behalf of the government, enterprise or organizational unit managed in meetings and other forums.","version":"2022","source_id":488,"level":1,"normalized_name":"managers"},{"code":"2","parent_code":null,"title":"PROFESSIONALS","description":"Professionals increase the existing stock of knowledge, apply scientific or artistic concepts and theories, teach about the foregoing in a systematic manner, or engage in any combination of these activities. Competent performance in most occupations in this major group requires skills at the fourth ISCO skill level.\nTasks performed by professionals usually include: conducting analysis and research, and developing concepts, theories and operational methods, and advising on or applying existing knowledge related to physical sciences including mathematics, engineering and technology, and to life sciences including the medical and health services, as well as to social sciences and humanities; teaching the theory and practice of one or more disciplines at different educational levels; teaching and educating handicapped persons; providing various business, legal and social services; creating and performing works of art; providing spiritual guidance; preparing scientific papers and reports. Supervision of other workers may be included.","version":"2022","source_id":584,"level":1,"normalized_name":"professionals"},{"code":"3","parent_code":null,"title":"TECHNICIANS AND ASSOCIATE PROFESSIONALS","description":"Technicians and associate professionals perform mostly technical and related tasks connected with research and the application of scientific or artistic concepts and operational methods, and government or business regulations. Most occupations in this major group require skills at the third ISCO skill level.\nTasks performed by technicians and associate professionals usually include: undertaking and carrying out technical work connected with research and the application of concepts and operational methods in the fields of physical sciences including engineering and technology, life sciences including the medical profession, and social sciences and humanities; initiating and carrying out various technical services related to trade, finance, administration, including administration of government laws and regulations, and to social work; providing technical support for the arts and entertainment; participating in sporting activities; executing some religious tasks. Supervision of other workers may be included.","version":"2022","source_id":669,"level":1,"normalized_name":"technicians and associate professionals"},{"code":"4","parent_code":null,"title":"CLERICAL SUPPORT WORKERS","description":"Clerical support workers record, organize, store, compute and retrieve information-related; and perform a number of clerical duties in connection with money-handling operations, travel arrangements, requests for information, and appointments. Most occupations in this Major Group require skills at the second ISCO skill level.\nTasks performed by clerical support workers usually include: stenography, typing, and operating word processors and other office machines; entering data into computers; carrying out secretarial duties; recording and computing numerical data; keeping records relating to stocks, production and transport; keeping records relating to passenger and freight transport; carrying out clerical duties in libraries; filing documents; carrying out duties in connection with mail services; preparing and checking material for printing; writing on behalf of illiterate persons; performing money-handling operations; dealing with travel arrangements; supplying information requested by clients and making appointments; and operating a telephone switchboard. Supervision of other workers may be included.","version":"2022","source_id":698,"level":1,"normalized_name":"clerical support workers"},{"code":"5","parent_code":null,"title":"SERVICE AND SALES WORKERS","description":"Service and sales workers provide personal and protective services related to travel, housekeeping, catering, personal care, or protection against fire and unlawful acts, or demonstrate and sell goods in wholesale or retail shops and similar establishments, as well as at stalls and on markets. Most occupations in this Major Group require skills at the second PSOC skill level.\nTasks performed by service and sales workers usually include: organizing and providing services during travel; housekeeping; preparing and serving of food and beverages; caring for children; providing personal and basic health care at homes or in institutions, as well as hairdressing, beauty treatment and companionship; telling fortunes; embalming and arranging funerals; providing security services and protecting individuals and property against fire and unlawful acts; enforcing of law and order; posing as models for advertising, artistic creation and display of goods; selling goods in wholesale or retail establishments, as well as at stalls and on markets; and demonstrating goods to potential customers. Supervision of other workers may be included.","version":"2022","source_id":739,"level":1,"normalized_name":"service and sales workers"},{"code":"6","parent_code":null,"title":"SKILLED AGRICULTURAL, FORESTRY AND FISHERY WORKERS","description":"Skilled agricultural, forestry and fishery workers grow and harvest field or tree and shrub crops, gather wild fruits and plants, breed, tend or hunt animals, produce a variety of animal husbandry products, cultivate, conserve and exploit forests, breed or catch fish and cultivate or gather other forms of aquatic life in order to provide food, shelter and income for themselves and their households. Most occupations in this major group require skills at the second ISCO skill level.\nTasks performed by skilled agricultural, forestry and fishery workers usually include: preparing the soil; sowing, planting, spraying, fertilizing and harvesting field crops; growing fruit and other tree and shrub crops; growing garden vegetables and horticultural products; gathering wild fruits and plants; breeding, raising, tending or hunting animals mainly to obtain meat, milk, hair, fur, skin, sericultural, apiarian or other products; cultivating, conserving and exploiting forests; breeding or catching fish; cultivating or gathering other forms of aquatic life; storing and carrying out some basic processing of their produce; selling their products to purchasers, marketing organizations or at markets. Supervision of other workers may be included.","version":"2022","source_id":775,"level":1,"normalized_name":"skilled agricultural forestry and fishery workers"},{"code":"7","parent_code":null,"title":"CRAFT AND RELATED TRADES WORKERS","description":"Craft and related trades workers apply specific knowledge and skills in the fields to construct and maintain buildings, form metal, erect metal structures, set machine tools, or make, fit, maintain and repair machinery, equipment or tools, carry out printing work produce or process foodstuffs, textiles, or wooden, metal and other equipment or tools, carry out printing work produce or process foodstuffs, textiles, or wooden, metal and other articles, including handicraft goods.\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of all stages of the production process, the materials and tools used, and the nature and purpose of the final product. Most occupations in this major group require skills at the second ISCO skill level.\nTasks performed by craft and related trades workers usually include: constructing, maintaining and repairing buildings and other structures; casting, welding and shaping metal; installing and erecting heavy metal structures, tackle and related equipment; making machinery, tools, equipment, and other metal articles; setting for operators, or setting and operating various machine tools; fitting, maintaining and repairing industrial machinery, including engines and vehicles, as well as electrical and electronic instruments and other equipment; making precision instruments, jewelry, household and other precious-metal articles, pottery, glass and related products; producing handicrafts; executing printing work; and producing and processing foodstuffs and various articles made of wood, textiles, leather and related materials. Supervision of other workers may be included.","version":"2022","source_id":842,"level":1,"normalized_name":"craft and related trades workers"},{"code":"8","parent_code":null,"title":"PLANT AND MACHINE OPERATORS, AND ASSEMBLERS","description":"Plant and machine operators, and assemblers operate and monitor industrial and agricultural machinery and equipment on the spot or by remote control, drive and operate trains, motor vehicles and mobile machinery and equipment, or assemble products from component parts according to strict specifications and procedures.\nThe work mainly calls for experience with and an understanding of industrial and agricultural machinery and equipment as well as an ability to cope with machine-paced operations and to adapt to technological innovations. Most occupations in this major group require skills at the second ISCO skill level. Tasks performed by plant and machine operators and assemblers usually include: operating and monitoring mining or other industrial machinery and equipment for processing metal, minerals, glass, ceramics, wood, paper, or chemicals; operating and monitoring machinery and equipment used to produce articles made of metal, minerals, chemicals, rubber, plastics, wood, paper, textiles, fur, or leather, and which process foodstuffs and related products; driving and operating trains and motor vehicles; driving, operating and monitoring mobile industrial and agricultural machinery and equipment; assembling products from component parts according to strict specifications and procedures. Supervision of other workers may be included.","version":"2022","source_id":886,"level":1,"normalized_name":"plant and machine operators and assemblers"},{"code":"9","parent_code":null,"title":"ELEMENTARY OCCUPATIONS","description":"Elementary occupations involve the performance of simple and routine tasks which may require the use of hand-held tools and considerable physical effort. Most occupations in this major group require skills at the first ISCO skill level.\nTasks performed by workers in elementary occupations usually include: cleaning, restocking supplies and performing basic maintenance in apartments, houses, kitchens, hotels, offices and other buildings; washing cars and windows; helping in kitchens and performing simple tasks in food preparation; delivering messages or goods; carrying luggage and handling baggage and freight; stocking vending machines or reading and emptying meters; collecting and sorting refuse; sweeping streets and similar places; performing various simple farming, fishing, hunting or trapping tasks performing simple tasks connected with mining, construction and manufacturing including product-sorting; packing and unpacking produce by hand and filling shelves; providing various street services; pedaling or hand-guiding vehicles to transport passengers and goods; driving animal-drawn vehicles or machinery. Supervision of other workers may be included.","version":"2022","source_id":920,"level":1,"normalized_name":"elementary occupations"},{"code":"01","parent_code":"0","title":"COMMISSIONED ARMED FORCES OFFICERS","description":"Commissioned armed forces officers provide leadership and management to organizational units in the armed forces and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces. This group includes all members of the armed forces holding the rank of second lieutenant (or equivalent) or higher.\n\nExamples of the occupations classified here: Admiral, Air commodore, Air force captain, Air force flight lieutenant, Air force group captain, Air force pilot officer, Air marshal, Armed forces officer cadet, Army brigadier, Army cadet officer, Army captain, Army colonel, Army general, Army lieutenant colonel, Army major, Army second lieutenant, Field marshal, Midshipman, Military flying officer, Military naval officer, Navy captain, Navy commander, Navy commodore, Navy lieutenant commander, Navy sublieutenant, Squadron leader, Wing commander","version":"2022","source_id":921,"level":2,"normalized_name":"commissioned armed forces officers"},{"code":"02","parent_code":"0","title":"NON-COMMISSIONED ARMED FORCES OFFICERS","description":"Non-commissioned armed forces officers enforce military discipline and supervise the activities of those employed in Armed forces occupations, other ranks, and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces. This group includes members of the armed forces holding ranks such as sergeant, warrant officer and sergeant major.\n\nExamples of the occupations classified here: Army sergeant, Flight sergeant, Master sergeant, Military quartermaster, Navy boatswain, Sergeant major, Warrant officer","version":"2022","source_id":922,"level":2,"normalized_name":"non-commissioned armed forces officers"},{"code":"03","parent_code":"0","title":"ARMED FORCES OCCUPATIONS, OTHER RANKS","description":"Armed forces occupations, other ranks include all conscripted and non-conscripted members of the armed forces except commissioned and non-commissioned officers. They perform specific military tasks and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces.\n\nExamples of the occupations classified here: Air force corporal, Airman, Army corporal, Bombardier, Gunner, Infantryman/woman, Navy coxswain, Navy seaman, Paratrooper, Rifleman/woman","version":"2022","source_id":923,"level":2,"normalized_name":"armed forces occupations other ranks"},{"code":"11","parent_code":"1","title":"CHIEF EXECUTIVES, SENIOR OFFICIALS AND LEGISLATORS","description":"Chief executives, senior officials and legislators formulate and review the policies and plan, direct coordinate and evaluate the overall activities of enterprises, governments and other organizations with the support of other managers.\n\nTasks performed usually include: presiding over or participating in the proceedings of legislative bodies, boards of directors and committees; formulating and advising on the policy budgets, laws and regulations of enterprises, governments and other organizations; establishing objectives for enterprises, government departments or agencies and other organizations; formulating or approving and evaluating programs and policies and procedures for their implementation; ensuring appropriate systems and procedures are developed and implemented to provide budgetary control; authorizing material, human and financial resources to implement policies and programs; monitoring and evaluating performance of the organization or enterprise; selecting, or approving the selection of senior staff; performing ceremonial duties and representing the enterprise, government, organization or community at official occasions and in meetings, negotiations, conventions and public hearings.","version":"2022","source_id":462,"level":2,"normalized_name":"chief executives senior officials and legislators"},{"code":"12","parent_code":"1","title":"ADMINISTRATIVE AND COMMERCIAL MANAGERS","description":"Administrative and commercial managers plan, organize, direct, control and coordinate the financial, administrative, human resource, policy, planning, research and development, advertising, public relations, and sales and marketing activities of enterprises and organizations, or of enterprises that provide such services to other enterprises and organizations.\n\nTasks performed by workers in this sub-major group usually include: formulating and administering policy advice, strategic and financial planning; establishing and directing operational and administrative procedures; implementing, monitoring and evaluating strategies and policies; providing advice to senior managers; directing the development of initiatives for new products, marketing, public relations and advertising campaigns; determining and directing sales activities, product mix, customer service standards; setting prices and credit arrangements; ensuring compliance with relevant legislation, regulations and standards; controlling selection, training and performance of staff; preparing budgets and overseeing financial operations; consulting with the chief executive and with managers of other departments or sections; controlling expenditure and ensuring the efficient use of resources; representing the enterprise or organization in negotiations, and at conventions, seminars, public hearings and forums.","version":"2022","source_id":469,"level":2,"normalized_name":"administrative and commercial managers"},{"code":"13","parent_code":"1","title":"PRODUCTION AND SPECIALIZED SERVICES MANAGERS","description":"Production and specialized services managers plan direct and coordinate the production of the goods and the provision of the specialized professional and technical services provided by an enterprise or organization. They are responsible for manufacturing, mining, construction, logistics, information and communications technology operations, for large scale agricultural, forestry and fisheries operations, and for the provision of health, education, social welfare, banking, insurance and other professional and technical services.\n\nTasks performed by workers in this sub-major group usually include: planning details of activities in terms of output, services provided, quality, quantity, cost, timeliness and labor requirements; setting standards and objectives; controlling the operation of plant and of procedures; assuring quality of the goods produced and services provided; preparing tenders and contract bids; establishing and managing budgets, monitoring costs, and adjusting activities, procedures and resources to minimize costs; overseeing the acquisition and installation of new plant and equipment; coordinating the implementation of health and safety requirements; planning and directing daily operations; controlling the operation of plant and of procedures; overseeing the selection, training and performance of staff; preparing, or arranging for the preparation of, reports, budgets and forecasts; and representing the enterprise or organization in negotiations with other agencies, and at conventions, seminars, public hearings and forums.","version":"2022","source_id":483,"level":2,"normalized_name":"production and specialized services managers"},{"code":"14","parent_code":"1","title":"HOSPITALITY, RETAIL AND OTHER SERVICES MANAGERS","description":"Hospitality, shop and related services managers plan, organize and direct the operations of establishments which provide accommodation, hospitality, retail and other services.\n\nTasks performed by workers in this sub-major group usually include: planning and organizing special functions, sporting, gaming and entertainment activities and the range and mix of products, stock levels and service standards; promoting and selling goods and services; observing liquor, gaming, health and other laws and regulations; developing and reviewing policies, programs and procedures concerning customer relations and goods and services provided; promoting facilities, for conferences, conventions and trade shows, to potential customers; organizing the purchase and maintenance of transport vehicles, equipment and fuel, and transporting goods; controlling the selection, training and supervision of staff; ensuring compliance with occupational health and safety regulations.","version":"2022","source_id":488,"level":2,"normalized_name":"hospitality retail and other services managers"},{"code":"21","parent_code":"2","title":"SCIENCE AND ENGINEERING PROFESSIONALS","description":"Physical, mathematical and engineering science professionals conduct research, improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to fields such as physics, astronomy, meteorology, chemistry, geophysics, geology, mathematics, statistics, computing, architecture, engineering, and technology.\n\nTasks performed by workers in this sub-major group usually include: conducting research, enlarging, advising on or applying scientific knowledge obtained through the study of structures and properties of physical matter and phenomena, chemical characteristics and processes of various substances, materials and products, and of mathematical, statistical and computing concepts and methods; advising on, designing and directing construction of buildings, towns and traffic systems, or civil engineering and industrial structures, as well as machines and other equipment, and advising on and applying mining methods, and ensuring their optimum use; surveying land and sea and making maps; studying and advising on technological aspects of particular materials, products and processes, and on efficiency of production and work organization; and preparing scientific papers and reports. Supervision of other workers may be included.","version":"2022","source_id":516,"level":2,"normalized_name":"science and engineering professionals"},{"code":"22","parent_code":"2","title":"HEALTH PROFESSIONALS","description":"Health professionals conduct research, improve or develop concepts, theories and operational methods, and apply scientific knowledge relating to medicine, nursing, dentistry, veterinary medicine, pharmacy, and promotion of health.\n\nTasks performed by workers in this sub-major group usually include: conducting research and obtaining scientific knowledge through the study of human and animal disorders and illnesses and ways of treating them; advising on or applying preventive and curative measures, or promoting health; preparing scientific papers and reports. Supervision of other workers may be included.","version":"2022","source_id":531,"level":2,"normalized_name":"health professionals"},{"code":"23","parent_code":"2","title":"TEACHING PROFESSIONALS","description":"Teaching professionals teach the theory and practice of one or more disciplines at different educational levels, conduct research and improve or develop concepts, theories and operational methods pertaining to their particular discipline, and prepare scholarly papers and books.\n\nTasks performed by workers in this sub-major group usually include: conducting classes, courses, or tutorials at a particular educational level, for educational and vocational purposes, including private lessons; conducting adult literacy programmes; teaching and educating persons learning difficulties or special needs; designing and modifying curricula; inspecting and advising on teaching methods and aids; participating in decisions concerning the organization of teaching and related activities at schools and universities; conducting research in particular subjects to improve or develop concepts, theories or operational methods for application in industrial and other fields; preparing scholarly papers and books. Supervision of other workers may be included.","version":"2022","source_id":543,"level":2,"normalized_name":"teaching professionals"},{"code":"24","parent_code":"2","title":"BUSINESS AND ADMINISTRATION PROFESSIONALS","description":"Business and administration professionals perform analytical, conceptual and practical tasks to provide services in financial matters, human resource development, public relations and marketing, sales in the technical, medical, information and communication technology areas and conduct, reviews of organizational structures, methods and systems as well as quantitative analyzes of information affecting investment programs.\n\nTasks performed by workers in this sub-major group usually include: collecting, analyzing and interpreting information on the financial viability, cost structures and trading effectiveness of organizations; conducting audits, preparing financial statements and controlling treasury systems for organizations; developing and reviewing financial plans and strategies, executing buy and sell orders, and negotiating the purchase and sale of commodities; developing, implementing and evaluating staff recruitment, training and development programs; researching, developing and implementing marketing and public relations campaigns; studying and developing methods and policies to improve and promote government and business operations and effectiveness; acquiring and updating knowledge of employers’ and competitors’ goods and services, and market conditions; assessing customers’ needs and explaining and demonstrating goods and services to them.","version":"2022","source_id":554,"level":2,"normalized_name":"business and administration professionals"},{"code":"25","parent_code":"2","title":"INFORMATION AND COMMUNICATION TECHNOLOGY PROFESSIONALS","description":"Information and communications technology professionals conduct research, plan, design, write, test, provide advice and improve information technology systems, hardware, software and related concepts for specific applications; develop associated documentation including principles, policies and procedures; and design, develop, control, maintain and support databases and other information systems to ensure optimal performance and data integrity and security.\n\nTasks performed usually include: researching information technology use in business functions; identifying areas for improvement and researching the theoretical aspects and operational methods for the use of computers; evaluating, planning and designing hardware or software configurations for specific applications including for Internet, Intranet and multimedia systems; designing, writing, testing and maintaining computer programs; designing and developing database architecture and database management systems; developing and implementing security plans and data administration policy, and administering computer networks and related computing environments; analyzing, developing, interpreting and evaluating complex system design and architecture specifications, data models and diagrams in the development, configuration and integration of computer systems.","version":"2022","source_id":563,"level":2,"normalized_name":"information and communication technology professionals"},{"code":"26","parent_code":"2","title":"LEGAL, SOCIAL AND CULTURAL PROFESSIONALS","description":"Legal, social and cultural professionals conduct research, improve or develop concepts, theories and operational methods, or apply knowledge relating to the law, storage and retrieval of information and artefacts, psychology, social welfare, politics, economics, history, religion, languages, sociology, other social sciences, and to arts and entertainment.\n\nTasks performed by workers in this sub-major group usually include: conducting research on legal problems; drafting laws and regulations; advising clients on legal cases; pleading and conducting cases in a court of law; presiding over judicial proceedings in a court of law; developing and maintaining library and gallery collections of archives; conducting research, improving or developing concepts, theories and operational methods or applying knowledge relating to the field of social sciences; conceiving, creating and performing in literary and artistic works; interpreting and communicating news, ideas, impressions and facts.","version":"2022","source_id":584,"level":2,"normalized_name":"legal social and cultural professionals"},{"code":"31","parent_code":"3","title":"SCIENCE AND ENGINEERING ASSOCIATE PROFESSIONALS","description":"Science and engineering associate professionals perform technical tasks connected with research and operational methods in science and engineering. They supervise and control technical and operational aspects of mining, manufacturing, construction and other engineering operations, and operate technical equipment including aircraft and ships.\n\nTasks performed by workers in this sub-major group usually include: setting up, monitoring and operating instruments and equipment, conducting and monitoring experiments and tests of systems; collecting and testing samples; recording observations and analyzing data; preparing, revising and interpreting technical drawings and diagrams; coordinating, supervising, controlling and scheduling the activities of other workers; operating and monitoring switchboards, computerized control systems, and multi-function process control machinery; perform technical functions to ensure safe and efficient movement and operations ships aircraft and other equipment.","version":"2022","source_id":610,"level":2,"normalized_name":"science and engineering associate professionals"},{"code":"32","parent_code":"3","title":"HEALTH ASSOCIATE PROFESSIONALS","description":"Health associate professionals perform technical and practical tasks to support diagnosis and treatment of illness, disease, injuries and impairments in humans and animals, and to support implementation of health care, treatment and referrals plans usually established by medical, veterinary, nursing and other health professionals.\n\nTasks performed by workers in the sub-major group usually include: testing and operating medical imaging equipment and administering radiation therapy; performing clinical tests on specimens of bodily fluids and tissues; preparing medications and other pharmaceutical compounds under the guidance of pharmacists; designing, fitting, servicing and repairing medical and dental devices and appliances; providing nursing and personal care and midwifery support services; using herbal and other therapies based on theories, beliefs and experiences originating in specific cultures.","version":"2022","source_id":627,"level":2,"normalized_name":"health associate professionals"},{"code":"33","parent_code":"3","title":"BUSINESS AND ADMINISTRATION ASSOCIATE PROFESSIONALS","description":"Business and administration associate professionals perform mostly technical tasks connected with the practical application of knowledge relating to financial accounting and transaction matters, mathematical calculations, human resource development, selling and buying financial instruments, specialized secretarial tasks, and enforcing or applying relevant government rules. Also included are workers who provide business services such as customs clearance, conference planning, job placements, buying and selling real estate or bulk commodities, and serving as agents for performers such as athletes and artists.\n\nTasks performed by workers in this sub-major group usually include recording and transmitting buy and sell orders for securities, stocks, bonds or other financial instruments and for foreign exchange for future or immediate delivery; submitting credit and loan applications to management with recommendations for approval or rejection; approving or rejecting applications within authorized limits ensuring that credit standards of the institution are respected; maintaining complete records of all financial transactions of an undertaking according to general bookkeeping principles, with guidance from Accountants; assisting in planning and performing mathematical, statistical, actuarial, accounting and related calculations; selling and buying financial instruments.","version":"2022","source_id":651,"level":2,"normalized_name":"business and administration associate professionals"},{"code":"34","parent_code":"3","title":"LEGAL, SOCIAL, CULTURAL AND RELATED PROFESSIONALS","description":"Legal, social, cultural and related associate professionals perform technical tasks connected with the practical application of knowledge relating to legal services, social work, culture, food preparation, sport and religion.\n\nTasks performed in this sub-major group usually include: providing technical and practical services and support functions in legal processes and investigations, social and community assistance programs, and religious and cultural activities; participating and adjudicating in sporting events; developing and delivering sports coaching, fitness and recreational programmes; combining creative and technical skills in a variety of artistic, cultural and culinary activities; creating dishes and menus and overseeing the preparation of meals.","version":"2022","source_id":663,"level":2,"normalized_name":"legal social cultural and related professionals"},{"code":"35","parent_code":"3","title":"INFORMATION AND COMMUNICATIONS TECHNICIAN","description":"Information and communications technicians provide support for the day-to-day running of computer systems, communications systems and networks and perform technical tasks related to telecommunications, broadcast of image and sound as well as other types of telecommunications signals on land, sea or in aircraft.\n\nTasks performed by workers in this sub-major group usually include: providing assistance to information and communications systems users ; installing new programs and equipment; establishing, operating and maintaining network and other data communications systems; installing, monitoring and supporting Internet and Intranet websites or web server hardware or software; modifying web pages; and performing web server backup and recovery operations; controlling equipment to record sound, edit and mix image and sound recordings; controlling and maintaining transmitting and broadcast systems and satellite systems for radio and television programmes; controlling and maintaining radio communications systems, satellite services, and multiplex systems on land, sea or in aircraft; providing technical assistance connected with research and the development of computer systems and telecommunications equipment, or testing prototypes; designing and preparing blueprints of circuitry according to the specifications given; providing technical supervision of the manufacture, utilization, maintenance and repair of telecommunications systems.","version":"2022","source_id":669,"level":2,"normalized_name":"information and communications technician"},{"code":"41","parent_code":"4","title":"GENERAL AND KEYBOARD CLERKS","description":"General and keyboard clerks record, organize, store and retrieve information; and perform a range of clerical and administrative tasks according to established procedures. \n\nTasks performed by workers in this Sub-Major Group usually include: operating personal computers, word-processors or typewriters; recording, inputting and processing data using computers; recording input and processing text; calculating; bookkeeping and similar office machines to input and process text and data; and performing a wide range of general clerical duties including preparing invoices, checking figures, filing, faxing or processing mail.","version":"2022","source_id":673,"level":2,"normalized_name":"general and keyboard clerks"},{"code":"42","parent_code":"4","title":"CUSTOMER SERVICE CLERKS","description":"Customer service clerks deal with clients in connection with money-handling operations, travel arrangements, requests for information, making appointments, operating telephone switchboards; and interviewing for surveys or to complete applications for eligibility for services.\n\nTasks performed by workers in this Sub-Major Group include: performing money-handling operations in banks, post offices, betting and gambling establishments; or dealing with travel arrangements; supplying information requested by clients and making appointments; operating telephone switchboards; greeting and receiving visitors; interviewing survey respondents; and interviewing applicants for services.","version":"2022","source_id":685,"level":2,"normalized_name":"customer service clerks"},{"code":"43","parent_code":"4","title":"NUMERICAL AND MATERIAL RECORDING CLERKS","description":"Numerical and material recording clerks obtain, compile and compute accounting, bookkeeping, statistical, financial and other numerical data; and take charge of cash transactions incidental to business matters. Some occupations classified here keep records of goods produced, purchased, stocked, dispatched and of materials needed at specified production dates; or keep records of operational aspects; and coordinate the timing of passenger and freight transport.\n\nTasks performed by workers in this Sub-Major Group usually include: helping with accounting and bookkeeping records and computations; calculating unit production costs; calculating wages and in some cases preparing wage packets and paying wages; taking charge of cash transactions incidental to the business; obtaining, compiling and computing statistical or actuarial data; performing clerical tasks relating to the financial transactions of an insurance establishment, bank or similar establishment; recording produced, stocked, ordered and dispatched goods; recording production materials received, put into stock or issued; computing quantities of the production materials required at specified dates; and helping with preparation and checking of production operation schedules; keeping records of operational aspects; and coordinating the timing of passenger and freight transport.","version":"2022","source_id":691,"level":2,"normalized_name":"numerical and material recording clerks"},{"code":"44","parent_code":"4","title":"OTHER CLERICAL SUPPORT WORKERS","description":"Other clerical support workers perform clerical duties in newspapers, courts, libraries and post offices; file documents; prepare information for processing; maintain personnel records; check material for consistency with original source material; and write on behalf of illiterate persons.\n\nTasks performed by workers in this Sub-Major Group usually include: recording information regarding acquisition, issue and return of library books; maintaining personnel records; classifying and filing various documents and other records; sorting, recording and delivering mail from post offices, as well as from or within an enterprise; coding; correcting proofs; performing a number of miscellaneous clerical duties; and writing on behalf of persons who are unable to read and write.","version":"2022","source_id":698,"level":2,"normalized_name":"other clerical support workers"},{"code":"51","parent_code":"5","title":"PERSONAL SERVICE WORKERS","description":"Personal service workers provide personal services related to travel, housekeeping, catering, child and personal care.\n\nTasks performed by workers in this Sub-Major Group usually include: organizing and providing of services during travel; housekeeping; preparing and serving food and beverages; providing personal and basic health care at homes or institutions, as well as hairdressing, beauty treatment and companionship; telling fortunes; and embalming and arranging funerals. Supervision of other workers may be included.","version":"2022","source_id":715,"level":2,"normalized_name":"personal service workers"},{"code":"52","parent_code":"5","title":"SALES WORKERS","description":"Sales workers sell and demonstrate goods in wholesale or retail shops, at stalls and markets, door-to-door, via telephone or customer contact centers. They may record and accept payment for goods and services purchased, and may operate small retail outlets.\n\nTasks performed by workers in this Sub-Major Group may include the following: selling goods in wholesale or retail establishments or at street or market stalls, door-to- door, via telephone or customer contact centers; demonstrating and displaying goods to potential customers; selling and serving food for immediate consumption at counters and in the street; buying or contracting a regular supply of products to be sold; stacking and displaying goods for sale, and wrapping and packing goods sold; determining product mix, stock and price levels for goods to be sold; operating cash registers, optical price scanners, computers or other equipment to record and accept payment for the purchase of goods and services. Supervision of other workers may be required in some occupations classified here.","version":"2022","source_id":729,"level":2,"normalized_name":"sales workers"},{"code":"53","parent_code":"5","title":"PERSONAL CARE WORKERS","description":"Personal care workers provide care, supervision and assistance for children, patients and elderly, convalescent or disabled persons in institutional and residential settings.\n\nTasks performed by workers in this Sub-Major Group usually include: assisting with mobility, washing and other personal needs; assisting children individually to learn social skills; supervising and participating in activities that enhance the child's physical, social, emotional and intellectual development in schools and pre-school; and observing and reporting concerns to appropriate medical or social service worker.","version":"2022","source_id":734,"level":2,"normalized_name":"personal care workers"},{"code":"54","parent_code":"5","title":"PROCTECTIVE SERVICES WORKERS","description":"Protective services workers protect individuals and property against fire and other hazards; maintain law and order; and enforce laws and regulations.\n\nTasks performed usually include: preventing, fighting and extinguishing fires; rescuing people from burning buildings and accident sites and those trapped in dangerous situations; maintaining law and order, enforcing laws and regulations, patrolling public areas and arresting suspected offenders; directing traffic and assuming authority in the event of accidents; watching over and maintaining order among inmates of prisons, reformatories or penitentiaries; patrolling or monitoring premises to guard property against theft and vandalism, controlling access to establishments and maintaining order and enforcing regulations at public events and within establishments. Supervision of other workers may be included.","version":"2022","source_id":739,"level":2,"normalized_name":"proctective services workers"},{"code":"61","parent_code":"6","title":"MARKET-ORIENTED SKILLED AGRICULTURAL WORKERS","description":"Market-oriented skilled agricultural workers plan, organize and perform farming operations to grow and harvest field or tree and shrub crops and produce a variety of animals and animal products for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\n\nTasks performed by workers in this sub-major group usually include: preparing the soil; sowing, planting, spraying, fertilizing and harvesting field crops, growing fruit and other tree and shrub crops; growing garden vegetables and horticultural products; raising, breeding and tending animals mainly to obtain meat, milk, hair, fur, skin, sericultural, apiarian or other products; storing and carrying out some processing of their produce; selling their products to purchasers, marketing organizations or at markets. Supervision of other workers may be included.","version":"2022","source_id":758,"level":2,"normalized_name":"market-oriented skilled agricultural workers"},{"code":"62","parent_code":"6","title":"MARKET-ORIENTED SKILLED FORESTRY, FISHERY AND HUNTING WORKERS","description":"Market-oriented skilled forestry, fishery and hunting workers plan, organize and perform operations to cultivate, conserve and exploit natural and plantation forests, breed and raise fish, harvest and catch fish and hunt and trap animals, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\n\nTasks performed by workers in this sub-major groups usually include: renting or investing, equipment and machinery and purchasing supplies; planning and undertaking forestry, aquaculture, fishery and hunting operations; maintaining buildings, tanks, machinery, and other equipment; delivering or marketing products; supervising and training other workers.","version":"2022","source_id":771,"level":2,"normalized_name":"market-oriented skilled forestry fishery and hunting workers"},{"code":"63","parent_code":"6","title":"SUBSISTENCE FARMERS, FISHERS, HUNTER AND GATHERERS","description":"Subsistence farmers, fishers, hunters and gatherers grow and harvest field or tree and shrub crops, vegetables and fruit, gather wild fruits, medicinal and other plants, tend or hunt animals, catch fish and gather various forms of aquatic life in order to provide food, shelter and a minimum of cash income for themselves and their households.\n\nTasks performed by workers in this sub-major group usually include - preparing the soil; sowing, planting, tending and harvesting field crops; growing vegetables, fruit and other tree and shrub crops; gathering wild fruits, medicinal and other plants; breeding, tending and feeding animals and poultry mainly to obtain meat, eggs, milk, hair, skin or other products; hunting or trapping animals; catching fish and gathering other forms of aquatic life; fetching water and gathering firewood; storing produce for later use and carrying out some processing of produce; building and maintaining houses and other shelters; making tools, clothes and utensils for use by the household; selling or bartering some products at local markets.","version":"2022","source_id":775,"level":2,"normalized_name":"subsistence farmers fishers hunter and gatherers"},{"code":"71","parent_code":"7","title":"BUILDING AND RELATED TRADES WORKERS, EXCLUDING ELECTRICIANS","description":"Building and related trades workers construct, maintain and repair buildings, erect and repair foundations, walls and structures of brick, stone and similar materials, shape and finish stone for building and other purposes, and extract and work solid minerals from underground or surface mines or quarries. The work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organization, the materials and tools used, and the nature and purpose of the final product.\n\nTasks performed by workers in this sub-major group include: constructing, maintaining and repairing buildings and other structures using traditional and/or modern building techniques; constructing and repairing foundations, walls and structures of brick, stone and similar materials; breaking quarried stone into slabs or blocks; cutting, shaping and finishing stone for building, ornamental, monumental and other purposes; erecting reinforced concrete frameworks and structures as well as finishing and repairing cement surfaces; cutting, shaping, assembling and maintaining wooden structures and fittings; and performing miscellaneous construction and building maintenance tasks.","version":"2022","source_id":791,"level":2,"normalized_name":"building and related trades workers excluding electricians"},{"code":"72","parent_code":"7","title":"METAL, MACHINERY AND RELATED TRADES WORKERS","description":"Metal, machinery and related trades workers cast, weld, forge and, by other methods, form metal, erect, maintain and repair heavy metal structures, engage in machine-tool setting as well as in fitting, maintaining and repairing machinery, including engines, vehicles, or produce tools and various non-precious-metal articles.\n\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organization, the materials and tools used, and the nature and purpose of the final product.\n\nTasks performed by workers in this sub-major group usually include: making molds and cores for casting metal; casting, welding and shaping metal; installing, erecting, maintaining and repairing heavy metal structures, tackle and related equipment; forging and forming steel and other non-precious metals to make and repair machinery, tools, equipment and other articles; setting for operators or setting and operating various machine tools; and fitting, maintaining and repairing industrial machinery, including engines and vehicles. Supervision of other workers may be included.","version":"2022","source_id":804,"level":2,"normalized_name":"metal machinery and related trades workers"},{"code":"73","parent_code":"7","title":"HANDICRAFT AND PRINTING WORKERS","description":"Handicraft and printing workers make and repair precision instruments, musical instruments, various articles such as jewelry, precious metalware, ceramics, porcelain ware and glassware, as well as handicrafts made of wood or textile, leather or related materials, or they perform printing or book-binding tasks.\n\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organization, the materials and tools used, and the nature and purpose of the final product.\n\nTasks performed by workers in this sub-major group usually include: making and repairing nautical, meteorological, optical and other precision instruments and equipment; making and repairing musical instruments; making jewelry and precious metalware; making pottery, porcelain ware, ceramics and glassware; painting and decorating various articles; producing handicraft articles in wood or textile, leather and related materials; and performing printing or book-binding tasks. Supervision of other workers may be included.","version":"2022","source_id":816,"level":2,"normalized_name":"handicraft and printing workers"},{"code":"74","parent_code":"7","title":"ELECTRICAL AND ELECTRONICS TRADES WORKERS","description":"Electrical and electronics trades workers install, fit and maintain electrical wiring systems and machinery and other electrical apparatus, electrical transmission and supply lines and cables, and electronic and telecommunications equipment and systems.\n\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organization, the materials and tools used, and the nature and purpose of the final product.\n\nTasks performed usually include: installing, maintaining, fitting and adjusting electrical and electronic wiring systems, machinery and equipment; examining blueprints, wiring diagrams and specifications to determine sequences and methods of operation; inspecting and testing electrical and electronic systems, equipment, cables and machinery to identify hazards, defects, and the need for adjustment or repair; installing maintaining and repairing electrical and telecommunications transmission lines; joining electrical, telecommunications and data cables; and maintaining, troubleshooting, fitting, adjusting, testing and repairing electronic equipment such as commercial and office machines and electronic instruments and control systems, computers, telecommunications and data transmission equipment.","version":"2022","source_id":822,"level":2,"normalized_name":"electrical and electronics trades workers"},{"code":"75","parent_code":"7","title":"FOOD PROCESSING, WOOD WORKING, GARMENT AND OTHER CRAFT AND RELATED TRADES WORKERS","description":"Food processing, wood working, garment and other craft and related trades workers treat and process agricultural and fisheries raw materials into food and other products, and produce and repair goods made of wood, textiles, fur, leather, or other materials.\n\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organization, the materials and tools used, and the nature and purpose of the final product.\n\nTasks performed by workers in this sub-major group usually include: treating and processing meat, fish, grain, fruit, vegetables and related materials into food stuffs, and tobacco into tobacco products; tasting and grading food products and beverages; treating and processing natural fibers, skins and hides; making and repairing furniture and other goods made of wood; preparing hides, skins and pelts for further use; and making and repairing textiles, garments, hats, shoes and related products. Supervision of other workers may be included.","version":"2022","source_id":842,"level":2,"normalized_name":"food processing wood working garment and other craft and related trades workers"},{"code":"81","parent_code":"8","title":"STATIONARY PLANT AND MACHINE OPERATORS","description":"Stationary plant and machine operators operate and monitor, on the spot or by remote control, industrial plant and machinery and equipment that are stationary, or for which mobility is not an integral part of operation. The work mainly calls for experience with and an understanding of the industrial plant, machinery or equipment being operated and monitored. Ability to cope with machine-paced operations and to adapt to innovations in machinery and equipment is often required.\n\nTasks performed by workers in this sub-major group usually include: setting up, operating and monitoring a variety stationary plant and machinery; detecting malfunctions and taking corrective action; examining outputs for defects and conformity to specifications and adjusting machine settings accordingly; performing maintenance, repairs and cleaning; recording data and maintaining production records. Supervision of other workers may be included.","version":"2022","source_id":868,"level":2,"normalized_name":"stationary plant and machine operators"},{"code":"82","parent_code":"8","title":"ASSEMBLERS","description":"Assemblers assemble prefabricated parts or components to form subassemblies, products and equipment, according to strictly laid down procedures. The products worked on may be moved from one worker to the next along assembly lines.\n\nTasks performed by workers in this sub-major group usually include: assembling components into various types of products and equipment, according to strictly laid down procedures.","version":"2022","source_id":871,"level":2,"normalized_name":"assemblers"},{"code":"83","parent_code":"8","title":"DRIVERS AND MOBILE PLANT OPERATORS","description":"Drivers and mobile plant operators drive and tend trains and motor vehicles, or drive, operate and monitor industrial and agricultural machinery and equipment, or execute deck duties on board ship and other water-borne craft.\n\nTasks performed by workers in this sub-major group usually include: driving and tending trains and motor vehicles; driving, operating and monitoring mobile industrial and agricultural machinery and equipment; carrying out deck duties on board ship and other water-borne craft.","version":"2022","source_id":886,"level":2,"normalized_name":"drivers and mobile plant operators"},{"code":"91","parent_code":"9","title":"CLEANERS AND HELPERS","description":"Cleaners and helpers perform various tasks in private households, hotels, offices, hospitals and other establishments, as well as in aircraft, trains coaches, trams and similar vehicles, in order to keep the interiors and fixtures clean, and launder and press garments and textiles by hand.\n\nTasks performed by workers in this sub-major group usually include: sweeping or vacuum cleaning, washing and polishing floors, furniture and other objects; taking care of linen and bed-making; helping with preparation of meals and cleaning in kitchens; washing and cleaning cars and windows; pressing or laundering garments and textiles by hand.","version":"2022","source_id":892,"level":2,"normalized_name":"cleaners and helpers"},{"code":"92","parent_code":"9","title":"AGRICULTURAL, FORESTRY AND FISHERY LABORERS","description":"Agricultural, forestry and fishery laborers perform simple and routine tasks in the production of crops and livestock, cultivation and maintenance of gardens and parks, exploitation and conservation of forests, and conduct of aquaculture and fisheries operations.\n\nTasks performed usually include: digging, raking and shoveling using hand tools; loading, unloading and stacking supplies, produce and other materials; watering, thinning, weeding and tending crops by hand or using hand tools; planting, harvesting picking and collecting produce by hand; feeding, watering, and cleaning animals and keeping their quarters clean; monitoring livestock, reporting on their condition; preparing and operating nets, lines and other fishing tackle and deck equipment; grading, sorting, bunching and packing produce into containers; performing minor repairs on fixtures, buildings equipment, vessels and fences.","version":"2022","source_id":898,"level":2,"normalized_name":"agricultural forestry and fishery laborers"},{"code":"93","parent_code":"9","title":"LABORERS IN MINING, CONSTRUCTION, MANUFACTURING AND TRANSPORT","description":"Laborers in mining, construction, manufacturing and transport perform simple and routine manual tasks in mining, quarrying, civil engineering, building, manufacturing, transport and storage operations, and operate human powered and animal drawn vehicles and machinery.\n\nTask performed by workers in this sub-major group usually include: digging holes and spreading excavated materials, sand, soil, and gravel using hand-held tools; sorting, loading, unloading, moving stacking and storing materials, equipment, products, supplies, baggage and cargo by hand; cleaning machinery, equipment, tools and work sites; packing and unpacking material and products and filling containers and shelves with products by hand; operating human powered and animal drawn vehicles and machinery.","version":"2022","source_id":908,"level":2,"normalized_name":"laborers in mining construction manufacturing and transport"},{"code":"94","parent_code":"9","title":"FOOD PREPARATION ASSISTANTS","description":"Food preparation assistants prepare and cook to order a small variety of pre-cooked food or beverages, clear tables, clean kitchen areas and wash dishes.\n\nTasks performed by workers usually include: preparing simple or pre-prepared foods and beverages such as sandwiches, pizzas, fish and chips, salads, and coffee; washing, cutting, measuring and mixing foods for cooking; operating cooking equipment such as grills, microwaves and deep-fat fryers; cleaning kitchens, food preparation areas and service areas; cleaning cooking and general utensils used in kitchens and restaurants.","version":"2022","source_id":910,"level":2,"normalized_name":"food preparation assistants"},{"code":"95","parent_code":"9","title":"STREET AND RELATED SALES AND SERVICE WORKERS","description":"Street and related sales and service workers provide sell goods, excluding food for immediate consumptions, and provide a variety of services on streets and in other public places such as stations.\n\nTasks include: buying or making various items for sale; loading and unloading items for sale and transporting them; obtaining the materials necessary to perform services; approaching people on the street to offer goods or services; cleaning and polishing shoes; cleaning and polishing car windows; running errands; assisting drivers to find a parking place and ensuring car is not damaged during driver’s absence; handing out leaflets and free newspapers; receiving immediate payment.","version":"2022","source_id":912,"level":2,"normalized_name":"street and related sales and service workers"},{"code":"96","parent_code":"9","title":"REFUSE WORKERS AND OTHER ELEMENTARY WORKERS","description":"Refuse workers and other elementary workers collect garbage from buildings, yards, streets and other public places or keep streets and other public places or perform odd jobs for private households or establishments.\n\nTasks include: collecting, loading and unloading garbage; sweeping streets, parks and other public places; chopping firewood; carrying water; beating dust out of carpets and performing other odd-job tasks.","version":"2022","source_id":920,"level":2,"normalized_name":"refuse workers and other elementary workers"},{"code":"011","parent_code":"01","title":"COMMISSIONED ARMED FORCES OFFICERS","description":"Commissioned armed forces officers provide leadership and management to organizational units in the armed forces and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces. This group includes all members of the armed forces holding the rank of second lieutenant (or equivalent) or higher.\nExamples of the occupations classified here: Admiral, Air commodore, Air force captain, Air force flight lieutenant, Air force group captain, Air force pilot officer, Air marshal, Armed forces officer cadet, Army brigadier, Army cadet officer, Army captain, Army colonel, Army general, Army lieutenant colonel, Army major, Army second lieutenant, Field marshal, Midshipman, Military flying officer, Military naval officer, Navy captain, Navy commander, Navy commodore, Navy lieutenant commander, Navy sublieutenant, Squadron leader, Wing commander","version":"2022","source_id":921,"level":3,"normalized_name":"commissioned armed forces officers"},{"code":"021","parent_code":"02","title":"NON-COMMISSIONED ARMED FORCES OFFICERS","description":"Non-commissioned armed forces officers enforce military discipline and supervise the activities of those employed in Armed forces occupations, other ranks, and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces. This group includes members of the armed forces holding ranks such as sergeant, warrant officer and sergeant major.\nExamples of the occupations classified here: Army sergeant, Flight sergeant, Master sergeant, Military quartermaster, Navy boatswain, Sergeant major, Warrant officer","version":"2022","source_id":922,"level":3,"normalized_name":"non-commissioned armed forces officers"},{"code":"031","parent_code":"03","title":"ARMED FORCES OCCUPATIONS, OTHER RANKS","description":"Armed forces occupations, other ranks include all conscripted and non-conscripted members of the armed forces except commissioned and non-commissioned officers. They perform specific military tasks and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces.\nExamples of the occupations classified here: Air force corporal, Airman, Army corporal, Bombardier, Gunner, Infantryman/woman, Navy coxswain, Navy seaman, Paratrooper, Rifleman/woman","version":"2022","source_id":923,"level":3,"normalized_name":"armed forces occupations other ranks"},{"code":"111","parent_code":"11","title":"LEGISLATORS AND SENIOR OFFICIALS","description":"Legislators and senior officials determine, formulate, advise on and direct the implementation of policies of national, state, regional or local governments or communities, and of special interest organizations. They make, ratify, amend or repeal laws, public rules and regulations and plan, organize, direct, control and evaluate the overall activities of government departments and agencies, traditional communities and special interest organizations. \nTasks performed usually include: presiding over or participating in the proceedings of legislative bodies and administrative councils of governments, legislative assemblies, local communities and special interest organizations; serving on government administrative boards or official committees; investigating matters of concern to the public and promoting the interests of constituents; formulating and advising on government policy, budgets, laws and regulations; establishing objectives for organizations and formulating or approving and evaluating programs and policies and procedures for their implementation; recommending, reviewing, evaluating and approving documents, briefs and reports submitted; ensuring appropriate systems and procedures are developed and implemented to provide budgetary control; allocating the use of communal land and other resources ; performing ceremonial duties and representing the government, organization or community at official occasions and in meetings, negotiations, conventions and public hearings.","version":"2022","source_id":461,"level":3,"normalized_name":"legislators and senior officials"},{"code":"112","parent_code":"11","title":"MANAGING DIRECTORS AND CHIEF EXECUTIVES","description":"Managing directors and chief executives formulate and review the policies and plan, direct, coordinate and evaluate the overall activities of enterprises or organizations (except special interest organizations and government departments) with the support of other managers, usually within guidelines established by a board of directors or a governing body to whom they are answerable for the operations undertaken and results.\nTasks performed usually include: planning, directing and coordinating the general functioning of an enterprise or organization; reviewing the operations and results of the enterprise, or organization, and reporting to boards of directors and governing bodies; determining objectives, strategies, policies and programs for the enterprise or organization; providing overall direction and management to organizations; establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; authorizing material, human and financial resources to implement organizational policies and programs; monitoring and evaluating performance of the organization or enterprise against established objectives and policies; consulting with senior subordinate staff and reviewing recommendations and reports; representing the organization at official occasions, in negotiations, at conventions, seminars, public hearings and forums; selecting, or approving the selection of senior staff; ensuring the organization complies with relevant legislation and regulations.","version":"2022","source_id":462,"level":3,"normalized_name":"managing directors and chief executives"},{"code":"121","parent_code":"12","title":"BUSINESS SERVICES AND ADMINISTRATION MANAGERS","description":"Business services and administration managers plan, organize, direct, control and coordinate the financial, administrative, human resource, policy, planning, activities of organizations, or of enterprises that provide such services to other enterprises and organizations.\nTasks usually include: formulating and administering policy advice, strategic and financial planning; establishing and directing operational and administrative procedures; implementing, monitoring and evaluating strategies and policies; providing advice to senior managers and board members on financial, administrative strategic, policy, program and legislative issues; ensuring compliance with relevant legislation, regulations and standards; controlling selection, training and performance of staff; preparing budgets and overseeing financial operations; consulting with the chief executive and with managers of other departments or sections; controlling expenditure and ensuring the efficient use of resources; representing the organization in negotiations, and at conventions, seminars, public hearings and forums.","version":"2022","source_id":466,"level":3,"normalized_name":"business services and administration managers"},{"code":"122","parent_code":"12","title":"SALES, MARKETING AND DEVELOPMENT MANAGERS","description":"Sales, marketing and development managers plan, organize, direct, control and coordinate the advertising, public relations, research and development, and sales and marketing activities of enterprises and organizations, or of enterprises that provide such services to other enterprises and organizations.\nTasks usually include: formulating and implementing policies and plans for advertising, public relations, product development, sales and marketing in consultation with other managers; directing the development of initiatives for new products or scientific research; marketing, public relations and advertising campaigns; determining and directing sales activities, product mix, customer service standards and merchandising methods and distribution policy; setting prices and credit arrangements; establishing and managing budgets and controlling expenditure to ensure the efficient use of resources; overseeing the selection, training and performance of staff; and representing the enterprise or organization at conventions, trade exhibitions and other forums.","version":"2022","source_id":469,"level":3,"normalized_name":"sales marketing and development managers"},{"code":"131","parent_code":"13","title":"PRODUCTION MANAGERS IN AGRICULTURE, FORESTRY AND FISHERIES","description":"Production managers in agriculture, forestry and fisheries plan, direct, and coordinate production in large scale agricultural, horticultural, forestry aquaculture and fishery operations such as plantations, large ranches, collective farms and co-operatives to grow and harvest crops, breed and raise livestock, fish and shellfish and to catch and harvest fish and other forms of aquatic life.\nTasks performed usually include: monitoring market activity and planning production to meet contract requirements and market demand; establishing and managing budgets, monitoring production output and costs, recording information such as farm and fisheries management practices, and preparing financial and operational reports; conferring with buyers to arrange for the sale of crops, catch and stock; contracting with farmers, skippers or independent owners for production of produce and management of production; planning the type, intensity and sequence of operations; purchasing machinery, equipment, and supplies; identifying and controlling environmental toxins, weeds, pests and diseases; organizing operations such as maintaining buildings, water supply systems and equipment; and overseeing the selection, training and performance of workers and contractors.","version":"2022","source_id":471,"level":3,"normalized_name":"production managers in agriculture forestry and fisheries"},{"code":"132","parent_code":"13","title":"MANUFACTURING, MINING, CONSTRUCTION, AND DISTRIBUTION MANAGERS","description":"Manufacturing, mining, construction, and distribution managers plan, organize, and coordinate the manufacturing, mineral extraction, construction, supply, storage and transportation operations.\nTasks performed usually include: planning details of activities in terms of output quality and quantity, cost, timeliness and labor requirements; controlling the operation of plant and quality procedures through planning of maintenance, designation of operating hours and supply of equipment; preparing tenders and contract bids; establishing and managing budgets, monitoring production output and costs, and adjusting processes and resources to minimize costs; overseeing the acquisition and installation of new plant and equipment; controlling the preparation of production records and reports; coordinating the implementation of health and safety requirements; planning and directing daily operations; and overseeing the selection, training and performance of staff.","version":"2022","source_id":475,"level":3,"normalized_name":"manufacturing mining construction and distribution managers"},{"code":"133","parent_code":"13","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY SERVICE MANAGERS","description":"Information and communications technology service managers plan, direct, and coordinate the acquisition, development, maintenance and use of computer and telecommunication systems.\nTasks usually include: consulting with users, management, vendors, and technicians to assess computing needs and system requirements and specifying technology to meet those needs; formulating and directing information and communication technology (ICT) strategies, policies and plans; directing the selection and installation of ICT resources and the provision of user training; directing ICT operations, analyzing workflow, establishing priorities, developing standards and setting deadlines; overseeing the security of ICT systems; assigning, reviewing, managing and leading the work of systems analysts, programmers, and other computer related workers; evaluating the organization's technology use and needs and recommending improvements, such as hardware and software upgrades; establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; establishing and directing operational and administrative procedures; overseeing the selection, training and performance of staff; and representing the enterprise or organization at ICT related conventions, seminars and conferences.","version":"2022","source_id":476,"level":3,"normalized_name":"information and communications technology service managers"},{"code":"134","parent_code":"13","title":"PROFESSIONAL SERVICES MANAGERS","description":"Professional services managers plan, direct and coordinate the provision of childcare, health, welfare, education and other professional services, and manage the branches of institutions providing financial and insurance services.\nTasks usually include: formulating policies and plans for the provision of services and operation of establishments; setting standards and objectives; developing and implementing programs and services to meet the needs of clients; directing and coordinating the allocation of resources; liaising with parents, boards, funding bodies, the community representatives and\nrelated agencies to discuss areas of cooperation and coordination; monitoring and controlling expenditure; overseeing the selection, development and performance of staff; preparing, or arranging for the preparation of, reports, budgets and forecasts; and representing the organization in negotiations other agencies, and at conventions, seminars, public hearings and forums.","version":"2022","source_id":483,"level":3,"normalized_name":"professional services managers"},{"code":"141","parent_code":"14","title":"HOTEL AND RESTAURANT MANAGERS","description":"Hotel and restaurant managers plan, organize and direct the operations of establishments that provide accommodation, meals, beverages and other hospitality services.\nTasks performed usually include: planning and organizing special functions, sporting, gaming and entertainment activities; directing and overseeing reservation, reception, room service and housekeeping activities; observing liquor, gaming, health and other laws and regulations; monitoring quality at all stages of preparation and presentation of food and services; controlling the selection, training and supervision of staff; and ensuring compliance with occupational health and safety regulations.","version":"2022","source_id":485,"level":3,"normalized_name":"hotel and restaurant managers"},{"code":"142","parent_code":"14","title":"RETAIL AND WHOLESALE TRADE MANAGERS","description":"Retail and wholesale trade managers plan, organize, coordinate and control the operations of establishments that sell goods on a retail or wholesale basis. They are responsible for the budgets, staffing and strategic and operational direction of shops, or of organizational units within shops that sell particular types of product. \nTasks usually include: determining product mix, stock levels and service standards; formulating and implementing purchasing and marketing policies, and setting prices; promoting and advertising the establishment's goods and services; maintaining records of stock levels and financial transactions; undertaking budgeting for the establishment; controlling selection, training and supervision of staff; and ensuring compliance with occupational health and safety regulations.","version":"2022","source_id":486,"level":3,"normalized_name":"retail and wholesale trade managers"},{"code":"143","parent_code":"14","title":"OTHER SERVICES MANAGERS","description":"Other services managers plan, organize, and control the operations of establishments that provide sporting, cultural, recreational, travel, customer contact and other amenity services.\nTasks usually include: planning and organizing the range and mix of services or activities provided; ensuring that facilities are kept clean and in good condition; keeping abreast of new trends and developments relevant to the service provided; advising on the facilities available and promoting publicity; checking and keeping custody of all cash receipts and making regular stock checks; establishing and managing budgets; controlling expenditure and ensuring the efficient use of resources; planning and directing daily operations; controlling the selection, supervision and performance of staff; and ensuring compliance with health and safety requirements.","version":"2022","source_id":488,"level":3,"normalized_name":"other services managers"},{"code":"211","parent_code":"21","title":"PHYSICAL AND EARTH SCIENCE PROFESSIONALS","description":"Physical and earth science professionals conduct research, improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to physics, astronomy, meteorology, chemistry, geology and geophysics.\nTasks performed usually include: enlarging scientific knowledge through research and experiments related to mechanics, thermodynamics, optics, sonics, electricity, magnetism, electronics, nuclear physics, astronomy, various branches of chemistry, atmospheric conditions and the physical nature of the Earth; and advising on or applying this knowledge in such fields as manufacturing, agriculture, medicine, navigation, space exploration, oil, gas, water and mineral exploitation, telecommunications and other services, or civil engineering; preparing scientific papers and reports.","version":"2022","source_id":493,"level":3,"normalized_name":"physical and earth science professionals"},{"code":"212","parent_code":"21","title":"MATHEMATICIANS, ACTUARIES, STATISTICIANS AND DATA SCIENTISTS","description":"Mathematicians, actuaries, statisticians and data scientists conduct research, improve or develop mathematical, actuarial and statistical concepts, theories and operational models and techniques and apply this knowledge to a wide range of tasks in such fields as engineering, business and social and other sciences.\nTasks performed usually include: studying, improving and developing mathematical, actuarial and statistical theories and techniques; advising on or applying mathematical principles, models and techniques to a wide range of tasks in the fields of engineering, natural, social or life sciences; conducting logical analyzes of management problems, especially in terms of input-output effectiveness, and formulating mathematical models of each problem usually for programming and solution by computer; designing and putting into operation pension schemes and life, health, social and other types of insurance systems; applying mathematics, statistics, probability and risk theory to assess potential financial impacts of future events. \nPlanning and organizing surveys and other statistical collections, and designing questionnaires; evaluating, processing, analyzing, and interpreting statistical data and preparing them for publication; advising on or applying various data collection methods and statistical methods and techniques, and determining reliability of findings, especially in such fields as business or medicine as well as in other areas of natural, social or life sciences; preparing scientific papers and reports; supervising the work of mathematical, actuarial and statistical assistants and statistical clerks.","version":"2022","source_id":497,"level":3,"normalized_name":"mathematicians actuaries statisticians and data scientists"},{"code":"213","parent_code":"21","title":"LIFE SCIENCE PROFESSIONALS","description":"Life science professionals apply knowledge gained from research into human, animal and plant life and their interactions with each other and the environment to develop new knowledge, improve agricultural and forestry production, and solve human health and environmental problems.\nTasks performed usually include: collecting, analyzing and evaluating experimental and field data to identify and develop new processes and techniques; providing advice and support to governments, organizations and businesses about ecological sustainable development of natural resources.","version":"2022","source_id":500,"level":3,"normalized_name":"life science professionals"},{"code":"214","parent_code":"21","title":"ENGINEERING PROFESSIONALS (Excluding electrotechnology)","description":"Engineering professionals (excluding electrotechnology) design, plan and organize the testing, construction, installation and maintenance of structures, machines and their components, and production systems and plants, and plan production schedules and work procedures to ensure engineering projects are undertaken safely, efficiently and in a cost effective manner. \nTasks performed usually include: planning and designing chemical process systems, civil engineering projects, mechanical equipment and systems, mining and drilling operations, and other engineering projects; specifying and interpreting drawings and plans, and determining construction methods; supervising the construction of structures, water and gas supply and transportation systems, and the manufacture, installation, operation and maintenance of equipment, machines and plant; organizing and managing project labor and the delivery of materials, plant and equipment; estimating total costs and preparing detailed cost plans and estimates as tools for budgetary control; resolving design and operational problems in the various fields of engineering through the application of engineering technology.","version":"2022","source_id":507,"level":3,"normalized_name":"engineering professionals excluding electrotechnology"},{"code":"215","parent_code":"21","title":"ELECTROTECHNOLOGY ENGINEERS","description":"Electrotechnology engineers conduct research on and design, advise, plan and direct the construction and operation of electronic, electrical and telecommunications systems, components, motors, and equipment. They organize and establish control systems to monitor the performance and safety of electrical and electronic assemblies and systems. \nTasks performed usually include: conducting research, advising on and directing the maintenance and repair of electrical, electronic and telecommunications products and systems; advising on and designing power stations and systems that generate, transmit and distribute electrical power; establishing control standards to monitor performance and safety of electrical, electronic and telecommunication systems and equipment.","version":"2022","source_id":510,"level":3,"normalized_name":"electrotechnology engineers"},{"code":"216","parent_code":"21","title":"ARCHITECTS, PLANNERS, SURVEYORS AND DESIGNERS","description":"Architects, planners, surveyors and designers plan and design landscapes, building exteriors and interiors; products for manufacture; and information for visual communication, publication and display. They conduct survey work to precisely position geographical features, design, prepare and revise maps, and develop and implement plans and policies for controlling the use of land.\nTasks performed usually include: determining the objectives and constraints of the design brief by consulting with clients and stakeholders; formulating design concepts and plans that harmonize aesthetic considerations with technical, functional, ecological and production requirements; preparing sketches, diagrams, illustrations, animations; plans, maps, charts, samples and models to communicate design concepts and other information; analyzing photographs, satellite imagery, survey documents and data, maps, records, reports and statistics; undertaking research and analyzing functional, spatial, commercial, cultural, safety, environmental and aesthetic requirements.","version":"2022","source_id":516,"level":3,"normalized_name":"architects planners surveyors and designers"},{"code":"221","parent_code":"22","title":"MEDICAL DOCTORS","description":"Medical doctors study, diagnose, treat and prevent illness, disease, injury, and other physical and mental impairments in humans through the application of the principles and procedures of modern medicine. They plan, supervise and evaluate the implementation of care and treatment plans by other health care providers, and conduct medical education and research activities.\nTasks performed usually include: conducting physical examinations of patients and interviewing them and their families to determine their health status ; ordering diagnostic tests and analyzing findings; prescribing and administering curative treatments and preventive measures; performing surgery and other clinical procedures; monitoring patients’ progress and response to treatment; advising on health, nutrition and lifestyle behaviors which aid prevention or treatment of disease and disorders; identifying and managing complications before, during and after childbirth; planning, managing and implementing referral plans for patients in need of specialized, long-term or other types of health care services; exchanging medical information with other health professionals to ensure continuing and comprehensive care; reporting births, deaths and notifiable diseases to government authorities; conducting research into human disorders and illnesses and preventive or curative methods.","version":"2022","source_id":518,"level":3,"normalized_name":"medical doctors"},{"code":"222","parent_code":"22","title":"NURSING AND MIDWIFERY PROFESSIONALS","description":"Nursing and midwifery professionals provide treatment and care services for people who are physically or mentally ill, disabled or infirm, and others in need of care due to potential risks to health including before, during and after childbirth. They assume responsibility for the planning, management and evaluation of the care of patients, including the supervision of other health care workers, working autonomously or in teams with medical doctors and others in the practical application of preventive and curative measures.\nTasks performed usually include: assessing, planning, providing and evaluating nursing and midwifery care for patients according to the practice and standards of modern nursing and midwifery; coordinating the care of patients in consultation with other health professionals and members of health teams; developing and implementing care plans, treatments and therapies, including administering medications; monitoring and alleviating pain and discomfort experienced by patients using a variety of therapies, including the use of pain-killing drugs; monitoring patients' health condition, including progress of pregnancy and responses to curative treatment; providing information to patients, families and communities about a range of health issues, including prevention of illness, treatment and care, pregnancy and childbirth, and other topics; supervising and coordinating the work of other health care workers; conducting research on nursing and midwifery practice and preparing scientific papers and reports.","version":"2022","source_id":520,"level":3,"normalized_name":"nursing and midwifery professionals"},{"code":"223","parent_code":"22","title":"TRADITIONAL AND COMPLEMENTARY MEDICINE PROFESSIONALS","description":"Traditional and complementary medicine professionals prevent, diagnose and treat illness, disease, injury, and other physical and mental impairments and maintain general health in humans by applying knowledge, skills and practices acquired through extensive study of the theories, beliefs and experiences, originating in specific cultures.\nTheir tasks include: a) conducting physical examinations of patients and interviewing them and their families to determine their health status; b) developing and implementing treatment plans for physical, mental and psychosocial ailments using applications such as acupuncture, ayurvedic, homoeopathic and herbal medicine; c) evaluating and documenting patients' progress through treatment plans; d) providing health, nutrition and lifestyle advice to individuals, families and communities; e) prescribing and preparing traditional medicines, such as herbal, plant, mineral and animal extracts, to stimulate the body's capacity for self-healing; f) exchanging information about patients with other health care workers as needed to ensure continuing and comprehensive health care; and g) conducting research into traditional and complementary medicines and treatments and disseminating findings such as through scientific papers and reports.\nExamples of the occupations classified here: Acupuncturist, Ayuverdic practitioner, Chinese herbal medicine practitioner, Homeopath, Naturopath, Unani practitioner","version":"2022","source_id":521,"level":3,"normalized_name":"traditional and complementary medicine professionals"},{"code":"224","parent_code":"22","title":"PARAMEDICAL PRACTITIONERS","description":"Paramedical practitioners provide advisory, diagnostic, curative and preventive medical services for humans more limited in scope and complexity than those carried out by medical doctors. They work autonomously or with limited supervision of medical doctors, and apply advanced clinical procedures for treating and preventing diseases, injuries and other physical or mental impairments common to specific communities.\nTheir tasks include: a) conducting physical examinations of patients and interviewing them and their families to determine their health status, and recording patients' medical information; b) performing basic or more routine medical and surgical procedures, including prescribing and administering treatments, medications and other preventive or curative measures, especially for common diseases and disorders; c) administering or ordering diagnostic tests, such as x-ray, electrocardiogram, and laboratory tests; d) performing therapeutic procedures, such as injections, immunizations, suturing and wound care, and infection management; e) assisting medical doctors with complex surgical procedures; f) monitoring patients' progress and response to treatment, and identifying signs and symptoms requiring referral to medical doctors; g) advising patients and families on diet, exercise and other habits which aid prevention or treatment of disease and disorders; h) identifying and referring complex or unusual cases to medical doctors, hospitals or other places for specialized care; and i) reporting births, deaths and notifiable diseases to government authorities to meet legal and professional reporting requirements.\nExamples of the occupations classified here: Advanced care paramedic, Feldsher, Paramedic clinical officer, Primary care paramedic, Surgical technician\nSome related occupations classified elsewhere: Emergency paramedic - 3258, General practitioner - 2211, Medical assistant - 3256, Surgeon - 2212","version":"2022","source_id":522,"level":3,"normalized_name":"paramedical practitioners"},{"code":"225","parent_code":"22","title":"VETERINARIANS","description":"Veterinarians diagnose, prevent and treat diseases, injuries and dysfunctions of animals. They may provide care to a wide range of animals or specialize in the treatment of a particular animal group or in a particular specialty area, or provide professional services to commercial firms producing biological and pharmaceutical products.\nTheir tasks include: a) determining the presence and nature of abnormal conditions by physical examination, laboratory testing and through diagnostic imaging techniques including radiography and ultrasound; b) treating animals medically and surgically, and administering and prescribing drugs, analgesics, and general and local anesthetics; c) performing surgery, dressing wounds and setting broken bones; d) rendering obstetric and dental services to animals; e) participating in programs designed to prevent the occurrence and spread of animal diseases; f) inoculating animals against, and testing for, infectious diseases and notifying authorities of outbreaks of infectious animal diseases; g) performing autopsies to determine cause of death; h) advising clients on health, nutrition and feeding, hygiene, breeding and care of animals; and i) providing euthanasia services for animals.\nExamples of the occupations classified here: Animal nutritionist, Animal pathologist, Public health veterinarian , Veterinarian , Veterinary epidemiologist , Veterinary intern, Veterinary surgeon","version":"2022","source_id":523,"level":3,"normalized_name":"veterinarians"},{"code":"226","parent_code":"22","title":"OTHER HEALTH PROFESSIONALS","description":"Other health professionals provide health services related to dentistry, pharmacy, environmental health and hygiene, occupational health and safety, physiotherapy, nutrition, hearing, speech, vision and rehabilitation therapies. This minor group includes all human health professionals, except doctors, traditional and complementary medicine practitioners, veterinarians, nurses, midwives and paramedical professionals.","version":"2022","source_id":531,"level":3,"normalized_name":"other health professionals"},{"code":"231","parent_code":"23","title":"UNIVERSITY AND HIGHER EDUCATION TEACHERS","description":"University and higher education teachers prepare and deliver lectures and conduct tutorials in one or more subjects within a prescribed course of study at a university or other higher educational institution. They conduct research, and prepare scholarly papers and books. \nTheir tasks include: a) designing and modifying curricula and preparing courses of study in accordance with requirements; b) preparing and delivering lectures and conducting tutorials, seminars and laboratory experiments; c) stimulating discussion and independent thought among students; d) supervising, where appropriate, experimental and practical work undertaken by students; e) administering, evaluating and marking examination papers and tests; f) directing research of post-graduate students or other members of department; g) researching into and developing concepts, theories and operational methods for application in industrial and other fields; h) preparing scholarly books, papers or articles; and i) participating in departmental and faculty meetings and in conferences and seminars.\nExamples of the occupations classified here: Assistant professor, College professor, Information technology professor, Professor, University lecturer\nSome related occupations classified elsewhere: Dean - 1345, Higher education faculty head - 1345, University chancellor - 1120, Vocational education teacher - 2320","version":"2022","source_id":532,"level":3,"normalized_name":"university and higher education teachers"},{"code":"232","parent_code":"23","title":"VOCATIONAL EDUCATION TEACHERS","description":"Vocational education teachers teach or instruct vocational or occupational subjects in adult and further education institutions and to senior students in secondary schools and colleges. They prepare students for employment in specific occupations or occupational areas for which university or higher education is not normally required.\nTheir tasks include: a) developing curricula and planning course content and methods of instruction; b) determining training needs of students or workers and liaising with individuals, industry and other education sectors to ensure provision of relevant education and training programs;c) presenting lectures and conducting discussions to increase students' knowledge and competence;d) instructing and monitoring students in the use of tools, equipment and materials and the prevention of injury and damage; e) observing and evaluating students' work to determine progress, provide feedback, and make suggestions for improvement; f) administering oral, written or performance tests to measure progress, evaluate training effectiveness and assess competency; g) preparing reports and maintaining records such as student grades, attendance rolls, and training activity details; h) supervising independent or group projects, field placements, laboratory work, or other training; i) providing individualized instruction and tutorial or remedial instruction; and j) conducting on-the-job training sessions to teach and demonstrate principles, techniques, procedures, or methods of designated subjects.\nExamples of the occupations classified here: Automotive technology instructor, Cosmetology instructor, Vocational education teacher\nRelated occupation classified elsewhere: Secondary education teacher - 2330","version":"2022","source_id":533,"level":3,"normalized_name":"vocational education teachers"},{"code":"233","parent_code":"23","title":"SECONDARY EDUCATION TEACHERS","description":"Secondary education teachers teach one or more subjects at secondary education level, excluding subjects intended to prepare students for employment in specific occupational areas.\nTheir tasks include: a) designing and modifying curricula and preparing educational courses of study in accordance with curriculum guidelines; b) establishing and enforcing rules for behavior and procedures for maintaining order among students; c) preparing and giving lessons, discussions, and demonstrations in one or more subjects; d) establishing clear objectives for all lessons, units, and projects and communicating those objectives to students; e) preparing materials and classrooms for class activities; f) adapting teaching methods and instructional materials to meet students' varying needs and interests; g) observing and evaluating students’ performance and behavior; h) preparing, administering and marking tests, assignments and examinations to evaluate pupils' progress; i) preparing reports about pupils' work and conferring with other teachers and parents; j) participating in meetings concerning the school's educational or organizational policies; and k) planning, organizing and participating in school activities such as excursions, sporting events and concerts.\nExamples of the occupations classified here: High school teacher, Secondary education teacher","version":"2022","source_id":534,"level":3,"normalized_name":"secondary education teachers"},{"code":"234","parent_code":"23","title":"PRIMARY SCHOOL AND EARLY CHILDHOOD TEACHERS","description":"Primary school and early childhood teachers teach a range of subjects at the primary level of education and organize educational activities for children below primary school age.\nTasks performed usually include: preparing programme of learning and giving instruction in a range of subjects at the primary education level, planning and organizing activities designed to facilitate children’s development of language, physical and social skills; preparing reports. Supervision of other workers may be included.","version":"2022","source_id":536,"level":3,"normalized_name":"primary school and early childhood teachers"},{"code":"235","parent_code":"23","title":"OTHER TEACHING PROFESSIONALS","description":"Other teaching professionals conduct research and advise on teaching methods, teach people with learning difficulties or special needs; teach non-native languages for migration and related purposes; give private tuition; teach arts, information technology and other subjects outside the mainstream primary, secondary and higher education systems and provide other teaching services not classified elsewhere in Sub-major group 23, Teaching professionals.\nTasks performed usually include: conducting research and developing or advising on teaching methods, courses and aids; teaching physically handicapped children, young persons or adults or those with learning difficulties or other with special needs, teaching non-native languages for migration purposes; teaching students in practice, theory and performance of music, drama, dance, visual and other arts; developing, scheduling and conducting training programs and courses for information technology users.","version":"2022","source_id":543,"level":3,"normalized_name":"other teaching professionals"},{"code":"241","parent_code":"24","title":"FINANCE PROFESSIONALS","description":"Finance professionals plan, develop, organize, administer, invest, manage and conduct quantitative analyses of either financial accounting systems or funds for individuals, establishments and public or private institutions.\nTasks performed usually include: preparing and organizing financial statements for an organization; reviewing financial materials of an organization; providing financial advice to individuals and organizations; preparing analytic reports concerning segments of the economy and the economy as a whole.","version":"2022","source_id":546,"level":3,"normalized_name":"finance professionals"},{"code":"242","parent_code":"24","title":"ADMINISTRATION PROFESSIONALS","description":"Administration professionals apply various concepts and theories related to improving the effectiveness of organizations and the individuals within the organization.\nTasks performed usually include: evaluating the structure of organizations and suggesting areas of improvement; ensuring that the operational activities of an organization are consistent with the policy objectives of the organization; recruiting, training, developing, and counselling personnel within an organization.","version":"2022","source_id":550,"level":3,"normalized_name":"administration professionals"},{"code":"243","parent_code":"24","title":"SALES, MARKETING AND PUBLIC RELATIONS PROFESSIONALS","description":"Sales, marketing and public relations professionals plan, develop, coordinate and implement programs of information dissemination to promote organizations, goods and services, and represent companies in selling a range of technical, industrial, medical, pharmaceutical and ICT goods and services.\nTasks performed usually include: commissioning and undertaking market research, analyzing the findings, and planning advertising marketing and public relations activities; supporting business growth and development through the preparation and execution of marketing objectives, policies and programs; planning and organizing publicity campaigns; appraising and selecting material submitted by writers, photographers, illustrators and others to create favorable publicity; acquiring and updating knowledge of employers’ and competitors’ goods and services, and market conditions; assessing customers’ needs and explaining and demonstrating goods and services to them; visiting regular and prospective client businesses to establish and act on marketing opportunities; quoting and negotiating prices and credit terms, and completing contracts.","version":"2022","source_id":554,"level":3,"normalized_name":"sales marketing and public relations professionals"},{"code":"251","parent_code":"25","title":"SOFTWARE AND APPLICATIONS DEVELOPERS AND ANALYST","description":"Software and applications developers and analysts conduct research, plan, design, write, test, provide advice on and improve information technology systems, such as hardware, software and other applications to meet specific requirements. \nTasks performed usually include: researching information technology use in business functions and identifying areas in which improvements could be made to maximize effectiveness and efficiency; conducting research into the theoretical aspects of and operational methods for the use of computers; evaluating, planning and designing hardware or software configurations for specific applications; designing, writing, testing and maintaining computer programs for specific requirements; evaluating, planning and designing Internet, Intranet and multimedia systems.","version":"2022","source_id":559,"level":3,"normalized_name":"software and applications developers and analyst"},{"code":"252","parent_code":"25","title":"DATABASE AND NETWORK PROFESSIONALS","description":"Database and network professionals design, develop, control, maintain and support the optimal performance and security of information technology systems and infrastructure, including databases, hardware and software, networks and operating systems.\nTasks performed usually include: designing and developing database architecture, data structures, dictionaries and naming conventions for information systems projects; designing, constructing, modifying, integrating, implementing and testing database management systems; developing and implementing security plans, data administration policy, documentation and standards; maintaining and administering computer networks and related computing environments; analyzing, developing, interpreting and evaluating complex system design and architecture specifications, data models and diagrams in the development, configuration and integration of computer systems.","version":"2022","source_id":563,"level":3,"normalized_name":"database and network professionals"},{"code":"261","parent_code":"26","title":"LEGAL PROFESSIONALS","description":"Legal professionals conduct research on legal problems, advise clients on legal aspects of problems, plead cases or conduct prosecutions in courts of law, preside over judicial proceedings in courts of law, and draft laws and regulations.\nTasks performed usually include: giving clients legal advice, undertaking legal business on clients’ behalf, and conducting litigation when necessary, or presiding over judicial proceedings- and pronouncing judgement in courts of law. Supervision of other workers may be included.","version":"2022","source_id":566,"level":3,"normalized_name":"legal professionals"},{"code":"262","parent_code":"26","title":"LIBRARIANS, ARCHIVISTS AND CURATORS","description":"Librarians, archivists and curators develop and maintain the collections of archives, libraries, museums, art galleries, and similar establishments.\nTasks performed usually include: appraising or developing and organizing the contents of archives and artefacts of historical, cultural and artistic interest, and ensuring their safe-keeping and preservation; organizing the collections of and exhibitions at museums, art galleries and similar establishments; developing and the collections of and exhibitions at museums, art galleries and similar establishments; developing and maintaining the systematic collection of recorded and published material and making it available to users in libraries and related institutions; preparing scholarly papers and reports; conducting research.","version":"2022","source_id":568,"level":3,"normalized_name":"librarians archivists and curators"},{"code":"263","parent_code":"26","title":"SOCIAL AND RELIGIOUS PROFESSIONALS","description":"Social and related professionals conduct research, improve or develop concepts, theories and operational methods, or apply knowledge relating to philosophy, politics, economics, sociology, anthropology, history, philology, languages, psychology, and other social sciences, or they provide social services to meet the needs of individuals and families in a community.\nTasks performed usually include: formulating and applying solutions to present or projected economic, political or social problems; researching into and analyzing past events and activities and tracing the origin and evolution of the human race; studying the origin and development of languages, or translating or interpreting them; studying mental processes and behavior of individuals and groups; providing social services; preparing scholarly papers and reports. Supervision of other workers may be included.","version":"2022","source_id":574,"level":3,"normalized_name":"social and religious professionals"},{"code":"264","parent_code":"26","title":"AUTHORS, JOURNALISTS AND LINGUISTS","description":"Authors, journalists and linguists conceive and create literary works, interpret and communicate news and public affairs through the media and translate or interpret from one language into another.\nTasks performed usually include: writing literary works; appraising merits of literary and other works of art; collecting information about current affairs and writing about them; researching, investigating, interpreting and communicating news and public affairs through newspapers, television, radio and other media; translating written material from one language to another; simultaneously translating from one language to another.","version":"2022","source_id":577,"level":3,"normalized_name":"authors journalists and linguists"},{"code":"265","parent_code":"26","title":"CREATIVE AND PERFORMING ARTISTS","description":"Creative and performing artists communicate ideas, impressions and facts in a wide range of media to achieve particular effects; interpret a composition such as a musical score or a script to perform or direct the performance; and host the presentation of such performance and other media events.\nTasks performed usually include: conceiving and creating visual art forms; conceiving and writing original music; devising, directing, rehearsing and performing in music, dance, theatrical and film productions; assuming creative, financial and organizational responsibilities in the production of television programmes, films, and stage presentations; studying script, play or book and preparing and rehearsing interpretation; selecting and introducing music, videos and other entertainment material for broadcast and making commercial and public service announcements.","version":"2022","source_id":584,"level":3,"normalized_name":"creative and performing artists"},{"code":"311","parent_code":"31","title":"PHYSICAL AND ENGINEERING SCIENCE TECHNICIANS","description":"Physical and engineering science technicians perform technical tasks to aid in research on and the practical application of concepts, principles and operational methods particular to physical sciences including such areas as engineering, technical drawing or economic efficiency of production processes.\nTasks performed usually include: undertaking and carrying out technical work related to chemistry, physics, geology, meteorology, astronomy, engineering, or technical drawing; setting up, operating, and maintaining laboratory instruments and equipment, monitoring experiments, making observations, and calculating and recording results; preparing materials for experimentation; conducting tests of systems; collecting and testing samples; recording observations and analyzing data; preparing, revising and interpreting technical drawings, wiring diagrams, circuit board assembly diagrams, or layout drawings.","version":"2022","source_id":593,"level":3,"normalized_name":"physical and engineering science technicians"},{"code":"312","parent_code":"31","title":"MINING, MANUFACTURING AND CONSTRUCTION SUPERVISORS","description":"Mining, manufacturing and construction supervisors coordinate, supervise, control and schedule the activities of workers in manufacturing, mining and construction operations.\nTasks performed usually include: overseeing, supervising and coordinating the activities of tradespersons, process control technicians, machine operators, assemblers, laborers and other workers; organizing and planning daily work; preparing cost estimates, records and reports; identifying shortages of staff or supplies; ensuring safety of workers; instructing and training new staff.","version":"2022","source_id":596,"level":3,"normalized_name":"mining manufacturing and construction supervisors"},{"code":"313","parent_code":"31","title":"PROCESS CONTROL TECHNICIANS","description":"Process control technicians operate and monitor switchboards, computerized control systems, multi-function process control machinery and maintain processing units in electrical power generation and distribution, wastewater, sewage treatment and waste disposal plants, chemical, petroleum and natural gas refineries in metal processing and other multiple process operations.\nTasks performed usually include: operating electronic or computerized control panels from a central control room to monitor and optimize processes; controlling process start-up and shut-down; operating and monitoring switchboards and related equipment; monitoring and inspecting equipment and systems to detect malfunctions; taking readings from charts, meters and gauges at established intervals; troubleshooting and take corrective action as necessary; maintaining records, logs and reports; communicating with other personnel to assess equipment operating status; cleaning and maintaining equipment; supervising plant and machine operators and other workers.","version":"2022","source_id":602,"level":3,"normalized_name":"process control technicians"},{"code":"314","parent_code":"31","title":"LIFE SCIENCE TECHNICIANS AND RELATED ASSOCIATE PROFESSIONALS","description":"Life science technicians and related associate professionals perform a variety of technical tasks to support life science professionals with their research, development, management, conservation and protection work, in areas such as biology, botany, zoology, biotechnology and biochemistry, and to agriculture, fisheries and forestry.\nTasks performed usually include: conducting tests, experiments, laboratory analyzes, field research and surveys to collect information using accepted scientific methods; keeping records; assisting in analyzing data and preparing reports; operating and maintaining equipment.","version":"2022","source_id":605,"level":3,"normalized_name":"life science technicians and related associate professionals"},{"code":"315","parent_code":"31","title":"SHIP AND AIRCRAFT CONTROLLERS AND TECHNICIANS","description":"Ship and aircraft controllers and technicians, command and navigate ships and aircraft, perform technical functions to ensure safe and efficient movement and operations, and develop electrical, electromechanical, and computerized air control systems.\nTasks performed usually include: controlling the operation of mechanical, electrical and electronic equipment on board ship or on aircraft, commanding and navigating ships or aircraft, directing the movements of ships or aircraft and developing electrical, electromechanical, and computerized air control systems.","version":"2022","source_id":610,"level":3,"normalized_name":"ship and aircraft controllers and technicians"},{"code":"321","parent_code":"32","title":"MEDICAL AND PHARMACEUTICAL TECHNICIANS","description":"Medical and pharmaceutical technicians perform technical tasks to assist in diagnosis and treatment of illness, disease, injuries and impairments.\nTasks usually include: testing and operating radiographic, ultrasound and other medical imaging equipment; administering radiopharmaceuticals or radiation to patients to detect or treat diseases; performing clinical tests on specimens of bodily fluids and tissues; preparing medications and other pharmaceutical compounds under the guidance of pharmacists; designing, fitting, servicing and repairing medical and dental devices and appliances.","version":"2022","source_id":614,"level":3,"normalized_name":"medical and pharmaceutical technicians"},{"code":"322","parent_code":"32","title":"NURSING AND MIDWIFERY ASSOCIATE PROFESSIONALS","description":"Nursing and midwifery associate professionals provide basic nursing and personal care for people who are physically or mentally ill, disabled or infirm, and others in need of care due to potential risks to health including before, during and after childbirth. They generally work under the supervision of, and in support of implementation of health care, treatment and referrals plans established by, medical, nursing, midwifery and other health professionals.\nTasks performed usually include: providing nursing and personal care, treatment and advice to patients as per care plans as established by health professionals; assisting professional nurses, midwives and medical doctors in administering medication and treatments; cleaning wounds and applying surgical dressings; providing advice to individuals, families and communities on topics related to health, contraception, pregnancy and childbirth; assessing progress during pregnancy and childbirth, providing or assisting in delivery care, and recognizing signs and symptoms requiring referral to a health professional; providing care and support to women and newborns following childbirth.","version":"2022","source_id":616,"level":3,"normalized_name":"nursing and midwifery associate professionals"},{"code":"323","parent_code":"32","title":"TRADITIONAL AND COMPLEMENTARY MEDICINE ASSOCIATE PROFESSIONALS","description":"Traditional and complementary medicine associate professionals prevent, care for and treat human physical and mental illnesses, disorders and injuries using herbal and other therapies based on theories, beliefs and experiences originating in specific cultures. \nTheir tasks include: a) examining patients and interviewing them and their families to determine their health status and the nature of physical or mental disorders or illnesses or other ailments; b) recommending and providing care and treatment for illnesses and other ailments using traditional techniques and medicaments, such as physical manipulation and exercises, blood-letting using natural vessels, and preparations using herbs, plants, insects and animal extracts; c) providing care and treatment for physical injuries such as setting and healing fractured and dislocated bones using traditional methods of physical manipulation and herbal therapies; d) advising individuals, families and the community on health, nutrition, hygiene, lifestyle and other issues to maintain or improve health and well-being; and e) referring patients to, and exchanging information with, other health care providers to ensure comprehensive and continuing care.\nExamples of the occupations classified here: Acupuncture technician, Ayurvedic technician, Bonesetter, Drugless treatment healer, Healer of indigenous people (e.g. Mansi-bok (Ibaloi); Mansip-ok (Kankana-ey) in Cordilleras), Herbalist, Homeopathy technician , Scraping and cupping therapist, Village healer, Witch doctor\nSome related occupations classified elsewhere: Acupressure therapist - 3255, Acupuncturist - 2230, Ayuverdic practitioner - 2230, Chinese herbal medicine practitioner - 2230, Chiropractor - 2269, Faith healer - 3413, Homeopath - 2230, Hydrotherapist - 3255, Naturopath - 2230, Osteopath - 2269, Traditional midwife - 3222","version":"2022","source_id":617,"level":3,"normalized_name":"traditional and complementary medicine associate professionals"},{"code":"324","parent_code":"32","title":"VETERINARY TECHNICIANS AND ASSISTANTS","description":"Veterinary technicians and assistants carry out advisory, diagnostic, preventive and curative veterinary tasks, more limited in scope and complexity than those carried out by veterinarians. They care for animals under treatment and in temporary residence at veterinary facilities and assist veterinarians to perform procedures and operations.\nTheir tasks include: a) advising communities and individuals on the treatment of animals and their diseases and injuries; b) conducting examinations of animals to make diagnoses or refer more difficult cases to veterinarians when needed; c) treating ill or injured animals, especially for common diseases and disorders; d) cleaning and sterilizing examination tables and instruments and preparing materials used in the examination and treatment of animals; e) carrying out technical tasks connected with artificial insemination of animals; f) getting animals ready for examination or treatment and restraining or holding them during treatment; g) assisting veterinarians to administer anesthetics and oxygen during treatment; h) placing animals in cages for recovery from operations and monitoring their condition; i) producing radiographs, collecting samples, and performing other laboratory tests to assist in diagnosis of animal health problems; and j) performing routine animal dental procedures and assisting veterinarians with animal dentistry.\nExamples of the occupations classified here: Artificial inseminator, Veterinary assistant, Veterinary laboratory technician, Veterinary nurse, Veterinary vaccinator\nSome related occupations classified elsewhere: Animal attendant - 5164, Veterinarian - 2250, Veterinary aide - 5164","version":"2022","source_id":618,"level":3,"normalized_name":"veterinary technicians and assistants"},{"code":"325","parent_code":"32","title":"OTHER HEALTH ASSOCIATE PROFESSIONALS","description":"Other health associate professionals perform technical tasks and provide support services in dentistry, medical records administration, community health, the correction of reduced visual acuity, physiotherapy, environmental health, emergency medical treatment and other activities to support and promote human health.\nTasks usually include: providing basic care services for the prevention and treatment of diseases and disorders of the teeth and mouth; advising communities and individuals on hygiene, diet and other preventive measures to reduce potential risks to health; compiling and maintaining patients’ medical records to document condition and develop the necessary skills and resources to improve their health status; providing advice and education on sanitation and hygiene to limit the spread of infectious diseases; fitting and dispensing optical lenses; investigate the implementation of rules and regulations relating to environmental and occupational factors that may potentially affect human health; massaging the soft tissues of the body; showing patients to examination rooms and preparing them for examination; attending accidents, emergencies and requests for medical assistance.","version":"2022","source_id":627,"level":3,"normalized_name":"other health associate professionals"},{"code":"331","parent_code":"33","title":"FINANCIAL AND MATHEMATICAL ASSOCIATE PROFESSIONALS","description":"Financial and mathematical associate professionals place a value on various items and property, maintain records of financial transactions, analyze loan application information and render a decision, buy and sell financial instruments, and perform mathematical and related calculations.\nRecording and transmitting buy and sell orders for securities, stocks, bonds or other financial instruments and for foreign exchange for future or immediate delivery; submitting credit and loan applications to management with recommendations for approval or rejection; or approve or reject applications within authorized limits ensuring that credit standards of the institution are respected; maintaining complete records of all financial transactions of an undertaking according to general bookkeeping principles, with guidance from Accountants; assisting in planning and performing mathematical, statistical, actuarial, accounting and related calculations.","version":"2022","source_id":632,"level":3,"normalized_name":"financial and mathematical associate professionals"},{"code":"332","parent_code":"33","title":"SALES AND PURCHASING AGENTS AND BROKERS","description":"Sales and purchasing agents and brokers represent companies, governments and other organizations to buy and sell commodities, goods, insurance, shipping and other services to industrial, professional, commercial or other establishments, or act as independent agents to bring together buyers and sellers of commodities and services.\nTasks performed usually include obtaining information about, monitoring and analyzing market trends and conditions and employer’s and competitors goods and services; obtaining information about clients’ needs and identifying suitable products and services; explaining and demonstrating products and services to clients; negotiating prices, contracts, terms, conditions and shipping arrangements for purchase or sale of goods, services or commodities.","version":"2022","source_id":636,"level":3,"normalized_name":"sales and purchasing agents and brokers"},{"code":"333","parent_code":"33","title":"BUSINESS SERVICE AGENTS","description":"Business service agents establish contacts to sell various business services such as advertising space in the media, carry out customs clearance activities ensuring that necessary documents are in order, match jobseekers with vacancies, find workers for employers, arrange contracts for the performance of athletes, entertainers and artists, as well as for the publication of books, the production of plays, or the recording, performing and sale of music, plan and organize conferences and similar events.\nTasks performed usually include: Carrying out customs clearing procedures for exports or imports; arranging and coordinating conference and event services, such as conference facilities, catering, signage, displays, audiovisual and computer equipment, accommodation, transport and social events, for participants; matching jobseekers with vacancies; finding workers for vacant posts for employers; showing real estate properties to be sold or leased to prospective buyers or tenants and explaining terms of sale or conditions of rent or lease; selling by auction various kinds of property, cars, commodities, livestock, art, jewelry and other objects; arranging contracts for performers and performances.","version":"2022","source_id":641,"level":3,"normalized_name":"business service agents"},{"code":"334","parent_code":"33","title":"ADMINISTRATIVE AND SPECIALIZED SECRETARIES","description":"Administrative and specialized secretaries provide organizational, communication and documentation support services, utilizing specialized knowledge of the business activity of the organization in which they are employed. They take supervisory responsibility for office clerks in the organization.\nTasks performed usually include: coordinating, assigning and reviewing the work of clerical support workers; desktop publishing; preparing and processing legal documents and papers, such as deeds, wills, affidavits and briefs; implementing and supporting the communication, documentation and internal managerial coordination activities of an organizational unit, on some occasions utilizing specialized knowledge of the business activity of the organization; scheduling and confirming meetings and appointments and communicating messages for clients; compiling, recording and reviewing legal and medical records, reports, documents and correspondence.","version":"2022","source_id":645,"level":3,"normalized_name":"administrative and specialized secretaries"},{"code":"335","parent_code":"33","title":"REGULATORY GOVERNMENT ASSOCIATE PROFESSIONALS","description":"Regulatory government associate professionals administer, enforce or apply relevant government rules and regulations relating to national borders, taxes, social benefits, and issue or examine applications for licenses or authorizations in connection with travel, exports and imports of goods, establishment of businesses, erection of buildings and other activities subject to government regulations.\nTasks performed usually include: patrolling national borders and checking persons and vehicles, travel and transport documents and goods transported across the border to ensure enforcement of government rules and regulations; examining tax returns to determine taxes payable by persons and businesses; examining and deciding on applications for social benefits, examining and deciding on applications for government authorizations and licenses necessary to travel, export or import goods, erect buildings, establish businesses or undertake other activities subject to government regulations; monitoring the application of price, wage or weights and measures regulations. They may receive guidance from senior government officials or Managers. Supervision of other workers may be included.","version":"2022","source_id":651,"level":3,"normalized_name":"regulatory government associate professionals"},{"code":"341","parent_code":"34","title":"LEGAL, SOCIAL AND RELIGIOUS ASSOCIATE PROFESSIONALS","description":"Legal, social and religious associate professionals provide technical and practical services and support functions in legal processes and investigations, social and community assistance programs and religious activities.\nTasks performed usually include: assisting and supporting legal, social work and religious professionals; obtaining and analyzing evidence, preparing legal documents and serving court orders; administering and implementing social assistance programs and community services; assisting clients to deal with personal and social problems; providing practical assistance, guidance and moral support to individuals and communities.","version":"2022","source_id":654,"level":3,"normalized_name":"legal social and religious associate professionals"},{"code":"342","parent_code":"34","title":"SPORTS AND FITNESS WORKERS","description":"Sports and fitness workers prepare for and compete in sporting events for financial gain, train amateur and professional sportsmen and women to enhance performance, promote participation and standards in sport, organize and officiate sporting events, and provide instruction, training and supervision for various forms of exercise and other recreational activities.\nTasks performed usually include: participating in competitive sporting events; conducting sports training to develop ability in and knowledge of the sport; compiling rules concerning the conduct of sporting competitions, and controlling the progress of these events; planning, organizing and conducting practice sessions; developing and designing fitness programmes; delivering group exercise classes and personal tuition in a variety of fitness activities; promoting sports and sports skills development, and overseeing the participation of young people in sport.","version":"2022","source_id":658,"level":3,"normalized_name":"sports and fitness workers"},{"code":"343","parent_code":"34","title":"ARTISTIC, CULTURAL AND CULINARY ASSOCIATE PROFESSIONALS","description":"Artistic cultural and culinary associate professionals combine creative skills and technical and cultural knowledge in taking and processing still photographs; design and decoration of theatre sets, shop displays and the interiors of homes; preparation of objects for display; maintenance of library and gallery collections, records and cataloguing systems; creation of menus and preparation and presentation of food; provision of support for stage, film and television production; and in other areas of artistic and cultural endeavor.\nTasks performed usually include: operating still cameras to photograph people, events, scenes, materials, products and other subjects; applying artistic techniques to product design, interior decoration and sales promotion; mounting and preparing objects for display; designing and arranging exhibit furnishings, display cases and display areas; designing menus and overseeing the preparation of food; assisting directors and performers with the staging of theatrical, motion picture, television or commercial productions.","version":"2022","source_id":663,"level":3,"normalized_name":"artistic cultural and culinary associate professionals"},{"code":"351","parent_code":"35","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY OPERATIONS AND USER SUPPORT TECHNICIANS","description":"Information technology operations and user support technicians provide support for the day-to-day running of communications systems, computer systems and networks and provide technical assistance to users.\nTasks performed usually include: operating and controlling peripheral and related computer equipment; monitoring systems for equipment failure or errors in performance; loading peripheral equipment, such as printers, with selected materials for operating runs, or oversee loading of peripheral equipment by peripheral equipment operators; answering user inquiries regarding software or hardware operation to resolve problems; installing and performing minor repairs to hardware, software, or peripheral equipment, following design or installation specifications; overseeing the daily performance of systems; setting up equipment for employee use, performing or ensuring proper installation of cables, operating systems, or appropriate software; establishing, operating and maintaining network and other data communications systems; installing, monitoring and supporting the reliability and usability of Internet and Intranet websites or web server hardware or software; modifying web pages; and performing web server backup and recovery operations.","version":"2022","source_id":667,"level":3,"normalized_name":"information and communications technology operations and user support technicians"},{"code":"352","parent_code":"35","title":"TELECOMMUNICATIONS AND BROADCASTING TECHNICIANS","description":"Telecommunications and broadcasting technicians control technical functioning of equipment to record and edit images and sound and for transmitting radio and television broadcasts of images and sounds, as well as other types of telecommunication signals on land, sea or in aircraft, perform technical tasks connected with telecommunications engineering research and with the design, manufacture, assembly, construction, operation, maintenance and repair of telecommunications systems.\nTasks performed usually include: controlling equipment to record sound, edit and mix image and sound recordings; controlling and maintaining transmitting and broadcast systems and satellite systems for radio and television programmes; controlling and maintaining radio communications systems, satellite services, and multiplex systems on land, sea or in aircraft; providing technical assistance connected with research and the development of telecommunications equipment, or testing prototypes; designing and preparing blueprints of circuitry according to the specifications given; providing technical supervision of the manufacture, utilization, maintenance and repair of telecommunications systems.","version":"2022","source_id":669,"level":3,"normalized_name":"telecommunications and broadcasting technicians"},{"code":"411","parent_code":"41","title":"GENERAL OFFICE CLERKS","description":"General office clerks perform a range of clerical and administrative tasks according to established procedures. \nTheir tasks include: a) recording, preparing, sorting, classifying and filing information; b) sorting, opening and sending mail; c) photocopying and sending documents; d) preparing reports and correspondence of a routine nature; e) recording issue of equipment to staff; f) responding to telephone or electronic enquiries or forwarding to appropriate person; g) checking figures, preparing invoices and recording details of financial transactions made; and h) transcribing information into computers, and proof-reading and correcting copy.\nExamples of the occupations classified here: Document receiving clerk, Laboratory office clerk, Livelihood office clerk, Office clerk, Office maintenance clerk, Office record clerk, Office records filing clerk, Registrar clerk","version":"2022","source_id":670,"level":3,"normalized_name":"general office clerks"},{"code":"412","parent_code":"41","title":"SECRETARIES (GENERAL)","description":"Secretaries (general) use typewriters, personal computers or other word-processing equipment to transcribe correspondence and other documents; check and format documents prepared by other staff; deal with incoming and outgoing mail; screen requests for meetings or appointments; and perform a variety of administrative support tasks. \nTheir tasks include: a) checking, formatting and transcribing correspondence, minutes and reports from dictation, electronic documents or written drafts to conform to office standards, using typewriter, personal computer or other word processing equipment; b) using various computer software packages, including spreadsheets, to provide administrative support; c) dealing with incoming or outgoing mail; d) scanning, recording and distributing mail, correspondence and documents; e) screening requests for meetings or appointments and helping to organize meetings; f) screening and recording leave and other staff-members' entitlements; g) organizing and supervising filing systems; and h) dealing with routine correspondence on their own initiative.\nExamples of the occupations classified here: Marketing secretary, Office secretary, Parish secretary, Sales secretary, Secretary, Typing secretary, Word processing secretary\nSome related occupations classified elsewhere: Administrative secretary - 3343, Executive assistant - 3343, Legal secretary - 3342, Medical secretary - 3344","version":"2022","source_id":671,"level":3,"normalized_name":"secretaries general"},{"code":"413","parent_code":"41","title":"KEYBOARD OPERATORS","description":"Keyboard operators input and process text and data; and prepare, edit and generate documents for storage, processing, publication and transmission. \nTasks performed usually include: entering data and codes required to process information; retrieving, confirming and updating data in storage and keeping records of data input; taking records of proceedings in rapid shorthand using computerized equipment and shorthand-writing machines; transcribing information recorded in shorthand and on sound recording equipment, and proofreading and correcting copy; and reproducing the spoken word, environmental sounds and song lyrics as captions for cinema and television programming.","version":"2022","source_id":673,"level":3,"normalized_name":"keyboard operators"},{"code":"421","parent_code":"42","title":"TELLERS, MONEY COLLECTORS AND RELATED CLERKS","description":"Tellers, money collectors and related clerks perform money-handling operations in establishments relating to banking, postal services, betting or gambling, pawning and debt-collecting. \nTasks performed usually include: dealing with clients of banks or post offices in connection with money operations or postal services; receiving and paying off bets on results of sporting events; conducting gambling games; lending money against articles deposited or other securities; and collecting debts and other payments.","version":"2022","source_id":677,"level":3,"normalized_name":"tellers money collectors and related clerks"},{"code":"422","parent_code":"42","title":"CLIENT INFORMATION WORKERS","description":"Client information workers provide or obtain information in person, by telephone or electronic means such as e-mail in connection with making travel arrangements; describing the products or services of an organization; registering and greeting guests and visitors; making appointments; connecting telephone calls; and collecting information from survey respondents or applicants for services. \nTasks performed usually include: preparing itineraries and making travel and hotel reservations for clients; greeting and receiving clients and visitors; registering accommodation guests; providing information concerning the goods, services or policies of an organization; making appointments; operating a telephone switchboard; and interviewing survey respondents and applicants for eligibility.","version":"2022","source_id":685,"level":3,"normalized_name":"client information workers"},{"code":"431","parent_code":"43","title":"NUMERICAL CLERKS","description":"Numerical clerks obtain, compile and compute accounting, bookkeeping, statistical, financial and other numerical data; and take charge of cash transactions incidental to business matters. \nTasks performed usually include: helping with accounting and bookkeeping records and computations; calculating unit production costs; calculating wages and in some cases, preparing wage pockets and paying wages; taking charge of cash transactions incidental to the business; obtaining, compiling and computing statistical or actuarial data; and performing clerical tasks relating to the financial transactions of an insurance establishment, bank or similar establishment.","version":"2022","source_id":688,"level":3,"normalized_name":"numerical clerks"},{"code":"432","parent_code":"43","title":"MATERIAL RECORDING AND TRANSPORT CLERKS","description":"Material recording and transport clerks keep records of goods produced, purchased, stocked, dispatched and of materials needed at specified production dates, or keep records of operational aspects and coordinate the timing of passenger and freight transport. \nTasks performed usually include: recording produced, stocked, ordered and dispatched goods; recording production materials received, put into stock or issued; computing quantities of the production materials required at specified dates; and helping with preparation and checking of production operation schedules; keeping records of operational aspects; and coordinating the timing of passenger and freight transport.","version":"2022","source_id":691,"level":3,"normalized_name":"material recording and transport clerks"},{"code":"441","parent_code":"44","title":"OTHER CLERICAL SUPPORT WORKERS","description":"Other clerical support workers perform clerical duties in newspapers, courts, libraries and post offices; file documents; prepare information for processing; maintain personnel records; check material for consistency with original source material; and write on behalf of illiterate persons.\nTasks performed by workers in this Minor Group usually include: recording information regarding acquisition, issue and return of library books; maintaining personnel records; classifying and filing various documents and other records; sorting, recording and delivering mail from post offices, as well as from or within an enterprise; coding; correcting proofs; performing a number of miscellaneous clerical duties; and writing on behalf of persons who are unable to read and write.","version":"2022","source_id":698,"level":3,"normalized_name":"other clerical support workers"},{"code":"511","parent_code":"51","title":"TRAVEL ATTENDANTS, CONDUCTORS AND GUIDES","description":"Travel attendants, conductors and guides provide various personal services in connection with travelling by aircraft, train, ship, bus or other vehicle; and escorting individuals and groups on travel tours, sightseeing visits and excursions. \nTasks performed usually include: ensuring the comfort and safety of passengers; serving food and refreshments; providing information and answering questions in connection with travel; collecting or issuing tickets on board public transport; and accompanying individuals or groups on sightseeing tours or excursions and describing points of interest.","version":"2022","source_id":701,"level":3,"normalized_name":"travel attendants conductors and guides"},{"code":"512","parent_code":"51","title":"COOKS","description":"Cooks plan, organize, prepare and cook meals in hotels, restaurants and other eating places, on board ships, on passenger trains and in private households.\nTheir tasks include: a) planning meals, preparing and cooking foodstuffs; b) planning, supervising and coordinating the work of kitchen helpers; c) checking the quality of food; d) weighing, measuring and mixing ingredients according to recipes and personal judgement; e) regulating the temperature of ovens, grills, roasters and other cooking equipment; inspecting and cleaning the kitchen, kitchen equipment, serving areas, etc. to ensure safe and sanitary food handling practices; and f) operating large-volume cooking equipment such as grills, deep-fat fryers, or griddles.\nExamples of the occupations classified here: Cook, Head cook, Preserving cook, Private service cook, Shipcook\nSome related occupations classified elsewhere: Cafe manager - 1412, Chef - 3434, Fastfood preparer - 9411, Restaurant manager - 1412","version":"2022","source_id":702,"level":3,"normalized_name":"cooks"},{"code":"513","parent_code":"51","title":"WAITERS AND BARTENDERS","description":"Waiters and bartenders serve food and beverages in commercial dining and drinking places, clubs, institutions and canteens, on board ships and on passenger trains.\nTasks performed usually include: assisting in keeping bar properly stocked; washing used glassware and cleaning bar area; serving alcoholic and non-alcoholic drinks at a bar; setting tables with clean linen, cutlery, crockery and glassware; serving food and beverages; advising on the choice of wines and serving them; taking orders for food and/or drinks and passing order to kitchen; presenting bill; and accepting payment.","version":"2022","source_id":704,"level":3,"normalized_name":"waiters and bartenders"},{"code":"514","parent_code":"51","title":"HAIRDRESSERS, BEAUTICIANS AND RELATED WORKERS","description":"Hairdressers, beauticians and related workers cut and dress hair; shave and trim beards; give beauty treatment; apply cosmetics and make-up; and give other kinds of treatment to individuals in order to improve their appearance.\nTheir tasks include: discussing customers’ requirements; cutting and dressing hair; shaving and trimming beards; giving beauty treatment, and applying cosmetics and make up; shaping and polishing finger and toe nails and treating minor ailments of the human foot; and attending clients taking bath and administering elementary massage.","version":"2022","source_id":706,"level":3,"normalized_name":"hairdressers beauticians and related workers"},{"code":"515","parent_code":"51","title":"BUILDING AND HOUSEKEEPING SUPERVISORS","description":"Building and housekeeping supervisors coordinate, schedule, and supervise the work of cleaners and other housekeeping staff in commercial, industrial and residential premises. They take responsibility for housekeeping and caretaking functions in hotels, offices, apartments, houses and private dwellings.\nTasks usually include: assigning tasks and inspecting building areas to see that cleaning, housekeeping and maintenance work has been done properly; issuing of supplies and equipment and inventory stocks to ensure that the supplies on hand are adequate; screening and hiring job applicants; training both new and experienced employees; recommending promotions, transfers or dismissals; and performing some cleaning, housekeeping and maintenance tasks.","version":"2022","source_id":709,"level":3,"normalized_name":"building and housekeeping supervisors"},{"code":"516","parent_code":"51","title":"OTHER PERSONAL SERVICES WORKERS","description":"Other personal services workers recount past and predict future events in persons’ lives; provide companionship and other personal services; groom, train and care for animals; provide embalming and funeral services; and train people to drive vehicles.\nTasks performed usually include: casting horoscopes; providing companionship or valet services and other personal services to clients; providing embalming and funeral services; feeding, handling, training and grooming animals; and instructing students under actual driving conditions.","version":"2022","source_id":715,"level":3,"normalized_name":"other personal services workers"},{"code":"521","parent_code":"52","title":"STREET AND MARKET SALESPERSONS","description":"Street and market salespersons sell goods from stalls on markets or in streets and prepare and sell hot or cold food and beverages ready for immediate consumption in streets and public places.\nTasks performed usually include: obtaining permission to set up a stand at a particular place in streets, markets or other open spaces or to sell food and drinks on the streets; buying or contracting a regular supply of products to be sold; erecting and dismantling stalls and stands; transporting, storing, loading and unloading products for sale; stacking, displaying and selling goods, food and drinks and accepting payment; wrapping and packing goods sold; preparing food and drinks for sale; pushing, pedaling or carrying hand-cart, truck, tray or basket to bring food and drinks to the desired place in the street, or to public places such as stations or cinemas; and keeping accounts and maintaining a record of stock levels.","version":"2022","source_id":717,"level":3,"normalized_name":"street and market salespersons"},{"code":"522","parent_code":"52","title":"SHOP SALESPERSONS","description":"Shop salespersons sell a range of goods and services directly to the public or on behalf of retail and wholesale establishments. They explain functions and qualities of these goods and services; and may operate small shops or supervise the activities of shop sales assistants and cashiers.\nTasks performed usually include: determining customer requirements and advising on product range, price, delivery, warranties and product use and care; demonstrating and explaining and selling goods and services to customers; accepting payment for by a variety of payment methods and preparing sales invoices; undertaking or assisting with the ongoing management of stock such as product inventories and participating in stock takes; tacking and displaying goods for sale, and wrapping and packing goods sold; determining product mix, stocks and price levels for goods to be sold; and supervising and coordinating the activities of shop sales assistants, checkout operators and other workers in supermarkets and department stores.","version":"2022","source_id":720,"level":3,"normalized_name":"shop salespersons"},{"code":"523","parent_code":"52","title":"CASHIERS AND TICKET CLERKS","description":"Cashiers and ticket clerks operate cash registers, optical price scanners, computers or other equipment to record and accept payment for the purchase of goods, services and admissions in settings such as stores, restaurants and ticket offices.\nTheir tasks include: a) receiving and verifying payment by cash, check, credit card or automatic debit in stores, ticket offices, or similar establishments; b) giving change and issuing receipts; c) issuing tickets for attendance at sporting and cultural events; d) counting and recording money received or paid out and balancing against cash register sales records; e) receiving incoming cash, checking it against sales slips and other documents, and preparing it for deposit at bank; f) operating cash register to calculate total to be paid from or to clients; g) scanning, weighing and recording prices of goods; and h) wrapping and placing merchandise in bags.\nExamples of the occupations classified here: Cash clerk, Cash register clerk, Cashier, Checkout operator, Service station cashier , Store cashier, Entertainment and sporting event ticket issuing clerk, Toll collector\nSome related occupations classified elsewhere: Checkout supervisor - 5222, Service station attendant - 5245, Shop sales assistant - 5223, Travel ticket issuing clerk - 4221","version":"2022","source_id":721,"level":3,"normalized_name":"cashiers and ticket clerks"},{"code":"524","parent_code":"52","title":"OTHER SALES WORKERS","description":"Other sales workers display, demonstrate, display and sell goods, food and services, usually to the general public, in context other than sales in markets, streets and shops. It includes sales workers not classified in Minor Groups 521. Street and Market Salespersons; 522. Shop Salespersons; and 523. Cashiers and Ticket Clerks.\nTasks performed may include: displaying and demonstrating items for sale; posing for photographs, film and video, advertising, still photography or for artistic creation; answering questions and offering advice on the use of goods and services; taking orders and making arrangements for payment, delivery and collection of goods or for provision of services; selling goods and services; and soliciting business by approaching potential customers by going from door-to-door or using the telephone or other electronic communications media; selling fuel, lubricants and other automotive products at service stations; and providing services such as fueling, cleaning, lubricating and performing minor repairs to motor vehicles.","version":"2022","source_id":729,"level":3,"normalized_name":"other sales workers"},{"code":"531","parent_code":"53","title":"CHILD CARE WORKERS AND TEACHERS' AIDES","description":"Child care workers and teachers' aides provide care and supervision for children in schools, residential homes and child care facilities.\nTasks performed usually include: assisting children individually to learn social skills; demonstrating, supervising and participating in activities that enhance the physical, social, emotional and intellectual development of children in schools and pre-schools; assisting in preparation of materials and equipment for children's education and recreational activities before-school, after-school, during vacation and in day care centers.","version":"2022","source_id":731,"level":3,"normalized_name":"child care workers and teachers aides"},{"code":"532","parent_code":"53","title":"PERSONAL CARE WORKERS IN HEALTH SERVICES","description":"Personal care workers in health services provide personal care and assistance with mobility and activities of daily living to patients, and elderly, convalescent and disabled people in health care and residential settings.\nTasks performed usually include: assisting patients with mobility, personal care and communication needs; sterilizing surgical and other instruments and equipment; observing and reporting concerns to the appropriate medical or social service workers, preparing patients for examination and treatment; and participating in planning the care of individuals.","version":"2022","source_id":734,"level":3,"normalized_name":"personal care workers in health services"},{"code":"541","parent_code":"54","title":"PROCTECTIVE SERVICES WORKERS","description":"Protective services workers protect individuals and property against fire and other hazards; maintain law and order; and enforce laws and regulations.\nTasks performed usually include: preventing, fighting and extinguishing fires; rescuing people from burning buildings and accident sites and those trapped in dangerous situations; maintaining law and order, enforcing laws and regulations, patrolling public areas and arresting suspected offenders; directing traffic and assuming authority in the event of accidents; watching over and maintaining order among inmates of prisons, reformatories or penitentiaries; patrolling or monitoring premises to guard property against theft and vandalism, controlling access to establishments and maintaining order and enforcing regulations at public events and within establishments. Supervision of other workers may be included.","version":"2022","source_id":739,"level":3,"normalized_name":"proctective services workers"},{"code":"611","parent_code":"61","title":"MARKET GARDENERS AND CROP GROWERS","description":"Market gardeners and crop growers plan, organize and perform operations to grow and harvest field crops, to grow fruit and other tree and shrub crops, to grow garden vegetables and medicinal and other plants, and to produce horticultural and horticultural nurseries products, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTasks performed usually include: monitoring market activity and conditions, determining types and quantities of crops to be grown, and planning and coordinating production accordingly; purchasing seeds, bulbs and fertilizer; investing in land and land improvements; preparing land, sowing, planting, cultivating and harvesting various crops; tending working animals and maintaining farm buildings, machinery and equipment; producing saplings, bulbs and seeds; storing and carrying out some processing of produce; delivering or marketing farm products. Supervision of other workers may be included.","version":"2022","source_id":748,"level":3,"normalized_name":"market gardeners and crop growers"},{"code":"612","parent_code":"61","title":"ANIMAL PRODUCERS","description":"Animal producers plan, organize and perform farming operations to breed and raise domesticated animals, poultry, insects and non-domesticated animals for the production of meat, dairy products, honey, skins, textiles and other products or for use as working, sporting or recreational animals, for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTask performed usually include: monitoring market activity and conditions, determining kinds and amounts of products to produce, planning and coordinating production accordingly; raising, feeding and tending animals; preparing animals or animal products for market; monitoring and examining animals to detect illness, injury, or disease, and to check physical condition such as rate of weight gain; performing duties related to animal reproduction, such as breeding, artificial insemination, and helping with animal births; renting or investing in and maintaining and cleaning buildings, machinery, equipment, and structures; storing and carrying out some processing of produce; promoting and marketing products, arranging the sale, purchase and transportation of stock, produce and supplies and maintaining and evaluating records of activities and transactions; training and supervising workers in animal care procedures, maintenance duties, and health and safety precautions and hiring and discharging workers and contractors.","version":"2022","source_id":757,"level":3,"normalized_name":"animal producers"},{"code":"613","parent_code":"61","title":"MIXED CROP AND ANIMAL PRODUCERS","description":"Mixed crop and animal producers plan, organize and perform farming operations to grow and harvest field, tree and various other crops, as well as to breed, raise and tend animals and to produce a variety of animal husbandry products, for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) monitoring market activity and conditions, determining kinds and amounts of crops to be grown and animals to be raised, and planning and coordinating production accordingly; b) purchasing seeds, fertilizer, and other supplies; c) performing operations such as land preparation, sowing, planting, cultivating and harvesting crops; d) producing or buying fodder and other food supplies; e) breeding, raising and tending animals; f) killing and skinning animals, and preparing animals or animal products for market; g) renting or investing in and maintaining and cleaning farm buildings, machinery, equipment, and structures; h) storing and carrying out some processing of produce; i) promoting and marketing products, arranging the sale, purchase and transportation of livestock, produce and supplies and maintaining and evaluating records of farm activities and transactions; andj) training and supervising workers in animal care procedures, maintenance duties, and health and safety precautions and hiring and discharging workers and contractors.\nExamples of the occupations classified here: Farmer (mixed farming), Skilled farm worker (mixed farming)\nSome related occupations classified elsewhere: Agricultural production manager – 1311, Mixed farming laborer - 9213, Plantation manager - 1311","version":"2022","source_id":758,"level":3,"normalized_name":"mixed crop and animal producers"},{"code":"621","parent_code":"62","title":"FORESTRY AND RELATED WORKERS","description":"Forestry and related workers plan, organize and perform operations to cultivate, conserve and exploit natural and plantation forests.\nTasks usually include: assessing sites for reforestation, selecting seedlings and planting trees using manual planting tools and establishing and caring for forest stands; young forest stands, trim, top and fell trees and saw them into logs; shaping rough wooden products from logs at felling site; stacking logs and loading them in chutes or floating them down rivers; keeping watch to detect forest fires, participating in fire fighting operations complete fire fighting reports and maintaining fire fighting equipment; controlling weeds and undergrowth in regenerating forest stands using manual tools and chemicals; operating and maintaining a skidder, bulldozer or other prime mover to pull a variety of scarification or site preparation equipment over areas to be regenerated; collecting seed cones, pruning trees, assisting in planting surveys and marking trees for subsequent operations; training and supervising other workers in forestry procedures, including forestry laborers and plant operators.","version":"2022","source_id":762,"level":3,"normalized_name":"forestry and related workers"},{"code":"622","parent_code":"62","title":"FISHERY WORKERS, HUNTERS AND TRAPPERS","description":"Fishery workers, hunters and trappers breed and raise fish, harvest and catch fish and hunt and trap animals, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTasks usually include: breeding, raising and cultivating fish, mussels, oysters and other forms of aquatic life as cash crops or for release into freshwater or saltwater; monitoring environments to ensure maintenance of optimum conditions for aquatic life; cleaning, freezing, icing or salting catch on- or offshore and preparing fish and other products for shipment; renting or investing in and maintaining buildings, tanks, machinery, fishing vessels and other equipment; preparing and repairing nets and other fishing gear and equipment; operating fishing vessels to, from and at fishing grounds; baiting, setting, operating and hauling in fishing gear; setting traps to catch mammals, birds or reptiles; delivering or marketing products; supervising and training other workers.","version":"2022","source_id":771,"level":3,"normalized_name":"fishery workers hunters and trappers"},{"code":"631","parent_code":"63","title":"SUBSISTENCE CROP FARMERS","description":"Subsistence crop farmers grow and harvest field or tree and shrub crops, vegetables and fruit, in order to provide food, shelter and a minimum of cash income for themselves and their households.\nTheir tasks include: a) preparing the soil, sowing, planting, tending and harvesting field crops; b) growing vegetables, fruit and other tree and shrub crops; c) fetching water and gathering firewood; d) storing for later use and carrying out some processing of produce; e) building and maintaining makeshift houses and other shelters for own use; f) making tools, clothes and utensils for use by the household; and g) selling or bartering some products at local markets.\nExample of the occupations classified elsewhere: Subsistence crop farmer, Subsistence gardener, Subsistence vegetable grower\nSome related occupations classified elsewhere: Crop farm laborer - 9211, Firewood collector- 9624, Water collector- 9624","version":"2022","source_id":772,"level":3,"normalized_name":"subsistence crop farmers"},{"code":"632","parent_code":"63","title":"SUBSISTENCE LIVESTOCK FARMERS","description":"Subsistence livestock farmers breed, raise and tend livestock in order to provide food, shelter and a minimum of cash income for themselves and their households.\nTheir tasks include: a) cultivating pastures, or managing grazing lands, and monitoring feed and water supplies needed to maintain condition of livestock; b) monitoring and examining animals to detect illness, injury, or disease, and to check physical condition; c) grooming and marking animals and shearing coats to collect hair or wool; d) herding or leading livestock to pastures, grazing land and water supplies; e) raising, tending, feeding and milking animals or draining blood from them; f) breeding animals and helping with animal births; g) slaughtering and skinning animals and preparing them and their products for consumption or sale; h) carrying out some processing of animal products; i) building and maintaining makeshift houses and other shelters for own use; j) making tools, clothes and utensils for use by the household; k) fetching water and gathering firewood; and l) buying, bartering and selling animals and some products.\nExample of occupation classified here: Subsistence cattle farmer\nSome related occupations classified elsewhere: Livestock farm laborer - 9212, Mixed crop and livestock farm laborers - 9213, Water and firewood collector - 9624","version":"2022","source_id":773,"level":3,"normalized_name":"subsistence livestock farmers"},{"code":"633","parent_code":"63","title":"SUBSISTENCE MIXED CROP AND LIVESTOCK FARMERS","description":"Subsistence mixed crop and livestock farmers grow and harvest field or tree and shrub crops, vegetables and fruit, gather wild fruits, medicinal and other plants, tend or hunt animals, and/or catch fish and gather various forms of aquatic life in order to provide food, shelter and a minimum of cash income for themselves and their households.\nTheir tasks include: a) preparing the soil, sowing, planting, tending and harvesting field crops; b) growing vegetables, fruit and other tree and shrub crops; c) gathering wild fruits, medicinal and other plants; d) breeding, tending and feeding animals and poultry mainly to obtain meat, eggs, milk, hair, skin or other products; e) fetching water and gathering firewood; f) storing produce for later use and carrying out some processing of produce; g) building and maintaining makeshift houses and other shelters for own use; h) making tools, clothes and utensils for use by the household; i) selling or bartering some products at local markets.\nExample of occupation classified here: Mixed subsistence farmer","version":"2022","source_id":774,"level":3,"normalized_name":"subsistence mixed crop and livestock farmers"},{"code":"634","parent_code":"63","title":"SUBSISTENCE FISHERS, HUNTERS, TRAPPERS AND GATHERERS","description":"Subsistence fishers, hunters, trappers and gatherers gather wild fruits medicinal and other plants; hunt and trap animals; and catch fish and gather various forms of aquatic life in order to provide food, shelter, and a minimum of cash income for themselves and their households.\nTheir tasks include: a) gathering wild fruits, roots, medicinal and other plants; b) hunting or trapping animals mainly to obtain meat, milk, hair, skin or other products; c) fetching water and gathering firewood; d) catching fish and gathering other forms of aquatic life; e) storing or carrying out some processing of their produce; f) building and maintaining houses and other shelters; g) making tools, clothes and utensils for use by the household; and h) selling or bartering some products at local markets.\nExamples of the occupations classified here: Subsistence collector, Subsistence diver, Subsistence fisher, Subsistence gatherer\nSome related occupations classified elsewhere: Livestock farm laborer – 9212, Subsistence crop farmer - 6310, Subsistence livestock farmer - 6320, Water and firewood collector – 9624","version":"2022","source_id":775,"level":3,"normalized_name":"subsistence fishers hunters trappers and gatherers"},{"code":"711","parent_code":"71","title":"BUILDING FRAME AND RELATED TRADES WORKERS","description":"Building frame and related trades workers construct, maintain and repair buildings, erect and repair foundations, walls and structures of brick, stone and similar materials, shape and finish stone for building and other purposes, and perform miscellaneous construction and building maintenance tasks.\nTasks performed by workers in this minor group include: constructing, maintaining and repairing buildings and other structures by using traditional and/or modern building techniques; constructing and repairing foundations, walls and structures of brick, stone and similar materials; breaking quarried stone into slabs or blocks; cutting, shaping and finishing stone for building, ornamental, monumental and other purposes; erecting reinforced concrete frameworks and structures as well as finishing and repairing cement surfaces; cutting, shaping, assembling and maintaining wooden structures and fittings; and performing miscellaneous construction and building maintenance tasks. Supervision of other workers may be included.","version":"2022","source_id":781,"level":3,"normalized_name":"building frame and related trades workers"},{"code":"712","parent_code":"71","title":"BUILDING FINISHERS AND RELATED TRADES WORKERS","description":"Building finishers and related trades workers cover, apply or install, maintain and repair roofs, floors, walls, insulation systems, glass in windows or other frames, as well as plumbing, piping and electrical systems in buildings and other structures.\nTasks performed usually include: covering roof frameworks with one or more kinds of material; installing parquet and other kinds of flooring or covering floors and walls with tiles or mosaic panels; applying plaster to walls and ceilings; applying insulating material to walls, floors and ceilings; cutting, fitting and setting glass in windows and similar openings; and installing plumbing and pipeline systems; installing electrical wiring and related equipment. Supervision of other workers may be included.","version":"2022","source_id":788,"level":3,"normalized_name":"building finishers and related trades workers"},{"code":"713","parent_code":"71","title":"PAINTERS, BUILDING STRUCTURE CLEANERS AND RELATED TRADES WORKERS","description":"Painters, building structure cleaners and related trades workers prepare surfaces and apply paint and similar materials to buildings and other structures, vehicles or various manufactured articles. They cover interior walls and ceilings with wallpaper, clean chimneys and exterior surfaces of buildings and other structures.\nTasks performed usually include: preparing surfaces and applying paint and similar materials to buildings and other structures; applying paint or varnish to vehicles or various manufactured articles, usually with a hand-spraying device; covering interior walls and ceilings with wallpaper, silk or other fabrics; cleaning chimneys; and cleaning exterior surfaces of buildings and other structures. Supervision of other workers may be included.","version":"2022","source_id":791,"level":3,"normalized_name":"painters building structure cleaners and related trades workers"},{"code":"721","parent_code":"72","title":"SHEET AND STRUCTURAL METAL WORKERS, MOLDERS AND WELDERS, AND RELATED WORKERS","description":"Sheet and structural metal workers, molders and welders, and related workers, make molds and cores for casting metal, weld and cut metal parts, make and repair articles of sheet metal, and install, erect, maintain and repair heavy metal structures, tackle, cable-cars and related equipment.\nTasks performed usually include: making molds and cores for casting metal; casting, welding and shaping metal parts; making and repairing articles of sheet metal such as sheet steel, copper, tin, or brass; and installing, erecting, maintaining and repairing heavy metal structures, as well as tackle, cable cars and related equipment.","version":"2022","source_id":796,"level":3,"normalized_name":"sheet and structural metal workers molders and welders and related workers"},{"code":"722","parent_code":"72","title":"BLACKSMITHS, TOOLMAKERS AND RELATED TRADES WORKERS","description":"Blacksmiths, toolmakers and related trades workers, hammer and forge bars, rods or ingots of iron, steel and other metals to make and repair various kinds of tools, equipment and other articles, set machine tools for operators or set and operate various machine tools, and polish and sharpen surfaces.\nTasks performed usually include: hammering and forging iron, steel and other metals to make and repair various kinds of tools, equipment and other articles; setting machine tools for operators or setting and operating various machine tools working to fine tolerances; and polishing and sharpening metal surfaces and tools.","version":"2022","source_id":800,"level":3,"normalized_name":"blacksmiths toolmakers and related trades workers"},{"code":"723","parent_code":"72","title":"MACHINERY MECHANICS AND REPAIRERS","description":"Machinery mechanics and repairers fit, install, maintain and repair engines, vehicles, agricultural or industrial machinery and similar mechanical equipment.\nTasks performed usually include: fitting, installing, maintaining and repairing engines, vehicles, agricultural or industrial machinery and similar mechanical equipment.","version":"2022","source_id":804,"level":3,"normalized_name":"machinery mechanics and repairers"},{"code":"731","parent_code":"73","title":"HANDICRAFT WORKERS","description":"Handicraft workers combine artistic and manual skills to design, make, repair, adjust, maintain and decorate precision instruments, musical instruments, jewelry and other precious-metals, pottery and porcelain ware. They apply traditional and/or recently developed techniques to carve, mold, assemble, weave and decorate various glass, ceramics, textile, straw, stone, wood and leather articles.\nTasks performed usually include: making, calibrating, repairing, maintaining and installing musical and precision instruments; fabricating, adjusting, repairing, or appraising jewelry, ceremonial or religious items, gold, silver, other precious metals, or gems; cutting, filing, polishing and setting precious and semiprecious stones including gems and diamonds and engraving designs on jewelry and precious metal articles; preparing pottery, porcelain ware, sanitary ware, bricks, tiles and abrasive wheels by hand or by machine; blowing, molding, pressing, cutting, trimming, grinding and polishing glass, shaping molten glass according to patterns; decorating articles made of wood, metal, textiles, glass, ceramics and other materials, and planning, laying out and painting letters, figures, monograms and designs to make signs; applying traditional techniques like seasoning, impregnation to prepare wood, straw, rattan, reeds, stone, clay, shells, and other materials, and carving, molding, assembling, weaving, or painting and decorating various articles for personal or household use, or for decorative purposes; preparing materials to make wicker furniture, brushes and brooms and weaving various kinds of baskets; and applying traditional techniques and patterns to produce woven fabrics, knitted, embroidered and other garments and household articles.","version":"2022","source_id":813,"level":3,"normalized_name":"handicraft workers"},{"code":"732","parent_code":"73","title":"PRINTING TRADES WORKERS","description":"Printing trades’ workers compose and set type prior to printing, set up and operate printing presses, bind and finish printed products, and prepare stencils and operate screen printing equipment.\nTasks performed usually include: operating graphic cameras and other photographic equipment to reproduce camera-ready copy onto films, plates and digital output devices; operating computer screen-based equipment for scanning, color separation and correction, retouching and other processes used to transfer copy to film and produce film for plate, cylinder and digital output productions; setting up, operating and monitoring machines used in typesetting, photographing copy, printing and cutting, folding, collating and binding printed material; performing routine finishing operations and machine maintenance; and preparing stencils and operating screen printing equipment.","version":"2022","source_id":816,"level":3,"normalized_name":"printing trades workers"},{"code":"741","parent_code":"74","title":"ELECTRICAL EQUIPMENT INSTALLERS AND REPAIRERS","description":"Electrical equipment installers and repairers install, fit and maintain electrical wiring systems and related equipment, electrical machinery and other electrical apparatus and electrical transmission and supply lines and cables.\nTasks performed usually include: installing, maintaining, fitting and adjusting electrical wiring systems, machinery and equipment; examining blueprints, wiring diagrams and specifications to determine sequences and methods of operation; inspecting and testing electrical systems, equipment, cables and machinery to identify hazards, defects, and the need for adjustment or repair; and installing maintaining and repairing electrical transmission lines; joining electrical cables.","version":"2022","source_id":820,"level":3,"normalized_name":"electrical equipment installers and repairers"},{"code":"742","parent_code":"74","title":"ELECTRONICS AND TELECOMMUNICATIONS INSTALLERS AND REPAIRERS","description":"Electronics and telecommunications installers and repairers fit, maintain, adjust and repair electronic equipment such as commercial and office machines and electronic instruments and control systems and install, repair and maintain telecommunications equipment, data transmission equipment, cables, antennae and repair, fit and maintain computers.\nTasks performed usually include: examining and testing machines, equipment, instruments and control systems to diagnose faults; adjusting, repairing, and replacing worn and defective parts and wiring, and maintaining machines, equipment and instruments; installing electronic instruments and control systems; fitting and adjusting electronic equipment; maintaining, troubleshooting, fitting, adjusting, testing and repairing computers, data transmission equipment and computer peripherals; installing, maintaining, repairing, and diagnosing malfunctions of microwave, telemetry, multiplexing, satellite and other radio and electromagnetic wave communications systems; providing technical advice and information, and monitoring the performance of complex telecommunications networks and equipment; installing, joining and repairing cabling for computer, radio, telephone and television transmission; and installing, maintaining and repairing antennae used in communications.","version":"2022","source_id":822,"level":3,"normalized_name":"electronics and telecommunications installers and repairers"},{"code":"751","parent_code":"75","title":"FOOD PROCESSING AND RELATED TRADES WORKERS","description":"Food processing and related trades workers slaughter animals, treat and prepare them and related food items for human and animal consumptions, make various kinds of bread, cakes and other flour products, process and preserve fruit, vegetables and related foods, taste and grade various food products and beverages, or prepare tobacco and make tobacco products. \nTasks performed usually include: slaughtering animals; treating meat and fish and preparing them and related food items; making various kinds of bread, cakes and other flour products; processing and preserving fruit, vegetables and related foods; tasting and grading various food products and beverages; and preparing tobacco and making tobacco products. Supervision of workers may be included.","version":"2022","source_id":828,"level":3,"normalized_name":"food processing and related trades workers"},{"code":"752","parent_code":"75","title":"WOOD TREATERS, CABINET-MAKERS AND RELATED TRADES WORKERS","description":"Wood treaters, cabinet-makers and related trades workers preserve and treat wood; produce waferboards, particleboards, hardboards, insulation boards, plywood, veneers and similar wood products; and make, decorate and repair wooden furniture, vehicles and other wooden products. They use specialized hand tools and set-up, operate and tend wood processing and woodworking equipment, machines and machine tools.\nTasks performed usually include: operating and tending treating and other equipment to dry lumber and other wood products, and to treat chemically and impregnate wood products with preservatives; operating woodworking machines to cut, shape and form parts and components; studying plans, verifying dimensions of articles to be made, fitting parts together to form complete units and checking the quality and fit of pieces to ensure adherence to specifications; setting and adjusting various kinds of machines for operation by others; setting-up, programming, operating and monitoring several types of woodworking machines to fabricate, repair or refinish wooden parts for furniture, fixtures and other wood products; and reading and interpreting specifications or following verbal instructions.","version":"2022","source_id":831,"level":3,"normalized_name":"wood treaters cabinet-makers and related trades workers"},{"code":"753","parent_code":"75","title":"GARMENT AND RELATED TRADES WORKERS","description":"Garment and related trades workers fit, alter and repair tailored clothing; design, and make textile and fur garments, leather or fur products; repair, renovate and decorate garments, gloves and other products of textile; create patterns for garments; install, repair and replace upholstery of furniture, fixtures, orthopedic appliances and furnishings of automobiles; trim, scrape, tan, buff and dye animal hides, pelts or skins; modify and repair footwear and leather articles.\nTasks performed usually include: fitting, altering, repairing tailored clothing; designing and making made-to-measure clothing, from textile fabrics, light leather and other material, or make hats or wigs; make garment style changes; creating precision master patterns for production of garments, other textile, and leather or fur products; sewing together, joining, darning, repairing, renovating and decorating garments, gloves and other products of textile, fur, light leather and other materials and fabricating and assembling sails, awnings and tarpaulins; installing, repairing and replacing upholstery of furniture, fixtures, orthopedic appliances; seats, panels, and other furnishings of automobiles, railway coaches, aircraft, ships and similar items; trimming, scraping, cleaning, tanning, buffing and dying animal hides, pelts or skins to produce leather stock and finished furs for making garments and other products; and making, modifying and repairing standard, custom or orthopedic footwear and natural or synthetic leather articles.","version":"2022","source_id":837,"level":3,"normalized_name":"garment and related trades workers"},{"code":"754","parent_code":"75","title":"OTHER CRAFT AND RELATED WORKERS","description":"Other craft and related workers work under the surface of water, using underwater breathing apparatus; position, assemble, and detonate explosives; inspect and test, raw materials, manufactured components and products; remove unwanted organisms to prevent damage to crops and buildings and other structures. This group includes other trade and craft occupations not classified elsewhere in major group 7, Craft and related trades workers.\nTasks performed usually include: ensuring safety precautions; performing various underwater tasks, loading explosives into blast holes; mixing chemicals according to instructions; and operating and monitoring equipment for spraying pests and weeds.","version":"2022","source_id":842,"level":3,"normalized_name":"other craft and related workers"},{"code":"811","parent_code":"81","title":"MINING AND MINERAL PROCESSING PLANT OPERATORS","description":"Mining and mineral processing plant operators operate and monitor plant and machinery which extract rock and minerals from the earth, process minerals and stone, drill wells and bores, and manufacture and finish cement and stone products.\nTasks performed usually include: setting up, operating and monitoring a variety of mining and mineral processing plant and machinery such as drilling rigs and auxiliary machines and equipment, continuous mining machinery, and cutting, crushing, grinding, pumping and mixing plant and machinery; operating washing, separating, extracting and combining equipment to remove waste and recover minerals; operating plant and machinery to make cement, concrete, artificial stone, and precast concrete and stone products; monitoring the performance of a variety of plant and machinery, detecting malfunctions and taking corrective action; performing plant and machinery maintenance, repairs and cleaning; and maintaining production records.","version":"2022","source_id":846,"level":3,"normalized_name":"mining and mineral processing plant operators"},{"code":"812","parent_code":"81","title":"METAL PROCESSING AND FINISHING PLANT OPERATORS","description":"Metal processing and finishing plant operators, operate and monitor single function process control machinery and equipment to control the conversion, processing and finishing of mineral ores and metals.\nTasks performed usually include: setting up, preparing and adjusting metal and ore processing and finishing machinery; coordinating and monitoring the operation of a particular aspect of metal processing production and finishing; verifying equipment for malfunctions, monitoring gauges, carrying out routine operating tests and arranging for maintenance; checking, testing and analyzing sample products; recording data and writing production logs.","version":"2022","source_id":848,"level":3,"normalized_name":"metal processing and finishing plant operators"},{"code":"813","parent_code":"81","title":"CHEMICAL AND PHOTOGRAPHIC PRODUCTS PLANT AND MACHINE OPERATORS","description":"Chemical and photographic products plant and machine operators operate and monitor machines which process a variety of chemicals and other ingredients to produce pharmaceuticals, toiletries, explosives and photographic or other chemical products.\nTasks performed usually include: operating and monitoring machines and equipment which blend, mix, package and otherwise process chemicals and chemical products to give them the desired properties for further industrial production, or to make finished products. Supervision of other workers may be included.","version":"2022","source_id":850,"level":3,"normalized_name":"chemical and photographic products plant and machine operators"},{"code":"814","parent_code":"81","title":"RUBBER, PLASTIC AND PAPER PRODUCTS MACHINE OPERATORS","description":"Rubber, plastic and paper products machine operators operate and monitor machines which knead and blend rubber and rubber compounds, and plastics or produce different paper products from paper, paperboard, cardboard and similar materials.\nTasks performed usually include: operating and monitoring machines which knead and blend rubber and rubber compounds, and produce various components and products from natural and synthetic rubber and plastics; operating and monitoring machines which produce various paper products; examining outputs for defects and conformity to specifications and adjusting machine settings accordingly.","version":"2022","source_id":853,"level":3,"normalized_name":"rubber plastic and paper products machine operators"},{"code":"815","parent_code":"81","title":"TEXTILE, FUR AND LEATHER PRODUCTS MACHINE OPERATORS","description":"Textile, fur and leather products machine operators operate and monitor various types of machines which prepare, process and treat fibers, yarn, thread, leather, fur; produce, modify and repair footwear, garments and manufacture or dry clean textiles or fur and light leather articles.\nTasks include operating and monitoring weaving and knitting machines which process yarn or thread into woven, non-woven and knitted products; operating and monitoring machines which prepare fibers, and spin, double, twist and wind yarn and thread from natural textile fibers; operating and monitoring sewing machines to make, repair, darn and renovate textile, fur, synthetic or leather garments or embroider ornamental designs on garments or other materials; operating and monitoring machines which bleach, shrink, dye, and otherwise treat fibers, yarn, cloth or dry clean garments, fur, rugs, carpets; operating and monitoring various machines which prepare leather or treat fur or wool-bearing pelts; operating and monitoring machines which produce, modify and repair standard, custom or orthopedic footwear and leather articles, such as luggage, brief cases, handbags.","version":"2022","source_id":861,"level":3,"normalized_name":"textile fur and leather products machine operators"},{"code":"816","parent_code":"81","title":"FOOD AND RELATED PRODUCTS MACHINE OPERATORS","description":"Food and related machine operators set, operate and attend machinery used to slaughter animals, trim meat from carcasses; bake, freeze, heat, crush, mix, blend and otherwise process foodstuffs, beverages and tobacco leaves.\nTheir tasks include: a) operating and monitoring machinery used to restrain, stun, slaughter animals and trim carcasses into standard meat and fish cuts; b) setting, operating and attending machinery and ovens to mix, bake and otherwise prepare bread and flour confectionery products; c) operating machinery to crush, mix, malt, cook and ferment grains and fruits to produce beer, wines, malt liquors, vinegar, yeast and related products; d) attending equipment to make jam, toffee, cheese, processed cheese, margarine, syrup, ice, pasta, ice-cream, sausages, chocolate, maize starch, edible fats and dextrin; e) operating equipment to cool, heat, dry, roast, blanch, pasteurize, smoke, sterilize, freeze, evaporate and concentrate foodstuffs and liquids used in food processing; f) mixing, pulping, grinding, blending and separating foodstuffs and liquids with churning, pressing, sieving, grinding and filtering equipment; and g) processing tobacco leaves by machine to make cigarettes, cigars, pipe and other tobacco products.\nExamples of the occupations classified here: Bakery products machine operator, Bread production machine operator, Chocolate production machine operator, Cigar production machine operator, Cigarettes production machine operator, Dairy products machine operator, Fish processing machine operator, Meat processing machine operator, Milk processing machine operator, Noodle production machine operator, Sugarcane processing machine operator, Tobacco processing machine operator\nRelated occupation classified elsewhere: Bottling machine operator - 8183","version":"2022","source_id":862,"level":3,"normalized_name":"food and related products machine operators"},{"code":"817","parent_code":"81","title":"WOOD PROCESSING AND PAPERMAKING PLANT OPERATORS","description":"Wood processing and papermaking plant operators monitor, operate, and control automated lumber mill equipment sawing wood, cutting veneer and making plywood, and otherwise preparing wood for further use. Pulp mill machine operators operate and monitor various types of processing machinery and equipment to produce pulp.\nTheir tasks include: a) examining logs and rough lumber to determine size, condition, quality and other characteristics to decide best lumber cuts to carry out, or operating automated equipment to convey logs through laser scanners which determine the most productive and profitable cutting patterns; b) sorting, stacking and placing logs and wood billets onto conveyors and lathes from trucks for processing into chips, veneers and pulp; c) operating and monitoring screening equipment, bleaching equipment, digesters, mixing tanks, washers, and other pulp processing machinery and equipment to carry out one or more cellulose processing steps; d) observing equipment and machinery panel indicators, gauges, level indicators and other equipment instruments to detect machinery and equipment malfunctions and ensure process steps are carried out according to specifications; e) operating and monitoring plywood core-laying machines and hot-plate plywood presses and machines which cut veneer; and f) transporting processed wood products, such as plywood, chipboard sheets and panels to work areas.","version":"2022","source_id":864,"level":3,"normalized_name":"wood processing and papermaking plant operators"},{"code":"818","parent_code":"81","title":"OTHER STATIONARY PLANT AND MACHINE OPERATORS","description":"This unit group includes stationary plant and machine operators not classified elsewhere in sub-major group 81, Stationary plant and machine operators. The group includes, for instance, operators of machines which make silicon chips and splice cables and ropes.\nTask performed usually include: monitoring kilns, furnaces and other machinery and equipment used in the manufacture of glass, ceramics, porcelain, tiles or bricks; operating machines to anneal, harden or decorate glass and ceramics; maintaining and operating stationary steam engines, boilers, turbines and auxiliary equipment; operating and monitoring machines which weigh, pack and label products, or fill containers with products;","version":"2022","source_id":868,"level":3,"normalized_name":"other stationary plant and machine operators"},{"code":"821","parent_code":"82","title":"ASSEMBLERS","description":"Assemblers assemble prefabricated parts or components to form subassemblies, products and equipment, according to strictly laid down procedures. The products worked on may be moved from one worker to the next along assembly lines.\nTasks performed usually include: assembling components into various types of products and equipment, according to strictly laid down procedures; reviewing work orders, specifications, diagrams and drawings to determine materials needed and assembly instructions; recording production and operational data on specified forms; inspecting and testing completed components and assemblies, wiring installations and circuits; rejecting faulty assemblies and components.","version":"2022","source_id":871,"level":3,"normalized_name":"assemblers"},{"code":"831","parent_code":"83","title":"LOCOMOTIVE ENGINE DRIVERS AND RELATED WORKERS","description":"Locomotive engine drivers and related workers drive, or assist in driving, locomotive engines to transport passengers and freight, take charge of and safeguard railway freight trains during runs, control the movement of railway traffic by operating signals, switch rolling stock and make up trains in railway yards, make up trains for hauling in mines and control their movement.\nTasks performed usually include driving or assisting in driving railway engines, operating railway signals, switching rolling stock and making up trains in railway yards, making up trains in mines and controlling their movement.","version":"2022","source_id":873,"level":3,"normalized_name":"locomotive engine drivers and related workers"},{"code":"832","parent_code":"83","title":"CAR, VAN AND MOTORCYCLE DRIVERS","description":"Car, van and motorcycle drivers drive and tend motor cycles, motorized tricycles, cars or vans to transport passengers, materials or goods.\nTasks performed usually include: driving and tending motor cycles, motorized tricycles, cars or vans in order to transport materials, goods or passengers.","version":"2022","source_id":879,"level":3,"normalized_name":"car van and motorcycle drivers"},{"code":"833","parent_code":"83","title":"HEAVY TRUCK AND BUS DRIVERS","description":"Heavy truck and bus drivers drive and tend heavy trucks, lorries, buses or street tramcars to transport goods, liquids, heavy materials, mail or passengers.\nTasks performed usually include: driving and tending heavy trucks, lorries, buses or street tramcars in order to transport goods, liquids, heavy materials, mail or passengers.","version":"2022","source_id":881,"level":3,"normalized_name":"heavy truck and bus drivers"},{"code":"834","parent_code":"83","title":"MOBILE PLANT OPERATORS","description":"Mobile plant operators drive, tend, operate and monitor special -purpose motorized, machinery or equipment used for clearing or preparing land; digging, moving, and spreading earth, rock and similar materials; and lifting or moving heavy objects.\nTasks performed usually include: preparing and positioning plant for operation; adjusting speed, height and depth of implements; driving and operating mobile plant; operating attachments to lift, swing and release trees, logs, earth and other heavy objects or materials; operating and monitoring lifting trucks and stationary or mobile cranes in construction, transportation and storage operations; servicing machinery and performing minor repairs.","version":"2022","source_id":885,"level":3,"normalized_name":"mobile plant operators"},{"code":"835","parent_code":"83","title":"SHIPS' DECK CREWS AND RELATED WORKERS","description":"Ship’s deck crews and related workers carry out deck duties on board ship and similar duties on board other water-borne craft.\nTheir tasks include: a) standing look-out watches at sea and when entering or leaving harbor or other narrow waters; b) steering ship according to instructions; c) handling ropes and wires, and operates mooring equipment; d) maintaining and, in some cases, operating ship’s equipment, cargo gear, rigging, life-saving and firefighting appliances; e) performing deck and hull cleaning, scraping, painting and other maintenance duties as required; and f) breaking out, rigging and stowing cargo-handling gear, stationary rigging and running gear.\nExamples of the occupations classified here: Bargeman, Boatman, Boatswain Deck cadet, Ferry hand, Lifeboat coxswain, Reefer repairman\nSailor, Seaman, Tug hand, Yacht crew","version":"2022","source_id":886,"level":3,"normalized_name":"ships deck crews and related workers"},{"code":"911","parent_code":"91","title":"DOMESTIC, HOTEL AND OFFICE CLEANERS AND HELPERS","description":"Domestic, hotel and office cleaners and helpers sweep, vacuum clean, wash, polish, take care of household linen, purchase household supplies; perform various tasks in order to keep clean and tidy the interiors and fixtures of hotels, offices and other establishments, as well as of aircraft, trains, buses and similar vehicles.\nTasks performed usually include: sweeping or vacuum cleaning, washing and polishing floors, furniture and other objects in hotels, offices and other establishments; making beds, supplying towels, soap and related items; helping with preparation of meals and washing dishes; cleaning, disinfecting and deodorizing kitchens, bathrooms and toilets.","version":"2022","source_id":888,"level":3,"normalized_name":"domestic hotel and office cleaners and helpers"},{"code":"912","parent_code":"91","title":"VEHICLE, WINDOW, LAUNDRY AND OTHER HAND CLEANING WORKERS","description":"Vehicle, window, laundry and other hand cleaning workers clean windows, showcases or other surfaces of buildings or vehicles and press, launder or dry-clean linen and other textiles by hand.\nTasks usually include: cleaning, washing and polishing cars; washing windows or other glass surfaces with water or various solutions, drying and polishing them; laundering and pressing linen, clothing, fabrics and similar articles by hand in a laundry or other establishments; cleaning by hand and with chemical solutions clothing, fabrics leather goods and similar articles in dry-cleaning or other establishments.","version":"2022","source_id":892,"level":3,"normalized_name":"vehicle window laundry and other hand cleaning workers"},{"code":"921","parent_code":"92","title":"AGRICULTURAL, FORESTRY AND FISHERY LABORERS","description":"Agricultural, forestry and fishery laborers perform simple and routine tasks in the production of crops and livestock, cultivation and maintenance of gardens and parks, exploitation and conservation of forests, and conduct of aquaculture and fisheries operations.\nTasks performed usually include: digging, raking and shoveling using hand tools; loading unloading and stacking supplies, produce and other materials; watering, thinning, weeding and tending crops by hand or using hand tools; planting, harvesting picking and collecting produce by hand; feeding, watering, and cleaning animals and keeping their quarters clean; monitoring livestock, reporting on their condition; preparing and operating nets, lines and other fishing tackle and deck equipment; grading, sorting, bunching and packing produce into containers; performing minor repairs on fixtures, buildings equipment, vessels and fences.","version":"2022","source_id":898,"level":3,"normalized_name":"agricultural forestry and fishery laborers"},{"code":"931","parent_code":"93","title":"MINING AND CONSTRUCTION LABORERS","description":"Mining and construction laborers perform simple and routine manual tasks in mining, quarrying, civil engineering and building operations.\nTasks usually include: digging and filling holes and trenches using hand held tools; shoveling and spreading excavated materials, sand, soil, and gravel; sorting, loading, unloading, stacking and storing tools, materials and equipment and transporting them around work sites; cleaning machinery, equipment, tools and work sites and removing obstructions.","version":"2022","source_id":901,"level":3,"normalized_name":"mining and construction laborers"},{"code":"932","parent_code":"93","title":"MANUFACTURING LABORERS","description":"Manufacturing laborers perform a variety of manual tasks in manufacturing, assist the work of machine operators and assemblers, and undertake product-sorting and hand-assembling of components.\nTasks performed usually include: packing material and various products by hand; filling bottles, boxes, bags and other containers with products by hand; labelling products and containers by hand; conveying goods, material, equipment to work area; cleaning machinery, equipment and tools; carrying out manual sorting of products or components; carrying out simple hand-assembling of components.","version":"2022","source_id":903,"level":3,"normalized_name":"manufacturing laborers"},{"code":"933","parent_code":"93","title":"TRANSPORT AND STORAGE LABORERS","description":"Transport and storage laborers propel cycles and similar vehicles and drive animal-drawn vehicles to transport passengers or goods, drive animal-drawn machinery, handle freight and baggage and stock shelves.\nTasks performed usually include: propelling cycles and similar vehicles to transport passengers or goods, driving animal-drawn vehicles to transport passengers or goods, driving animal-drawn machinery, carrying out freight handling by hand, and stocking shelves and display areas in stores.","version":"2022","source_id":908,"level":3,"normalized_name":"transport and storage laborers"},{"code":"941","parent_code":"94","title":"FOOD PREPARATION ASSISTANTS","description":"Food preparation assistants prepare and cook to order a small variety of pre-cooked food or beverages, clear tables, clean kitchen areas and wash dishes.\nTasks performed by workers usually include: preparing simple or pre-prepared foods and beverages such as sandwiches, pizzas, fish and chips, salads, and coffee; washing, cutting, measuring and mixing foods for cooking; operating cooking equipment such as grills, microwaves and deep-fat fryers; cleaning kitchens, food preparation areas and service areas; cleaning cooking and general utensils used in kitchens and restaurants.","version":"2022","source_id":910,"level":3,"normalized_name":"food preparation assistants"},{"code":"951","parent_code":"95","title":"STREET AND RELATED SERVICE WORKERS","description":"Street and related service workers provide a variety of services on streets and in other public places, including cleaning shoes, washing car windows, running errands, looking after property, and providing other on-the-spot street services.\nTheir tasks include: a) obtaining the materials necessary to perform services; b) approaching people on the street to offer services; c) cleaning and polishing shoes; d) cleaning and polishing car windows; e) running errands; f) assisting drivers to find a parking place and ensuring car is not damaged during driver’s absence; g) handing out leaflets and free newspapers; and h) receiving immediate payment.\nExamples of the occupations classified here: Barker, Car guard, Car window washer, Errand boy, Leaflet distributor, Shoe polisher\nSome related occupations classified elsewhere: Leaflet and newspaper deliverer - 9621, Service station attendant - 5245","version":"2022","source_id":911,"level":3,"normalized_name":"street and related service workers"},{"code":"952","parent_code":"95","title":"STREET VENDORS (excluding food)","description":"Street vendors (excluding food) sell a usually limited range of goods (excluding food for immediate consumption) in streets and public places such as stations, cinemas or theatres.\nTheir tasks include: a) buying or receiving items for sale, or making simple items; b) loading and unloading basket, tray, push-cart, bicycle, hand truck or other vehicle, to transport goods to the streets or public places such as stations or cinemas; c) displaying goods or calling out to attract customer’s attention; d) approaching potential customers on street and offering goods for sale; and e) receiving immediate payment.\nExamples of the occupations classified here: Ambulant non-food vendor, Cigarette ambulant vendor, Hawker, Newspaper vendor, Peddler, Rug ambulant vendor, Sampaguita ambulant vendor\nSome related occupations classified elsewhere: Door-to-door sales representative - 5243, Free newspaper distributor - 9510, Market salesperson - 5211, Street food vendor - 5212, Street stall salesperson - 5211","version":"2022","source_id":912,"level":3,"normalized_name":"street vendors excluding food"},{"code":"961","parent_code":"96","title":"REFUSE WORKERS","description":"Refuse workers collect, process and recycle garbage from buildings, yards, streets and other public places, or keep streets and other public places clean.\nTasks usually include: collecting, loading and unloading garbage; sweeping streets, parks and other public places; sorting and recycling garbage such as paper, glass, plastic or aluminum.","version":"2022","source_id":915,"level":3,"normalized_name":"refuse workers"},{"code":"962","parent_code":"96","title":"OTHER ELEMENTARY WORKERS","description":"Other elementary workers deliver and carry messages and packages, collect money and stock vending machines, read meters, collect water and firewood, collect and issue tickets for parking or events.\nTasks performed usually include: chopping wood, collecting water and firewood; delivering messages, packages and other items within or between establishments, or elsewhere; performing duties as a post-runner; issuing and collecting tickets and passes; calculating parking charges; filling storage areas of vending machines and collecting money from containers; reading electricity, gas or water meters and recording consumption.","version":"2022","source_id":920,"level":3,"normalized_name":"other elementary workers"},{"code":"0110","parent_code":"011","title":"COMMISSIONED ARMED FORCES OFFICERS","description":"Commissioned armed forces officers provide leadership and management to organizational units in the armed forces and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces. This group includes all members of the armed forces holding the rank of second lieutenant (or equivalent) or higher.\nExamples of the occupations classified here: Admiral, Air commodore, Air force captain, Air force flight lieutenant, Air force group captain, Air force pilot officer, Air marshal, Armed forces officer cadet, Army brigadier, Army cadet officer, Army captain, Army colonel, Army general, Army lieutenant colonel, Army major, Army second lieutenant, Field marshal, Midshipman, Military flying officer, Military naval officer, Navy captain, Navy commander, Navy commodore, Navy lieutenant commander, Navy sublieutenant, Squadron leader, Wing commander","version":"2022","source_id":921,"level":4,"normalized_name":"commissioned armed forces officers"},{"code":"0210","parent_code":"021","title":"NON-COMMISSIONED ARMED FORCES OFFICERS","description":"Non-commissioned armed forces officers enforce military discipline and supervise the activities of those employed in Armed forces occupations, other ranks, and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces. This group includes members of the armed forces holding ranks such as sergeant, warrant officer and sergeant major.\nExamples of the occupations classified here: Army sergeant, Flight sergeant, Master sergeant, Military quartermaster, Navy boatswain, Sergeant major, Warrant officer","version":"2022","source_id":922,"level":4,"normalized_name":"non-commissioned armed forces officers"},{"code":"0310","parent_code":"031","title":"ARMED FORCES OCCUPATIONS, OTHER RANKS","description":"Armed forces occupations, other ranks include all conscripted and non-conscripted members of the armed forces except commissioned and non-commissioned officers. They perform specific military tasks and/or perform similar tasks to those performed in a variety of civilian occupations outside the armed forces.\nExamples of the occupations classified here: Air force corporal, Airman, Army corporal, Bombardier, Gunner, Infantryman/woman, Navy coxswain, Navy seaman, Paratrooper, Rifleman/woman","version":"2022","source_id":923,"level":4,"normalized_name":"armed forces occupations other ranks"},{"code":"1111","parent_code":"111","title":"LEGISLATORS","description":"Legislators determine, formulate, and direct policies of national, state, regional or local governments and international governmental agencies, and make, ratify, amend or repeal laws, public rules and regulations. They include elected and non-elected members of parliaments, councils and governments.\nTheir tasks include: a) presiding over or participating in the proceedings of legislative bodies and administrative councils of national, state, regional or local governments or legislative assemblies; b) determining, formulating, and directing policies of national, state, regional or local governments; c) making, ratifying, amending or repealing laws, public rules and regulations within a statutory or constitutional framework; d) serving on government administrative boards or official committees; e) investigating matters of concern to the public and promoting the interests of the constituencies which they represent; f) attending community functions and meetings to provide service to the community, understand public opinion and provide information on government plans; g) negotiating with other legislators and representatives of interest groups in order to reconcile differing interests, and to create policies and agreements; and h) as members of the government, directing senior administrators and officials of government departments and agencies in the interpretation and implementation of government policies.\nExamples of the occupations classified here: City/Municipal Councilor, Congressman, Member of the Barangay Council (Sangguniang Pambarangay), Member of the Provincial Board (Sangguniang Panlalawigan), Senator","version":"2022","source_id":458,"level":4,"normalized_name":"legislators"},{"code":"1112","parent_code":"111","title":"SENIOR GOVERNMENT OFFICIALS","description":"Senior government officials advise governments on policy matters, oversee the interpretation and implementation of government policies and legislation by government departments and agencies, represent their country abroad and act on its behalf, or carry out similar tasks in intergovernmental organizations. They plan, organize, direct, control and evaluate the overall activities of municipal or local, regional and national government departments, boards, agencies or commissions in accordance with legislation and policies established by government and legislative bodies.\nTheir tasks include: a) advising national, state, regional or local governments and legislators on policy matters; b) advising on the preparation of government budgets, laws and regulations, including amendments; c) establishing objectives for government departments or agencies in accordance with government legislation and policy; d) formulating or approving and evaluating programs and procedures for the implementation of government polices in conjunction or consultation with government; e) recommending, reviewing, evaluating and approving documents, briefs and reports submitted by middle managers and senior staff members; f) ensuring appropriate systems and procedures are developed and implemented to provide budgetary control; g) coordinating activities with other senior government managers and officials; h) making presentations to legislative and other government committees regarding policies programs or budgets; and i) overseeing the interpretation and implementation of government policies and legislation by government departments and agencies.\nExamples of the occupations classified here: Administrator/Deputy administrator, Ambassador, Attaché, City administrator, Consul General, Director general/Deputy director general/ Assistant director general, Executive director/Deputy executive director, Government chief of staff, Government civil registrar Government commission chairperson, Government director/assistant director, Governor/Deputy governor of the Bangko Sentral ng Pilipinas, Governor/Vice governor, Mayor/Vice mayor, National treasurer, Ombudsman, Police inspector-general, Postmaster general, President/Vice, President of the Republic of the Philippines, Solicitor general/Associate solicitor general","version":"2022","source_id":459,"level":4,"normalized_name":"senior government officials"},{"code":"1113","parent_code":"111","title":"TRADITIONAL CHIEFS AND HEADS OF VILLAGES","description":"Traditional chiefs and heads of villages perform a variety of legislative, administrative and ceremonial tasks and duties, determined by ancient traditions, as well as by the division of rights and responsibilities between village chiefs and the local, regional and national authorities.\nTheir tasks include: a) allocating the use of communal land and other resources among households in the community or village; b) collecting and distributing surplus production of the community or village; settling disputes between members of the community or village; c) settling disputes between members of the community or village; d) disciplining members of the community or village for violation of rules and customs; e) performing ceremonial duties in connection with births, marriages, deaths, harvests and other important occasions; f) representing the community or village on local or regional councils; and g) informing the community or village about government rules and regulations.\nExamples of the occupations classified here: Barangay Chairperson/Captain, Barangay Kagawad, Sangguniang Kabataan (SK) Chairperson, Tribe Chieftain/Head","version":"2022","source_id":460,"level":4,"normalized_name":"traditional chiefs and heads of villages"},{"code":"1114","parent_code":"111","title":"SENIOR OFFICIALS OF SPECIAL-INTEREST ORGANIZATIONS","description":"Senior officials of special-interest organizations determine, formulate and direct the implementation of policies of special-interest organizations, such as political-party organizations, trade unions, employers' organizations, trade and industry associations, humanitarian or charity organizations, or sports associations, and represent their organizations and act on their behalf.\nTheir tasks include: a) determining and formulating the policies, rules and regulations of the organization; b) planning, directing and coordinating the general functioning of the organization; c) reviewing the operations and results of the organization and reporting to boards of directors and governing bodies, the organization’s membership and funding agencies; d) negotiating on behalf of the organization, its members and relevant special-interest groups; e) promoting the interests of the organization, its members and relevant special-interest groups before the legislature, government or general public; f) planning, organizing and directing sections charged with implementing the organization's policies, programmes, rules and regulations; g) ensuring appropriate systems and procedures are developed and implemented to provide budgetary control; h) monitoring and evaluating performance of the organization or enterprise against established objectives and policies; and i) representing the organization at official occasions and board meetings, in negotiations, at conventions, public hearings and forums.\nExamples of the occupations classified here: Economic-interest organization senior official, Employers' organization director-general, Employers' organization president, Employers' organization secretary-general, Employers' organization senior official, Humanitarian organization senior official, Labor organization, senior official, Political party leader, Political party senior official, Special-interest organization senior official, Trade union chairperson, Trade union president, Trade union secretary-general, Trade union senior official","version":"2022","source_id":461,"level":4,"normalized_name":"senior officials of special-interest organizations"},{"code":"1120","parent_code":"112","title":"MANAGING DIRECTORS AND CHIEF EXECUTIVES","description":"Managing directors and chief executives formulate and review the policies and plan, direct coordinate and evaluate the overall activities of enterprises or organizations (except special interest organizations and government departments) with the support of other managers, usually within guidelines established by a board of directors or a governing body to whom they are answerable for the operations undertaken and results.\nTheir tasks include: a) planning, directing and coordinating the general functioning of an enterprise or organization; b) reviewing the operations and results of the enterprise, or organization and reporting to boards of directors and governing bodies; c) determining objectives, strategies, policies and programs for the enterprise or organization; d) providing overall leadership and management to the enterprise or organization; e) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; f) authorizing material, human and financial resources to implement organizational policies and programs; g) monitoring and evaluating performance of the organization or enterprise against established objectives and policies; h) consulting with senior subordinate staff and reviewing recommendations and reports; i) representing the organization at official occasions and board meetings, in negotiations, at conventions, seminars, public hearings and forums; j) selecting, or approving the selection of senior staff; and k) ensuring the organization complies with relevant legislation and regulations.\nExamples of the occupations classified here: Chief executive officer, Chief operation officer, Corporate director, Corporation chief executive, Managing director, Regional manager, University chancellor","version":"2022","source_id":462,"level":4,"normalized_name":"managing directors and chief executives"},{"code":"1211","parent_code":"121","title":"FINANCE MANAGERS","description":"Finance managers plan, direct and coordinate the financial operations of an enterprise or organization, in consultation with senior managers and with managers of other departments or sections.\nTheir tasks include: a) planning, directing and coordinating the financial operations of an enterprise or organization; b) assessing the financial situation of the enterprise or organization, preparing budgets and overseeing financial operations; c) consulting with the chief executive and with managers of other departments or sections; d) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; e) establishing and directing operational and administrative procedures; f) planning and directing daily operations; g) overseeing the selection, training and performance of staff; and h) representing the enterprise or organization in dealings with outside bodies.\nExamples of the occupations classified here: Accounting manager, Administration manager, Budgeting manager, Company secretary, Compensation manager, Finance comptroller, Finance manager, Investment manager\nSome related occupations classified elsewhere: Financial controller - 2411, Financial institution branch manager - 1346, Management accountant - 2411","version":"2022","source_id":463,"level":4,"normalized_name":"finance managers"},{"code":"1212","parent_code":"121","title":"HUMAN RESOURCE MANAGERS","description":"Human resource managers, plan, direct and coordinate policies concerning the personnel, industrial relations and occupational health and safety activities of an enterprise or organization, or of enterprises that provide human resource services to other enterprises and organizations. \nTheir tasks include: a) planning, directing and coordinating the personnel and industrial relations activities, policies and practices of an enterprise or organization; b) planning and organizing procedures for recruitment, training, promotion, transfer and dismissal of staff; c) planning and organizing negotiations and procedures for determination of wage structures and level and for consultation with workers on conditions of employment; d) overseeing safety, health and related programmes and activities; e) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; f) establishing and directing operational and administrative procedures; g) overseeing the development and implementation of management information systems; h) ensuring compliance with standards and legislation relating to employees rights, health and safety, equal opportunity and related concerns; i) overseeing the selection, training and performance of staff for the entire enterprise or organization; j) consulting with senior management and with managers of other departments; and k) representing the enterprise or organization in dealings with outside bodies.\nExamples of the occupations classified here: Assistant training manager, Benefits/Rewards manager, Employee welfare manager, Industrial relations manager, Labor relations manager, Learning and development manager, Personnel/human resource manager, Recruitment manager, Training manager","version":"2022","source_id":464,"level":4,"normalized_name":"human resource managers"},{"code":"1213","parent_code":"121","title":"POLICY AND PLANNING MANAGERS","description":"Policy and planning managers plan, organize, direct and coordinate policy advice and strategic planning activities within government or for non-government organizations and private sector agencies, or manage the activities of enterprises that provide policy and strategic planning services.\nTheir tasks include: a) developing, implementing and monitoring strategic plans, programs, policies, processes, systems and procedures to achieve goals, objectives and work standards; b) developing, directing, administering and participating in policy research and analysis; c) coordinating the implementation of policies and practices; d) establishing activity measures and measurements of accountability; e) planning and directing daily operations; f) leading and managing the activities of policy development and strategic planning staff; g) overseeing the selection, training and performance of staff; and h) representing the enterprise or organization in negotiations, and at conventions, seminars, public hearings and forums.\nExamples of the occupations classified here: Corporate compliance manager, Corporate planning manager, Corporate quality assurance manager, Corporate services manager, Policy manager, Strategic planning manager","version":"2022","source_id":465,"level":4,"normalized_name":"policy and planning managers"},{"code":"1219","parent_code":"121","title":"BUSINESS SERVICES AND ADMINISTRATION MANAGERS NOT ELSEWHERE  CLASSIFIED","description":"This unit group covers business services and administration managers not classified elsewhere in minor group 121, Business services and administration managers. For instance, the group includes occupations such as facilities manager, cleaning services manager, administrative services manager.\nTheir tasks would include: a) providing administrative, strategic planning and operational support, research and advice to senior management on matters such as the management of building facilities and administrative services; b) developing and managing the organization's administrative and physical resources; c) developing and implementing administrative and procedural statements and guidelines for use by staff in the organization; d) analyzing complex resource management issues and initiatives that affect the organization, and preparing associated reports, correspondence and submissions; e) providing information and support for the preparation of financial reports and budgets; f) leading, managing and developing administrative staff to ensure smooth business operations and the provision of accurate and timely information; g) representing the enterprise or organization in negotiations, and at conventions, seminars, public hearings and forums; h) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; i) planning and directing daily operations; and j) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Administrative services manager, Business services manager, Charging facility manager, Cleaning manager, Cleaning services manager, Cleaning services managing-proprietor, Corporate Service Manager, Facilities manager, Personal care manager, Personal care services managing-proprietor, Safety manager, Utility manager","version":"2022","source_id":466,"level":4,"normalized_name":"business services and administration managers not elsewhere classified"},{"code":"1221","parent_code":"122","title":"SALES AND MARKETING MANAGERS","description":"Sales and marketing managers plan, direct and coordinate the sales and marketing activities of an enterprise or organization, or of enterprises that provide sales and marketing services to other enterprises and organizations.\nTheir tasks include: a) planning and organizing special sales and marketing programmes based on sales records and market assessments; planning and directing daily operations; b) determining price lists, discount and delivery terms, sales promotion budgets, sales methods, special incentives and campaigns; c) establishing and directing operational and administrative procedures related to sales and marketing activities; d) leading and managing the activities of sales and marketing staff; e) planning and directing daily operations; f) establishing and managing budgets and controlling expenditure to ensure the efficient use of resources; g) overseeing the selection, training and performance of staff; and h) representing the enterprise or organization at sales and marketing conventions, trade exhibitions and other forums.\nExamples of the occupations classified here: Consumer credit manager, Customer services manager, Marketing director, Marketing manager, Sales director, Sales manager, Store manager, Telemarketing manager","version":"2022","source_id":467,"level":4,"normalized_name":"sales and marketing managers"},{"code":"1222","parent_code":"122","title":"ADVERTISING AND PUBLIC RELATIONS MANAGERS","description":"Advertising and public relations managers plan, direct and coordinate the advertising, public relations and public information activities of enterprises and organizations or of enterprises that provide related services to other enterprises and organizations.\nTheir tasks include: a) planning, directing and coordinating the advertising and public relations activities of an enterprise or organization; b) negotiating advertising contracts with clients or with newspapers, radio and television stations, sports and cultural organizations and advertising agencies; c) planning and managing information programmes to inform legislators, the mass media and the general public about the plans, accomplishments and points of view of the enterprise or organization; d) leading and managing the activities of advertising and public relations staff; e) establishing and managing budgets and controlling expenditure and ensuring the efficient use of resources; f) establishing and directing operational and administrative procedures; g) planning and directing daily operations; and h) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Advertisement and promo assistant manager, Advertising manager, Advertising director, Circulation manager, Communication development manager, Promotions department manager, Public relations manager,","version":"2022","source_id":468,"level":4,"normalized_name":"advertising and public relations managers"},{"code":"1223","parent_code":"122","title":"RESEARCH AND DEVELOPMENT MANAGERS","description":"Research and development managers plan, direct and coordinate the research and development activities of an enterprise or organization or of enterprises that provide related services to other enterprises and organizations.\nTheir tasks include: a) planning, directing and coordinating research and development activities, in-house or commissioned from external research organizations, to develop new or improved technical processes, products, knowledge, or utilization of materials; b) planning the overall research and development programme of an enterprise or organization, specifying goals and budgetary requirements; c) leading and managing the activities of research and development staff; d) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; e) establishing and directing operational and administrative procedures; f) planning and directing daily operations; g) overseeing the selection, training and performance of staff; and h) representing the enterprise or organization at conventions, seminars and conferences.\nExamples of the occupations classified here: Product development manager, Research and development manager, Research manager, Research project manager","version":"2022","source_id":469,"level":4,"normalized_name":"research and development managers"},{"code":"1311","parent_code":"131","title":"AGRICULTURAL AND FORESTRY PRODUCTION MANAGERS","description":"Agricultural and forestry production managers plan, direct, and coordinate production in large scale agricultural, horticultural and forestry operations such as plantations, large ranches, collective farms and agricultural cooperatives to grow and harvest crops, and breed and raise livestock.\nTheir tasks include: a) monitoring agricultural and forestry market activity and planning production to meet contract requirements and market demand; b) establishing and managing budgets, monitoring production output and costs, recording information such as farm management practices, and preparing financial and operational reports; c) conferring with buyers to arrange for the sale of crops and livestock; d) contracting with farmers or independent owners for production of crops and livestock, or for management of production; e) planning the type, intensity and sequence of farm operations (e.g. determining the best times for planting, spraying and harvesting); f) analyzing soil to determine types and quantities of fertilizer required for maximum production; g) purchasing machinery, equipment, and supplies such as tractors, seed, fertilizer, and chemicals; h) identifying and controlling agricultural and forest environmental toxins, weeds, pests and diseases; i) organizing farming operations such as maintaining buildings, water supply systems and equipment; j) directing and coordinating activities such as planting, irrigation, chemical application, harvesting, and grading; k) inspecting plantations and fields to determine maturity dates of crops, or to estimate potential crop damage from weather; and l) overseeing the selection, training and performance of agricultural and forestry workers and contractors.\nExamples of the occupations classified here: Agricultural farm manager/overseers, Agricultural general manager, Agricultural production and operations manager, Chicken farm operations manager, Forestry general manager, Game fowl farm operations manager, Livestock farm operations manager, Plantation manager, Poultry farm operations manager, Ranch manager","version":"2022","source_id":470,"level":4,"normalized_name":"agricultural and forestry production managers"},{"code":"1312","parent_code":"131","title":"AQUACULTURE AND FISHERIES PRODUCTION MANAGERS","description":"Aquaculture and fisheries production managers plan, direct, and coordinate production in large scale aquaculture and fishery operations to catch and harvest fish and shellfish, and to grow fish shellfish or other forms of aquatic life, as cash crops or for release into freshwater or saltwater.\nTheir tasks include: a) monitoring aquaculture and fishery market activity and planning production and fishing activities to meet contract requirements and market demand; b) establishing and managing budgets, monitoring production output and costs, recording information such as fisheries management practices, and preparing financial and operational reports; c) conferring with buyers to arrange for the sale of produce and catches; d) contracting with fishing skippers or owners of vessels and aquaculture farms for fishing and aquaculture operations, or for management of production; e) conducting and organizing aquaculture or fishery stock examinations in order to identify diseases or parasites; f) devising and coordinating activities to improve fish hatching and growth rates, and to prevent disease in hatcheries; g) monitoring environments to maintain or improve conditions for aquatic life; h) directing and monitoring trapping and spawning of fish, egg incubation, and fry rearing, applying knowledge of management and fish culturing techniques; i) coordinating the selection and maintenance of brood stock; j) directing and monitoring the transfer of mature fish to lakes, ponds, streams, or commercial tanks; k) purchasing machinery, equipment, and supplies such as vessels and nets; l) organizing operations such as maintenance of ships, boats and equipment; and m) overseeing the selection, training and performance of aquaculture or fishery workers and contractors.\nExamples of the occupations classified here: Aquaculture production manager, Fishing general manager, Fishing operations manager, Fishing shore captain, Trawler manager\nSome related occupations classified elsewhere: Fish farmer - 6221, Coastal waters fishing vessel skipper - 6222, Deep sea fishing master - 6223, Fish hatchery manager - 6221, Oyster farmer - 6224, Seafood farmer - 6221","version":"2022","source_id":471,"level":4,"normalized_name":"aquaculture and fisheries production managers"},{"code":"1321","parent_code":"132","title":"MANUFACTURING MANAGERS","description":"Manufacturing managers plan, direct, and coordinate manufacturing production activities of large enterprises or as the manager of a small manufacturing company.\nTheir tasks include: a) determining, implementing and monitoring production strategies, policies and plans; b) planning details of production activities in terms of output quality and quantity, cost, time available and labor requirements; c) controlling the operation of production plant and quality procedures through planning of maintenance, designation of operating hours and supply of parts and tools; d) establishing and managing budgets, monitoring production output and costs, and adjusting processes and resources to minimize costs; e) consulting with and informing other managers about production matters; f) overseeing the acquisition and installation of new plant and equipment; g) controlling the preparation of production records and reports; h) coordinating the implementation of occupational health and safety requirements; i) identifying business opportunities and determining products to be manufactured; j) researching and implementing regulatory and statutory requirements affecting manufacturing operations and the environment; k) overseeing the provision of quotes for the manufacture of specialized goods and establishing contracts with customers and suppliers; and l) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Food production managers, Manufacturer, Manufacturing general manager, Manufacturing manager, Production and operations / manufacturing manager\nRelated occupation classified elsewhere: Manufacturing production supervisor - 3122","version":"2022","source_id":472,"level":4,"normalized_name":"manufacturing managers"},{"code":"1322","parent_code":"132","title":"MINING MANAGERS","description":"Mining managers plan, direct, and coordinate the production activities of mining, quarrying and oil and gas extraction operations.\nTheir tasks include: a) conferring with other managers to set production quotas, plan extraction sites and develop policies for the removal of raw materials; b) evaluating efficiency of production sites to determine adequacy of personnel, equipment and technologies used, and make changes to work schedule or equipment when necessary; c) planning details of production activities in terms of output quality and quantity, cost, time available and labor requirements; d) controlling the operation of plant and quality procedures through planning of maintenance, designation of operating hours and supply of equipment; e) establishing and managing budgets, monitoring production output and costs, and adjusting processes and resources to minimize costs; f) overseeing the acquisition and installation of new plant and equipment;g) controlling the preparation of production records and reports; h) coordinating the implementation of health and safety requirements; i) researching and implementing regulatory and statutory requirements affecting mineral extraction operations and the environment; and j) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Mine manager, Mining equipment manager, Mining production manager, Oil and gas exploration manager, Oil and gas extraction production manager, Quarry manager, Quarry production manager\nSome related occupations classified elsewhere: Mine deputy - 3121, Mine supervisor - 3121, Mine under-manager - 3121, Quarry supervisor - 3121","version":"2022","source_id":473,"level":4,"normalized_name":"mining managers"},{"code":"1323","parent_code":"132","title":"CONSTRUCTION MANAGERS","description":"Construction managers plan, direct and coordinate the construction of civil engineering projects, buildings and dwellings.\nTheir tasks include: a) interpreting architectural drawings and specifications; b) coordinating labor resources, and procurement and delivery of materials, plant and equipment; c) negotiating with building owners, property developers and subcontractors involved in the construction process to ensure projects are completed on time and within budget; d) preparing tenders and contract bids; e) operating and implementing coordinated work programs for sites; f) ensuring adherence to building legislation and standards of performance, quality, cost and safety; g) arranging submission of plans to local authorities; h) building under contract, or subcontracting specialized building services; i) arranging building inspections by relevant authorities; j) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; and k) overseeing the selection, training and performance of staff and subcontractors;\nExamples of the occupations classified here: Civil engineering project manager, Construction manager, Construction project manager, Construction site manager, Demolition manager, Project builder\nSome related occupations classified elsewhere: Building construction supervisor - 3123, House builder - 7111","version":"2022","source_id":474,"level":4,"normalized_name":"construction managers"},{"code":"1324","parent_code":"132","title":"SUPPLY, DISTRIBUTION AND RELATED MANAGERS","description":"Supply, distribution and related managers plan, direct and coordinate the supply, transportation, storage and distribution of goods.\nTheir tasks include: a) determining, implementing and monitoring purchasing, storage and distribution strategies, policies and plans; b) preparing and implementing plans to maintain required stock levels at minimum cost; c) negotiating contracts with suppliers to meet quality, cost and delivery requirements; d) monitoring and reviewing storage and inventory systems to meet supply requirements and control stock levels; e) operating recording systems to track all movements of goods, and ensuring re-ordering and re-stocking at optimal times; f) liaising with other departments and customers concerning requirements for outward goods and associated forwarding transportation; g) overseeing the recording of purchase, storage and distribution transactions; h) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; i) establishing and directing operational and administrative procedures; j) planning and directing daily operations; and k) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Assistant shipping manager, Bus Station Manager, Distribution manager, Electric vehicle fleet manager, Freight forwarding manager, Imports and exports manager, Logistics manager, Material resources manager, Port captain, Public Utility Vehicle (PUV) operations manager, Purchasing manager, Railway station manager, Railway station master, Shipping manager, Supply chain manager, Supply manager, Transport general manager, Transport network vehicle service (TNVS) vehicle manager, Transport operations manager, Truck-for-hire operations manager, Warehouse manager","version":"2022","source_id":475,"level":4,"normalized_name":"supply distribution and related managers"},{"code":"1330","parent_code":"133","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY SERVICE MANAGERS","description":"Information and communications technology service managers plan, direct, and coordinate the acquisition, development, maintenance and use of computer and telecommunication systems.\nTheir tasks include: a) consulting with users, management, vendors, and technicians to assess computing needs and system requirements and specifying technology to meet those needs; b) formulating and directing information and communication technology (ICT) strategies, policies and plans; c) directing the selection and installation of ICT resources and the provision of user training; d) directing ICT operations, analyzing workflow, establishing priorities, developing standards and setting deadlines; e) overseeing the security of ICT systems; f) assigning, reviewing, managing and leading the work of systems analysts, programmers, and other computer-related workers; g) evaluating the organization's technology use and needs and recommending improvements, such as hardware and software upgrades; h) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; i) establishing and directing operational and administrative procedures; j) overseeing the selection, training and performance of staff; and k) representing the enterprise or organization at ICT related conventions, seminars and conferences.\nExamples of the occupations classified here: Application development manager, Chief information officer, Data operations manager, Data processing manager, Electronic data processing (EDP) manager, ICT development manager, Information and communication technology manager, Information systems director, Information technology manager, Internet service provider manager, Management information system (MIS) manager, Network manager, Telecommunications services manager,","version":"2022","source_id":476,"level":4,"normalized_name":"information and communications technology service managers"},{"code":"1341","parent_code":"134","title":"CHILD CARE SERVICE MANAGERS","description":"Child care service managers plan, direct, and coordinate and evaluate the provision of care for children in before-school, after-school, vacation and day care centers and services.\nTheir tasks include: a) developing and implementing programs to enhance the physical, social, emotional and intellectual development of young children; b) establishing and monitoring budgets and determining allocation of funds for staff, supplies, materials, equipment and maintenance; c) overseeing and coordinating the provision of care for children in before-school, after-school, day, and vacation care centers; d) directing and supervising child carers in providing care and supervision for young children; e) managing physical facilities and making sure all buildings and equipment are maintained to ensure the center is a safe area for children, staff and visitors; f) reviewing and interpreting government codes, and developing procedures to meet codes (e.g., concerning safety and security); g) monitoring children’s progress and conferring with parents or guardians; h) preparing and maintaining records and accounts for a child care center; and i) recruiting and evaluating staff and coordinating their professional development.\nExample of occupation classified here: Child care center manager","version":"2022","source_id":477,"level":4,"normalized_name":"child care service managers"},{"code":"1342","parent_code":"134","title":"HEALTH SERVICE MANAGERS","description":"Health service managers plan, direct, coordinate and evaluate the provision of clinical and community health care services in hospitals, clinics, public health agencies and similar organizations.\nTheir tasks include: a) providing overall direction and management for the service, facility, organization or center; b) directing, supervising and evaluating the work activities of medical, nursing, technical, clerical, service, maintenance, and other personnel; c) establishing objectives and evaluative or operational criteria for units they manage; d) directing or conducting recruitment, hiring and training of personnel; e) developing, implementing and monitoring procedures, policies and performance standards for medical, nursing, technical and administrative staff; f) monitoring the use of diagnostic services, inpatient beds, facilities, and staff to ensure effective use of resources and assess the need for additional staff, equipment, and services; g) controlling administrative operations such as budget planning, report preparation and expenditure on supplies, equipment and services; h) liaising with other health and welfare service providers, boards and funding bodies to coordinate the provision of services; i) advising government bodies about measures to improve health and welfare services and facilities; and j) representing the organization in negotiations, and at conventions, seminars, public hearings and forums.\nExamples of the occupations classified here: Chief public health officer, Clinical director, Community health care coordinator, Director of nursing, Health facility administrator, Hospital matron, Medical administrator\nRelated occupation classified elsewhere: Aged care service manager - 1343","version":"2022","source_id":478,"level":4,"normalized_name":"health service managers"},{"code":"1343","parent_code":"134","title":"AGED CARE SERVICE MANAGERS","description":"Aged care service managers plan, direct coordinate and evaluate the provision of residential and personal care services for individuals and families who are in need of such services due to the effects of ageing.\nTheir tasks include: a) providing overall direction and management for a service, facility, organization or center; b) directing, supervising and evaluating the work activities of medical, nursing, technical, clerical, service, maintenance, and other personnel; c) establishing objectives and evaluative or operational criteria for units they manage; d) directing or conducting recruitment, hiring and training of personnel; e) developing, implementing and monitoring procedures, policies and performance standards for nursing, personal care, technical, and administrative staff; f) coordinating and administering welfare programs and care services for the elderly; g) controlling administrative operations such as budget planning, report preparation, expenditure on supplies, equipment and services; h) liaising with other health and welfare providers, boards and funding bodies to coordinate the provision of services; i) advising government bodies about measures to improve health and welfare services and facilities; and j) representing the organization in negotiations, and at conventions, seminars, public hearings and forums.\nExamples of the occupations classified here: Aged care home director, Community aged care coordinator, Nursing home director, Retirement village coordinator\nRelated occupation classified elsewhere: Health service manager - 1342","version":"2022","source_id":479,"level":4,"normalized_name":"aged care service managers"},{"code":"1344","parent_code":"134","title":"SOCIAL WELFARE MANAGERS","description":"Social welfare managers plan, direct, and coordinate the provision of social and community service programs such as income support, family assistance, children’s services and other community programs and services.\nTheir tasks include: a) providing overall direction and management for a service, facility, organization or center; b) developing, implementing and monitoring procedures, policies and standards for staff; c) monitoring and evaluating resources devoted to the provision of welfare, housing, and other social services; d) controlling administrative operations such as budget planning, report preparation, expenditure on supplies, equipment and services; e) liaising with other welfare and health services providers, boards and funding bodies to discuss areas of health and welfare service cooperation and coordination; f) advising government bodies about measures to improve welfare services and facilities; g) representing the organization in negotiations, and at conventions, seminars, public hearings and forums; h) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; i) establishing and directing operational and administrative procedures; j) overseeing the selection, training and performance of staff; and k) representing the organization at conventions, seminars and conferences.\nExamples of the occupations classified here: Community center manager, Family services manager, Housing services manager, Welfare center manager","version":"2022","source_id":480,"level":4,"normalized_name":"social welfare managers"},{"code":"1345","parent_code":"134","title":"EDUCATION MANAGERS","description":"Education managers plan, direct, coordinate and evaluate the educational and administrative aspects of education services, primary and secondary schools, colleges and faculties and departments in universities and other educational institutions.\nTheir tasks include: a) determining educational programs based on frameworks established by education authorities and governing bodies; b) implementing systems and procedures to monitor school performance and student enrolments; c) directing administrative and clerical activities concerning student admissions and educational services; d) controlling administrative operations such as budget planning, report preparation, expenditure on supplies, equipment and services; e) providing leadership and guidance to teaching, academic and administrative staff as well as to students; f) evaluating the work of teachers and lecturers by visiting classrooms, observing teaching methods, reviewing instructional objectives and examining learning materials; g) promoting the educational program, and representing the service or institution in the wider community; h) supervising the maintenance of educational facilities; i) developing and enforcing a disciplinary code to create a safe and conducive environment for students and teachers; j) organizing and implementing methods of raising additional funds in conjunction with parent and community groups and sponsors; and k) controlling selection, training and supervision of staff.\nExamples of the occupations classified here: Assistant principal, Chief education supervisor, City school superintendent, College administrator, College dean, College director, Division school superintendent, Head teacher, Public school district supervisor, School administrator, School president, School principal, School supervisor, Universities and Colleges president","version":"2022","source_id":481,"level":4,"normalized_name":"education managers"},{"code":"1346","parent_code":"134","title":"FINANCIAL AND INSURANCE SERVICES BRANCH MANAGERS","description":"Financial and insurance services branch managers plan, direct, and coordinate the branches of institutions that provide financial and insurance services, such as banks, building societies, credit unions and insurance companies. They provide advice and assistance to clients on financial and insurance matters.\nTheir tasks include: a) planning, directing and coordinating the activities of staff in the branch; b) establishing and maintaining relationships with individual and business customers; c) providing advice and assistance to customers on their financial and insurance needs and other related matters such as changes in law that may affect customers; d) examining, evaluating and processing loan and insurance applications; e) monitoring credit extension decisions; f) conducting financial investigations; g) overseeing the flow of cash and financial instruments, and the preparation of financial and regulatory reports; h) approving or rejecting, or coordinating the approval or rejection of, lines of credit commercial, real estate and personal loans; i) coordinating cooperation with other branches of the company; j) managing budgets, controlling expenditure and ensuring the efficient use of resources; and k) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Bank manager, Credit union manager, Financial Institution branch manager, Insurance agency branch manager, Insurance area manager, Insurance underwriting and claims branch manager, Money changing branch manager\nSome related occupations classified elsewhere: Credit and loans officer - 3312, Finance manager - 1211, Insurance agent - 3321","version":"2022","source_id":482,"level":4,"normalized_name":"financial and insurance services branch managers"},{"code":"1349","parent_code":"134","title":"PROFESSIONAL SERVICES MANAGERS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers managers who plan, direct coordinate and evaluate the provision of specialized professional and technical services and are not classified in sub-major group 12, Business services and administration managers, or elsewhere in sub-major group 13, Professional services managers. For instance, managers responsible for the provision of policing, corrective, library, legal and fire services are classified here. \nIn such cases tasks would include: a) providing overall direction and management for a service, facility, organization or center; b) developing, implementing and monitoring procedures, policies and standards for staff; c) directing, supervising and evaluating the work activities of professional technical, clerical, service, maintenance, and other personnel; d) monitoring and evaluating resources devoted to the provision of services; e) controlling administrative operations such as budget planning, report preparation, expenditure on supplies, equipment and services; f) planning, directing and coordinating the provision of services; g) coordinating cooperation with other service provision agencies in the same or related fields; h) managing budgets, controlling expenditure and ensuring the efficient use of resources; and i) overseeing the selection, training and performance of staff.\nExamples of the occupations classified here: Archives manager, Art gallery manager, Correctional services manager, Legal service manager, Library manager, Museum manager, Police superintendent, Prison governor","version":"2022","source_id":483,"level":4,"normalized_name":"professional services managers not elsewhere classified"},{"code":"1411","parent_code":"141","title":"HOTEL MANAGERS","description":"Hotel managers plan, organize and direct the operations of hotels, motels and similar establishments to provide guest accommodation and other services.\nTheir tasks include: a) directing and overseeing reservation, reception, room service and housekeeping activities; b) supervising security arrangements, and garden and property maintenance; c) planning and supervising bar, restaurant, function and conference activities; d) observing liquor, gaming, and other laws and regulations; e) assessing and reviewing customer satisfaction; f) overseeing accounting and purchasing activities; g) undertaking budgeting for the establishment; h) controlling selection, training and supervision of staff; i) ensuring compliance with occupational health and safety regulations; and j) providing guests with local tourism information, and arranging tours and transportation.\nExamples of the occupations classified here: Hotel manager, Hostel manager, Motel manager\nRelated occupation classified elsewhere: Bed and breakfast operator - 5152","version":"2022","source_id":484,"level":4,"normalized_name":"hotel managers"},{"code":"1412","parent_code":"141","title":"RESTAURANT MANAGERS","description":"Restaurant managers plan, organize and direct the operations of cafes, restaurants and related establishments to provide dining and catering services.\nTheir tasks include: a) planning menus in consultation with chefs and cooks; b) planning and organizing special functions; c) arranging the purchasing and pricing of goods according to budget; d) maintaining records of stock levels and financial transactions; e) ensuring dining, kitchen and food storage facilities comply with health regulations and are clean, functional and of suitable appearance; f) conferring with customers to assess their satisfaction with meals and service; g) selecting, set staff work schedules, training and supervising waiting and kitchen staff; h) taking reservations, greeting guests and assisting in taking orders; i) negotiating arrangements with clients and suppliers; and j) ensuring compliance with occupational health and safety regulations.\nExamples of the occupations classified here: Café manager, Catering services manager, Restaurant manager\nRelated occupation classified elsewhere: Chef - 3434","version":"2022","source_id":485,"level":4,"normalized_name":"restaurant managers"},{"code":"1420","parent_code":"142","title":"RETAIL AND WHOLESALE TRADE MANAGERS","description":"Retail and wholesale trade managers, plan, organize, co-ordinate and control the operations of establishments that sell goods on a retail or wholesale basis. They are responsible for the budgets, staffing and strategic and operational direction of shops, or of organizational units within shops that sell particular types of product. \nTheir tasks include: a) determining product mix, stock levels and service standards; b) formulating and implementing purchasing and marketing policies, and setting prices; c) promoting and advertising the establishment’s goods and services; d) maintaining records of stock levels and financial transactions; e) undertaking budgeting for the establishment; f) controlling selection, training and supervision of staff; and g) ensuring compliance with occupational health and safety regulations.\nExamples of the occupations classified here: Commissary manager, Grocery manager, Retail trade manager, Shop manager, Specialized store manager, Supermarket manager, Wholesale trade manager\nSome related occupations classified elsewhere: Sales manager - 1221, Shop sales assistant - 5223, Shop supervisor - 5222, Shopkeeper - 5221","version":"2022","source_id":486,"level":4,"normalized_name":"retail and wholesale trade managers"},{"code":"1431","parent_code":"143","title":"SPORTS, RECREATION AND CULTURAL CENTRE MANAGERS","description":"Sports, recreation and cultural center managers plan, organize, and control the operations of establishments that provide sporting, artistic, theatrical and other recreational and amenity services.\nTheir tasks include: a) planning and organizing the range and mix of entertainment, attractions, cultural activities, and sports and fitness programmes to be offered by the center; b) ensuring that facilities are kept clean and in good condition; c) keeping abreast of new trends and developments in the creative arts and arranging theatrical productions and performances by bands and orchestras; d) advising on the facilities available and promoting publicity in relation to events, shows and activities; e) checking and keeping custody of all cash receipts and making regular stock checks; f) establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; g) planning and directing daily operations; h) controlling the selection, supervision and performance of staff; and i) ensuring compliance with health and safety regulations.\nExamples of the occupations classified here: Amusement and theme park manager, Billiards or pool hall manager, Casino manager, Cinema manager, Concert hall manager, Dance studio manager, Funfair (peryahan) operations manager, Leisure center manager, Lottery outlet manager, Riding school manager, Sports center manager, Theater hall manager, Theme park manager\nSome related occupations classified elsewhere: Art gallery manager - 1349, Library manager - 1349, Museum manager - 1349","version":"2022","source_id":487,"level":4,"normalized_name":"sports recreation and cultural centre managers"},{"code":"1439","parent_code":"143","title":"SERVICES MANAGERS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers managers that plan, direct and coordinate the provision of services and are not classified in sub-major group 13, Production and specialized services managers or elsewhere in sub-major group 14, Hospitality, retail and other services managers. For instance, managers of travel agencies, conference centers, contact centers and shopping centers are classified here.\nExamples of the occupations classified here: Auto repair shop manager, Barbershop manager, Beauty parlor/salon manager, Camp site manager, Caravan park manager, Computer repair shop manager, Computer/internet shop manager, Conference center manager, Contact center manager, Laundry shop manager, Shopping center manager, Spa and wellness center manager, Travel agency manager","version":"2022","source_id":488,"level":4,"normalized_name":"services managers not elsewhere classified"},{"code":"2111","parent_code":"211","title":"PHYSICISTS AND ASTRONOMERS","description":"Physicists and astronomers conduct research and improve or develop concepts, theories and operational methods concerning matter, space, time, energy, forces and fields and the interrelationship between these physical phenomena. They apply scientific knowledge relating to physics and astronomy in industrial, medical, military or other fields. \nTheir tasks include: a) conducting research and improving or developing concepts, theories, instrumentation, software and operational methods related to physics and astronomy; b) conducting experiments, tests and analyses on the structure and properties of matter in fields such as mechanics, thermodynamics, electronics, communications, power generation and distribution, aerodynamics, optics and lasers, remote sensing, medicine, sonics, magnetism, and nuclear physics; c) evaluating results of investigations and experiments and expressing conclusions, mainly using mathematical techniques and models; d) applying principles, techniques and processes to develop or improve industrial, medical, military and other practical applications of the principles and techniques of physics or astronomy; e) ensuring the safe and effective delivery of radiation (ionizing and non-ionizing) to patients to achieve a diagnostic or therapeutic result as prescribed by a medical practitioner; f) ensuring the accurate measurement and characterization of physical quantities used in medical applications; g) testing, commissioning and evaluating equipment used in applications such as imaging, medical treatment and dosimetry; h) advising and consulting with medical practitioners and other health care professionals in optimizing the balance between the beneficial and deleterious effects of radiation; i) observing, analyzing and interpreting celestial phenomena and developing methods, numerical models and techniques to extend knowledge of fields such as navigation, satellite communication, space exploration, celestial bodies and cosmic radiation; j) developing, implementing and maintaining standards and protocols for the measurement of physical phenomena and for the use of nuclear technology in industrial and medical applications; and k) preparing scientific papers and reports.\nExamples of the occupations classified here: Astronomer, Astronomical scientist, Medical physicist, Nuclear physicist, Physicist\nSome related occupations classified elsewhere: Nuclear medicine specialist physician - 2212, Radiographer - 3211, Radiologist - 2212","version":"2022","source_id":489,"level":4,"normalized_name":"physicists and astronomers"},{"code":"2112","parent_code":"211","title":"METEOROLOGISTS","description":"Meteorologists prepare short-term or long-term weather forecasts used in aviation, shipping, agriculture and other areas and for the information of the general public. They conduct research related to the composition, structure and dynamics of the atmosphere.\nTheir tasks include: a) investigating direction and speed of air movements, pressures, temperatures, humidity, physical and chemical transformation of pollutants and other phenomena such as cloud formation and precipitation, electrical disturbances or solar radiation; b) studying data collected from meteorological stations, radar and satellite imagery and computer model output to plot and forecast weather conditions; c) preparing and reporting short-term or long-term weather maps, forecasts and warnings relating to atmospheric phenomena such as cyclones, storms and other hazards to life and property and disseminating information about atmospheric conditions through a variety of media including radio, television, print and the Internet; d) conducting experiments in fog dispersal, cloud seeding, rain enhancement and other types of weather modification programs; e) developing and testing mathematical computer models of weather and climate for experimental or operational use; f) participating in studies of the effect of weather on the environment; g) analyzing the impact of industrial projects and human activity on the climate and quality of the air and work with the social science, engineering and economic communities to develop appropriate mitigation strategies; h) engaging in the design and development of new equipment and procedures for meteorological data collection, remote sensing, or for related applications; i) conducting research on and improving or developing concepts, theories and operational methods related to the composition, structure and dynamics of the atmosphere and preparing scientific papers and reports on the outcome of this research; and j) preparing scientific papers and reports.\nExamples of the occupations classified here: Climatologist, Hydrometeorologist, Meteorological scientist, Meteorologist, Weather forecaster","version":"2022","source_id":490,"level":4,"normalized_name":"meteorologists"},{"code":"2113","parent_code":"211","title":"CHEMISTS","description":"Chemists conduct research, improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to chemistry, to develop new knowledge or products and for quality and process control.\nTheir tasks include: a) conducting research and improving or developing concepts, instruments, theories and operational methods related to chemistry; b) conducting experiments, tests and analyses to investigate chemical composition and energy and chemical changes in various natural or synthetic substances, materials and products; c) developing procedures for environmental control, quality control and various other procedures for manufacturers or users; d) conducting programs of sample and data collection and analysis to identify and quantify environmental toxicants; e) participating in interdisciplinary research and development projects working with chemical engineers, biologists, microbiologists, agronomists, geologists or other professionals; f) using micro-organisms to convert substances into new compounds; g) determining ways to strengthen or combine materials or develop new materials; h) reproducing and synthesizing naturally occurring substances and creating new artificial substances; and i) preparing scientific papers and reports.\nExamples of the occupations classified here: Analytical chemist, Application chemist, Chemists, Food chemist, Forensic chemist, Laboratory chemist, Pharmaceutical chemist, Physical chemist, Quality control chemist, Research and development chemist\nSome related occupations classified elsewhere: Biochemist - 2131, Pharmacist - 2262, Pharmacologist - 2131","version":"2022","source_id":491,"level":4,"normalized_name":"chemists"},{"code":"2114","parent_code":"211","title":"GEOLOGISTS AND GEOPHYSICISTS","description":"Geologists and geophysicists conduct research; improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to geology and geophysics in such fields as oil, gas and mineral exploration and extraction, water conservation, civil engineering, telecommunications and navigation, and assessment and mitigation of the effects of development and waste disposal projects on the environment. \nTheir tasks include: a) conducting research and improving or developing concepts, theories and operational methods related to geology and geophysics; b) studying composition and structure of the Earth's crust, examining rocks, minerals, fossils and other materials, to determine processes affecting the development of the Earth, trace evolution of past life, establish nature and chronology of geological formations and assess their commercial applications; c) interpreting research data and preparing geological reports, maps, charts and diagrams, reports and papers; d) applying geological knowledge to problems encountered in civil engineering projects such as the construction of dams, bridges, tunnels, and large buildings; and land reclamation projects; e) using various remote sensing programs to investigate and measure seismic, gravitational, electrical, thermal, and magnetic forces affecting the Earth; f) estimating weight, size and mass of the Earth and composition and structure of its interior, and studying the nature, activity and predictability of volcanoes, glaciers and earthquakes; g) charting the Earth's magnetic field and applying this and other collected data for broadcasting, navigation and other purposes; h) studying and measuring physical properties of seas and the atmosphere and their inter-relationship, such as the exchange of thermal energy; i) locating and determining the nature and extent of oil, gas and mineral deposits using seismological, gravimetric, magnetic, electrical or radiometric methods; identifying deposits of construction materials and determining their characteristics and suitability for use as concrete aggregates, road fill or for other applications; j) researching the movement, distribution and physical properties of ground and surface waters; and k) advising in areas such as waste management, route and site selection and the restoration of contaminated sites.\nExamples of the occupations classified here: Geological oceanographer, Geological engineer, Geologist, Geophysical oceanographer, Geophysical scientist, Geophysicist, Geothermal engineer, Hydrogeologist, Hydrographer, Hydrologist, Mineral analyst, Mineralogist, Petrologist, Seismologist, Volcanologist,","version":"2022","source_id":492,"level":4,"normalized_name":"geologists and geophysicists"},{"code":"2119","parent_code":"211","title":"OTHER PHYSICAL AND EARTH SCIENCE PROFESSIONALS","description":"","version":"2022","source_id":493,"level":4,"normalized_name":"other physical and earth science professionals"},{"code":"2121","parent_code":"212","title":"MATHEMATICIANS","description":"Mathematicians develop mathematical models, concepts, theories, operational methods and techniques to provide solution to the problems. They provide advice on the practical application of mathematics in the field of business, engineering and all other sciences.\nTheir tasks include: a) developing and/or improving mathematical theories, principles, concepts and operational methods and techniques; b) advising on or applying mathematical concepts, theories and principles to an extensive tasks in the fields of engineering and all sciences; c) conducting logical analyzes of management problems, especially in terms of input-output effectiveness, and formulating mathematical models of each problem usually for programming and solution by computer; and d) supervising the work of mathematical assistants and clerks.\nExamples of the occupations classified here: Mathematician, Operations research analyst\nSome related occupations classified elsewhere: Mathematical assistant - 3314, Mathematical statistician - 2122","version":"2022","source_id":494,"level":4,"normalized_name":"mathematicians"},{"code":"2122","parent_code":"212","title":"STATISTICIANS","description":"Workers in this unit group conduct research, improve or develop mathematical and other aspects of statistical concepts, theories and operational methods and techniques, and advise on or engage in their practical application, in such fields as business or medicine, as well as in other areas of natural, social or life sciences.\nTheir tasks include: a) studying, improving and developing statistical theories and methodologies; b) planning and organizing surveys and other statistical collections, and designing questionnaires; c) evaluating, processing, analyzing, and interpreting statistical data and preparing them for publication; d) advising on or applying various data collection methods and statistical methods and techniques, and determining reliability of findings, especially in such fields as business or medicine as well as in other areas of natural, social or life sciences; and e) preparing scientific papers and reports.\nExamples of the occupations classified here: Biometrician, Demographer, Statistician","version":"2022","source_id":495,"level":4,"normalized_name":"statisticians"},{"code":"2123","parent_code":"212","title":"ACTUARIES","description":"Actuaries conduct research and improve or develop mathematical and actuarial concepts, theories and operational methods and techniques and advise on or engage in their practical application in such fields as engineering, business and social and other sciences.\nTheir tasks include: a) studying, improving and developing actuarial theories and techniques;b) designing and putting into operation pension schemes and life, health, social and other types of insurance systems; c) applying mathematics, statistics, probability and risk theory to assess potential financial impacts of future events; d) evaluating, processing, analyzing, and interpreting statistical data and preparing them for publication; e) preparing scientific papers and reports; and f) supervising the work of actuarial assistants and statistical clerks.\nExamples of the occupations classified here: Actuarial analyst, Actuarial consultant, Actuarial researcher, Actuarial specialist, Insurance actuary\nSome related occupations classified elsewhere: Actuarial assistant - 3314, Actuarial clerk - 4312","version":"2022","source_id":496,"level":4,"normalized_name":"actuaries"},{"code":"2124","parent_code":"212","title":"DATA SCIENTIST","description":"Data scientists use analytical tools and techniques to extract meaningful insights from data. They may use a variety of methods to obtain data, including through access to other organizations’ databases or by using web-scraping tools. They develop algorithms and models to support programs for machine learning. They often use data visualization software to present their findings, and make recommendations for business decisions or process changes based on the results of their analysis.\nTheir tasks include: a) determining which data are available and useful for the project; b) collecting, categorizing, and analyzing data; c) creating, validating, testing, and updating algorithms and models; d) using data visualization software to present findings; and e) making business recommendations to stakeholders based on data analysis\nExamples of the occupations classified here: Big data research scientist, Data science specialist, Data scientist, Predictive analytics specialists","version":"2022","source_id":497,"level":4,"normalized_name":"data scientist"},{"code":"2131","parent_code":"213","title":"BIOLOGISTS, BOTANISTS, ZOOLOGISTS AND RELATED SCIENTISTS","description":"Biologists, botanists, zoologists and related professionals study living organisms and their interactions with each other and with the environment, and apply this knowledge to solve human health and environmental problems. They work in diverse fields such as botany, zoology, ecology, marine biology, genetics, immunology, pharmacology, toxicology, physiology, bacteriology and virology.\nTheir tasks include: a) undertaking research in laboratories and in the field to increase scientific knowledge of living organisms; to discover new information; to test hypotheses; to solve problems in areas such as the environment, agriculture and health; and to develop new products, processes and techniques for pharmaceutical, agricultural and environmental use; b) designing and conducting experiments and tests; c) gathering human, animal, insect and plant specimens and data, and studying their origin, development, chemical and physical form, structure, composition, and life and reproductive processes; d) examining living organisms using a variety of specialized equipment, instruments, technologies and techniques such as electron microscopes, telemetry, global positioning systems, biotechnology, satellite imaging, genetic engineering, digital imaging analysis, polymerase chain reaction and computer modelling; e) identifying, classifying, recording and monitoring living organisms and maintaining databases; f) to the scientific community in scientific journals or at conferences for scrutiny and further debate; g) designing and carrying out environmental impact assessments to identify changes caused by natural or human factors; and h) providing advice to governments, organizations and businesses in areas such as conservation, management of natural resources, the effects of climate change and pollution.\nExamples of the occupations classified here: Aquatic biologist, Bacteriologist, Biochemist, Biochemistry Technologist, Bioinformatics specialist, Biologist, Biomedical Officer, Biomedical researcher, Biophysicist, Biotechnologist, Botanist, Cell geneticist, Entomologist, Epidemiologist, Genomicist, Marine biologist, Microbiologist, Microbiology Technologist, Molecular biologist, Molecular geneticist, Mycologist, Nanotechnologist, Parasitologist, Pharmacologist, Physiologist, Plant entomologist, Plant geneticist, Plants and animals taxonomist, Veterinary Microbiologist, Virologist, Zoologist\nRelated occupation classified elsewhere: Ecologist - 2133","version":"2022","source_id":498,"level":4,"normalized_name":"biologists botanists zoologists and related scientists"},{"code":"2132","parent_code":"213","title":"FARMING, FORESTRY AND FISHERIES ADVISERS","description":"Farming, forestry and fisheries advisers study and provide assistance and advice on farm, forestry and fisheries management, including cultivation, fertilization, harvesting, soil erosion and composition, disease prevention, nutrition, crop rotation and marketing. They develop techniques for increasing productivity, and study and develop plans and policies for land and fisheries management.\nTheir tasks include: a) collecting and analyzing data and samples related to produce, feed, soil, water quality and other factors affecting farm, forest or fishery production; b) advising on techniques for improving the production of crops, livestock and fish, and alternative production options; c) advising on livestock and crop disease, control of pests and weeds, soil improvement, animal husbandry and feeding programs; d) studying the environmental factors affecting commercial crop production, pasture growth, animal breeding, fish stocks and the growth and health of forest trees; e) studying the effects of cultivation techniques, soils, insects, diseases and fisheries practices on animal, crop, forestry and fisheries yield; f) studying fish migration, growth, feeding and spawning and devising methods of collecting, fertilizing, incubating and hatching fish eggs; g) researching into characteristics, use capability and productivity of soils and applying findings to development of improved agricultural, horticultural and forestry practices; h) developing procedures and techniques for solving agricultural problems and improving the efficiency of production; i) managing forest and fisheries resources to maximize their long-term commercial, recreational and environmental benefits; j) studying the propagation and culture of forest trees, methods for improving the growth of stock, and the effects of thinning on forest yields; k) investigating, planning and implementing management procedures to cope with the effects of fires, floods, droughts, soil erosion, pests and diseases; and l) preparing scientific reports and conducting advisory information sessions and lectures for farming, forestry and fishing communities and other groups.\nExamples of the occupations classified here: Agriculturist, Agroforester, Agronomist, Aquaculturist, Farming adviser, Fisheries adviser, Forester, Forestry adviser, Forestry scientist, Horticultural scientist, Silviculturist, Soil scientist","version":"2022","source_id":499,"level":4,"normalized_name":"farming forestry and fisheries advisers"},{"code":"2133","parent_code":"213","title":"ENVIRONMENTAL PROTECTION PROFESSIONALS","description":"Environmental protection professionals study and assess the effects on the environment of human activity such as air, water and noise pollution, soil contamination, climate change, toxic waste and depletion and degradation of natural resources. They develop plans and solutions to protect, conserve, restore, minimize and prevent further damage to the environment.\nTheir tasks include: a) Environmental protection professionals study and assess the effects on the environment of human activity such as air, water and noise pollution, soil contamination, climate change, toxic waste and depletion and degradation of natural resources. They develop plans and solutions to protect, conserve, restore, minimize and prevent further damage to the environment; b) conducting research, performing tests, collecting samples, performing field and laboratory analysis to identify sources of environmental problems and recommending ways to prevent, control and remediate the impact of environmental problems; c) assessing the likely impact that potential or proposed activities, projects and developments may have on the environment, and recommending whether such developments should proceed; d) developing and coordinating the implementation of environmental management systems to enable organizations to identify, monitor and control the impact of their activities, products and services on the environment; e) conducting audits to evaluate environmental impact of existing activities, processes, wastes, noises and substances; f) assessing an organization's compliance with government and internal environmental regulations and guidelines, identifying violations and determining appropriate remedial action; g) providing technical advice and support services to organizations on how best to deal with environmental problems in order to reduce environmental damage and minimize financial loss; and h) developing conservation plans.\nExamples of the occupations classified here: Air pollution analyst, Conservation officer, Conservation scientist, Ecologist, Environment quality controller, Environmental adviser, Environmental auditor, Environmental consultant, Environmental impact assessment specialist, Environmental planner, Environmental research scientist, Environmental scientist, Environmentalist, Water quality analyst\n\nSome related occupations classified elsewhere:\nEnvironmental engineer - 2143, Environmental health officer - 2263","version":"2022","source_id":500,"level":4,"normalized_name":"environmental protection professionals"},{"code":"2141","parent_code":"214","title":"INDUSTRIAL AND PRODUCTION ENGINEERS","description":"Industrial and production engineers conduct research and design, organize and oversee the construction, operation and maintenance of process plant and installations. They establish programs for the coordination of manufacturing activities; and assess cost effectiveness and safety.\nTheir tasks include: a) studying functional statements, organizational charts and project information to determine functions and responsibilities of workers and work units and to identify areas of duplication; b) establishing work measurement programs and analyzing work samples to develop standards for labor utilization; c) analyzing workforce utilization, facility layout, operational data and production schedules and costs to determine optimum worker and equipment efficiencies; d) developing specifications for manufacture, and determining materials, equipment, piping, material flows, capacities and layout of plant and systems; e) organizing and managing project labor and the delivery of materials, plant and equipment; f) establishing standards and policies for installation, modification, quality control, testing, inspection and maintenance according to engineering principles and safety regulations; g) inspecting plant to improve and maintain performance; h) directing the maintenance of plant buildings and equipment, and coordinating the requirements for new designs, surveys and maintenance schedules; i) advising management on new production methods, techniques and equipment; and j) liaising with materials buying, storing and controlling departments to ensure a steady flow of supplies.\nExamples of the occupations classified here: Industrial and production plant engineer, Industrial and production quality control engineer, Industrial design engineer, Industrial efficiency engineer, Industrial engineer, Methods engineer, Production engineer, Production planning engineer, Time and motion engineer\nRelated occupation classified elsewhere: Manufacturing production manager - 1321","version":"2022","source_id":501,"level":4,"normalized_name":"industrial and production engineers"},{"code":"2142","parent_code":"214","title":"CIVIL ENGINEERS","description":"Civil engineers conduct research, advise on, design, and direct construction; manage the operation and maintenance of civil engineering structures; or study and advise on technological aspects of particular materials.\nTheir tasks include: a) conducting research and developing new or improved theories and methods related to civil engineering; b) advising on and designing structures such as bridges, dams, docks, roads, airports, railways, canals, pipelines, waste-disposal and flood-control systems, and industrial and other large buildings; c) determining and specifying construction methods, materials and quality standards, and directing construction work; d) establishing control systems to ensure efficient functioning of structures as well as safety and environmental protection; e) organizing and directing maintenance and repair of existing civil engineering structures; f) analyzing the behavior of soil and rock when placed under pressure by proposed structures and designing structural foundations; and g) analyzing the stability of structures and testing the behavior and durability of materials used in their construction.\nExamples of the occupations classified here: Civil engineer, Construction engineer, Construction site engineer, Geotechnical engineer, Hydraulics engineer, Soil mechanics engineer, Structural engineer, Transportation Engineer\nSome related occupations classified elsewhere: Civil engineering project manager - 1323, Geoscientist - 2114, Metallurgist - 2146, Mining engineer - 2146, Town and traffic planners - 2164","version":"2022","source_id":502,"level":4,"normalized_name":"civil engineers"},{"code":"2143","parent_code":"214","title":"ENVIRONMENTAL ENGINEERS","description":"Environmental engineers conduct research, advise on, design and direct implementation of solutions to prevent, control or remedy negative impacts of human activity on the environment utilizing a variety of engineering disciplines. They conduct environmental assessments of construction and civil engineering projects and apply engineering principles to pollution control, recycling and waste disposal.\nTheir tasks include: a) conducting research, assessing and reporting on the environmental impact of existing and proposed construction, civil engineering and other activities; b) inspecting industrial and municipal facilities and programs to evaluate operational effectiveness and ensure compliance with environmental regulations; c) designing and overseeing the development of systems, processes and equipment for control, management, or remediation of water, air, or soil quality; d) providing environmental engineering assistance in network analysis, regulatory analysis, and planning or reviewing database development; e) obtaining, updating, and maintaining plans, permits, and standard operating procedures; f) providing engineering and technical support for environmental remediation and litigation projects, including remediation system design and determination of regulatory applicability; g) monitoring progress of environmental improvement programs; h) advising corporations and government agencies of procedures to follow in cleaning up contaminated sites to protect people and the environment; and i) collaborating with environmental scientists, planners, hazardous waste technicians, engineers from other disciplines, and specialists in law and business to address environmental problems.\nExamples of the occupations classified here: Air pollution control engineer, Environmental analyst, Environmental engineer, Environmental remediation specialist, Wastewater process engineer","version":"2022","source_id":503,"level":4,"normalized_name":"environmental engineers"},{"code":"2144","parent_code":"214","title":"MECHANICAL ENGINEERS","description":"Mechanical engineers conduct research; advise on, design, and direct production of machines, aircraft, ships, machinery and industrial plant, equipment and systems; advise on and direct their functioning, maintenance and repair; or study and advise on mechanical aspects of particular materials, products or processes.\nTheir tasks include: a) advising on and designing machinery and tools for manufacturing, mining, construction, agricultural, and other industrial purposes; b) advising on and designing steam, internal combustion and other non-electric motors and engines used for propulsion of railway locomotives, road vehicles or aircraft, or for driving industrial or other machinery; c) advising on and designing: hulls, superstructures and propulsion systems of ships; mechanical plant and equipment for the release, control and utilization of energy; heating, ventilation and refrigeration systems, steering gear, pumps, and other mechanical equipment; d) advising on and designing airframes, undercarriages and other equipment for aircraft as well as suspension systems, brakes, vehicle bodies and other components of road vehicles; e) advising on and designing non-electrical parts of apparatus or products such as word processors, computers, precision instruments, cameras and projectors; f) establishing control standards and procedures to ensure efficient functioning and safety of machines, machinery, tools, motors, engines, industrial plant, equipment, or systems; and g) ensuring that equipment, operation and maintenance comply with design specifications and safety standards.\nExamples of the occupations classified here: Aeronautical engineer, Aerospace engineer, Agricultural machines engineer, Automotive engineer, Biosystems engineer, Engine designer, Heating, ventilation and aircondition engineer, Industrial machinery and tools engineer, Machinery and equipment maintenance engineer, Marine engineer, Mechanical engineer, Power plant engineer","version":"2022","source_id":504,"level":4,"normalized_name":"mechanical engineers"},{"code":"2145","parent_code":"214","title":"CHEMICAL ENGINEERS","description":"Chemical engineers conduct research and develop, advise on and direct commercial-scale chemical processes and production of various substances and items such as crude oil, petroleum derivatives, food and drink products, medicines, or synthetic materials. They direct maintenance and repair of chemical plant and equipment and study and advise on chemical aspects of particular materials, products or processes.\nTheir tasks include: a) conducting research and advising on, and developing commercial-scale chemical processes to refine crude oil and other liquids or gases, and to produce substances and items such as petroleum derivatives, explosives, food and drink products, medicines, or synthetic materials; b) specifying chemical production methods, materials and quality standards and ensuring that they conform to specifications; c) establishing control standards and procedures to ensure safety and efficiency of chemical production operations and safety of workers operating equipment or working in close proximity to on-going chemical reactions; d) designing chemical plant equipment and devising processes for manufacturing chemicals and products; e) performing tests throughout stages of production to determine degree of control over variables, including temperature, density, specific gravity, and pressure; f) developing safety procedures to be employed; g) preparing estimates of production costs and production progress reports for management; and h) performing laboratory studies of steps in manufacture of new products and testing proposed process in small scale operation such as a pilot plant.\nExamples of the occupations classified here: Chemical engineer, Chemical process engineer, Fuel technologist, Petroleum and natural gas chemical engineer, Plastic technologist, Refinery process engineer","version":"2022","source_id":505,"level":4,"normalized_name":"chemical engineers"},{"code":"2146","parent_code":"214","title":"MINING ENGINEERS, METALLURGISTS AND RELATED PROFESSIONALS","description":"Mining engineers, metallurgists and related professionals conduct research on and design and develop and maintain commercial-scale methods of extracting metals from their ores, or minerals, water, oil or gas from the earth and of developing new alloys, ceramic and other materials, or study and advise on mining or metallurgical aspects of particular materials, products or processes.\nTheir tasks include: a) determining the location and planning the extraction of coal, metallic ores, non-metallic minerals, and building materials, such as stone and gravel; b) determining most suitable methods of efficient mining and extraction, types of machinery to be used, planning layout and directing construction of shafts and tunnels; c) determining drilling site and devising methods of controlling the flow of water, oil or gas from wells; d) planning and directing storage, initial treatment and transportation of water, oil or gas; e) establishing safety standards and procedures and first-aid facilities, especially underground; f) conducting research, developing methods of extracting metals from their ores and advising on their application; g) investigating properties of metals and alloys, developing new alloys and advising on and supervising technical aspects of metal and alloy manufacture and processing; h) maintaining technical liaison and consultancy with other relevant specialists such as geologists and geophysicists; and i) examining deposits or mines to evaluate profitability.\nExamples of the occupations classified here: Coal mining engineer, Extractive metallurgist, Metal mining engineer, Metallurgical engineer, Metallurgist, Mining engineer, Petroleum and natural gas extraction engineer\nSome related occupations classified elsewhere: Geologist - 2114, Geophysicist - 2114","version":"2022","source_id":506,"level":4,"normalized_name":"mining engineers metallurgists and related professionals"},{"code":"2149","parent_code":"214","title":"ENGINEERING PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers engineering professionals not classified elsewhere in minor group 214, Engineering professionals (excluding electrotechnology) or in minor group 215, Electrotechnology engineers. For instance, the group includes those who conduct research, advise on or develop engineering procedures and solutions concerning workplace safety, biomedical engineering, optics, materials, nuclear power generation and explosives.\nTheir tasks include: a) applying knowledge of engineering to the design, development, and evaluation of biological and health systems and products, such as artificial organs, prostheses, and instrumentation; b) designing devices used in various medical procedures, imaging systems such as magnetic resonance imaging, and devices for automating insulin injections or controlling body functions; c) designing components of optical instruments such as lenses, microscopes, telescopes, lasers, optical disc systems and other equipment that utilize the properties of light; d) designing, testing, and coordinating the development of explosive ordnance material to meet military procurement specifications; e) designing and overseeing construction and operation of nuclear reactors and power plants and nuclear fuels reprocessing and reclamation systems; f) designing and developing nuclear equipment such as reactor cores, radiation shielding, and associated instrumentation and control mechanisms; g) assessing damage and providing calculations for marine salvage operations; h) studying and advising on engineering aspects of particular manufacturing processes, such as those related to glass, ceramics, textiles, leather products, wood, and printing; and i) identifying potential hazards and introducing safety procedures and devices.\nExamples of the occupations classified here: Biomedical engineer, Ceramics engineer, Explosive ordinance engineer, Marine salvage engineer, Materials engineer, Optical engineer, Quantity surveyor, Reservoir and drilling engineer, Safety engineer, Sanitary engineer, Satellite engineer, Test engineer","version":"2022","source_id":507,"level":4,"normalized_name":"engineering professionals not elsewhere classified"},{"code":"2151","parent_code":"215","title":"ELECTRICAL ENGINEERS","description":"Electrical engineers conduct research and advise on, design, and direct the construction and operation of electrical systems, components, motors and equipment, and advise on and direct their functioning, maintenance and repair, or study and advise on technological aspects of electrical engineering materials, products and processes. \nTheir tasks include: a) advising on and designing power stations and systems which generate, transmit and distribute electrical power; b) supervising, controlling and monitoring the operation of electrical generation, transmission and distribution systems; c) advising on and designing systems for electrical motors, electrical traction and other equipment, or electrical domestic appliances; d) specifying electrical installation and application in industrial and other buildings and objects; e) establishing control standards and procedures to monitor performance and safety of electrical generating and distribution systems, motors and equipment; and f) determining manufacturing methods for electrical systems, as well as maintenance and repair of existing electrical systems, motors and equipment. \nExamples of the occupations classified here: Electric power generation engineer, Electrical engineer, Electrical failure analysis engineer, Electromechanical engineer, Photovoltaic (PV) system designer, Power distribution and transmission engineer\nSome related occupations classified elsewhere: Broadcast Engineer - 2153, Electronics engineer - 2152, Nuclear power generation engineer - 2149, Telecommunications Engineer - 2153","version":"2022","source_id":508,"level":4,"normalized_name":"electrical engineers"},{"code":"2152","parent_code":"215","title":"ELECTRONICS ENGINEERS","description":"Electronics engineers conduct research on, design, and direct the construction functioning, maintenance and repair of electronic systems and study and advise on technological aspects of electronic engineering materials, products or processes.\nTheir tasks include: a) advising on and designing electronic devices or components, circuits, semi-conductors, and systems; b) specifying production or installation methods, materials and quality standards and directing production or installation work of electronic products and systems; c) establishing control standards and procedures to ensure efficient functioning and safety of electronic systems, motors and equipment; d) organizing and directing maintenance and repair of existing electronic systems and equipment; e) designing electronic circuits and components for use in fields such as aerospace guidance and propulsion control, acoustics, or instruments and controls; f) researching and advising on radar, telemetry and remote control systems, microwaves and other electronic equipment; g) designing and developing signal processing algorithms and implementing these through appropriate choice of hardware and software; and h) developing apparatus and procedures to test electronic components, circuits and systems.\nExamples of the occupations classified here: Computer hardware engineer, Electronic product test engineer, Electronics engineer, Electronics engineering technologist, Instrumentation engineer","version":"2022","source_id":509,"level":4,"normalized_name":"electronics engineers"},{"code":"2153","parent_code":"215","title":"TELECOMMUNICATIONS ENGINEERS","description":"Telecommunications engineers conduct research and advise on, design, and direct the construction functioning, maintenance and repair of telecommunication systems and equipment. They study and advise on technological aspects of telecommunication engineering materials, products or processes.\nTheir tasks include: a) advising on and designing telecommunications devices or components, systems, equipment and distribution centers; b) specifying production or installation methods, materials, quality and safety standards and directing production or installation work of telecommunications products and systems; c) organizing and directing maintenance and repair of existing telecommunication systems, motors and equipment; d) researching and advising on telecommunications equipment; e) planning and designing communications networks based on wired, fiber optical and wireless communication media; f) designing and developing signal processing algorithms and implementing these through appropriate choice of hardware and software; and g) designing telecommunications networks and radio and television distribution systems, including both cable and over the air.\nExamples of the occupations classified here: Broadcast engineer, Radio engineer, Telecommunications engineer, Telecommunications engineering technologist\nRelated occupation classified elsewhere: Electronics engineer - 2152","version":"2022","source_id":510,"level":4,"normalized_name":"telecommunications engineers"},{"code":"2161","parent_code":"216","title":"BUILDING ARCHITECTS","description":"Building architects design commercial, industrial, institutional, residential and recreational buildings and plan and monitor their construction, maintenance and rehabilitation.\nTheir tasks include: a) developing new or improved architectural theories and methods; b) inspecting sites and consulting clients, management and other stakeholders to determine type, style and size of proposed buildings and alterations to existing buildings; c) providing information regarding designs, materials and estimated building times; d) preparing project documentation, including sketches and scale drawings, and integrating structural, mechanical and aesthetic elements in final designs; e) writing specifications and contract documents for use by builders and calling tenders on behalf of clients; f) making necessary contacts to ensure feasibility of projects regarding style, cost, timing, and compliance with regulations; g) identifying and finding best solutions for problems regarding function and quality of interior environments of buildings and making necessary designs, drawings and plans; h) monitoring construction or rehabilitation work to ensure compliance with specifications and quality standards; and i) maintaining technical liaison and consultancy with other relevant specialists.\nExamples of the occupations classified here: Building architect, Interior architect\nSome related occupations classified elsewhere: Interior decorator - 3432, Interior designer - 3432, Landscape architect - 2162","version":"2022","source_id":511,"level":4,"normalized_name":"building architects"},{"code":"2162","parent_code":"216","title":"LANDSCAPE ARCHITECTS","description":"Landscape architects plan and design landscapes and open spaces for projects such as, parks, schools, institutions, roads, external areas for commercial, industrial and residential sites, and plan and monitor their construction, maintenance and rehabilitation.\nTheir tasks include: a) developing new or improved theories and methods in landscape architecture; b) inspecting sites and consulting clients, management and other stakeholders to determine type, style and size of proposed buildings, parks, roads and other open spaces; c) compiling and analyzing site and community data about geographical and ecological features, landforms, soils, vegetation, site hydrology, visual characteristics and human-made structures, to formulate land use and development recommendations, and for preparing environmental impact statements; d) preparing reports, site plans, working drawings, specifications and cost estimates for land development, showing location and details of proposals, including ground modeling, structures, vegetation and access; e) writing specifications and contract documents for use by builders and civil engineering contractors and calling tenders on behalf of clients; f) making necessary contacts to ensure feasibility of projects regarding style, cost, timing, and compliance with regulations; g) identifying and finding best solutions for problems regarding function and quality of exterior environments and making necessary designs, drawings and plans; h) monitoring construction or rehabilitation work to ensure compliance with specifications and quality standards; and i) maintaining technical liaison and consultancy with other relevant specialists.\nExample of occupation classified here: Landscape architect \nSome related occupations classified elsewhere: Building architect - 2161, Urban planner - 2164","version":"2022","source_id":512,"level":4,"normalized_name":"landscape architects"},{"code":"2163","parent_code":"216","title":"PRODUCT AND GARMENT DESIGNERS","description":"Product and garment designers design and develop products for manufacture and prepare designs and specifications of products for mass, batch and one-off production.\nTheir tasks include: a) determining the objectives and constraints of the design brief by consulting with clients and stakeholders; b) formulating design concepts for clothing, textiles, industrial, commercial and consumer products, and jewelry; c) harmonizing aesthetic considerations with technical, functional, ecological and production requirements; d) preparing sketches, diagrams, illustrations, plans, samples and models to communicate design concepts; e) negotiating design solutions with clients, management, and sales and manufacturing staff; f) selecting, specifying and recommending functional and aesthetic materials, production methods and finishes for manufacture; g) detailing and documenting the selected design for production; h) preparing and commissioning prototypes and samples; and i) supervising the preparation of patterns, programs and tooling, and the manufacturing process.\nExamples of the occupations classified here: Costume designer, Fashion designer, Garment designer, Industrial designer, Jewelry designer\nSome related occupations classified elsewhere: Engine designer - 2144, Interior designer - 3432","version":"2022","source_id":513,"level":4,"normalized_name":"product and garment designers"},{"code":"2164","parent_code":"216","title":"TOWN AND TRAFFIC PLANNERS","description":"Town and traffic planners develop and implement plans and policies for the controlled use of urban and rural land and for traffic systems. They conduct research and provide advice on economic, environmental and social factors affecting land use and traffic flows.\nTheir tasks include: a) planning layout and coordinating development of urban areas; b) compiling and analyzing data on economic, legal, political, cultural, demographic, sociological, physical and environmental factors affecting land use; c) conferring with government authorities, communities and specialists in fields such as architecture, planning, social science the environment and the law; d) devising and recommending use and development of land, and presenting narrative and graphic plans, programs and designs to groups and individuals; e) advising governments, companies and communities on urban and regional planning issues and proposals; f) reviewing and evaluating environmental impact reports; g) planning layout and coordinating development of urban areas; h) planning and the development of land areas for parks, schools, institutions, airports, roadways and related projects, and for commercial, industrial and residential sites; and i) planning and advising on routing and control of road traffic and public transportation systems for efficiency and safety.\nExamples of the occupations classified here: City planner, Land plannerTown planner, Traffic planner, Urban planner","version":"2022","source_id":514,"level":4,"normalized_name":"town and traffic planners"},{"code":"2165","parent_code":"216","title":"CARTOGRAPHER AND SURVEYORS","description":"Cartographers and surveyors determine the exact position of, or prepare and revise digital, graphic and pictorial maps, charts or other visual representation of, natural and constructed features and boundaries of land, seas, underground areas and celestial bodies, applying scientific and mathematical principles.\nTheir tasks include: a) surveying, measuring and describing land surfaces, mines, underground surfaces, sea, river and lake beds; b) noting exact position of various features and recording survey data in digital form; c) making charts and maps to be used in determining navigable waters and channels and in planning construction of marine structures; d) planning and conducting aerial photographic surveys; e) designing, compiling and revising maps and charts using aerial and other photographs, satellite imagery, survey documents and data, existing maps and records, reports and statistics; f) undertaking research and development of surveying and photogrammetric measurement systems, cadastral systems and land information systems; g) studying and advising on technical, aesthetic and economic aspects of map production; and h) maintaining technical liaison and consultancy with other relevant specialists.\nExamples of the occupations classified here: Aerial surveyor, Cadastral surveyor, Cartographer, Geodesist, Hydrographic surveyor, Land surveyor, Mine surveyor, Photogrammetrist\nSome related occupations classified elsewhere: Building surveyor - 3112, Marine surveyor - 3115, Quantity surveyor- 2149","version":"2022","source_id":515,"level":4,"normalized_name":"cartographer and surveyors"},{"code":"2166","parent_code":"216","title":"GRAPHIC AND MULTIMEDIA DESIGNERS","description":"Graphic and multimedia designers design information content for visual and audio communication, publication and display using print, film, electronic, digital and other forms of visual and audio media. They create special effects, animation, or other visual images for use in computer games, movies, music videos, print media and advertisements.\nTheir tasks include: a) determining the objectives and constraints of the design brief by consulting with clients and stakeholders; b) undertaking research and analyzing functional communication requirements; c) formulating design concepts for the subject to be communicated; d) preparing sketches, diagrams, illustrations and layouts to communicate design concepts; e) designing complex graphics and animation to satisfy functional, aesthetic and creative requirements of the design brief; f) creating two-dimensional and three-dimensional images depicting objects in motion or illustrating a process, using computer animation or modeling programs; g) negotiating design solutions with clients, management, sales and production staff; h) selecting, specifying or recommending functional and aesthetic materials and media for publication, delivery or display; i) detailing and documenting the selected design for production; and j) supervising or carrying out production in the chosen media.\nExamples of the occupations classified here: 2D animators, 2D designers, 3D animators, 3D designers, Animator, Caricature artists, Computer games designer, Digital artist, Illustrator, Infographic designers, Multimedia designer, Publication designer, Website designer\nSome related occupations classified elsewhere: Interior architect - 2161, Interior designer - 3432, Multimedia developer - 2513, Visual artist - 2651, Web developer - 2513","version":"2022","source_id":516,"level":4,"normalized_name":"graphic and multimedia designers"},{"code":"2211","parent_code":"221","title":"GENERALIST MEDICAL PRACTIONERS","description":"Generalist medical practitioners diagnose, treat and prevent illness, disease, injury, and other physical and mental impairments and maintain general health in humans through application of the principles and procedures of modern medicine. They do not limit their practice to certain disease categories or methods of treatment, and may assume responsibility for the provision of continuing and comprehensive medical care to individuals, families and communities.\nTheir tasks include: a) conducting physical examinations of patients and interviewing them and their families to determine their health status; b) ordering laboratory tests, X-rays and other diagnostic procedures and analyzing findings to determine the nature of disorders or illnesses; c) providing continuing medical care for patients including prescribing, administering, counselling on and monitoring curative treatments and preventive measures; d) performing surgery and other clinical procedures; e) advising individuals, families and communities on health, nutrition and lifestyle which aid prevention or treatment of disease and disorders; f) providing referrals to patients and families for specialized care in hospitals, rehabilitation centers or other types of health care centers; g) identifying, managing and providing referrals for complications before, during and after childbirth; h) recording patients' medical information and history and exchanging information with specialist practitioners and other health workers as required for continuing medical care; i) reporting births, deaths and notifiable diseases to government authorities to meet legal and professional requirements; j) conducting research in human health and medical services and disseminating the findings such as through scientific reports; and k) planning and participating in programs designed to prevent the occurrence and spread of common diseases.\nExamples of the occupations classified here: District medical doctor - therapist, Family medical practitioner, Medical doctor, Medical officer, Medical practitioner, Physician, Primary health care physician, Resident medical officer specializing in general practice\nSome related occupations classified elsewhere: Clinical officer - 2240, Internal medicine physician - 2212, Psychiatrist - 2212, Surgeon - 2212","version":"2022","source_id":517,"level":4,"normalized_name":"generalist medical practioners"},{"code":"2212","parent_code":"221","title":"SPECIALIST MEDICAL PRACTITIONERS","description":"Specialist medical practitioners diagnose, treat and prevent illness, disease, injury, and other physical and mental impairments in humans, using specialized testing, diagnostic, medical, surgical, physical and psychiatric techniques, through application of the principles and procedures of modern medicine. They specialize in certain disease categories, types of patient or methods of treatment and may conduct medical education and research in their chosen areas of specialization.\nTheir tasks include: a) conducting physical examinations of patients and interviewing them and their families to determine their health status; b) considering medical information provided by a referring doctor or other health care provider; c) ordering specialized diagnostic tests to determine the nature of disorders or illnesses; d) prescribing, administering and monitoring patients' responses to treatments, medications, anesthetics, psychotherapies, physical rehabilitation programmes and other preventive and curative measures;e) performing surgery of a general or specialized nature; f) managing complications before, during and after childbirth; g) recording patients' medical information and exchanging information with other health professionals to ensure the provision of comprehensive care; h) reporting births, deaths and notifiable diseases to government authorities to meet legal and professional requirements; i) providing information to patients and families and communities about preventive measures, treatment and care for specific ailments; j) performing autopsies to determine cause of death; k) conducting research into specific human disorders and illnesses and preventive or curative methods and disseminating the findings such as through scientific reports; and l) planning and participating in programs designed to prevent the occurrence and spread of specific diseases.\nExamples of the occupations classified here: Allergologist, Anesthesiologist, Anesthetist, Cardiologist, Dermatologist, Ear, Nose, and Throat (ENT) physician, Emergency medicine specialist, Emergency physician, Forensic pathologist, Gynecologist, Infectious diseases specialist, Internal medicine physician, Medical pathologist, Medical specialist practitioner, Nephrologist, Neurologist, Neurosurgeon, Obstetrician, Oncologist, Ophthalmologist, Pathologist, Pediatrician, Preventive medicine specialist, Psychiatrist, Radiologist, Resident medical officer in specialist training, Rheumatologist, Surgeon, Urologist\nSome related occupations classified elsewhere: Biomedical researcher - 2131, Clinical psychologist - 2634, Dental practitioner - 2261, Dental surgeon - 2261, General practitioner - 2211, Oral and maxillofacial surgeon - 2261, Resident medical officer specializing in general practitioner - 2211","version":"2022","source_id":518,"level":4,"normalized_name":"specialist medical practitioners"},{"code":"2221","parent_code":"222","title":"NURSING PROFESSIONALS","description":"Nursing professionals provide treatment, support and care services for people who are in need of nursing care due to the effects of ageing, injury, illness or other physical or mental impairment, or potential risks to health. They assume responsibility for the planning and management of the care of patients, including the supervision of other health care workers, working autonomously or in teams with medical doctors and others in the practical application of preventive and curative measures. \nTheir tasks include: a) planning, providing and evaluating nursing care for patients according to the practice and standards of modern nursing; b) coordinating the care of patients in consultation with other health professionals and members of health teams; c) developing and implementing care plans for the biological, social, and psychological treatment of patients in collaboration with other health professionals; d) planning and providing personal care, treatments and therapies including administering medications, and monitoring responses to treatment or care plan; e) cleaning wounds and applying surgical dressings and bandages; f) monitoring pain and discomfort experienced by patients and alleviating pain using a variety of therapies, including the use of pain-killing drugs; g) planning and participating in health education programmes, health promotion and nurse education activities in clinical and community settings; h) answering questions from patients and families and providing information about prevention of ill-health, treatment and care; i) supervising and coordinating the work of other nursing, health and personal care workers; and j) conducting research on nursing practices and procedures and disseminating findings such as through scientific papers and reports.\nExamples of the occupations classified here: Anesthetic nurse, Audiometry nurse, Cardiovascular nurse, Chemotherapy nurse, Clinical consultant nurse, Clinical nurse, Company nurse, Coronary nurse, Cosmetic nurse, Dental nurse, Dermatological nurse, Dialysis nurse, District nurse, Emergency nurse, Endocrinology nurse, ENT nurse, Fertility nurse, Geriatric nurse, Hematology nurse, Hemodialysis nurse, Home health care nurse, Independent nurse practitioner, Industrial nurse, Intensive care unit nurse, Labor and delivery nurse, Medical ward nurse, Medico-legal nurse, Neonatal nurse, Neurology/neurosurgeon nurse, Nurse educator, Nurse practitioner, Obstetrics and gynecology (OB-GYN) nurse, Occupational health nurse, Oncology nurse, Ophthalmology nurse, Orthopedic nurse, Pain clinic and oncology nurse, Paramedic nurse, Pediatric nurse, Psychiatric nurse, Public health nurse, Pulmonary/respiratory nurse, Radiation therapy nurse, Radiotherapeutic nurse, School nurse, Surgical nurse, Urology nurse\nSome related occupations classified elsewhere: Associate professional midwife - 3222, Associate professional nurse - 3221, Clinic or hospital nursing aide - 5321, Paramedical practitioner - 2240, Professional midwife - 2222","version":"2022","source_id":519,"level":4,"normalized_name":"nursing professionals"},{"code":"2222","parent_code":"222","title":"MIDWIFERY PROFESSIONALS","description":"Midwifery professionals plan, manage, provide and evaluate midwifery care services before, during and after pregnancy and childbirth. They provide delivery care for reducing health risks to women and newborn children, working autonomously or in teams with other health care providers.\nTheir tasks include: a) planning, providing and evaluating care and support services for women and babies before, during and after pregnancy and childbirth according to the practice and standards of modern midwifery care; b) providing advice to women and families and conducting community education on health, nutrition, hygiene, exercise, birth and emergency plans, breastfeeding, infant care, family planning and contraception, lifestyle and other topics related to pregnancy and childbirth; c) assessing progress during pregnancy and childbirth, managing complications and recognizing warning signs requiring referral to a medical doctor with specialized skills in obstetrics; d) monitoring the health status of newborns, managing complications and recognizing warning signs requiring referral to a medical doctor with specialized skills in neonatology; e) monitoring pain and discomfort experienced by women during labor and delivery and alleviating pain using a variety of therapies, including the use of pain-killing drugs; f) reporting births to government authorities to meet legal and professional requirements; g) conducting research on midwifery practices and procedures and disseminating findings such as through scientific papers and reports; and h) planning and conducting midwifery education activities in clinical and community settings.\nExample of occupation classified here: Professional midwife \nSome related occupations classified elsewhere: Associate professional midwife - 3222, Associate professional nurse - 3221, Clinic or hospital nursing aide - 5321, Professional nurse - 2221","version":"2022","source_id":520,"level":4,"normalized_name":"midwifery professionals"},{"code":"2230","parent_code":"223","title":"TRADITIONAL AND COMPLEMENTARY MEDICINE PROFESSIONALS","description":"Traditional and complementary medicine professionals prevent, diagnose and treat illness, disease, injury, and other physical and mental impairments and maintain general health in humans by applying knowledge, skills and practices acquired through extensive study of the theories, beliefs and experiences, originating in specific cultures.\nTheir tasks include: a) conducting physical examinations of patients and interviewing them and their families to determine their health status; b) developing and implementing treatment plans for physical, mental and psychosocial ailments using applications such as acupuncture, ayurvedic, homoeopathic and herbal medicine; c) evaluating and documenting patients' progress through treatment plans; d) providing health, nutrition and lifestyle advice to individuals, families and communities; e) prescribing and preparing traditional medicines, such as herbal, plant, mineral and animal extracts, to stimulate the body's capacity for self-healing; f) exchanging information about patients with other health care workers as needed to ensure continuing and comprehensive health care; and g) conducting research into traditional and complementary medicines and treatments and disseminating findings such as through scientific papers and reports.\nExamples of the occupations classified here: Acupuncturist, Ayuverdic practitioner, Chinese herbal medicine practitioner, Homeopath, Naturopath, Unani practitioner","version":"2022","source_id":521,"level":4,"normalized_name":"traditional and complementary medicine professionals"},{"code":"2240","parent_code":"224","title":"PARAMEDICAL PRACTITIONERS","description":"Paramedical practitioners provide advisory, diagnostic, curative and preventive medical services for humans more limited in scope and complexity than those carried out by medical doctors. They work autonomously or with limited supervision of medical doctors, and apply advanced clinical procedures for treating and preventing diseases, injuries and other physical or mental impairments common to specific communities.\nTheir tasks include: a) conducting physical examinations of patients and interviewing them and their families to determine their health status, and recording patients' medical information; b) performing basic or more routine medical and surgical procedures, including prescribing and administering treatments, medications and other preventive or curative measures, especially for common diseases and disorders; c) administering or ordering diagnostic tests, such as x-ray, electrocardiogram, and laboratory tests; d) performing therapeutic procedures, such as injections, immunizations, suturing and wound care, and infection management; e) assisting medical doctors with complex surgical procedures; f) monitoring patients' progress and response to treatment, and identifying signs and symptoms requiring referral to medical doctors; g) advising patients and families on diet, exercise and other habits which aid prevention or treatment of disease and disorders; h) identifying and referring complex or unusual cases to medical doctors, hospitals or other places for specialized care; and i) reporting births, deaths and notifiable diseases to government authorities to meet legal and professional reporting requirements.\nExamples of the occupations classified here: Advanced care paramedic, Feldsher, Paramedic clinical officer, Primary care paramedic, Surgical technician\nSome related occupations classified elsewhere: Emergency paramedic - 3258, General practitioner - 2211, Medical assistant - 3256, Surgeon - 2212","version":"2022","source_id":522,"level":4,"normalized_name":"paramedical practitioners"},{"code":"2250","parent_code":"225","title":"VETERINARIANS","description":"Veterinarians diagnose, prevent and treat diseases, injuries and dysfunctions of animals. They may provide care to a wide range of animals or specialize in the treatment of a particular animal group or in a particular specialty area, or provide professional services to commercial firms producing biological and pharmaceutical products.\nTheir tasks include: a) determining the presence and nature of abnormal conditions by physical examination, laboratory testing and through diagnostic imaging techniques including radiography and ultrasound; b) treating animals medically and surgically, and administering and prescribing drugs, analgesics, and general and local anesthetics; c) performing surgery, dressing wounds and setting broken bones; d) rendering obstetric and dental services to animals; e) participating in programs designed to prevent the occurrence and spread of animal diseases; f) inoculating animals against, and testing for, infectious diseases and notifying authorities of outbreaks of infectious animal diseases; g) performing autopsies to determine cause of death; h) advising clients on health, nutrition and feeding, hygiene, breeding and care of animals; and i) providing euthanasia services for animals.\nExamples of the occupations classified here: Animal nutritionist, Animal pathologist, Public health veterinarian, Veterinarian, Veterinary epidemiologist, Veterinary intern, Veterinary surgeon","version":"2022","source_id":523,"level":4,"normalized_name":"veterinarians"},{"code":"2261","parent_code":"226","title":"DENTISTS","description":"Dentists diagnose, treat and prevent diseases, injuries and abnormalities of the teeth, mouth, jaws and associated tissues by applying the principles and procedures of modern dentistry. They use a broad range of specialized diagnostic, surgical and other techniques to promote and restore oral health.\nTheir tasks include: a) diagnosing diseases, injuries, irregularities and malformations of teeth and associated structures in the mouth and jaw using a range of methods such as radiographs, salivary tests and medical histories; b) providing preventative oral health care such as periodontal treatments, fluoride applications and oral health promotion; c) administering anesthetics to limit the amount of pain experienced by patients during procedures; d) prescribing medication for relief of ongoing pain after procedures; e) providing restorative oral care such as implants, complex crown and bridge restorations, and orthodontics, and repairing damaged and decayed teeth; f) providing surgical treatments such as extraction of teeth, biopsy of tissue, and performing orthodontic treatment; g) measuring and taking impressions of patients' jaws and teeth in order to determine the shape and size of dental prostheses; h) designing, making, and fitting prosthodontic appliances such as space maintainers, bridges, and dentures, or writing fabrication instructions or prescriptions for dental prosthetic technicians; i) restoring oral function with removable and fixed oral prostheses; j) educating patients and families on dental hygiene, nutrition and other measures to take care of oral health; and k) supervising dental hygienists, dental assistants and other staff.\nExamples of the occupations classified here: Dental practitioner, Dental surgeon, Dentist, Endodontist, Oral and maxillofacial surgeon, Oral pathologist, Orthodontist, Pedodontist, Periodontist, Prosthodontist","version":"2022","source_id":524,"level":4,"normalized_name":"dentists"},{"code":"2262","parent_code":"226","title":"PHARMACISTS","description":"Pharmacists store, preserve, compound, and dispense medicinal products and counsel on the proper use and adverse effects of drugs and medicines following prescriptions issued by medical doctors and other health professionals. They contribute to researching, testing preparing, prescribing and monitoring medicinal therapies for optimizing human health.\nTheir tasks include: a) receiving prescriptions for medicinal products from medical doctors and other health professionals, checking patients' medicine histories, and ensuring proper dosage and methods of administration and drug compatibility before dispensing; b) preparing or supervising the preparation and labelling of liquid medicines, ointments, powders, tablets and other medications to fill prescriptions; c) providing information and advice to prescribers and clients regarding drug interactions, incompatibility and contra-indications, side effects, dosage and proper medication storage; d) collaborating with other health care professionals to plan, monitor, review, and evaluate the quality and effectiveness of the medicine therapy of individual patients, and the effectiveness of particular drugs or therapies; e) maintaining prescription files and recording issue of narcotics, poisons and habit-forming drugs in accordance with legal and professional requirements; f) storing and preserving vaccines, serums and other drugs subject to deterioration; g) advising clients on and supplying non-prescription medicines and diagnostic and therapeutic aids for common conditions; h) supervising and coordinating the work of pharmacy technicians, pharmacy interns and pharmacy sales assistants; i) conducting research to develop and improve pharmaceuticals, cosmetics and related chemical products; j) conferring with chemists, engineering professionals and other professionals about manufacturing techniques and ingredients; k) testing and analyzing drugs to determine their identity, purity and strength in relation to specified standards; l) evaluating labels, packaging and advertising of drug products; and m) developing information and risks of particular drugs.\nExamples of the occupations classified here: Dispensing chemist, Hospital pharmacist, Industrial pharmacist, Pharmacist, Retail pharmacist\nSome related occupations classified elsewhere: Pharmaceutical chemist 2113, Pharmaceutical technician - 3213, Pharmacologist - 2131","version":"2022","source_id":525,"level":4,"normalized_name":"pharmacists"},{"code":"2263","parent_code":"226","title":"ENVIRONMENTAL AND OCCUPATIONAL HEALTH AND HYGIENE PROFESSIONALS","description":"Environmental and occupational health and hygiene professionals assess, plan and implement programs to recognize, monitor and control environmental factors that can potentially affect human health, to ensure safe and healthy working conditions, and to prevent disease or injury caused by chemical, physical, radiological and biological agents or ergonomic factors.\nTheir tasks include: a) developing, implementing and reviewing programs and policies to minimize potential environmental and occupational risks to health and safety; b) preparing and implementing plans and strategies for the safe, economic and suitable disposal of commercial, industrial, medical and household wastes; c) implementing prevention programs and strategies for communicable diseases, food safety, waste water treatment and disposal systems, recreation and domestic water quality, contaminated and hazardous substances; d) identifying, reporting and documenting hazards, and assessing and controlling risks in the environment and workplace and advising on compliance with relevant law and regulations; e) developing, implementing and monitoring programs to minimize workplace and environmental pollution involving chemical, physical and biological hazards; f) advising methods to prevent, eliminate, control, or reduce the exposure of workers, students, the public and the environment to radiological and other hazards; g) promoting ergonomic principles within the workplace such as matching furniture, equipment and work activities to the needs of employees; h) providing education, information, training, and advice to persons at all levels on aspects of occupational hygiene and environmental health; i) recording and investigating injuries and equipment damage, and reporting safety performance; and j) coordinating arrangements for the compensation, rehabilitation and return to work of injured workers.\nExamples of the occupations classified here: Environmental health officer, Occupational health and safety adviser, Occupational hygienist, Radiation protection expert\nSome related occupations classified elsewhere: Environmental protection professional - 2133, Health inspector - 3257, Occupational health and safety inspector - 3257, Occupational therapist - 2269, Sanitarian - 3257, Sanitary inspector - 3257, Specialist medical practitioner in public health - 2212, Specialist nurse in public health - 2221","version":"2022","source_id":526,"level":4,"normalized_name":"environmental and occupational health and hygiene professionals"},{"code":"2264","parent_code":"226","title":"PHYSIOTHERAPIST","description":"Physiotherapists assess, plan and implement rehabilitative programs that improve or restore human motor functions, maximize movement ability, relieve pain syndromes, and treat or prevent physical challenges associated with injuries, diseases and other impairments. They apply a broad range of physical therapies and techniques such as movement, ultrasound, heating, laser and other techniques.\nTheir tasks include: a) administering muscle, nerve, joint and functional ability tests to identify and assess physical problems of patients; b) establishing treatment goals with patients and designing treatment programs to reduce physical pain, strengthen muscles, improve cardiothoracic, cardiovascular and respiratory functions, restore joint mobility, and improve balance and coordination; c) developing, implementing and monitoring programs and treatments using the therapeutic properties of exercise, heat, cold, massage, manipulation, hydrotherapy, electrotherapy, ultraviolet and infra-red light and ultrasound in the treatment of patients; d) instructing patients and their families in procedures to be continued outside clinical settings; e) recording information on patients' health status and responses to treatment in medical records-keeping systems, and sharing information with other health professionals as required to ensure continuing and comprehensive care; f) developing and implementing programmes for screening and prevention of common physical ailments and disorders; and g) supervising the work of physiotherapy assistants and others.\nExamples of the occupations classified here: Geriatric physical therapist, Orthopedic physical therapist, Pediatric physical therapist, Physical therapist, Physiotherapist\nSome related occupations classified elsewhere: Acupressure therapist - 3255, Chiropractor - 3259, Hydrotherapist - 3255, Massage therapist - 3255, Occupational therapist - 2269, Osteopath - 3259, Physiotherapy technician - 3255, Podiatrist - 2269, Shiatsu therapist - 3255","version":"2022","source_id":527,"level":4,"normalized_name":"physiotherapist"},{"code":"2265","parent_code":"226","title":"DIETICIANS AND NUTRITIONIST","description":"Dieticians and nutritionists assess, plan and implement programs to enhance the impact of food and nutrition on human health.\nTheir tasks include: a) instructing individuals, families and communities on nutrition, the planning of diets and preparation of food to maximize health benefits and reduce potential risks to health; b) planning diets and menus, supervising the preparation and serving of meals, and monitoring food intake and quality to provide nutritional care in settings offering food services; c) compiling and assessing data relating to health and nutritional status of individuals, groups and communities based on nutritional values of food served or consumed; d) planning and conducting nutrition assessments, intervention programmes, and education and training to improve nutritional levels among individuals and communities; e) consulting with other health professionals and care providers to manage the dietary and nutritional needs of patients; f) developing and evaluating food and nutrition products to meet nutritional requirements; and g) conducting research on nutrition and disseminating the findings at scientific conferences and in other settings.\nExamples of the occupations classified here: Clinical dietician, Dietetic consultant, Dietician, Food and nutrition specialist, Food service dietician, Nutritionist, Public health nutritionist, Public health nutritionist, Sports nutritionist, Therapeutic/clinic dietician","version":"2022","source_id":528,"level":4,"normalized_name":"dieticians and nutritionist"},{"code":"2266","parent_code":"226","title":"AUDIOLOGISTS AND SPEECH THERAPIST","description":"Audiologists and speech therapists evaluate, manage and treat physical disorders affecting human hearing, speech, communication and swallowing. They prescribe corrective devices or rehabilitative therapies for hearing loss, speech disorders, and related sensory and neural problems and provide counselling on hearing safety and communication performance. \nTheir tasks include: a) evaluating hearing, speech and language performance in patients to determine the nature of hearing and communication disorders; b) administering hearing or speech/language tests or other examinations using specialized diagnostic instruments and equipment, and interpreting test results alongside other medical, social and behavioral diagnostic data to determine appropriate courses of treatment; c) planning, directing and participating in counselling, screening, speech rehabilitation and other programs related to hearing and communication; d) prescribing hearing aids and other assistive devices according to patients’ needs and instructing them in their use; e) planning and conducting treatment programs to manage physical disorders affecting speech and swallowing in patients such as stuttering and feeding disorders; f) counselling and guiding hearing and/or language-impaired individuals, their families, teachers and employers; and g) referring patients and families to additional medical or educational services if needed.\nExamples of the occupations classified here: Audiologist, Language therapist, Speech pathologist, Speech therapist","version":"2022","source_id":529,"level":4,"normalized_name":"audiologists and speech therapist"},{"code":"2267","parent_code":"226","title":"OPTOMETRISTS AND OPTHALMIC OPTICIANS","description":"Optometrists and ophthalmic opticians provide diagnosis, management and treatment services for disorders of the eyes and visual system. They counsel on eye care and prescribe optical aids or other therapies for visual disturbance.\nTheir tasks include: a) examining patients’ eyes and conducting diagnostic tests to assess ocular health and determine the nature and extent of vision problems and abnormalities; b) testing visual function using specialized instruments and equipment for measuring visual acuity and refractive error, function of visual pathways, visual fields, eye movements, freedom of vision and intraocular pressure; c) detecting, diagnosing and managing eye disease, including prescribing medications for the treatment of eye disease; d) consulting with and referring patients to ophthalmologists or other health professionals if additional medical treatment is necessary; e) detecting and diagnosing eye movement disorders and defects of binocular function, and planning and managing treatment programs, including counselling patients in eye exercises to coordinate movement and focusing of eyes; f) prescribing corrective eyeglasses, contact lenses and other vision aids, and checking optical devices for performance, safety, comfort and lifestyle; and g) advising on visual health matters such as contact lens care, vision care for the elderly, optics, visual ergonomics, and occupational and industrial eye safety.\nExamples of the occupations classified here: Ophthalmic optician, Optometrist, Orthoptist\nSome related occupations classified elsewhere: Dispensing optician - 3254, Ophthalmologist - 2212","version":"2022","source_id":530,"level":4,"normalized_name":"optometrists and opthalmic opticians"},{"code":"2269","parent_code":"226","title":"HEALTH PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers health professionals not classified elsewhere in sub-major group 22, Health professionals. For instance, the group includes occupations such as podiatrist, occupational therapist and other health professionals. \nTheir tasks include: a) interviewing patients and conducting diagnostic tests to determine their health status and the nature of physical or mental disorders, illnesses or other health problems; b) developing and implementing treatment plans for injuries, illnesses and other physical and mental impairments; c) evaluating and documenting patients' progress through treatment plans, and referring patients and families to medical doctors or other health care providers for specialized, rehabilitative or other care services as needed; d) assessing functional limitations of clients resulting from illness, disability or other impairment, and providing therapy; e) recommending environmental adaptations in the home, leisure, work and school environments on an individual or group basis to enable them to perform their daily activities and occupations; f) planning and implementing therapeutic programs on an individual and group basis for improving and maintaining physical, cognitive, emotional and social functioning, including through the use of arts and crafts, dance and movement, music and other recreational activities; g) identifying and prescribing treatments for conditions affecting the foot, ankle and related structures of the leg due to illness, disease or other physical impairment, and prescribing corrective footwear and advising on foot care to manage foot ailments; and h) performing minor surgical procedures such as on the foot and ankles.\nExamples of the occupations classified here: Arts therapist, Dance and movement therapist, Occupational therapist, Podiatrist, Pulmonary or respiratory therapist, Recreational therapist","version":"2022","source_id":531,"level":4,"normalized_name":"health professionals not elsewhere classified"},{"code":"2310","parent_code":"231","title":"UNIVERSITY AND HIGHER EDUCATION TEACHERS","description":"University and higher education teachers prepare and deliver lectures and conduct tutorials in one or more subjects within a prescribed course of study at a university or other higher educational institution. They conduct research, and prepare scholarly papers and books. \nTheir tasks include: a) designing and modifying curricula and preparing courses of study in accordance with requirements; b) preparing and delivering lectures and conducting tutorials, seminars and laboratory experiments; c) stimulating discussion and independent thought among students; d) supervising, where appropriate, experimental and practical work undertaken by students; e) administering, evaluating and marking examination papers and tests; f) directing research of post-graduate students or other members of department; g) researching into and developing concepts, theories and operational methods for application in industrial and other fields; h) preparing scholarly books, papers or articles; and i) participating in departmental and faculty meetings and in conferences and seminars.\nExamples of the occupations classified here: Assistant professor, College professor, Information technology professor, Professor, University lecturer\nSome related occupations classified elsewhere: Dean - 1345, Higher education faculty head - 1345, University chancellor - 1120, Vocational education teacher - 2320","version":"2022","source_id":532,"level":4,"normalized_name":"university and higher education teachers"},{"code":"2320","parent_code":"232","title":"VOCATIONAL EDUCATION TEACHERS","description":"Vocational education teachers teach or instruct vocational or occupational subjects in adult and further education institutions and to senior students in secondary schools and colleges. They prepare students for employment in specific occupations or occupational areas for which university or higher education is not normally required.\nTheir tasks include: a) developing curricula and planning course content and methods of instruction; b) determining training needs of students or workers and liaising with individuals, industry and other education sectors to ensure provision of relevant education and training programs; c) presenting lectures and conducting discussions to increase students' knowledge and competence; d) instructing and monitoring students in the use of tools, equipment and materials and the prevention of injury and damage; e) observing and evaluating students' work to determine progress, provide feedback, and make suggestions for improvement; f) administering oral, written or performance tests to measure progress, evaluate training effectiveness and assess competency; g) preparing reports and maintaining records such as student grades, attendance rolls, and training activity details; h) supervising independent or group projects, field placements, laboratory work, or other training; i) providing individualized instruction and tutorial or remedial instruction; and j) conducting on-the-job training sessions to teach and demonstrate principles, techniques, procedures, or methods of designated subjects.\nExamples of the occupations classified here: Automotive technology instructor, Cosmetology instructor, Vocational education teacher\nRelated occupation classified elsewhere: Secondary education teacher - 2330","version":"2022","source_id":533,"level":4,"normalized_name":"vocational education teachers"},{"code":"2330","parent_code":"233","title":"SECONDARY EDUCATION TEACHERS","description":"Secondary education teachers teach one or more subjects at secondary education level, excluding subjects intended to prepare students for employment in specific occupational areas.\nTheir tasks include: a) designing and modifying curricula and preparing educational courses of study in accordance with curriculum guidelines; b) establishing and enforcing rules for behavior and procedures for maintaining order among students; c) preparing and giving lessons, discussions, and demonstrations in one or more subjects; d) establishing clear objectives for all lessons, units, and projects and communicating those objectives to students; e) preparing materials and classrooms for class activities; f) adapting teaching methods and instructional materials to meet students' varying needs and interests; g) observing and evaluating students’ performance and behavior; h) preparing, administering and marking tests, assignments and examinations to evaluate pupils' progress; i) preparing reports about pupils' work and conferring with other teachers and parents; j) participating in meetings concerning the school's educational or organizational policies; and k) planning, organizing and participating in school activities such as excursions, sporting events and concerts.\nExamples of the occupations classified here: High school teacher, Secondary education teacher","version":"2022","source_id":534,"level":4,"normalized_name":"secondary education teachers"},{"code":"2341","parent_code":"234","title":"PRIMARY SCHOOL TEACHERS","description":"Primary school teachers teach a range of subjects at the primary education level.\nTheir tasks include: a) preparing daily and longer term lesson plans in accordance with curriculum guidelines; b) instructing children individually and in groups, using various teaching methods and materials (e.g. computers, books, games), adapting to children’s varying needs; c) maintaining discipline and good working habits in the classroom; d) planning and conduct activities with the children such as sporting activities, concerts and excursions; e) assigning and grading class work and homework; f) preparing, administering, and grading tests and assignments to evaluate children’s progress; g) observing and evaluating children’s performance and behavior; h) supervising children during classes and at other times in the school day, including the playground during breaks; i) participating in staff meetings and other sessions, and conferring with other teachers concerning educational issues; and j) preparing for and attending parent meetings to discuss children’s progress and problems.\nExample of occupation classified here: Primary school teacher\nSome related occupations classified elsewhere: Head teacher - 1345, School inspector - 2351, School principal - 1345","version":"2022","source_id":535,"level":4,"normalized_name":"primary school teachers"},{"code":"2342","parent_code":"234","title":"EARLY CHILHOOD EDUCATORS","description":"Early childhood educators promote the social, physical, and intellectual development of children below primary school age through the provision of educational and play activities.\nTheir tasks include: a) planning and organizing individual and group activities designed to facilitate the development of children's motor skills, cooperative and social skills, confidence and understanding; b) promoting language development through story-telling, role-play, songs, rhymes and informal conversations and discussions; c) leading children in activities that, provide opportunities for creative expression through the media of art, dramatic play, music and physical fitness; d) observing children in order to evaluate progress and to detect signs of developmental, emotional or health related problems with parents; e) observing and assessing nutritional health, welfare and safety needs of students and identifying factors which may impede students' progress; f) supervising children's activities to ensure safety and resolve conflicts; g) guiding and assisting children in the development of proper eating, dressing and toilet habits; h) discussing progress or problems of children with parents and other staff members and identifying appropriate actions and referrals to other services; and i) establishing and maintaining collaborative relationships with other service providers working with young children.\nExamples of the occupations classified here: Early childhood educator, Kindergarten teacher, Nursery school teacher, Pre-school teacher\nRelated occupation classified elsewhere: Child care center manager - 1341","version":"2022","source_id":536,"level":4,"normalized_name":"early chilhood educators"},{"code":"2351","parent_code":"235","title":"EDUCATION METHODS SPECIALISTS","description":"Education methods specialists conduct research and develop or advise on teaching methods, courses and aids. They review and examine teachers' work, the functioning of educational institutions and the results achieved and recommend changes and improvements.\nTheir tasks include: a) researching into current developments in curricula, teaching methods and other educational practices, and advising on necessary changes and possible improvements; b) evaluating and advising on contents of courses and methods of examination; c) researching into audio-visual and other teaching aids and advising on, planning and organizing their introduction in educational establishments; d) documenting subjects and courses developed, and evaluating new courses; e) providing ongoing professional development, training and consultative services to teachers; f) organizing and conducting workshops and conferences to train teachers in new programs and methods; g) developing the structure, content and objectives of new educational courses and programs; h) visiting schools periodically and conferring with administrative and teaching staff on questions relating to curricula, teaching methods, equipment and other matters; i) visiting classrooms to observe teaching techniques and to evaluate teachers performance, and scholastic results obtained; and j) preparing reports and making recommendations to educational authorities concerning possible changes and improvements in curricula, teaching methods, and other matters.\nExamples of the occupations classified here: Audio-visual teaching aids specialist, Curriculum coordinator, Curriculum developer, Education methods adviser, Education methods specialist, School inspector, Teaching aids specialist\nSome related occupations classified elsewhere: Educational psychologist - 2634, School counsellor - 2359, Student advisor - 2359","version":"2022","source_id":537,"level":4,"normalized_name":"education methods specialists"},{"code":"2352","parent_code":"235","title":"SPECIAL NEED TEACHERS","description":"Special needs teachers teach physically or mentally handicapped children, young persons, or adults, or those with learning difficulties or other special needs. They promote the social, emotional, intellectual and physical development of their students.\nTheir tasks include: a) assessing students' abilities and limitations with regard to intellectual, physical, social and emotional impairments, exceptional intellectual gifts, or other specific problems; b) designing or modifying curricula and preparing and delivering programmes, lessons and activities adapted to students’ abilities and needs; c) giving instruction on an individual or group basis using special techniques or aids appropriate to students’ needs; d) employing special educational strategies and techniques during instruction to improve the development of sensory- and perceptual-motor skills, language, cognition, and memory; e) establishing and enforcing rules for behavior and policies and procedures to maintain order among students; f) teaching academic subjects, and practical and self-help skills to students with hearing, sight and other impairments; g) stimulating and developing students’ confidence interests, abilities, manual skills and coordination; h) conferring with other staff members to plan and schedule lessons for special needs students; i) preparing and maintaining student data and other records and submitting reports; j) administering various forms of assessment and evaluating progress of each student; and k) conferring with students, parents, head teacher and other relevant professionals involved in the students’ care to develop individual educational plans designed to promote students' development.\nExamples of the occupations classified here: Learning disabilities special education teacher, Learning support teacher, Remedial teacher, Teacher for the mentally handicapped, Teacher for the physically handicapped, Teacher of gifted children, Teacher of the hearing impaired, Teacher of the sight impaired\nSome related occupations classified elsewhere: Primary school teacher - 2341, Secondary school teacher - 2330, Vocational education teacher - 2320","version":"2022","source_id":538,"level":4,"normalized_name":"special need teachers"},{"code":"2353","parent_code":"235","title":"OTHER LANGUAGE TEACHERS","description":"Other language teachers teach non-native languages to adults and children who are learning a language for reasons of migration, to fulfil employment requirements or opportunities, to facilitate participation in educational programmes delivered in a foreign language, or for personal enrichment. They work outside the mainstream primary, secondary and higher education systems, or in support of students and teachers within those systems.\nTheir tasks include: a) assessing the level of ability and the extent of language difficulties of students, and establishing students' needs and learning goals; b) planning, preparing and delivering lessons and workshops for groups and individuals with content and rate of progression adapted to students’ abilities and needs; c) designing and producing teaching materials and adapting existing materials; d) assessing students' progress; e) assisting students in classroom settings where subjects are taught in a language other than the students’ native language; f) providing assistance to other teachers by designing special teaching programs for students still learning the main language of instruction; g) assigning and correcting work, and preparing and grading exams; and h) assessing, recording and reporting on students’ progress.\nExamples of the occupations classified here: Intensive language teacher, Language researcher, Migrant education teacher, Practical language teacher, Second language teacher\nSome related occupations classified elsewhere: Primary school teacher - 2341, Secondary school teacher - 2330, University lecturer - 2310, Vocational education teacher - 2320","version":"2022","source_id":539,"level":4,"normalized_name":"other language teachers"},{"code":"2354","parent_code":"235","title":"OTHER MUSIC TEACHERS","description":"Other music teachers teach students in the practice, theory and performance of music outside the mainstream primary, secondary and higher education systems, but may provide private or small group tuition as an extra curricular activity in association with mainstream educational institutions. \nTheir tasks include: a) assessing the students’ level of ability and determining needs and learning goals; b) planning, preparing and delivering programs of study, lessons and workshops for individual students and groups; c) preparing and presenting material on the theory and interpretation of music; d) instructing and demonstrating practical aspects of singing or of playing a particular instrument; e) teaching students to read and write musical notation; f) assigning exercises and teaching pieces of music relevant to students’ level of ability, interests and talents; g) assessing students and offering advice, criticism and encouragement; h) revising curricula, course content, course materials and methods of instruction; i) preparing students for examinations, performances and assessments; j) arranging visits and tours to musical performances; and k) organizing and assisting in auditions or performances of students' work.\nExamples of the occupations classified here: Guitar teacher, Music teacher, Piano teacher, Voice teacher\nSome related occupations classified elsewhere: Primary school teacher - 2341, Secondary school teacher - 2330, University lecturer - 2310, Vocational education teacher - 2320","version":"2022","source_id":540,"level":4,"normalized_name":"other music teachers"},{"code":"2355","parent_code":"235","title":"OTHER ARTS TEACHERS","description":"Other arts teachers teach students in the practice, theory and performance of dance, drama, visual and other arts (excluding music) outside the mainstream primary, secondary and higher education systems, but may provide private or small group tuition as an extra curricular activity in association with mainstream educational institutions.\nTheir tasks include: a) assessing the students’ level of ability and determining learning needs; b) planning, preparing and delivering programs of study, lessons and workshops for individual students and groups; c) preparing and presenting material on the theory of the subject area being studied; d) instructing and demonstrating practical aspects of drama, dance, visual or other arts; e) assigning exercises and work relevant to students’ level of ability, interests and talents; f) assessing students and offering advice, criticism and encouragement; g) revising curricula, course content, course materials and methods of instruction; h) preparing students for examinations, performance and assessments; i) arranging visits and tours to exhibitions and performances; and j) organizing and assisting in performances or exhibitions of students' work.\nExamples of the occupations classified here: Cultural art teacher (instructor), Dance instructor, Dance teacher, Drama teacher, Painting teacher,Sculpture teacher\nSome related occupations classified elsewhere: Primary school teacher - 2341, Private music teacher - 2354, Secondary school teacher - 2330, University lecturer - 2310, Vocational education teacher - 2320","version":"2022","source_id":541,"level":4,"normalized_name":"other arts teachers"},{"code":"2356","parent_code":"235","title":"INFORMATION TECHNOLOGY TRAINERS","description":"Information technology trainers develop, schedule and conduct training programs and courses for computer and other information technology users outside the mainstream primary, secondary and higher education systems.\nTheir tasks include: a) identifying the information technology training needs and requirements of individual users and organizations; b) preparing and developing instructional training material and aids such as handbooks, visual aids, online tutorials, demonstration models, and supporting training reference documentation; c) designing, coordinating, scheduling and conducting training and development programs that can be delivered in the form of individual and group instruction, and facilitating workshops meetings; demonstrations and conferences; d) monitoring and performing ongoing evaluation and assessment of training quality and effectiveness, and reviewing and modifying training objectives, methods and course deliverables; e) gathering, investigating and researching background materials to gain a full understanding of the subject matter and systems; and f) keeping up-to-date with new product version releases, advances in software, and general information technology trends, writing end user products and materials such as user training, tutorial and instruction manuals, online help, and operating and maintenance instructions.\nExamples of the occupations classified here: Computer trainer, Information technology trainers, Software trainer\nSome related occupations classified elsewhere: Primary school teacher - 2341, Secondary school teacher - 2330, Staff development officer - 2424, University lecturer - 2310, Vocation education teacher - 2320","version":"2022","source_id":542,"level":4,"normalized_name":"information technology trainers"},{"code":"2359","parent_code":"235","title":"TEACHING PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers teaching professionals not classified elsewhere in Sub-major group 23, Teaching professionals. For instance, the group includes those who provide private tuition in subjects other than foreign languages and the arts, and those who provide educational counselling to students. \nTheir tasks include: a) assessing students’ level of ability and determining learning needs; b) planning, preparing and delivering programs of study, lessons and workshops for individual students and groups; c) preparing and presenting material on the theory of the subject area being studied; d) instructing and demonstrating practical aspects of the subject area being studied; e) assigning exercises and work relevant to students’ level of ability, interests and aptitude; f) assessing students and offering advice, criticism and encouragement; g) revising curricula, course content, course materials and methods of instruction; h) preparing students for examinations and assessments; i) counselling students regarding educational issues such as course and program selection, class scheduling, school adjustment, truancy, study habits, and career planning; j) counselling students to help them understand and overcome personal, social, or behavioral problems affecting their education; ank) preparing students for later educational experiences by encouraging them to explore learning opportunities and to persevere with challenging tasks.\nExamples of the occupations classified here: Adult literacy teacher, Literacy tutor, Mathematics coach, Professional tutor, School counselor\nSome related occupations classified elsewhere: Intensive language teacher - 2353, Migrant education teacher - 2353, Music teacher - 2354, Primary school teacher - 2341, Secondary school teacher - 2330, University lecturer - 2310, Vocation education teacher - 2320","version":"2022","source_id":543,"level":4,"normalized_name":"teaching professionals not elsewhere classified"},{"code":"2411","parent_code":"241","title":"ACCOUNTANTS","description":"Accountants plan, organize and administer accounting systems for individuals and establishments. Some occupations classified here examine and analyze the accounting and financial records of individuals and establishments to ensure accuracy and compliance with established accounting standards and procedures.\nTheir tasks include: a) advising on, planning and installing budgetary, accounts controlling and other accounting policies and systems; b) preparing and certifying financial statements for presentation to management, shareholders and statutory or other bodies; c) preparing tax returns, advising on taxation problems and contesting disputed claims before tax officials; d) preparing or reporting on profit forecasts and budgets; e) conducting financial investigations in such matters as suspected fraud, insolvency and bankruptcy; f) auditing accounts and bookkeeping records; g) conducting investigations and advising management on financial aspects of productivity, stockholdings, sales, new products, etc.; and h) devising and controlling a system to determine unit cost of products and services.\nExamples of the occupations classified here: Accountant, Audit examiner, Auditor, Bank accountant, Chartered accountant, Cost accountant, Financial accountant, Financial controller, Management accountant, Tax accountant\nSome related occupations classified elsewhere: Accounting clerk - 4311, Bookkeeper - 3313, Finance manager - 1211","version":"2022","source_id":544,"level":4,"normalized_name":"accountants"},{"code":"2412","parent_code":"241","title":"FINANCIAL AND INVESTMENT ADVISERS","description":"Financial and investment advisers develop financial plans for individuals and organizations, and invest and manage funds on their behalf.\nTheir tasks include: a) building and maintaining a client base; b) interviewing clients to determine financial status and objectives, risk tolerance and other information needed to develop financial plans and investment strategies; c) setting financial objectives, and developing and implementing strategies for achieving the financial objectives; d) arranging to buy and sell stocks and bonds for clients; e) monitoring investment performance, and reviewing and revising investment plans based on modified needs and changes in markets; and f) recommending and arranging insurance cover for clients.\nExamples of the occupations classified here: Estate planner, Financial adviser, Financial planner, Investment adviser","version":"2022","source_id":545,"level":4,"normalized_name":"financial and investment advisers"},{"code":"2413","parent_code":"241","title":"FINANCIAL ANALYST","description":"Financial analysts conduct quantitative analyses of information affecting investment programs of public or private institutions.\nTheir tasks include: a) analyzing financial information to produce forecasts of business, industry, and economic conditions for use in making investment decisions; b) maintaining knowledge and staying abreast of developments in the fields of industrial technology, business, finance, and economic theory; c) interpreting data affecting investment programs, such as price, yield, stability, future trends in investment risks, and economic influences; d) monitoring economic, industrial, and corporate developments through analysis of information obtained from financial publications and services, investment banking firms, government agencies, trade publications, company sources, and personal interviews; e) recommending investments and investment timing to companies, investment firm staff, or the investing public; f) determining the prices at which securities should be syndicated and offered to the public; g) preparing plans of action for investment based on financial analyses; h) evaluating and comparing the relative quality of various securities in a given industry; and i) presenting oral and written reports on general economic trends, individual corporations, and entire industries.\nExamples of the occupations classified here: Bond analyst, Budget analyst, Equity research analyst, Financial analyst, Financial modelers, Fiscal analyst, Investment analyst, Securities consultant","version":"2022","source_id":546,"level":4,"normalized_name":"financial analyst"},{"code":"2421","parent_code":"242","title":"MANAGEMENT AND ORGANIZATION ANALYST","description":"Management and organization analysts assist organizations to achieve greater efficiency and solve organizational problems. They study organizational structures, methods, systems and procedures.\nTheir tasks include: a) assisting and encouraging the development of objectives, strategies and plans aimed at achieving customer satisfaction and the efficient use of organizations’ resources; b) analyzing and evaluating current systems and structures; c) discussing current systems with staff and observing systems at all levels of organization; d) directing clients towards more efficient organization and developing solutions to organizational problems; e) undertaking and reviewing work studies by analyzing existing and proposed methods and procedures such as administrative and clerical procedures; f) recording and analyzing organizations’ work flow charts, records, reports, manuals and job descriptions; g) preparing and recommending proposals to revise methods and procedures, alter work flows, redefine job functions and resolve organizational problems; h) assisting in implementing approved recommendations, issuing revised instructions and procedure manuals, and drafting other documentation; and i) reviewing operating procedures and advising of departures from procedures and standards.\nExamples of the occupations classified here: Business consultant, Management consultant, Organization and methods analyst\nRelated occupation classified elsewhere: Business analyst (IT) - 2511","version":"2022","source_id":547,"level":4,"normalized_name":"management and organization analyst"},{"code":"2422","parent_code":"242","title":"POLICY ADMINISTRATION PROFESSIONALS","description":"Policy administration professionals develop and analyze policies guiding the design, implementation and modification of government and commercial operations and programs.\nTheir tasks include: a) liaising and consulting with program administrators and other interested parties to identify policy needs; b) reviewing existing policies and legislation to identify anomalies and out-of-date provisions; c) researching social, economic and industrial trends, and client expectations of programs and services provided; d) formulating and analyzing policy options, preparing briefing papers and recommendations for policy changes, and advising on preferred options; e) assessing impacts, financial implications, interactions with other programs and political and administrative feasibility of policies; f) conducting threat and risk assessments and developing responses; and g) reviewing operations and programs to ensure consistency with policies of the organization.\nExamples of the occupations classified here: Intelligence officer, Policy analyst, Political adviser","version":"2022","source_id":548,"level":4,"normalized_name":"policy administration professionals"},{"code":"2423","parent_code":"242","title":"PERSONNEL AND CAREERS PROFESSIONALS","description":"Personnel and careers professionals provide professional business services related to personnel policies such as employee recruitment or development, occupational analyzes and vocational guidance.\nTheir tasks include: a) advising on and performing personnel functions relating to employee recruitment, placement, training, promotion, compensation, and employee-management relations or other areas of personnel policy; b) studying and analyzing jobs performed in an establishment by various means, including interviews with workers, supervisors and management, and writing detailed position, job or occupation descriptions from information obtained; c) preparing occupational information or working on occupational classification systems; d) advising and working on the foregoing and other aspects of job and occupation analyzes in such fields as personnel administration, workforce research and planning, training, or occupational information and vocational guidance; and e) studying and advising individuals on employment opportunities, career choices and further education or training that may be desirable.\nExamples of the occupations classified here: Careers adviser, Human resource development specialist, Human resources expert, Industrial relations management specialist, Job analyst, Occupational analyst, Outplacement consultant, Personnel officer, Personnel specialist, Vocational guidance counsellor","version":"2022","source_id":549,"level":4,"normalized_name":"personnel and careers professionals"},{"code":"2424","parent_code":"242","title":"TRAINING AND STAFF DEVELOPMENT PROFESSIONALS","description":"Training and staff development professionals plan, develop, implement and evaluate training and development programs to ensure management and staff acquire the skills and develop the competencies required by organizations to meet organizational objectives.\nTheir tasks include: a) identifying training needs and requirements of individuals and organizations; b) setting human resource development objectives and evaluating learning outcomes; c) preparing and developing instructional training material and aids such as handbooks, visual aids, online tutorials, demonstration models, and supporting training reference documentation; d) designing, coordinating, scheduling and conducting training and development programs that can be delivered in the form of individual and group instruction, and facilitating workshops, meetings, demonstrations and conferences; e) liaising with external training providers to arrange delivery of specific training and development programs; f) promoting internal and external training and development, and evaluating these promotional activities; g) monitoring and performing ongoing evaluation and assessment of internal and external training quality and effectiveness, and reviewing and modifying training objectives, methods and course deliverables; and h) gathering, investigating and researching background materials to gain an understanding of various subject matters and system.\nExamples of the occupations classified here: Staff development officer, Training officer, Workforce development specialist","version":"2022","source_id":550,"level":4,"normalized_name":"training and staff development professionals"},{"code":"2431","parent_code":"243","title":"ADVERTISING AND MARKETING PROFESSIONALS","description":"Advertising and marketing professionals develop and coordinate advertising strategies and campaigns, determine the market for new goods and services, and identify and develop market opportunities for new and existing goods and services.\nTheir tasks include: a) planning, developing and organizing advertising policies and campaigns to support sales objectives; b) advising managers and clients on strategies and campaigns to reach target markets, creating consumer awareness and effectively promoting the attributes of goods and services; c) writing advertising copy and media scripts, and arranging television and film production and media placement; d) analyzing data regarding consumer patterns and preferences; e) interpreting and predicting current and future consumer trends; f) researching potential demand and market characteristics for new goods and services and collecting and analyzing data and other statistical information; g) supporting business growth and development through the preparation and execution of marketing objectives, policies and programs; h) commissioning and undertaking market research to identify market opportunities for new and existing goods and services; and i) advising on all elements of marketing such as product mix, pricing, advertising and sales promotion, selling, and distribution channels.\nExamples of the occupations classified here: Advertising account executive, Advertising specialist, Market research analyst, Marketing account executive, Marketing consultant, Marketing specialist, Media production specialist, Merchandising supervisor, Sales promotion specialist","version":"2022","source_id":551,"level":4,"normalized_name":"advertising and marketing professionals"},{"code":"2432","parent_code":"243","title":"PUBLIC RELATIONS PROFESSIONALS","description":"Public relations professionals plan, develop, implement and evaluate information and communication strategies that create an understanding and a favorable view of businesses and other organizations, their goods and services, and their role in the community.\nTheir tasks include: a) planning and organizing publicity campaigns and communication strategies; b) advising executives on the public relations implications of their policies, programs and practices preparing and controlling the issue of news and press releases; c) undertaking and commissioning public opinion research, analyzing the findings and planning public relations and promotional campaigns; d) organizing special events, seminars, entertainment, competitions and social functions to promote goodwill and favorable publicity; e) representing organizations and arranging interviews with publicity media; f) attending business, social and other functions to promote the organization; g) commissioning and obtaining photographs and other illustrative material; and h) selecting, appraising and revising material submitted by publicity writers, photographers, illustrators and others to create favorable publicity.\nExamples of the occupations classified here: Press liaison officer, Public relations copywriter, Public relations officer, Publicity agent","version":"2022","source_id":552,"level":4,"normalized_name":"public relations professionals"},{"code":"2433","parent_code":"243","title":"TECHNICAL AND MEDICAL SALE PROFESSIONALS (Excluding ICT)","description":"Technical and medical sales professionals (excluding ICT) represent companies in selling a range of industrial, medical and pharmaceutical goods and services to industrial, business, professional and other establishments.\nTheir tasks include: a) compiling lists of prospective client businesses using directories and other sources; b) acquiring and updating knowledge of employers’ and competitors’ goods and services, and market conditions; c) visiting regular and prospective client businesses to establish and act on selling opportunities; d) assessing clients' needs and resources and recommending appropriate goods or services; e) providing input to product design where goods or services must be tailored to suit clients’ needs; f) developing reports and proposals as part of sales presentation to demonstrate benefits from use of good or service; g) estimating costs of installing and maintaining equipment or service; h) monitoring customers’ changing needs and competitor activity, and reporting these developments to sales management; i) quoting and negotiating prices and credit terms, and preparing and administering sales contracts; j) arranging delivery of goods, installation of equipment and the provision of services; k) reporting to sales management on sales made and the marketability of goods and services; and l) consulting with clients after sale to ensure satisfaction resolve any problems and provide ongoing support.\nExamples of the occupations classified here: Industrial products sales representative, Medical and pharmaceutical products sales representative, Technical sales representative (except ICT)\nSome related occupations classified elsewhere: Commercial sales representative - 3322, Computers sales representative - 2434, Information and communications technology sales representative - 2434","version":"2022","source_id":553,"level":4,"normalized_name":"technical and medical sale professionals excluding ict"},{"code":"2434","parent_code":"243","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY SALE PROFESSIONALS","description":"Information and communications technology (ICT) sales professionals sell, at the wholesale level, a range of computer hardware, software and other information and communications technology goods and services including installations and provide specialized information as required.\nTheir tasks include: a) soliciting orders and selling goods to retail, industrial, wholesale and other establishments; b) selling technical equipment, supplies and related services to business establishments or individuals; c) discussing the needs of new and existing customers and providing specialized information about how particular equipment, supplies and services meet those needs; d) quoting and negotiating prices and credit terms, and completing contracts and recording orders; e) updating customer records and preparing sales reports; f) arranging delivery of goods, installation of equipment and the provision of services; and g) reporting customers' reactions and requirements to manufacturers.\nExamples of the occupations classified here: Communications technology sales representative, Computers sales representative\nRelated occupation classified elsewhere: Shop sales assistant - 5223","version":"2022","source_id":554,"level":4,"normalized_name":"information and communications technology sale professionals"},{"code":"2511","parent_code":"251","title":"SYSTEMS ANALYSTS","description":"Systems analysts conduct research, analyze and evaluate client information technology requirements, procedures or problems, and develop and implement proposals, recommendations, and plans to improve current or future information systems.\nTheir tasks include: a) consulting with users to formulate and document requirements and with management to ensure agreement on systems principles; b) identifying and analyzing business processes, procedures and work practices; c) identifying and evaluating inefficiencies and recommending optimal business practices, and system functionality and behavior; d) taking responsibility for deploying functional solutions, such as creating, adopting and implementing system test plans; e) developing functional specifications for use by systems developers; f) expanding or modifying systems to improve work flow or serve new purposes; and g) coordinating and linking the computer systems within an organization to increase compatibility.\nExamples of the occupations classified here: Computer scientist, Computer systems analyst, Computer systems designer, IT business analyst, IT systems designer, Systems consultant\nSome related occupations classified elsewhere: Computers communication analyst - 2523, Network analyst - 2523, Computers systems administrator - 2522","version":"2022","source_id":555,"level":4,"normalized_name":"systems analysts"},{"code":"2512","parent_code":"251","title":"SOFTWARE DEVELOPERS","description":"Software developers research, analyze and evaluate requirements for existing or new software applications and operating systems, and design, develop, test and maintain software solutions to meet these requirements.\nTheir tasks include: a) researching, analyzing and evaluating requirements for software applications and operating systems; b) researching, designing, and developing computer software systems; c) consulting with engineering staff to evaluate interface between hardware and software; d) developing and directing software testing and validation procedures; e) modifying existing software to correct errors, to adapt it to new hardware or to upgrade interfaces and improve performance; f) directing software programming and development of documentation; g) assessing, developing, upgrading and documenting maintenance procedures for operating systems, communications environments and applications software; and h) consulting with customers concerning maintenance of software system.\nExamples of the occupations classified here: Artificial intelligence (AI) software developer, Computer applications engineer, Programmer analyst, Software architect, Software designer, Software developer, Software engineer\nRelated occupation classified elsewhere: Application programmer - 2514","version":"2022","source_id":556,"level":4,"normalized_name":"software developers"},{"code":"2513","parent_code":"251","title":"WEB AND MULTIMEDIA DEVELOPERS","description":"Web and multimedia development professionals combine design and technical knowledge to research, analyze, evaluate, design, programme and modify websites, and applications that draw together text, graphics, animations, imaging, audio and video displays, and other interactive media.\nTheir tasks include: a) analyzing, designing and developing Internet sites applying a mixture of artistry and creativity with software programming and scripting languages and interfacing with operating environments; b) designing and developing digital animations, imaging, presentations, games, audio and video clips, and Internet applications using multimedia software, tools and utilities, interactive graphics and programming languages; c) communicating with network specialists regarding web-related issues, such as security and hosting web sites, to control and enforce Internet and web server security, space allocation, user access, business continuity, web site backup and disaster recovery planning; d) designing, developing and integrating computer code with other specialized inputs, such as image files, audio files and scripting languages, to produce, maintain and support web sites; and e) assisting in analyzing, specifying and developing Internet strategies, web-based methodologies and development plans.\nExamples of the occupations classified here: Animation programmer, Communications programmer, Digital content developers, Internet developer, Multimedia developer, Multimedia programmer, Website architect, Website developer, Website game developers\nSome related occupations classified elsewhere: Webmaster - 3514, Website administrator - 3514, Website designer - 2166, Website technician - 3514","version":"2022","source_id":557,"level":4,"normalized_name":"web and multimedia developers"},{"code":"2514","parent_code":"251","title":"APPLICATIONS PROGRAMMERS","description":"Applications programmers write and maintain programmable code outlined in technical instructions and specifications for software applications and operating systems.\nTheir tasks include: a) writing and maintaining program code outlined in instructions and specifications in accordance with quality accredited standards; b) revising, repairing or expanding existing programs to increase operating efficiency or adapt to new requirements; c) conducting trial runs of programs and software applications to confirm that they will produce the desired information; d) compiling and writing documentation of program development; and e) identifying and communicating technical problems, processes and solutions.\nExample of occupation classified here: Applications programmer\nSome related occupations classified elsewhere: Multimedia programmer - 2513, Programmer analyst - 2512, Software developer - 2512","version":"2022","source_id":558,"level":4,"normalized_name":"applications programmers"},{"code":"2519","parent_code":"251","title":"SOFTWARE AND APPLICATIONS DEVELOPERS AND ANALYST NOT ELSEWHERE CLASSIFIED","description":"This unit group covers software and applications developers and analysts not classified elsewhere in minor group 251, Software and applications developers and analysts. For instance the group includes those professionals specializing in quality assurance including software testing.\nTheir tasks include: a) developing and documenting software testing plans; b) installing software and hardware and configuring operating system software in preparation for testing; c) verifying that programmes function according to user requirements and established guidelines; d) executing, analyzing and documenting results of software application tests and information and telecommunication systems tests; and e) developing and implementing software and information system testing policies, procedures and scripts.\nExamples of the occupations classified here: Computers quality assurance analyst, Software tester, Systems tester","version":"2022","source_id":559,"level":4,"normalized_name":"software and applications developers and analyst not elsewhere classified"},{"code":"2521","parent_code":"252","title":"DATABASE DESIGNERS AND ADMINISTRATORS","description":"Database designers and administrators design, develop, control, maintain and support the optimal performance and security of databases.\nTheir tasks include: a) designing and developing database architecture, data structures, tables, dictionaries and naming conventions for information systems projects; b) designing, constructing, modifying, integrating, implementing and testing database management systems; c) conducting research and providing advice on the selection, application and implementation of database management tools; d) developing and implementing data administration policy, documentation, standards and models; e) developing policies and procedures for database access and usage and for the backup and recovery of data; and f) performing the operational establishment and preventive maintenance of backups, recovery procedures, and enforcing security and integrity controls.\nExamples of the occupations classified here: Data administrator, Database administrator, Database analyst, Database architect, Database designers\nSome related occupations classified elsewhere: Computers systems administrator - 2522, Network administrator - 2522, Webmaster - 3514, Website administrator - 3514","version":"2022","source_id":560,"level":4,"normalized_name":"database designers and administrators"},{"code":"2522","parent_code":"252","title":"SYSTEMS ADMINISTRATORS","description":"Systems administrators develop, control, maintain and support the optimal performance and security of information technology systems.\nTheir tasks include: a) maintaining and administering computer networks and related computing environments including computer hardware, systems software, applications software and all configurations; b) recommending changes to improve systems and network configurations, and determining hardware or software requirements related to such changes; c) diagnosing hardware and software problems; d) performing data backups and disaster recovery operations; and e) operating master consoles to monitor the performance of computer systems and networks, and to coordinate computer network access and use.\nExamples of the occupations classified here: Computer systems administrator, Computer systems administrator, Network administrator\nSome related occupations classified elsewhere: Database administrator - 2521, Network analyst - 2523, Webmaster - 3514, Website administrator - 3514, Website technician - 3514","version":"2022","source_id":561,"level":4,"normalized_name":"systems administrators"},{"code":"2523","parent_code":"252","title":"COMPUTER NETWORK PROFESSIONALS","description":"Computer network professionals research, analyze and recommend strategies for network architecture and development, implement, manage, maintain and configure network hardware and software, and monitor, troubleshoot and optimize performance.\nTheir tasks include: a) analyzing, developing, interpreting and evaluating complex system design and architecture specifications, data models and diagrams in the development, configuration and integration of computer systems; b) researching, analyzing, evaluating and monitoring network infrastructure to ensure networks are configured to operate at optimal performance; c) assessing and recommending improvements to network operations and integrated hardware, software, communications and operating systems; d) providing specialist skills in supporting and troubleshooting network problems and emergencies; e) installing, configuring, testing, maintaining and administering new and upgraded networks, software database applications, servers and workstations; f) preparing and maintaining procedures and documentation for network inventory, and recording diagnosis and resolution of network faults, enhancements and modifications to networks, and maintenance instructions; and g) monitoring network traffic, and activity, capacity and usage to ensure continued integrity and optimal network performance.\nExamples of the occupations classified here: Computers communication analyst, Network analyst\nSome related occupations classified elsewhere: Network administrator - 2522, System analyst - 2511","version":"2022","source_id":562,"level":4,"normalized_name":"computer network professionals"},{"code":"2529","parent_code":"252","title":"DATABASE AND NETWORK PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers database and network professionals elsewhere in Minor group 252, Database and network professionals. For instance, the group includes information and communications technology security specialists.\nTheir tasks include: a) developing plans to safeguard computer files against accidental or unauthorized modification, destruction, or disclosure and to meet emergency data processing needs; b) training users and promoting security awareness to ensure system security and to improve server and network efficiency; c) conferring with users to discuss issues such as computer data access needs, security violations, and programming changes; d) monitoring current reports of computer viruses to determine when to update virus protection systems; e) modifying computer security files to incorporate new software, correct errors, or change individual access status; f) monitoring use of data files and regulate access to safeguard information in computer files; g) performing risk assessments and executing tests of data processing system to ensure functioning of data processing activities and security measures; and h) encrypting data transmissions and erecting firewalls to conceal confidential information as it is being transmitted and to keep out tainted digital transfers.\nExamples of the occupations classified here: Data miner, Digital forensic specialist, ICT security specialist","version":"2022","source_id":563,"level":4,"normalized_name":"database and network professionals not elsewhere classified"},{"code":"2611","parent_code":"261","title":"LAWYERS","description":"Lawyers give clients legal advice on a wide variety of subjects, draw up legal documents, represent clients before administrative boards or tribunals and plead cases or conduct prosecutions in courts of justice, or instruct barristers to plead in higher courts of justice.\nTheir tasks include: a) giving clients legal advice on a wide variety of subjects and undertaking legal business on clients’ behalf; b) researching legal principles, statutes and previous court decisions related to specific cases; c) gathering evidence to formulate a defense or to initiate legal actions, by such means as interviewing clients and witnesses to ascertain the facts of a case; d) evaluate findings and develop strategies and arguments in preparation for presentation of cases; e) pleading clients’ cases before courts of law, tribunals and administrative boards or instructing barristers to plead in higher courts of justice; f) accepting briefs and pleading in the higher court; g) acting as prosecutor on behalf of the Government; h) negotiating settlements in matters which involve legal disputes; i) drafting legislation and preparing government regulations based on existing laws; and j) drawing up legal documents such as contracts, real estate transactions and wills and preparing statements of legal opinions.\nExamples of the occupations classified here: Attorney, Lawyer, Legal adviser, Legal counsel, Legal officer, Prosecutor, Solicitor\nSome related occupations classified elsewhere: Conveyancing clerk - 3411, Law clerk - 3411, Notary - 2619","version":"2022","source_id":564,"level":4,"normalized_name":"lawyers"},{"code":"2612","parent_code":"261","title":"JUDGES","description":"Judges preside over civil and criminal proceedings in courts of law.\nTheir tasks include: a) presiding over trials and hearings; b) interpreting and enforcing rules of procedure and making rulings regarding the admissibility of evidence; c) determining the rights and obligations of the parties involved, and, in cases tried by jury; d) instructing the jury on points of law that are applicable to the case; e) weighing and considering evidence in non-jury trials and deciding legal guilt or innocence or degree of liability of the accused or defendant; f) passing sentence on persons convicted in criminal cases, determining damages or other appropriate remedy in civil cases and issuing court orders; and g) researching legal issues and writing opinions on the issues.\nExamples of the occupations classified here: Associate judge, Chief justice, Judge, Magistrate\nSome related occupations classified elsewhere: Court clerk - 3411, Justice of the peace - 3411","version":"2022","source_id":565,"level":4,"normalized_name":"judges"},{"code":"2619","parent_code":"261","title":"LEGAL PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers legal professionals not classified elsewhere in Minor group 261, Legal professionals. For instance, the group includes those who perform legal functions other than pleading or prosecuting cases or presiding over judicial proceedings. \nTheir tasks include: a) giving advice on legal aspects of various personal, business and administrative problems; b) drawing up legal documents and contracts; and c) determining, by inquest, the causes of any death not obviously due to natural causes.\nExamples of the occupations classified here: Coroner, Jurist (except lawyer or judge), Notary","version":"2022","source_id":566,"level":4,"normalized_name":"legal professionals not elsewhere classified"},{"code":"2621","parent_code":"262","title":"ARCHIVISTS AND CURATORS","description":"Archivists and curators collect, appraise and ensure the safekeeping and preservation of the contents of archives, artefacts and records of historical, cultural, administrative and artistic interest, and of art and other objects. They plan, devise and implement systems for the safekeeping of records and historically valuable documents.\nTheir tasks include: a) evaluating and preserving records for administrative, historical, legal, evidential and other purposes; b) directing or carrying out the preparation of indexes, bibliographies, microfilm copies and other reference aids to the collected material and making them available to users; c) researching the origin, distribution and use of materials and objects of cultural and historical interest; d) organizing, developing and maintaining collections of artistic, cultural, scientific or historically significant; e) directing or undertaking classification and cataloguing of museum and art gallery collections and organizing exhibitions; f) researching into, appraising, and developing, organizing and preserving historically significant and valuable documents such as government papers, private papers, photographs, maps, manuscripts audio-visual materials; g) preparing scholarly papers and reports; h) planning and implementing the computerized management of archives and electronic records; i) organizing exhibitions at museums and art galleries, publicizing exhibits and arranging special displays for general, specialized or educational interest; and j) appraising and acquiring archival materials to build and develop an archival collection for research purposes.\nExamples of the occupations classified here: Archivist, Art gallery curator, Museum curator, Records manager","version":"2022","source_id":567,"level":4,"normalized_name":"archivists and curators"},{"code":"2622","parent_code":"262","title":"LIBRARIANS AND RELATED INFORMATION PROFESSIONALS","description":"Librarians and related information professionals collect, select, develop, organize and maintain library collections and other information repositories, organize and control other library services and provide information for users.\nTheir tasks include: a) organizing, developing and maintaining a systematic collection of books, periodicals and other printed, audio-visually and digitally recorded material; b) selecting and recommending acquisitions of books and other printed or audio-visually and digitally recorded material; c) organizing, classifying and cataloguing library material; d) managing library borrowing and inter-library loan facilities and information networks; e) retrieving material and providing information to business and other users based on the collection itself or on library and information-network systems; f) conducting research and analyzing or modifying library and information services in accordance with changes in users' needs; g) devising and implementing schemes and conceptual models for the storage, organization, classification and retrieval of information; h) preparing scholarly papers and reports; and i) performing manual, on-line and interactive media reference searches, making interlibrary loans and performing other functions to assist users in accessing library materials.\nExamples of the occupations classified here: Bibliographer, Cataloguer, Librarian","version":"2022","source_id":568,"level":4,"normalized_name":"librarians and related information professionals"},{"code":"2631","parent_code":"263","title":"ECONOMISTS","description":"Economists conduct research, monitor data, analyze information and prepare reports and plans to resolve economic and business problems and develop models to analyze, explain and forecast economic behavior and patterns. They provide advice to business, interest groups and governments to formulate solutions to present or projected economic and business problems.\nTheir tasks include: a) forecasting changes in the economic environment for short-term budgeting, long-term planning and investment evaluation; b) formulating recommendations, policies and plans for the economy, corporate strategies and investment, and undertaking feasibility studies for projects; c) monitoring economic data to assess the effectiveness, and advise on the appropriateness, of monetary and fiscal policies; d) forecasting production and consumption of specific products and services based on records of past production and consumption and general economic and industry-specific conditions; e) preparing forecasts of income and expenditure, interest rates and exchange rates; f) analyzing factors that determine labor force participation, employment, wages, unemployment and other labor market outcomes; g) applying mathematical formulae and statistical techniques and apply to test economic theories and devise solutions to economic problems; h) compiling, analyzing and interpreting economic data using economic theory and a variety of statistical and other techniques; i) evaluating the outcome of political decisions concerning public economy and finances and advising on economic policy and possible courses of action in the light of past, present and projected economic factors and trends; j) preparing scholarly papers and reports; k) examining problems related to the economic activities of individual companies; and l) conducting research on market conditions in local, regional or national areas to set sales and pricing levels for goods and services, to assess market potential and future trends and to develop business strategies.\nExamples of the occupations classified here: Econometrician, Economic adviser, Economic analyst, Economist, Labor economist, Microeconomist\nRelated occupation classified elsewhere: Statistician - 2122","version":"2022","source_id":569,"level":4,"normalized_name":"economists"},{"code":"2632","parent_code":"263","title":"SOCIOLOGISTS, ANTHROPOLOGISTS AND RELATED PROFESSIONALS","description":"Sociologists, anthropologists and related professionals investigate and describe the structure of societies, the origin and evolution of societies, and the interdependence between environmental conditions and human activities. They provide advice on the practical application of their findings in the formulation of economic and social policies.\nTheir tasks include: a) conducting research on the origin, development, structure, social patterns, organizations and inter-relationships of human society; b) tracing the origin and evolution of humanity through the study of changing characteristics and cultural and social institutions; c) tracing the development of humanity through the material remains of its past, such as dwellings, temples, tools, pottery, coins, weapons, or sculpture; d) studying physical and climatic aspects of areas and regions, and correlating these findings with economic, social and cultural activities; e) developing theories, models and methods to interpret and describe social phenomena; f) evaluating the outcome of political decisions concerning social policy; g) analyzing and evaluating social data; h) advising on the practical application of findings in the formulation of economic and social policies for population groups and regions, and for the development of markets; and i) preparing scholarly papers and reports.\nExamples of the occupations classified here: Anthropologist, Archaeologist, Criminologist, Ethnologist, Geographer, Sociologist","version":"2022","source_id":570,"level":4,"normalized_name":"sociologists anthropologists and related professionals"},{"code":"2633","parent_code":"263","title":"PHILOSOPHERS, HISTORIANS AND POLITICAL SCIENTISTS","description":"Philosophers, historians and political scientists conduct research into the nature of human experience and existence, phases or aspects of human history, and political structures, movements and behavior. They document and report on findings to inform and guide political and individual actions.\nTheir tasks include: a) researching, mostly by reasoning, into the general causes, principles and meanings of the world, human actions, experience and existence, and interpreting and developing philosophical concepts and theories; b) consulting and comparing primary sources, such as original or contemporary records of past events, and secondary sources such as archaeological or anthropological findings; c) extracting relevant material, checking its authenticity, and researching into and describing the history of a particular period, country or region, or a particular facet - for example economic, social or political - of its history; d) conducting research in such fields as political philosophy, or past and present theory and practice of political systems, institutions or behavior; e) observing contemporary political institutions and opinions, collecting data on them from various sources, including interviews with government and political party officials and other relevant persons; f) developing theories, models and methods to interpret and describe the nature of human experience and historical and political events and behavior; g) presenting findings and conclusions for publication or use by government, political parties or other organizations and interested persons; and h) preparing scholarly papers and reports.\nExamples of the occupations classified here: Genealogist, Historian, Philosopher, Political analyst, Political scientist\nRelated occupation classified elsewhere: Political adviser - 2422","version":"2022","source_id":571,"level":4,"normalized_name":"philosophers historians and political scientists"},{"code":"2634","parent_code":"263","title":"PSYCHOLOGISTS","description":"Psychologists research into and study the mental processes and behavior of human beings as individuals or in groups, and apply this knowledge to promote personal, social, educational or occupational adjustment and development.\nTheir tasks include: a) planning and carrying out tests to measure mental, physical and other characteristics such as intelligence, abilities, aptitudes, potentialities, etc., interpreting and evaluating results, and providing advice; b) analyzing the effect of heredity, social, occupational and other factors on individual thought and behavior; c) conducting counselling or therapeutic interviews with individuals and groups, and providing follow-up services; d) maintaining required contacts, such as those with family members, educational authorities or employers, and recommending possible solutions to, and treatment of, problems; e) studying psychological factors in the diagnosis, treatment and prevention of mental illnesses and emotional or personality disorders, and conferring with related professionals; f) preparing scholarly papers and reports; g) formulating achievement, diagnostic and predictive tests for use by teachers in planning methods and content of instruction; h) conducting surveys and research studies on job design, work groups, morale, motivation, supervision and management; and i) developing theories, models and methods to interpret and describe human behavior.\nExamples of the occupations classified here: Clinical psychologist, Developmental psychologist, Educational psychologist, Organizational psychologist, Psychologist, Psychometrician, Psychotherapist, Sports psychologist\nRelated occupation classified elsewhere: Psychiatrist - 2212","version":"2022","source_id":572,"level":4,"normalized_name":"psychologists"},{"code":"2635","parent_code":"263","title":"SOCIAL WORK AND COUNSELLING PROFESSIONALS","description":"Social work and counselling professionals provide advice and guidance to individuals, families, groups, communities and organizations in response to social and personal difficulties. They assist clients to develop skills and access resources and support services needed to respond to issues arising from unemployment, poverty, disability, addiction, criminal and delinquent behavior, marital and other problems.\nTheir tasks include: a) interviewing clients individually, in families, or in groups, to assess their situation and problems and determine the types of services required; b) analyzing the client's situation and presenting alternative approaches to resolving problems; c) compiling case records or reports for courts and other legal proceedings; d) providing counselling, therapy and mediation services and facilitating group sessions to assist clients to develop skills and insights needed to deal with and resolve their social and personal problems; e) planning and implementing programs of assistance for clients including crisis intervention and referral to agencies that provide financial assistance, legal aid, housing, medical treatment and other services; f) investigating cases of abuse or neglect and taking action to protect children and other at risk persons; g) working with offenders during and after sentence, to help them to integrate into the community and to change attitudes and behavior in order to reduce further offending; h) providing advice to prison governors and to probation and parole review boards that help determine whether, and under what conditions, an offender should be incarcerated, released from prison or undergo alternative correctional measures; i) acting as advocates for client groups in the community and lobbying for solutions to problems affecting them; j) developing prevention and intervention programs to meet community needs; and k) maintaining contact with other social service agencies, educational institutions and health care providers involved with clients to provide information and obtain feedback on clients' overall situation and progress.\nExamples of the occupations classified here: Addictions counselor, Bereavement counselor, Child and youth counselor, Counseling professionals, Family counselor, Marriage counselor, Parole officer, Probation officer, Social welfare officer, Social worker, Women's welfare organizer\nRelated occupation classified elsewhere: Welfare worker - 3412","version":"2022","source_id":573,"level":4,"normalized_name":"social work and counselling professionals"},{"code":"2636","parent_code":"263","title":"RELIGIOUS PROFESSIONALS","description":"Religious professionals function as perpetuators of sacred traditions, practices and beliefs. They conduct religious services, celebrate or administer the rites of a religious faith or denomination, provide spiritual and moral guidance and perform other functions associated with the practice of a religion.\nTheir tasks include: a) perpetuating sacred traditions, practices and beliefs; b) conducting religious services, rites and ceremonies; c) undertaking various administrative and social duties, including participating in committees and meetings of religious organizations; d) providing spiritual and moral guidance in accordance with the religion professed; e) propagating religious doctrines in own country or abroad; f) preparing religious sermons and preachings; g) developing and directing study courses and religious education programmes; h) counselling individuals regarding interpersonal, health, financial, and religious problems; and i) scheduling and participating in special events such as camps, conferences, seminars, and retreats.\nExamples of the occupations classified here: Chaplain, Imam, Missionary, Pastor, Priest, Religion minister\nSome related occupations classified elsewhere: Lay preacher - 3413, Monk - 3413, Nun - 3413","version":"2022","source_id":574,"level":4,"normalized_name":"religious professionals"},{"code":"2641","parent_code":"264","title":"AUTHORS AND RELATED WRITERS","description":"Authors and related writers plan, research and write books, scripts, storyboards, plays, essays, speeches, manuals, specifications and other non-journalistic articles (excluding material for newspapers, magazines and other periodicals) for publication or presentation.\nTheir tasks include: a) conceiving, writing and editing novels, plays, scripts, poetry and other material for publication or presentation; b) conducting research to establish factual content and to obtain other necessary information; c) writing scripts and continuities and preparing programmes for stage, film, radio and television productions; d) analyzing material, such as specifications, notes and drawings, and writing manuals, user guides and other documents to explain clearly and concisely the installation, operation and maintenance of software, electronic, mechanical and other equipment; e) writing brochures, handbooks and similar technical publications; and f) selecting material for publication, checking style, grammar and accuracy of content, arranging for any necessary revisions and checks proof copies before printing.\nExamples of the occupations classified here: Author, Book author, Book editor, Creative writer, Essayist, Indexer, Interactive media writer, Literary writer, Novelist, Playwright, Poet, Scriptwriter, Speech writer, Technical communicator, Technical writer, Writer\nSome related occupations classified elsewhere: Advertising copywriter - 2431, Journalist - 2642, Newspaper editor - 2642, Public relations copywriter - 2432","version":"2022","source_id":575,"level":4,"normalized_name":"authors and related writers"},{"code":"2642","parent_code":"264","title":"JOURNALISTS","description":"Journalists research, investigate, interpret and communicate news and public affairs through newspapers, television, radio and other media.\nTheir tasks include: a) collecting local, national and international news through interviews, investigation and observation, attending public events, seeking out records, reviewing written work, attending film and stage performances; b) collecting, reporting and commenting on news and current affairs for publication in newspapers and periodicals, or for broadcasting by radio, television or webcast media; c) receiving, analyzing and verifying news and other copy for accuracy; d) interviewing politicians and other public figures at press conferences and on other occasions, including individual interviews recorded for radio, television or webcast media; e) researching and reporting on developments in specialized fields such as medicine, science and technology; f) writing editorials and commentaries on topics of current interest to stimulate public interest and express the views of a publication or broadcasting station; g) writing critical reviews of literary, musical and other artistic works based on knowledge, judgement and experience for newspapers, television, radio and other media; h) selecting material for publication, checking style, grammar, accuracy and legality of content and arranging for any necessary revisions; i) liaising with production staff in checking final proof copies immediately prior to printing; and j) selecting, assembling and preparing publicity material about business or other organizations for issue through press, radio, television and other media.\nExamples of the occupations classified here: Columnist, Critic, Editor-in-chief, Journalist, News analyst, News media copywriter, Newspaper editor, Newspaper reporter, Sports writer, Sub editor, TV/Radio news producer, TV/Radio news reporter\nSome related occupations classified elsewhere: Author - 2641, Book editor - 2641, Camera operator - 3521, Photo journalist - 3431, Public relations officer - 2432","version":"2022","source_id":576,"level":4,"normalized_name":"journalists"},{"code":"2643","parent_code":"264","title":"TRANSLATORS, INTERPRETERS AND OTHER LINGUISTS","description":"Translators, interpreters and other linguists translate or interpret from one language into another and study the origin, development and structure of languages.\nTheir tasks include: a) studying relationships between ancient parent languages and modern language groups, tracing the origin and evolution of words, grammar and language forms, and presenting findings; b) advising on or preparing language classification systems, grammars, dictionaries and similar materials; c) translating from one language into another and ensuring that the correct meaning of the original is retained, that legal, technical or scientific works are correctly rendered, and that the phraseology and terminology of the spirit and style of literary works are conveyed as far as possible; d) developing methods for the use of computers and other instruments to improve productivity and quality of translation; e) interpreting from a spoken or a signed language into another spoken or signed language , in particular at conferences, meetings and similar occasions, and ensuring that the correct meaning and, as far as possible, the spirit of the original are transmitted; and f) revising and correcting translated material.\nExamples of the occupations classified here: Interpreter, Lexicographer, Philologist, Sign language interpreter, Subtitler, Translator, Translator-reviser\nSome related occupations classified elsewhere: Author - 2641, Book editor - 2641, Journalist - 2642","version":"2022","source_id":577,"level":4,"normalized_name":"translators interpreters and other linguists"},{"code":"2651","parent_code":"265","title":"VISUAL ARTISTS","description":"Visual artists create and execute works of art by sculpting, painting, drawing, creating cartoons, engraving or using other techniques.\nTheir tasks include: a) conceiving and developing ideas, designs and styles for paintings, drawings and sculptures; b) arranging objects, positioning models, and selecting landscapes and other visual forms according to chosen subject matter; c) selecting artistic media, method and materials; d) creating representational or abstract three-dimensional or relief forms by shaping, carving and working and combining materials such as, wood, stone, clay, metal, ice or paper; e) creating representational or abstract drawings and paintings using pencils, ink, chalk, oil paints, water colors or through the application of other techniques; f) creating drawings and engraving or etching them on metal, wood, or other materials; g) creating cartoons to depict persons and events, often in caricature; and h) restoring damaged, soiled and faded paintings and other art objects.\nExamples of the occupations classified here: Artistic engraver and etcher, Artistic painter, Cartoonist, Ceramic artist, Graphic artist, Murals painter, Picture restorer, Portrait painter, Sculptor, Sketch artist\nSome related occupations classified elsewhere: Decorative painter - 7316, Graphic designer - 2166, Industrial designer - 2163, Painting teacher - 2355, Potter - 7314","version":"2022","source_id":578,"level":4,"normalized_name":"visual artists"},{"code":"2652","parent_code":"265","title":"MUSICIANS, SINGERS AND COMPOSERS","description":"Musicians, singers and composers write, arrange, conduct and perform musical compositions.\nTheir tasks include: a) creating melodic, harmonic and rhythmic structures to express ideas and emotions in musical form; b) translating ideas and concepts into standard musical signs and symbols for reproduction and performance; c) adapting or arranging music for particular instrumental or vocal groups, instruments or occasions; d) conducting instrumental or vocal groups; e) selecting music for performances and assigning instrumental parts to musicians; f) playing one or more musical instruments as a soloist or as a member of an orchestra or a musical group; g) singing as soloists or members of vocal groups or other bands; and h) practicing and rehearsing to maintain a high standard of performance.\nExamples of the occupations classified here: Band leader, Bassoonist, Drummer, Flutist, Guitarist, Instrumentalist, Keyboardist, Music arranger, Music composer, Music conductor, Musician, Nightclub musician, Nightclub singer, Orchestra conductor, Pianist, Saxophonist, Singer, Street musician, Street singer, Trumpeter, Violinist, Vocal group conductor","version":"2022","source_id":579,"level":4,"normalized_name":"musicians singers and composers"},{"code":"2653","parent_code":"265","title":"DANCERS AND CHOREOGRAPHERS","description":"Dancers and choreographers conceive and create or perform dances.\nTheir tasks include: a) conceiving and creating dances, which often convey a story, theme, idea or mood, by a pattern of steps, movements and gestures; b) performing dances as a soloist, with a partner or as a member of a dancing group before live audiences or for film, television or other visual media; c) training, exercising and attending dance classes to maintain the required levels of ability and fitness; d) directing and participating in rehearsals to practice dance steps and techniques required for a performance; e) auditioning for dance roles or for memberships in dance companies; and f) coordinating the production music with the music directors.\nExamples of the occupations classified here: Ballet dancer, Belly dancer, Choreographer, Cultural dancer, Nightclub dancer, Professional dancer, Street dancer\nRelated occupation classified elsewhere: Dance teacher - 2355","version":"2022","source_id":580,"level":4,"normalized_name":"dancers and choreographers"},{"code":"2654","parent_code":"265","title":"FILM, STAGE AND RELATED DIRECTORS AND PRODUCERS","description":"Film, stage and related directors and producers oversee and control the technical and artistic aspects of motion pictures, television or radio productions and stage shows.\nTheir tasks include: a) choosing writers, studying scripts to determine artistic interpretation, and instructing actors on acting methods; b) directing all aspects of dramatic productions on stage, television, radio or in motion pictures, including choice of actors, and final decisions concerning costumes, set designs, sound or lighting effects; c) planning, organizing and controlling the various stages and scheduling involved in the production of presentations, motion pictures, television shows and radio programs; d) engaging and supervising all technical personnel, and determining the treatment, scope and scheduling of production; e) maintaining production archives and negotiating royalties; f) creating, planning, writing scripts for recording, videotaping and editing programs; and g) supervising the positioning of scenery, props and lighting and sound equipment.\nExamples of the occupations classified here: Director of photography, Documentary director, Film editor, Motion picture director, Stage director, Technical television or radio director, Theater producer, Theatrical director\nSome related occupations classified elsewhere: Broadcasting technician - 3521, Lighting technician - 3521, Sound technician - 3521, Stage manager - 3435, TV/Radio news producer - 2642, Video technician - 3521","version":"2022","source_id":581,"level":4,"normalized_name":"film stage and related directors and producers"},{"code":"2655","parent_code":"265","title":"ACTORS","description":"Actors portray roles in motion pictures, television or radio productions and stage shows.\nTheir tasks include: a) learning lines and cues and playing parts in dramatic productions on stage, commercials, television, radio or in motion pictures; b) assuming characters created by a playwright or author and communicating this to an audience; c) telling stories or reading literary works aloud to educate or entertain listeners; d) attending auditions and casting calls in order to audition for roles; e) preparing for performances through rehearsals under the instruction and guidance of production directors; f) reading scripts and undertaking research to gain understanding of parts, themes and characteristics; and g) acting parts and portraying roles as developed in rehearsals in film, television, radio and stage productions.\nExamples of the occupations classified here: Dubber or voice actor, Mime artist, Motion picture actor/actress, Radio actor/actress, Stage actor/actress, Storyteller, Theater actor/actress\nSome related occupations classified elsewhere: Stunt artist - 3435, Walker-on - 3435","version":"2022","source_id":582,"level":4,"normalized_name":"actors"},{"code":"2656","parent_code":"265","title":"ANNOUNCERS ON RADIO, TELEVISION AND OTHER MEDIA","description":"Announcers on radio, television and other media read news bulletins, conduct interviews, and make other announcements or introductions on radio, television, and in theatres and other establishments or media.\nTheir tasks include: a) reading news bulletins and making other announcements on radio or television; b) introducing performing artists or persons being interviewed, and making related announcements on radio, television, or in theatres, night-clubs and other establishments; c) interviewing persons in public, especially on radio and television; d) studying background information in order to prepare for programs or interviews; and e) commenting on music and other matters , such as weather or traffic conditions.\nExamples of the occupations classified here: Compere' (emcee, show host), News anchor, Radio and television disc or video jockey, Radio announcer, Sports announcer, Television announcer\nRelated occupation classified elsewhere: Journalist - 2642","version":"2022","source_id":583,"level":4,"normalized_name":"announcers on radio television and other media"},{"code":"2659","parent_code":"265","title":"CREATIVE AND PERFORMING ARTISTS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers all creative and performing artists not classified elsewhere in minor group 265, Creative and performing artists. For instance, the group includes clowns, magicians, acrobats and other performing artists.\nTheir tasks include: a) performing amusing antics and telling funny stories; b) performing tricks of illusion and sleight of hand, and feats of hypnotism; c) performing difficult and spectacular acrobatics, and gymnastic or juggling feats; and d) training and performing with animals.\nExamples of the occupations classified here: Acrobat, Aerialist, Clown, Disc jockey (bar and clubs), Hypnotist, Magician, Puppeteer, Stand-up comedian, Ventriloquist, Vlogger","version":"2022","source_id":584,"level":4,"normalized_name":"creative and performing artists not elsewhere classified"},{"code":"3111","parent_code":"311","title":"CHEMICAL AND PHYSICAL SCIENCE TECHNICIANS","description":"Chemical and physical science technicians perform technical tasks to aid in research in chemistry, physics, geology, geophysics, meteorology and astronomy, and in the development of industrial, medical, military and other practical applications of research results.\nTheir tasks include: a) collecting samples and preparing materials and equipment for experiments, tests and analyses; b) carrying out routine laboratory tests and performing a variety of technical support functions to assist chemical and physical scientists in research, development, analysis and testing; c) controlling the quality and quantity of laboratory supplies by testing samples and monitoring usage and preparing detailed estimates of quantities and costs of materials and labor required for projects, according to the specifications given; d) setting up, operating, and maintaining laboratory instruments and equipment, monitoring experiments, making observations, and calculating and recording results; e) preparing materials for experimentation such as freezing and slicing specimens and mixing chemicals; and f) collecting and testing earth and water samples, recording observations and analyzing data in support of geologists or geophysicists.\nExamples of the occupations classified here: Chemistry technician, Geology technician, Meteorology technician, Physics technician\nSome related occupations classified elsewhere: Chemical engineering technician - 3116, Chemical process technician - 3133, Life science technician - 3141","version":"2022","source_id":585,"level":4,"normalized_name":"chemical and physical science technicians"},{"code":"3112","parent_code":"311","title":"CIVIL ENGINEERING TECHNICIANS","description":"Civil engineering technicians perform technical tasks in civil engineering research, design, construction, operation, maintenance and repair of buildings and other structures, such as water supply and wastewater treatment systems, bridges, roads, dams and airports.\nTheir tasks include: a) performing or assisting with field and laboratory tests of soils and construction materials; b) providing technical assistance connected with the construction of buildings and other structures, and with surveys or the preparation of survey reports; c) ensuring compliance with design specifications, relevant legislation and regulations, and maintenance of desired standards of materials and work; d) applying technical knowledge of building and civil engineering principles and practices in order to identify and solve problems arising; e) assisting with the preparation of detailed estimates of quantities and costs of materials and labor required for projects, according to the specifications given; f) organizing maintenance and repairs; g) inspecting buildings and structures during and after construction to ensure that they comply with building, grading, zoning and safety laws and approved plans, specifications and standards, as well as with other rules concerning quality and safety of buildings; h) inspecting industrial plant, hotels, cinemas and other buildings and structures to detect fire hazards and advise on how they can be removed; and i) advising on the installation of fire detectors and sprinkler systems and the use of materials in the construction of buildings and means of transportation to reduce risk of fire and extent of damage and danger if fire occurs.\nExamples of the occupations classified here: Building inspector, Building surveyor, Civil engineering technician, Clerk of works, Fire inspector, Fire prevention specialist, Geotechnical technician, Surveying technician\nSome related occupations classified elsewhere: Fire investigator - 3119, Marine surveyor - 3115, Quantity surveyor - 2149","version":"2022","source_id":586,"level":4,"normalized_name":"civil engineering technicians"},{"code":"3113","parent_code":"311","title":"ELECTRICAL ENGINEERING TECHNICIANS","description":"Electrical engineering technicians perform technical tasks to aid in electrical engineering research, and in the design, manufacture, assembly, construction, operation, maintenance and repair of electrical equipment, facilities and distribution systems.\nTheir tasks include: a) providing technical assistance in research on and development of electrical equipment and facilities, or testing prototypes; b) designing and preparing blueprints of electrical installations and circuitry according to the specifications given; c) preparing detailed estimates of quantities and costs of materials and labor required for manufacture and installation, according to the specifications given; d) monitoring technical aspects of the manufacture, installation, utilization, maintenance and repair of electrical systems and equipment to ensure satisfactory performance and compliance with specifications and regulations; e) planning installation methods, checking completed installation for safety and controls or undertaking the initial running of the new electrical equipment or systems; and f) assembling, installing, testing, calibrating, modifying and repairing electrical equipment and installations to conform with regulations and safety requirements.\nExamples of the occupations classified here: Electric power transmission engineering technician, Electric vehicle (EV) electrical service technician, Electric vehicle supply equipment (EVSE) installation technician, Electrical engineering technician, Gas turbine electrical system technician, High voltage electrical engineering technician, Photovoltaic (PV) system installation technician, Photovoltaic (PV) system maintenance technician\nSome related occupations classified elsewhere: Electrical mechanic - 7412, Electronics engineering technician - 3114, Power production plant operator - 3131","version":"2022","source_id":587,"level":4,"normalized_name":"electrical engineering technicians"},{"code":"3114","parent_code":"311","title":"ELECTRONICS ENGINEERING TECHNICIANS","description":"Electronics engineering technicians perform technical tasks to aid in electronic research, and in the design, manufacture, assembly, construction, operation, maintenance and repair of electronic equipment.\nTheir tasks include: a) providing technical assistance in research and development of electronic equipment, or testing prototypes; b) designing and preparing blueprints of electronic circuitry according to the specifications given; c) preparing detailed estimates of quantities and costs of materials and labor required for the manufacture and installation of electronic equipment, according to the specifications given; d) monitoring technical aspects of the manufacture, utilization, maintenance and repair of electronic equipment to ensure satisfactory performance and ensure compliance with specifications and regulations; e) assisting in the design, development, installation, operation and maintenance of electronic systems; f) planning installation methods, checking completed installation for safety and controls or undertaking the initial running of the new electronic equipment or system; and g) conducting tests of electronic systems, collecting and analyzing data, and assembling circuitry in support of electronics engineers.\nExamples of the occupations classified here: Audio visual systems technician, Electronics and communication equipment technician, Electronics engineering technician, Electronics system technician\nSome related occupations classified elsewhere: Electrical engineering technician - 3113, Electronic equipment assembler - 8212, Electronics mechanic - 7421, Telecommunications engineering technician - 3522","version":"2022","source_id":588,"level":4,"normalized_name":"electronics engineering technicians"},{"code":"3115","parent_code":"311","title":"MECHANICAL ENGINEERING TECHNICIANS","description":"Mechanical engineering technicians perform technical tasks to aid in mechanical engineering research, and in the design, manufacture, assembly, construction, operation, maintenance and repair of machines, components and mechanical equipment.\nTheir tasks include: a) providing technical assistance in research on and development of machines and mechanical installations, facilities and components, or testing prototypes; b) designing and preparing layouts of machines and mechanical installations, facilities and components according to the specifications given; c) preparing detailed estimates of quantities and costs of materials and labor required for manufacture and installation according to the specifications given; d) monitoring technical aspects of manufacture, utilization, maintenance and repair of machines and mechanical installations, facilities and components to ensure satisfactory performance and compliance with specifications and regulations; e) developing and monitoring the implementation of safety standards and procedures for marine survey work in relation to ships' hulls, equipment and cargoes; f) assembling and installing new and modified mechanical assemblies, components, machine tools and controls, and hydraulic power systems; g) conducting tests of mechanical systems, collecting and analyzing data, and assembling and installing mechanical assemblies in support of mechanical engineers; and h) ensuring that mechanical engineering designs and finished work are within specifications, regulations and contract provisions.\nExamples of the occupations classified here: Aeronautics engineering technician, Aircraft maintenance technician, Auto service technician, Boiler technician, Electric vehicle (EV) mechanical service technician, Elevator technician, Gas turbine mechanical system technician, Industrial machinery and tools technician, Maintenance technician, Marine engineering technician, Marine surveyor, Mechanical engineering estimator, Mechanical engineering technician, Power plant technician\nSome related occupations classified elsewhere: Industrial machinery mechanic - 7233, Mechanical machinery assembler - 8211","version":"2022","source_id":589,"level":4,"normalized_name":"mechanical engineering technicians"},{"code":"3116","parent_code":"311","title":"CHEMICAL ENGINEERING TECHNICIANS","description":"Chemical engineering technicians perform technical tasks to aid in chemical engineering research, and in the design, manufacture, construction, operation, maintenance and repair of chemical plant.\nTheir tasks include: a) assisting in research on and development of industrial chemical processes, plant and equipment, or testing prototypes; b) designing and preparing layouts of chemical plants according to the specifications given; c) preparing detailed estimates of quantities and costs of materials and labor required for manufacture and installation according to the specifications given; d) monitoring technical aspects of the construction, installation, operation, maintenance and repair of chemical plants to ensure satisfactory performance and compliance with specifications and regulations; and e) conducting chemical and physical laboratory tests to assist scientists and engineers in making qualitative and quantitative analyses of solids, liquids, and gaseous materials.\nExamples of the occupations classified here: Chemical engineering estimator, Chemical engineering technician, Chemical laboratory technician, Petroleum engineering technician\nSome related occupations classified elsewhere: Chemical process technician - 3133, Chemical technician - 3111","version":"2022","source_id":590,"level":4,"normalized_name":"chemical engineering technicians"},{"code":"3117","parent_code":"311","title":"MINING AND METALLURGICAL TECHNICIANS","description":"Mining and metallurgical technicians perform technical tasks to assist in research and experiments related to metallurgy, in improving methods of extracting solid minerals, oil and gas, and in the design, construction, operation, maintenance and repair of mines and mine installations, of systems for transporting and storing oil and natural gas, and for extraction of metals from ores.\nTheir tasks include: a) providing technical assistance to aid in research on and development of processes to determine the properties of metals and new alloys; b) providing technical assistance in geological and topographical surveys, and in the design and layout of oil, natural gas and mineral ore extraction and transportation systems, and processing and refining plants for minerals and metals; c) preparing detailed estimates of quantities and costs of materials and labor required for mineral, oil and natural gas exploration, extraction, processing and transport projects; d) monitoring technical, regulatory and safety aspects of the construction, installation, operation, maintenance and repair of mineral ore, oil and natural gas exploration, extraction, transport and storage installations and of mineral processing plants; e) helping plan and design mines, mine shafts, tunnels and underground first-aid facilities; f) collecting and preparing rock, mineral and metal samples, performing laboratory tests to determine properties, analyzing and reporting test results and maintaining testing equipment; g) using microscopes, electromagnetic irradiation machines, spectrometers, spectrographs, densitometers and tension testing machines; and h) assisting scientists in the use of electrical, sonic, or nuclear measuring instruments in both laboratory and production activities to obtain data indicating potential sources of metallic ore, gas, or petroleum.\nExamples of the occupations classified here: Extractive engineering technician, Metallurgical technician, Mine inspector, Mines safety inspector, Mining engineering technician, Oil and gas wells acidizer, Petroleum and natural gas extraction technician\nSome related occupations classified elsewhere: Geology technician - 3111, Miner - 8111, Mining plant operator - 8111, Quarrier - 8111","version":"2022","source_id":591,"level":4,"normalized_name":"mining and metallurgical technicians"},{"code":"3118","parent_code":"311","title":"DRAFTSMEN","description":"Draftsmen prepare technical drawings, maps and illustrations from sketches, measurements and other data, and copy final drawings and paintings on to printing plates.\nTheir tasks include: a) preparing and revising working drawings from sketches and specifications prepared by engineers and designers for the manufacture, installation and erection of machinery and equipment or for the construction, modification, maintenance and repair of buildings, dams, bridges, roads and other architectural and civil engineering projects; b) operating computer-aided design and drafting equipment to create, modify and generate hard-copy and digital representations of working drawings; c) operating digitizing table or similar equipment to transfer hard-copy representation of working drawings, maps and other curves to digital form; d) preparing and revising illustrations for reference works, brochures and technical manuals dealing with the assembly, installation, operation, maintenance and repair of machinery and other equipment and goods; e) copying drawings and paintings onto stone or metal plates for printing; f) preparing wiring diagrams, circuit board assembly diagrams, and layout drawings used for manufacture, installation, and repair of electrical equipment in factories, power plants, and buildings; g) creating detailed working diagrams of machinery and mechanical devices, including dimensions, fastening methods, and other engineering information; and h) arranging for completed drawings to be reproduced for use as working drawings.\nExamples of the occupations classified here: Draftsman; Draftsman, architectural; Draftsman, cartographical; Draftsman, electrical; Draftsman, engineering/civil; Draftsman, hydrographic; Draftsman, lithographic; Draftsman, marine; Draftsman, mechanical; Draftsman, structural; Technical illustrator\nSome related occupations classified elsewhere: Cartographer - 2165, Surveyor - 2165","version":"2022","source_id":592,"level":4,"normalized_name":"draftsmen"},{"code":"3119","parent_code":"311","title":"PHYSICAL AND ENGINEERING SCIENCE TECHNICIANS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers physical and engineering science technicians not classified elsewhere in Minor group 311, Physical and engineering science technicians. For instance, the group includes those who assist scientists and engineers engaged in developing procedures or conducting research on safety, biomedical, environmental or industrial and production engineering.\nTheir tasks include: a) collecting data and providing technical assistance regarding: efficient, safe and economic utilization of personnel, material and equipment; methods of work and sequence of operations and supervision of their implementation; and efficient layout of plant or establishment; b) aiding in the identification of potential hazards and introducing safety procedures and devices; c) modifying and testing equipment and devices used in the prevention, control, and remediation of environmental pollution, site remediation, and land reclamation; d) assisting in the development of environmental pollution remediation devices under the direction of an engineer; and e) assisting engineers in testing and designing robotics equipment.\nExamples of the occupations classified here: Electric vehicle (EV) test technician, Fire investigator, Forensic science technician, Health physics technician, Industrial efficiency engineering technician, Instrument technician, Motor vehicle inspection system (MVIS) electric vehicle (EV) testing specialist, Production engineering technician, Quality control technician, Quantity surveying technician, Robotics technician, Test technician, Time and motion study technician\nSome related occupations classified elsewhere: Aeronautics engineering technician - 3115, Production engineer - 2149, Quantity surveyor - 2149","version":"2022","source_id":593,"level":4,"normalized_name":"physical and engineering science technicians not elsewhere classified"},{"code":"3121","parent_code":"312","title":"MINING SUPERVISORS","description":"Mining supervisors oversee mining and quarrying operations and directly supervise and coordinate the activities of miners working in underground and surface mines and quarries.\nTheir tasks include: a) directly supervising and coordinating the activities of workers who extract minerals and other natural deposits from the earth, operate underground conveyances or heavy equipment in surface mines and quarries; b) establishing methods to meet work schedules and recommending measures to mining managers to improve productivity; c) working with managerial and technical personnel, other departments and contractors to resolve operational problems and coordinate activities; d) providing reports and other information to mining managers about all aspects of mining or quarrying operations; and e) determining staffing and material needs for the mine or quarry.\nExamples of the occupations classified here: Mine deputy, Mine foreman, Mine supervisor, Mine under-manager, Quarry supervisor\nSome related occupations classified elsewhere: Mine inspector - 3117, Mine manager - 1322, Miner - 8111, Quarrier - 8111","version":"2022","source_id":594,"level":4,"normalized_name":"mining supervisors"},{"code":"3122","parent_code":"312","title":"MANUFACTURING SUPERVISORS","description":"Manufacturing supervisors coordinate and supervise the activities of process control technicians, machine operators, assemblers, and other manufacturing laborers.\nTheir tasks include: a) coordinating and supervising the activities of process control technicians, machine operators, assemblers, and other manufacturing laborers; b) organizing and planning the daily work with regard to plans, economy, staff and environment; c) preparing cost estimates, records and reports; d) identifying shortage of staff or components; e) ensuring safety of workers; and f) instructing and training new staff.\nExamples of the occupations classified here: Area coordinator, manufacturing, Assembly supervisor, Finishing supervisor, Production line leader, Production supervisor, manufacturing\nRelated occupation classified elsewhere: Manufacturing manager - 1321","version":"2022","source_id":595,"level":4,"normalized_name":"manufacturing supervisors"},{"code":"3123","parent_code":"312","title":"CONSTRUCTION SUPERVISORS","description":"Construction supervisors, coordinate, supervise and schedule the activities of workers engaged in the construction and repair of buildings and structures.\nTheir tasks include: a) reading specifications to determine construction requirements and planning procedures; b) organizing and coordinating the material and human resources required to complete jobs; c) examining and inspecting work progress; d) examining equipment and construction sites to ensure that heath and safety requirements are met; e) supervising construction sites and coordinating work with other construction projects; and f) supervising the activities of building trades workers, laborers and other construction workers.\nExamples of the occupations classified here: Building construction supervisor, Construction foreman, Site manager, construction\nSome related occupations classified elsewhere: Building work construction laborer - 9313, Civil engineering construction laborer - 9312, Clerk of works - 3112, Construction project manager - 1323, Project builder - 1323","version":"2022","source_id":596,"level":4,"normalized_name":"construction supervisors"},{"code":"3131","parent_code":"313","title":"POWER PRODUCTION PLANT OPERATORS","description":"Power-production plant operators operate, monitor and maintain switchboards and related equipment in electrical control centers which control the production and distribution of electrical or other power in transmission networks. The equipment operated includes reactors, turbines, generators and other auxiliary equipment in electrical power generating stations.\nTheir tasks include: a) operating, monitoring and inspecting various types of energy generating power plants; b) operating and controlling power generating systems and equipment including boilers, turbines, generators, condensers, and reactors in hydro, thermal, coal, oil, natural gas, and nuclear power plants to generate and distribute electrical power; c) controlling start-up and shut-down of power plant equipment, controlling switching operations, regulating water levels and communicating with systems operators to regulate and coordinate transmission loads, frequency and line voltages; d) taking readings from charts, meters and gauges at established intervals, troubleshooting and performing corrective action as necessary; e) completing and maintaining station records, logs and reports, and communicating with other plant personnel to assess equipment operating status; and f) cleaning and maintaining equipment such as generators, boilers, turbines, pumps, and compressors in order to prevent equipment failure or deterioration.\nExamples of the occupations classified here: Distribution control operator, Electric power plant operator, Generating station operator, Hydroelectric power plant operator, Nuclear power plant operator, Power system operator, Renewable energy plant operator, Solar power plant operator\nRelated occupation classified elsewhere: Steam engine and boiler operators - 8182","version":"2022","source_id":597,"level":4,"normalized_name":"power production plant operators"},{"code":"3132","parent_code":"313","title":"INCINERATOR AND WATER TREATMENT PLANT OPERATORS","description":"Incinerator and water-treatment plant operators monitor and operate computerized control systems and related equipment in solid and liquid waste treatment plants to regulate the treatment and disposal of sewage and wastes, and in water filtration and treatment plants to regulate the treatment and distribution of water.\nTheir tasks include: a) operating and monitoring computerized control systems, machinery and related equipment in wastewater treatment, sewage treatment, and liquid waste plants to regulate flow, treatment and disposal of sewage and wastes, and in water filtration and treatment plants to regulate the treatment and distribution of water for human consumption and for later disposal into natural water systems; b) controlling the operation of multiple-hearth incinerator furnaces and related equipment to burn sludge and solid waste in waste treatment plants; c) inspecting equipment and monitoring operating conditions, meters, filters, chlorinators, and gauges in central control room to determine load requirements, to verify that flows, pressures, and temperatures are within specification, and to detect malfunctions; d) monitoring and adjusting controls of auxiliary equipment, such as exhaust emissions, scrubbers, and incinerator heat recovery units; e) collecting and testing water and sewage samples for chemical and bacterial content, using test equipment and color analysis standards; f) analyzing test results to make adjustments to plant equipment and systems to disinfect and deodorize water and other liquids; g) performing security and safety checks in plant and on grounds; and h) completing and maintaining plant logs and reports.\nExamples of the occupations classified here: Incinerator operator, Liquid waste process operator, Pumping-station operator, Sewage plant operator, Wastewater operator, Water treatment plant operator","version":"2022","source_id":598,"level":4,"normalized_name":"incinerator and water treatment plant operators"},{"code":"3133","parent_code":"313","title":"CHEMICAL PROCESSING PLANT CONTROLLERS","description":"Chemical processing plant controllers operate and monitor chemical plants and adjust and maintain, processing units and equipment which distil, filter, separate, heat or refine chemicals.\nTheir tasks include: a) operating electronic or computerized control panel from a central control room to monitor and optimize physical and chemical processes for several processing units; b) adjusting equipment, valves, pumps, controls and process equipment; c) controlling the preparation, measuring and feeding of raw materials and processing agents such as catalysts and filtering media into plant; d) controlling process start-up and shut-down, troubleshooting and monitoring outside process equipment; e) verifying equipment for malfunctions, carrying out routine operating tests and arranging for maintenance; and f) analyzing sample products, performing tests, recording data and writing production logs.\nExamples of the occupations classified here: Chemical filtering and separating equipment operator, Chemical heat treating plant operator, Chemical process technician, Chemical still and reactor operator\nSome related occupations classified elsewhere: Petroleum and natural gas refining plant operators - 3134, Chemical products plant and machine operators - 8131","version":"2022","source_id":599,"level":4,"normalized_name":"chemical processing plant controllers"},{"code":"3134","parent_code":"313","title":"PETROLEUM AND NATURAL GAS REFINING PLANT OPERATORS","description":"Petroleum and natural gas refining plant operators operate and monitor plants and adjust and maintain processing units and equipment which refine, distil and treat petroleum, petroleum-based products and by-products, or natural gas.\nTheir tasks include: a) operating electronic or computerized control panels from a central control room to monitor and optimize physical and chemical processes for several processing units; b) adjusting equipment, valves, pumps, controls and process equipment; c) controlling process start-up and shut-down, troubleshooting and monitoring outside process equipment; d) verifying equipment for malfunctions, testing well pipes for leaks and fractures and arranging for maintenance; and e) analyzing sample products, performing tests, recording data and writing production logs.\nExamples of the occupations classified here: Gas plant operator, Paraffin plant operator, Petroleum and natural gas refining blender operator, Petroleum and natural gas refining still operator, Petroleum process operator, Refinery process technician\nSome related occupations classified elsewhere: Chemical processing plant controllers - 3133, Chemical products plant and machine operators - 8131","version":"2022","source_id":600,"level":4,"normalized_name":"petroleum and natural gas refining plant operators"},{"code":"3135","parent_code":"313","title":"METAL PRODUCTION PROCESS CONTROLLERS","description":"Metal production process controllers operate and monitor multi-function process control machinery and equipment to control the processing of metal converting and refining furnaces, metal-rolling mills, metal heat-treating, or metal-extrusion plant.\nTheir tasks include: a) coordinating and monitoring the operation of a particular aspect of metal processing production through control panels, computer terminals or other control systems, usually from a central control room; b) operating multi-function central process control machinery to grind, separate, filter, melt, roast, treat, refine or otherwise process metals; c) observing computer printouts, video monitors and gauges to verify specified processing conditions and to make necessary adjustments; d) coordinating and supervising production crew such as machine and process operators, assistants and helpers; e) starting up and shutting down the production system in cases of emergency or as required by schedule; f) providing and organizing training for members of production crew; and g) maintaining shift log of production and other data and preparing production and other reports.\nExamples of the occupations classified here: Blast furnace operator, Casting metal machine operator, Central control caster, Metal melting furnace operator, Metal processing control operator, Rolling mill control operator\nSome related occupations classified elsewhere: Ladle pourer - 8121, Metal finishing machine operator - 8122, Steel roller - 8121","version":"2022","source_id":601,"level":4,"normalized_name":"metal production process controllers"},{"code":"3139","parent_code":"313","title":"PROCESS CONTROL TECHNICIANS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers process control technicians not classified elsewhere in minor group 313 Process control technicians. For instance, the group includes those who operate multiple process control equipment in manufacturing assembly lines and paper and pulp production.\nExamples of the occupations classified here: Automated assembly line operator, Industrial robot controller, Paper and pulp panel board operator, Paper pulp refinery operator, Pulping control operator, Pulping technician","version":"2022","source_id":602,"level":4,"normalized_name":"process control technicians not elsewhere classified"},{"code":"3141","parent_code":"314","title":"LIFE SCIENCE TECHNICIANS (excluding medical)","description":"Life science technicians (except medical) provide technical support to life science professionals undertaking research, analysis and testing of living organisms, and development and application of products and processes resulting from research in areas such as natural resource management, environmental protection, plant and animal biology, microbiology, and cell and molecular biology.\nTheir tasks include: a) assisting in designing, setting up and conducting experiments; b) setting up, calibrating, operating and maintaining laboratory instruments and equipment; c) collecting and preparing specimens and samples, chemical solutions and slides and growing cultures for use in experiments; d) performing routine field and laboratory tests; e) monitoring experiments to ensure adherence to correct laboratory quality control procedures and health and safety guidelines; f) making observations of tests, and analyzing, calculating, recording and reporting test results using appropriate scientific methods; g) preserving, classifying and cataloguing specimens and samples; h) keeping detailed logs of worked performed; i) using computers to develop models and analyze data; j) using complex and high-powered equipment to perform work; k) participating in the research, development and manufacture of products and processes; l) ordering and stocking laboratory supplies; and m) maintaining relevant databases.\nExamples of the occupations classified here: Bacteriology technician, Biochemistry technician, Herbarium technician, Pharmacology technician, Serology technician, Tissue culture technician, Zoology technician\nSome related occupations classified elsewhere: Forensic science technician - 3119, Medical laboratory technician - 3212, Pathology laboratory technician - 3212, Pharmaceutical technician - 3213","version":"2022","source_id":603,"level":4,"normalized_name":"life science technicians excluding medical"},{"code":"3142","parent_code":"314","title":"AGRICULTURAL TECHNICIANS","description":"Agricultural technicians perform tests and experiments, and provide technical and scientific support to agricultural scientists, farmers and farm managers.\nTheir tasks include: a) preparing materials and equipment for experiments, tests and analyses; b) collecting and preparing specimens such as soils, plant or animal cells, tissues or parts or animal organs for experiments, tests and analyses; c) assisting with and performing experiments, tests and analyses applying methods and techniques such as microscopy, histochemistry, chromatography, electrophoresis and spectroscopy; d) identifying pathogenic micro-organisms and insects, parasites, fungi and weeds harmful to crops and livestock, and assisting in devising methods of control; e) analyzing produce to set and maintain standards of quality; f) conducting or supervising operational programs such as fish hatchery, greenhouse and livestock production programs; g) analyzing samples of seeds for quality, purity and germination rating; h) collecting data and estimating quantities and costs of materials and labor required for projects; and i) organizing maintenance and repairs of research equipment.\nExamples of the occupations classified here: Agronomy technician, Aquaculture technician, Dairy technician, Farm demonstrator, Field crop technician, Fishery technician, Herd tester, Horticultural technician, Orchard technician, Pest control technician, Plant propagation technician, Poultry technician, Prawn farm technician, Rice farm technician, Soil technician, Sugar farm technician\nSome related occupations classified elsewhere: Artificial inseminator - 3240, Veterinary technician - 3240","version":"2022","source_id":604,"level":4,"normalized_name":"agricultural technicians"},{"code":"3143","parent_code":"314","title":"FORESTRY TECHNICIANS","description":"Forestry technicians perform technical and supervisory functions in support of forestry research and forest management, harvesting, resource conservation and environmental protection.\nTheir tasks include: a) conducting forest inventories, surveys and field measurements following accepted scientific and operational procedures; b) assisting in and performing technical functions in the preparation of forest management and harvest plans using photogrammetric and mapping techniques and computerized information systems; c) assisting in planning and supervision of construction of access routes and forest roads; d) implementing, supervising and performing technical functions in silvicultural operations involving site preparation, planting, and tending of tree crops; e) coordinating activities such as timber scaling, forest fire suppression, disease or insect control or pre-commercial thinning of forest stands; f) supervising and performing technical functions in forest harvesting operations; g) ensuring adherence to regulations and policies concerning environmental protection, resource utilization, fire safety and accident prevention; h) supervising forest tree nursery operations; i) providing technical support to forestry research programs in areas such as tree improvement, seed orchard operations, insect and disease surveys or experimental forestry and forest engineering research; and j) preparing forest cultivation and cutting plans.\nExamples of the occupations classified here: Forestry technician, Silviculture technician","version":"2022","source_id":605,"level":4,"normalized_name":"forestry technicians"},{"code":"3151","parent_code":"315","title":"SHIPS' ENGINEER","description":"Ships’ engineers control and participate in the operation, maintenance and repair of mechanical, electrical and electronic equipment and machinery on board ship, or perform related supporting functions on shore.\nTheir tasks include: a) controlling and participating in the operation, maintenance and repair of mechanical, electrical and electronic equipment and machinery on board ship; b) ordering fuel and other engine-room department stores and maintaining record of operations; c) performing technical supervision of the installation, maintenance and repair of ship’s machinery and equipment to ensure compliance with specifications and regulations; d) inspecting and conducting maintenance and emergency repairs to engines, machinery and auxiliary equipment; and e) standing engine room watch, monitoring and noting performance of engines, machinery and auxiliary equipment.\nExamples of the occupations classified here: Chief ship engineer, Marine technical superintendent \nRelated occupation classified elsewhere: Marine engineer - 2144","version":"2022","source_id":606,"level":4,"normalized_name":"ships engineer"},{"code":"3152","parent_code":"315","title":"SHIPS' DECK OFFICERS AND PILOTS","description":"Ships’ deck officers and pilots command and navigate ships and similar vessels, and perform related functions on shore.\nTheir tasks include: a) commanding and navigating ship or similar vessel at sea or on inland waterways; b) controlling and participating in deck and bridge-watch activities; c) navigating vessels into and out of ports and through channels, straits and other waters where special knowledge is required; d) ensuring safe loading and unloading of cargo and observance of safety regulations and procedures by crew and passengers; e) performing technical supervision of maintenance and repair of ship to ensure compliance with specifications and regulations; f) applying knowledge of principles and practices relating to ship’s operation and navigation in order to identify and solve problems arising in the course of their work; g) ordering ship’s stores and recruiting crew as required and maintaining record of operations; and h) transmitting and receiving routine and emergency information with shore stations and other ships.\nExamples of the occupations classified here: Deck cadet, Inland waterways ship master, Marine deck superintendent, Sea ship captain, Sea ship master, Ship chief mate, Ship navigation officer, Ship pilot, Shipping operations officer, Yacht skipper\nSome related occupations classified elsewhere: Coastal fishery skipper - 6222, Sailor - 8350, Trawler skipper - 6223","version":"2022","source_id":607,"level":4,"normalized_name":"ships deck officers and pilots"},{"code":"3153","parent_code":"315","title":"AIRCRAFT PILOTS AND RELATED ASSOCIATE PROFESSIONALS","description":"Aircraft pilots and related associate professionals control the operation of mechanical, electrical and electronic equipment, in order to navigate aircraft for transporting passengers, mail and freight and perform related pre-flight and in-flight tasks.\nTheir tasks include: a) flying and navigating aircraft in accordance with established control and operating procedures; b) preparing and submitting flight plan or examining standard flight plan; c) controlling the operation of mechanical, electrical and electronic equipment and ensuring that all instruments and controls work properly; d) applying knowledge of principles and practices of flying in order to identify and solve problems arising in the course of their work; e) examining maintenance records and conducting inspections to ensure that aircraft are mechanically sound, maintenance has been performed and that all equipment is operational; f) signing necessary certificates and maintaining official records of flight; and g) obtaining briefings and clearances before flights and maintaining contact with air traffic or flight control during flight.\nExamples of the occupations classified here: Aerial crop sprayer, Aircraft maintenance officer, Aircraft pilot, Aircraft pilot, Astronaut, Flight engineer, Flight navigator, Flying instructor, Helicopter pilot","version":"2022","source_id":608,"level":4,"normalized_name":"aircraft pilots and related associate professionals"},{"code":"3154","parent_code":"315","title":"AIR TRAFFIC CONTROLLERS","description":"Air traffic controllers direct aircraft movements in airspace and on the ground, using radio, radar and lighting systems, and provide information relevant to the operation of aircraft.\nTheir tasks include: a) directing and controlling aircraft approaching and leaving airport and their movement on the ground; b) directing and controlling aircraft operating in designated airspace sector; c) examining and approving flight plans; d) informing flight crew and operations staff about weather conditions, operational facilities, flight plans and air traffic; e) applying knowledge of principles and practices of air traffic control in order to identify and solve problems arising in the course of their work; f) initiating and organizing emergency, search and rescue services and procedures; g) directing activities of all aircraft and service vehicles on or near airport runways; and h) maintaining radio and telephone contact with adjacent control towers, terminal control units and other control centers, and coordinating the movement of aircraft into adjoining areas.\nExamples of the occupations classified here: Airways communicator, Control tower officer, Control tower radio operator, Flight control tower operator, Flight radio operator","version":"2022","source_id":609,"level":4,"normalized_name":"air traffic controllers"},{"code":"3155","parent_code":"315","title":"AIR TRAFFIC SAFETY ELECTRONICS TECHNICIANS","description":"Air traffic safety electronics technicians perform technical tasks concerning the design, installation, management, operation, maintenance and repair of air traffic control and air navigation systems.\nTheir tasks include: a) carrying out technical duties related to the development of electronic and computerized air navigation systems and equipment, and testing prototypes; b) providing technical help in the design and layout of specific interface circuitry of air navigation and aircraft detection tracking systems; c) preparing and contributing to the preparation of cost estimates and technical and training specifications for air traffic control and safety equipment; d) providing or assisting with the technical supervision of construction, installation and operation of ground-based air navigation equipment and its maintenance and repair to ensure that standards and specifications are met; e) applying the knowledge and skills of air traffic safety engineering principles and practices in order to identify and solve problems arising in the course of their work; f) developing, modifying and debugging system software; g) modifying existing ground-based air navigation systems and equipment to adapt them to new air traffic control procedures, in order to improve capability, reliability and integrity, or to facilitate air traffic control procedures and airspace designation; h) controlling, monitoring and certifying communication navigation and surveillance air traffic management equipment and calibrating the ground-based air navigation system to ensure maximum accuracy and safety of flight, take-off and landing operations; and i) providing technical training and supervising other workers.\nExamples of the occupations classified here: Air traffic safety engineer, Air traffic safety technician, Airfield power technician, Ground signaling technician\nSome related occupations classified elsewhere: Aeromechanic - 7232, Aeronautical engineer - 2144, Avionics aircraft maintenance engineer - 7421, Avionics technician - 7421, Electronics engineer - 2151","version":"2022","source_id":610,"level":4,"normalized_name":"air traffic safety electronics technicians"},{"code":"3211","parent_code":"321","title":"MEDICAL IMAGING AND THERAPEUTIC EQUIPMENT TECHNICIANS","description":"Medical imaging and therapeutic equipment technicians test and operate radiographic, ultrasound and other medical imaging equipment to produce images of body structures for the diagnosis and treatment of injury, disease and other impairments. They may administer radiation treatments to patients under the supervision of a radiologist or other health professional.\nTheir tasks include: a) operating or overseeing operation of radiologic, ultrasound and magnetic imaging equipment to produce images of the body for diagnostic purposes; b) explaining procedures, observing and positioning patients, and using protection devices to ensure safety and comfort during examination, scan, or treatment; c) position imaging or treatment equipment, monitoring video displays, and adjusting settings and controls according to technical specifications; d) reviewing and evaluating developed x-rays, video tape, or computer generated information to determine if images are satisfactory for diagnostic purposes and recording results of procedures; e) monitoring patients' conditions and reactions, reporting abnormal signs to a medical practitioner; f) measuring and recording radiation dosage or radiopharmaceuticals received and used for patients, following prescription issued by a medical practitioner; g) administering, detecting and mapping radiopharmaceuticals or radiation in patients' bodies, using radioisotope, camera or other equipment for diagnosing and treating diseases; and h) recording and disposing of radioactive materials and storing radiopharmaceuticals, following radiation safety procedures.\nExamples of the occupations classified here: Cobalt machine technician, Computed Tomography (CT) scan technologist, Diagnostic medical radiographer, Dialysis machine technician, Electrocardiographic equipment technician, Electroencephalographic equipment technician, Endoscopic microscopy technician, Mammographer, Medical radiation therapist, Medical scanning equipment technician, Medical ultrasound machine technician, Medical x-ray equipment technician, Nuclear medicine technologist, Radiographer, Radiology technician, Sonographer\nSome related occupations classified elsewhere: Medical imaging assistant - 5329, Medical physicist - 2111, Radiation protection expert - 2263, Radiologist - 2212","version":"2022","source_id":611,"level":4,"normalized_name":"medical imaging and therapeutic equipment technicians"},{"code":"3212","parent_code":"321","title":"MEDICAL AND PATHOLOGY LABORATORY TECHNICIANS","description":"Medical and pathology laboratory technicians perform clinical tests on specimens of bodily fluids and tissues in order to obtain information about the health of a patient or cause of death.\nTheir tasks include: a) conducting chemical analysis of body fluids, including blood, urine, and spinal fluid, to determine presence of normal and abnormal components; b) operating, calibrating and maintaining equipment used in quantitative and qualitative analysis, such as spectrophotometers, calorimeters, flame photometers, and computer-controlled analyzers; c) entering data from analysis of laboratory tests and clinical results into records-keeping systems and reporting results to medical practitioners and other health professionals; d) analyzing samples of biological material for chemical content or reaction; e) setting up, cleaning, and maintaining laboratory equipment; f) analyzing laboratory findings to check the accuracy of the results; g) establishing and monitoring programs to ensure the accuracy of laboratory results and developing, standardizing, evaluating, and modifying procedures, techniques and tests used in the analysis of specimens; h) obtaining specimens, cultivating, isolating and identifying micro-organisms for analysis; i) examining cells stained with dye to locate abnormalities; and j) inoculating fertilized eggs, broths, or other bacteriological media with organisms.\nExamples of the occupations classified here: Biological laboratory technician, Biomedical technician, Blood-bank technician, Cytology technician, Medical laboratory technician, Pathology laboratory technician\nSome related occupations classified elsewhere: Forensic science technician - 3119, Pathologist - 2212, Phlebotomist - 5329, Veterinary technician - 3240","version":"2022","source_id":612,"level":4,"normalized_name":"medical and pathology laboratory technicians"},{"code":"3213","parent_code":"321","title":"PHARMACEUTICAL TECHNICIANS AND ASSISTANTS","description":"Pharmaceutical technicians and assistants perform a variety of tasks associated with dispensing medicinal products under the guidance of a pharmacist or other health professional.\nTheir tasks include: a) preparing medications and other pharmaceutical compounds under the guidance of a pharmacist or other health professional; b) dispensing medicines and drugs to clients and giving written and oral instructions on their use, as prescribed by medical doctors, veterinarians or other health professionals; c) receiving prescriptions or refill requests from health professionals and verifying that information is complete and accurate according to medical records keeping standards; d) maintaining proper storage and security conditions for drugs; e) filling and labelling containers with prescribed medications; f) assisting clients by answering questions, locating items or referring them to a pharmacist for medication information; g) pricing and filing prescriptions that have been filled and establish and maintaining patient records, including lists of medications taken by individual patients; h) ordering, labelling, and counting stock of medications, chemicals, and supplies, and entering inventory data into records-keeping systems; and i) cleaning and preparing equipment and containers used to prepare and dispense medicines and pharmaceutical compounds.\nExamples of the occupations classified here: Dispensing technician, Pharmaceutical assistant, Pharmaceutical technician\nSome related occupations classified elsewhere: Pharmacist - 2262, Pharmacology technician - 3141, Pharmacy aide - 5329","version":"2022","source_id":613,"level":4,"normalized_name":"pharmaceutical technicians and assistants"},{"code":"3214","parent_code":"321","title":"MEDICAL AND DENTAL PROSTHETIC TECHNICIANS","description":"Medical and dental prosthetic technicians design, fit, service and repair medical and dental devices and appliances following prescriptions or instructions established by a health professional. They may service a wide range of support instruments to correct physical medical or dental problems such as neck braces, orthopedic splints, artificial limbs, hearing aides, arch supports, dentures, and dental crowns and bridges.\nTheir tasks include: a) examining, interviewing, and measuring patients in order to determine their appliance needs, and to identify factors that could affect appliance fit; b) conferring with medical and dental practitioners in order to formulate specifications and prescriptions for devices and appliances; c) interpreting prescriptions or specifications to determine the type of product or device to be fabricated, and the materials and tools that will be required; d) making or receiving casts or impressions of patients' torsos, limbs, mouths or teeth for use as fabrication patterns; e) designing and making orthotic and prosthetic devices using materials such as thermoplastic and thermosetting materials, metal alloys and leather, and hand and power tools; f) fitting appliances and devices onto patients, testing and evaluating them, and making adjustments for proper fit, function, and comfort; g) repairing, modifying, and maintaining medical and dental prosthetic and supportive devices, according to specifications; h) bending, forming, and shaping fabric or material so that it conforms to prescribed contours needed to fabricate structural components; i) fabricating full and partial dentures and constructing mouth guards, crowns, metal clasps, inlays, bridgework and other aids; and j) instructing patients in the use and care of prosthetic or orthotic devices.\nExamples of the occupations classified here: Dental mechanic, Dental technician, Denturist, Orthodontic technician, Orthopedic appliance maker, Orthotic technician, Orthotist, Prosthetic technician, Prosthetist\nSome related occupations classified elsewhere: Dental aide - 5329, Surgical instruments maker - 7311","version":"2022","source_id":614,"level":4,"normalized_name":"medical and dental prosthetic technicians"},{"code":"3221","parent_code":"322","title":"NURSING ASSOCIATE PROFESSIONALS","description":"Nursing associate professionals provide basic nursing and personal care for people in need of such care due to effects of ageing, illness, injury, or other physical or mental impairment. They generally work under the supervision of, and in support of implementation of health care, treatment and referrals plans established by, medical, nursing and other health professionals.\nTheir tasks include: a) providing nursing and personal care and treatment and health advice to patients as per care plans established by health professionals; b) administering medications and other treatments to patients, monitoring patients' condition and responses to treatment, and referring patients and their families to a health professional for specialized care as needed; c) cleaning wounds and applying surgical dressings; d) updating information on patients' condition and treatments received in records-keeping systems; e) assisting in planning and managing the care of individual patients; and f) assisting in giving first-aid treatment in emergencies.\nExamples of the occupations classified here: Assistant nurse, Associate professional nurse\nSome related occupations classified elsewhere: Associate professional midwife - 3222, Clinical nurse consultant - 2221, Home nursing aide - 5322, Hospital or clinic nursing aide - 5321, Professional midwife - 2222, Professional nurse - 2221, Specialist nurse - 2221","version":"2022","source_id":615,"level":4,"normalized_name":"nursing associate professionals"},{"code":"3222","parent_code":"322","title":"MIDWIFERY ASSOCIATE PROFESSIONALS","description":"Midwifery associate professionals provide basic health care and advice before, during and after pregnancy and childbirth. They implement care, treatment and referral plans usually established by medical, midwifery and other health professionals.\nTheir tasks include: a) providing advice to women, families and communities on health, nutrition, hygiene, exercise, birth and emergency plans, breastfeeding, infant care, family planning and contraception, lifestyle and other topics related to pregnancy and childbirth; b) assessing progress during pregnancy and childbirth, and recognizing signs and symptoms requiring referral to a health professional; c) providing delivery care, usually only in the absence of identified potential complications, or assisting medical doctors or midwifery professionals with delivery care; and d) providing care and support to women and newborns following childbirth, monitoring their health status, and identifying signs and symptoms requiring referral to a health professional.\nExamples of the occupations classified here: Assistant midwife, Traditional midwife\nSome related occupations classified elsewhere: Birth assistant - 5321, Clinical nurse consultant - 2221, Midwifery attendant - 5321, Nursing aide - 5321, Professional midwife - 2222, Professional nurse - 2221, Specialist nurse - 2221","version":"2022","source_id":616,"level":4,"normalized_name":"midwifery associate professionals"},{"code":"3230","parent_code":"323","title":"TRADITIONAL AND COMPLEMENTARY MEDICINE ASSOCIATE PROFESSIONALS","description":"Traditional and complementary medicine associate professionals prevent, care for and treat human physical and mental illnesses, disorders and injuries using herbal and other therapies based on theories, beliefs and experiences originating in specific cultures. \nTheir tasks include: a) examining patients and interviewing them and their families to determine their health status and the nature of physical or mental disorders or illnesses or other ailments; b) recommending and providing care and treatment for illnesses and other ailments using traditional techniques and medicaments, such as physical manipulation and exercises, blood-letting using natural vessels, and preparations using herbs, plants, insects and animal extracts; c) providing care and treatment for physical injuries such as setting and healing fractured and dislocated bones using traditional methods of physical manipulation and herbal therapies; d) advising individuals, families and the community on health, nutrition, hygiene, lifestyle and other issues to maintain or improve health and well-being; and e) referring patients to, and exchanging information with, other health care providers to ensure comprehensive and continuing care.\nExamples of the occupations classified here: Acupuncture technician, Ayurvedic technician, Bonesetter, Drugless treatment healer, Healer of indigenous people (e.g. Mansi-bok (Ibaloi); Mansip-ok (Kankana-ey) in Cordilleras), Herbalist, Homeopathy technician , Scraping and cupping therapist, Village healer, Witch doctor\nSome related occupations classified elsewhere: Acupressure therapist - 3255, Acupuncturist - 2230, Ayuverdic practitioner - 2230, Chinese herbal medicine practitioner - 2230, Chiropractor - 2269, Faith healer - 3413, Homeopath - 2230, Hydrotherapist - 3255, Naturopath - 2230, Osteopath - 2269, Traditional midwife - 3222","version":"2022","source_id":617,"level":4,"normalized_name":"traditional and complementary medicine associate professionals"},{"code":"3240","parent_code":"324","title":"VETERINARY TECHNICIANS AND ASSISTANTS","description":"Veterinary technicians and assistants carry out advisory, diagnostic, preventive and curative veterinary tasks, more limited in scope and complexity than those carried out by veterinarians. They care for animals under treatment and in temporary residence at veterinary facilities and assist veterinarians to perform procedures and operations.\nTheir tasks include: a) advising communities and individuals on the treatment of animals and their diseases and injuries; b) conducting examinations of animals to make diagnoses or refer more difficult cases to veterinarians when needed; c) treating ill or injured animals, especially for common diseases and disorders; d) cleaning and sterilizing examination tables and instruments and preparing materials used in the examination and treatment of animals; e) carrying out technical tasks connected with artificial insemination of animals; f) getting animals ready for examination or treatment and restraining or holding them during treatment; g) assisting veterinarians to administer anesthetics and oxygen during treatment; h) placing animals in cages for recovery from operations and monitoring their condition; i) producing radiographs, collecting samples, and performing other laboratory tests to assist in diagnosis of animal health problems; and j) performing routine animal dental procedures and assisting veterinarians with animal dentistry.\nExamples of the occupations classified here: Artificial inseminator, Veterinary assistant, Veterinary laboratory technician, Veterinary nurse, Veterinary vaccinator\nSome related occupations classified elsewhere: Animal attendant - 5164, Veterinarian - 2250, Veterinary aide - 5164","version":"2022","source_id":618,"level":4,"normalized_name":"veterinary technicians and assistants"},{"code":"3251","parent_code":"325","title":"DENTAL ASSISTANTS AND THERAPISTS","description":"Dental assistants and therapists provide basic dental care services for the prevention and treatment of diseases and disorders of the teeth and mouth, as per care plans and procedures established by a dentist or other oral health professional.\nTheir tasks include: a) advising communities and individuals on dental hygiene, diet and other preventive measures to reduce potential risks to oral health; b) conducting visual and physical examinations of patients' mouths, teeth and related structures to assess oral health status; c) identifying cases of patients with poor oral health or oral disease requiring referral to a dentist or other health professional; d) assisting dentists during complex dental procedures; e) providing fluoride treatments, cleaning and removing deposits from teeth, preparing cavities and placing fillings, administering local anesthesia, and performing other types of basic or routine clinical dental procedures; f) preparing, cleaning and sterilizing dental instruments, equipment and materials used in the examination and treatment of patients; g) getting patients ready for examination or treatment including explaining procedures and correct positioning; h) taking impressions of the mouth and dental radiographs to support diagnosis and fitting of dental prosthetics.\nExamples of the occupations classified here: Dental assistant, Dental hygienist, Dental therapist\nSome related occupations classified elsewhere: Dental aid - 5329, Dental mechanic - 3214, Dental prosthetist - 3214, Dental technician - 3214, Dentist - 2261","version":"2022","source_id":619,"level":4,"normalized_name":"dental assistants and therapists"},{"code":"3252","parent_code":"325","title":"MEDICAL RECORDS AND HEALTH INFORMATION TECHNICIANS","description":"Medical records and health information technicians develop, maintain and implement health records processing, storage and retrieval systems in medical facilities and other health care settings to meet the legal professional, ethical and administrative records-keeping requirements of health services delivery.\nTheir tasks include: a) planning, developing, maintaining and operating a variety of health record indexes and storage and retrieval systems to collect, classify, store and analyze information; b) transcribing, compiling and processing patient medical records, admission and discharge documents, and other medical reports into records-keeping systems to provide data for patient monitoring and referral, epidemiological monitoring, research, billing, cost control and care improvement; c) reviewing records for completeness, accuracy and compliance with regulations; d) translating narrative descriptions and numeric information from medical records and other documents on health services delivery into codes associated with standard classification systems; e) protecting the security of medical records to ensure that confidentiality is maintained and releasing information to authorized persons and agencies in accordance with regulations; and f) supervising clerical and administrative workers involved in the maintenance of medical records.\nExamples of the occupations classified here: Clinical coder, Contact tracer, Disease registry technician, Health information clerk, Medical records analyst, Medical records clerk, Medical records technician, Medical records unit supervisor\nSome related occupations classified elsewhere: Data entry clerk - 4132, Filing clerk - 4132, Medical secretary - 3344","version":"2022","source_id":620,"level":4,"normalized_name":"medical records and health information technicians"},{"code":"3253","parent_code":"325","title":"COMMUNITY HEALTH WORKERS","description":"Community health workers provide health education, referral and follow up, case management, and basic preventive health care and home visiting services to specific communities. They provide support and assistance to individuals and families in navigating the health and social services system.\nTheir tasks include: a) providing information to families and communities on a range of health issues including nutrition, hygiene, infant and child care, immunizations, family planning, risk factors and prevention of common infectious diseases, poisoning prevention, first aid for treatment of simple and common ailments, substance abuse, domestic violence, and other topics; b) visiting families in their homes to provide information on the health, social and other services available and support them in gaining access to these services; c) visiting families who do not usually access medical establishments to monitor on a regular basis certain conditions, such as progress with pregnancy, child growth and development, and environmental sanitation; d) distributing to households medical supplies for the prevention and treatment of endemic diseases such as malaria, pneumonia and diarrhea diseases, and instructing family and community members in the use of these products; e) conducting outreach efforts to groups who do not usually access medical establishments with information and basic medical supplies for prevention and management of certain health conditions for which they are most at risk, such as HIV/AIDS and other communicable diseases; and f) collecting data from households and communities who do not usually access medical establishments for purposes of patient monitoring and referral and reporting to meet health regulations.\nExamples of the occupations classified here: Community health aide, Community health promoter, Community health worker, Village health worker\nSome related occupations classified elsewhere: Home care aide - 5322, Traditional midwife - 3222, Village healer - 3230","version":"2022","source_id":621,"level":4,"normalized_name":"community health workers"},{"code":"3254","parent_code":"325","title":"DISPENSING OPTICIANS","description":"Dispensing opticians design, fit and dispense optical lenses based on a prescription from an ophthalmologist or optometrist for the correction of reduced visual acuity. They service corrective eyeglasses, contact lenses, low-vision aids and other optical devices. \nTheir tasks include: a) examining and taking facial and eye measurements of clients for fitting of eyeglasses and other optical devices; b) providing advice to clients with selection and maintenance of eyeglasses and frames, types of contact lenses and other optical devices for performance, safety, comfort and lifestyle; c) interpreting optical prescriptions and preparing work order for optical laboratory for grinding and mounting of lenses in frames, preparation of contact lenses and other required work; and d) verifying exactness of finished optical appliances and devices to the original prescription and fit of clients.\nExamples of the occupations classified here: Contact lens optician, Contact lens technician, Optical technician\nSome related occupations classified elsewhere: Ophthalmic optician - 2267, Ophthalmologist - 2212, Optometrist - 2267, Orthoptist - 2267","version":"2022","source_id":622,"level":4,"normalized_name":"dispensing opticians"},{"code":"3255","parent_code":"325","title":"PHYSIOTHERAPY TECHNICIANS AND ASSISTANTS","description":"Physiotherapy technicians and assistants provide physical therapeutic treatments to patients in circumstances where functional movement is threatened by injury, disease or impairment. Therapies are usually provided as per rehabilitative plans established by a physiotherapist or other health professional.\nTheir tasks include: a) administering manual treatments such as massage therapy or pressure point therapy; b) administering electrical modality treatments, ultrasound, and other physical therapies using specialized techniques and equipment, including infra-red lamps, wet compresses, and herbal and mineral therapies; c) instructing, motivating, safeguarding and assisting patients as they practice physical exercises, relaxation techniques and functional activities; d) conferring with physiotherapists or other health care providers to evaluate patient information for planning, modifying, and coordinating treatment; e) monitoring and recording patients' progress during treatments, including measuring their range-of-joint motion and vital signs; and f) fitting patients for orthopedic braces, prostheses, and other physical supportive devices such as crutches, and instructing patients in the use of such devices.\nExamples of the occupations classified here: Acupressure therapist, Electrotherapist, Hydrotherapist, Massage therapist, Physical rehabilitation technician, Physiotherapy assistant, Physiotherapy technician, Shiatsu therapist\nSome related occupations classified elsewhere: Chiropractor - 3259, Occupational therapist - 2269, Physiotherapist - 2264, Podiatrist - 2269","version":"2022","source_id":623,"level":4,"normalized_name":"physiotherapy technicians and assistants"},{"code":"3256","parent_code":"325","title":"MEDICAL ASSISTANTS","description":"Medical assistants perform basic clinical and administrative tasks to support patient care under the direct supervision of a medical practitioner or other health professional.\nTheir tasks include: a) interviewing patients and their families to obtain information on their health status and medical history; b) assisting medical doctors and other health professionals to examine and treat patients, including measuring and recording vital signs, administering medications, and performing routine clinical procedures such as giving injections and removing sutures; c) getting patients ready for examination and treatment, including explaining procedures and showing them to examination rooms; d) preparing and handling medical instruments and supplies, including sterilizing instruments and disposing of contaminated supplies in accordance with safety procedures; e) collecting blood, tissue or other specimens, and preparing them for laboratory testing; f) providing information to patients and families on health care topics including medications prescribed by a medical doctor or other health professional; g) providing prescription and drug refill information to pharmacies; h) maintaining cleanliness of patient waiting and examination rooms;i) recording information on patients' medical history, diagnostic testing and treatment procedures and results, and other information in medical records-keeping systems; and j) scheduling appointments with patients, and preparing documentation required for billing, reporting and insurance purposes.\nExamples of the occupations classified here: Clinical assistant, Medical assistant, Ophthalmic assistant\nSome related occupations classified elsewhere: Dental assistant - 3251, Medical imaging assistant - 5329, Medical prosthetic technician - 3214, Medical secretary - 3344, Paramedical clinical officer - 2240, Physiotherapy assistant - 3255","version":"2022","source_id":624,"level":4,"normalized_name":"medical assistants"},{"code":"3257","parent_code":"325","title":"ENVIRONMENTAL AND OCCUPATIONAL HEALTH INSPECTORS AND ASSOCIATES","description":"Environmental and occupational health inspectors and associates investigate the implementation of rules and regulations relating to environmental factors that may affect human health, safety in the workplace, and safety of processes for the production of goods and services. They may implement and evaluate programs to restore or improve safety and sanitary conditions under the supervision of a health professional.\nTheir tasks include: a) advising employers’ and workers’ representatives on the implementation of government and other rules and regulations concerning occupational safety and the working environment; b) inspecting places of work to ensure that the working environment, machinery and equipment conform to government and other rules, regulations and standards related to sanitation and/or occupational and environmental health and safety; c) giving advice on environmental sanitary problems and techniques; d) inspecting places of work and, by interviews, observations and other means, obtaining information about work practices and accidents to determine compliance with safety rules and regulations; e) inspecting areas of production, processing, transport, handling, storage and sale of products to ensure conformity with government and other rules, regulations and standards; f) advising enterprises and the general public on the implementation of government and other rules and regulations concerning hygiene, sanitation, purity and grading of primary products, food, drugs, cosmetics and similar goods; g) inspecting establishments to ensure that they conform to government and other rules and regulations concerning emission of pollutants and disposal of dangerous wastes; h) initiating action to maintain or improve hygiene and prevent pollution of water, air, food or soil; i) promoting preventive and corrective measures such as control of disease carrying organisms and of harmful substances in the air, hygienic food handling, proper disposal of waste and cleaning of public places; and j) estimating quantities and costs of materials and labor required for health, safety and sanitation remediation projects;\nExamples of the occupations classified here: Charging safety officer, Electric vehicle (EV) fleet and depot safety officer, Environmental sanitation inspector, Food sanitation and safety inspector, Health inspector, Occupational health and safety inspector, Pollution control associate, Pollution inspector, Pollution inspector, Product safety inspector, Safety and health inspector, Sanitarian, Sanitary inspector, Zoning inspector\nSome related occupations classified elsewhere: Environmental health officer - 2263, Occupational health and safety adviser - 2263, Occupational hygienist - 2263, Radiation protection expert - 2263","version":"2022","source_id":625,"level":4,"normalized_name":"environmental and occupational health inspectors and associates"},{"code":"3258","parent_code":"325","title":"AMBULANCE WORKERS","description":"Ambulance workers provide emergency health care to patients who are injured, sick, infirm, or otherwise physically or mentally impaired prior to and during transport to medical facilities.\nTheir tasks include: a) assessing health status of persons involved in accidents, natural disasters and other emergency situations, and determining needs for immediate and specialized medical assistance; b) performing medical procedures and administering drugs and other therapies according to protocol for emergency medical treatment, including resuscitating and defibrillating patients and operating life-support equipment; c) monitoring changes in health status of patients during transport to and from medical, rehabilitation and other health care facilities; d) providing information and training to community groups and essential service workers in first aid for initial care of an illness or injury; e) attending and/or patrolling large-scale public gatherings and other events where health emergencies are more likely to occur; and f) recording information on patients' conditions and treatments provided in medical records-keeping systems.\nExamples of the occupations classified here: Ambulance officer, Ambulance paramedic, Emergency medical technician, Emergency paramedic, Medical emergency service personnel\nSome related occupations classified elsewhere: Ambulance driver - 8322, Paramedical practitioner - 2240","version":"2022","source_id":626,"level":4,"normalized_name":"ambulance workers"},{"code":"3259","parent_code":"325","title":"HEALTH ASSOCIATE PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers health associate professionals not classified elsewhere in Sub-major group 32, Health associate professionals. For instance the group includes occupations such as chiropractor, osteopath and other health associate professionals.\nTheir tasks include: a) interviewing and examining patients to obtain information on their health status and the nature and extent of injury, illness or other physical or mental health problem; b) administering therapeutic care and treatment to patients, including the manual and physical chiropractic an osteopathic techniques; c) monitoring patients' progress through treatment plans, and identifying signs and symptoms requiring referral to a medical doctor or other health professional; d) recording information on patients' health status and responses to treatment in medical records-keeping systems; and e) sharing information with other health care providers when required to ensure continuing and comprehensive care.\nExamples of the occupations classified here: Anesthesia technician, Family planning counselor, Human immunodeficiency virus (HIV) Counselor, Occupational therapy technician, Respiratory therapy technician","version":"2022","source_id":627,"level":4,"normalized_name":"health associate professionals not elsewhere classified"},{"code":"3311","parent_code":"331","title":"SECURITIES AND FINANCE DEALERS AND BROKERS","description":"Securities and finance dealers and brokers buy and sell securities, stocks, bonds and other financial instruments, and deal on the foreign exchange, on spot, or on futures markets, on behalf of their own company or for customers on a commission basis. They recommend transactions to clients or senior management.\nTheir tasks include: a) obtaining information about the financial circumstances of customers and companies in which investments may be made; b) analyzing market trends for securities, bonds, stocks and other financial instruments, including foreign exchange; c) informing prospective customers about market conditions and prospects; d) advising on and participating in the negotiation of terms for, and organization of, loans and placement of stocks and bonds in the financial market to raise capital for customers; and e) recording and transmitting buy and sell orders for securities, stocks, bonds or other financial instruments and for foreign exchange for future or immediate delivery.\nExamples of the occupations classified here: Crypto currency trader, Foreign exchange broker, Foreign exchange dealer, Securities broker, Securities salesperson, Stocks and shares broker\nSome related occupations classified elsewhere: Bond analyst - 2413, Commodities broker - 3324, Commodity futures dealer - 3324, Securities clerk - 4312","version":"2022","source_id":628,"level":4,"normalized_name":"securities and finance dealers and brokers"},{"code":"3312","parent_code":"331","title":"CREDIT AND LOANS OFFICERS","description":"Credit and loan officers analyze and evaluate financial information on applications for credit and loans and determine approval or disapproval of the client for the credit or loan or recommend to management approval or disapproval.\nTheir tasks include: a) interviewing applicants for personal, mortgage, student and business loans; b) researching and evaluating loan applicant’s financial status, references, credit and ability to repay the loan; c) submitting credit and loan applications to management with recommendations for approval or rejection; d) approving or rejecting loan applications within authorized limits ensuring that credit standards of the institution are respected; e) keeping records of payments, and preparing routine letters requesting payment for overdue accounts and forwarding these for legal action; and f) completing credit and loan documentation.\nExamples of the occupations classified here: Credit analyst, Credit union officer, Loans officer, Mortgage officer\nRelated occupation classified elsewhere: Financial institution branch manager - 1346","version":"2022","source_id":629,"level":4,"normalized_name":"credit and loans officers"},{"code":"3313","parent_code":"331","title":"ACCOUNTING ASSOCIATE PROFESSIONALS","description":"Accounting associate professionals maintain complete records of financial transactions of an undertaking and verify accuracy of documents and records relating to such transactions.\nTheir tasks include: a) maintaining complete records of all financial transactions of an undertaking according to general bookkeeping principles, with guidance from Accountants; b) verifying accuracy of documents and records relating to payments, receipts and other financial transactions; c) preparing financial statements and reports for specified periods; d) applying knowledge of bookkeeping principles and practices in order to identify and solve problems arising in the course of their work; e) using standard computer software packages to perform accounting and related calculations; and f) supervising the work of accounts and bookkeeping clerks.\nExamples of the occupations classified here: Accounting assistant, Accounting officer, Accounting technician, Associate auditor, Audit assistant, Bank reconciliation assistant, Bookkeeper\nSome related occupations classified elsewhere: Accountant - 2411, Actuarial assistant - 3314, Bookkeeping clerk - 4311","version":"2022","source_id":630,"level":4,"normalized_name":"accounting associate professionals"},{"code":"3314","parent_code":"331","title":"STATISTICAL, MATHEMATICAL AND RELATED ASSOCIATE PROFESSIONALS","description":"Statistical, mathematical and actuarial associate professionals assist in planning the collection, processing and presentation of statistical, mathematical or actuarial data and in carrying out these operations, usually working under the guidance of statisticians, mathematicians and actuaries.\nTheir tasks include: a) assisting in planning and performing statistical, mathematical, actuarial, and related calculations; b) preparing detailed estimates of quantities and costs of materials and labor required for statistical census and survey operations;c) performing technical tasks connected with establishing, maintaining and using registers and sampling frames for census and survey operations; d) performing technical tasks connected with data collection and quality control operations in censuses and surveys; e) using standard computer software packages to perform mathematical, actuarial, statistical, accounting and related calculations; f) preparing statistical, mathematical, actuarial, accounting and other results for presentation in graphical or tabular form; g) applying knowledge of statistical, mathematical, actuarial, accounting and related principles and practices in order to identify and solve problems arising in the course of their work; and h) supervising the work of statistical clerks.\nExamples of the occupations classified here: Actuarial assistant, Mathematical assistant, Statistical assistant\nSome related occupations classified elsewhere: Accounting assistant - 3313, Actuary - 2120, Mathematician - 2121, Statistical clerk - 4312, Statistician - 2122","version":"2022","source_id":631,"level":4,"normalized_name":"statistical mathematical and related associate professionals"},{"code":"3315","parent_code":"331","title":"VALUERS AND LOSS ASSESSORS","description":"Valuers and loss assessors value property and various goods and assess losses covered by insurance policies.\nTheir tasks include: a) determining the quality or value of raw materials, real estate, industrial equipment, personal and household effects, works of art, gems and other objects; b) assessing the extent of damage or loss and liabilities of insurance companies and underwriters for losses covered by insurance policies; c) obtaining records of sales and value of similar items or property; d) inspecting items or property to evaluate condition, size, and construction; and e) preparing reports of value, outlining the estimation factors and methods used.\nExamples of the occupations classified here: Appraiser, Claims assessor, Claims inspector, Insurance assessor, Jewelry appraiser, Real estate appraiser, Valuer\nRelated occupation classified elsewhere: Auctioneer - 3339","version":"2022","source_id":632,"level":4,"normalized_name":"valuers and loss assessors"},{"code":"3321","parent_code":"332","title":"INSURANCE REPRESENTATIVES","description":"Insurance representatives advise on and sell life, accident, automobile, liability, endowment, fire, marine and other types of insurance to new and established clients.\nTheir tasks include: a) obtaining information about customers’ circumstances necessary to determine appropriate type of insurance and conditions; b) negotiating with customers to determine type and degree of risk for which insurance is required; c) explaining details of insurance and conditions, risk coverage premiums and benefits to customers; d) assisting clients to determine the type and level of coverage required, calculating premiums and establishing method of payment; e) negotiating and placing reinsurance contracts; and f) advising on, negotiating terms for and placing insurance contracts for large or special types of projects, installations or risks.\nExamples of the occupations classified here: Assistant underwriter, Insurance adviser, Insurance agent, Insurance broker, Insurance dealer, Insurance underwriter\nSome related occupations classified elsewhere: Insurance agency manager - 1346, Insurance assessor - 3315, Insurance clerk - 4312, Securities broker - 3311","version":"2022","source_id":633,"level":4,"normalized_name":"insurance representatives"},{"code":"3322","parent_code":"332","title":"COMMERCIAL SALES REPRESENTATIVES","description":"Commercial sales representatives represent companies to sell various goods and services to businesses and other organizations and provide product specific information as required.\nTheir tasks include: a) soliciting orders and selling goods to retail, industrial, wholesale and other establishments; b) selling equipment, supplies and related services to business establishments or individuals; c) obtaining and updating knowledge of market conditions and of employer’s and competitors’ goods and services; d) providing prospective customers with information about the characteristics and functions of the products and equipment for sale, and demonstrating its use or qualities; e) reporting customers’ reactions and requirements to suppliers and manufacturers; and f) following up clients to ensure satisfaction with products purchased.\nExamples of the occupations classified here: After-sale service adviser, Canvasser, Commercial sales agent, Commercial traveler, Franchise relation officer, Manufacturing sales agent, Manufacturing sales consultant\nSome related occupations classified elsewhere: Door to door sales representative - 5243, Information and communications technology sales professional - 2434, Medical sale representative - 2433, Sales manager - 1221, Shop sale assistant - 5223, Technical sales representative - 2433","version":"2022","source_id":634,"level":4,"normalized_name":"commercial sales representatives"},{"code":"3323","parent_code":"332","title":"BUYERS","description":"Buyers buy goods and services for use or resale on behalf of industrial, commercial, government or other establishments and organizations.\nTheir tasks include: a) determining or negotiating contract terms and conditions, awarding supplier contracts or recommending contract awards for the purchase of equipment, raw materials products, services and the purchasing of merchandise for resale; b) obtaining information about requirements and stock and developing specifications for quantity and quality to be purchased, costs, delivery dates and other contract conditions; c) purchasing general and specialized equipment, materials or business services for use or for further processing by their establishment; d) inviting tenders, consulting with suppliers and reviewing quotations; e) purchasing merchandise for resale by retail or wholesale establishments; f) studying market reports, trade periodicals and sales promotion materials and visiting trade shows, showrooms, factories and product design events; g) interviewing suppliers and negotiating prices, discounts, credit terms and transportation arrangements; h) overseeing distribution of merchandise to outlets and maintaining adequate stock levels; and i) establishing delivery schedules, monitoring progress and contacting clients and suppliers to resolve problems. \nExamples of the occupations classified here: Procurement officer, Purchasing agent, Purchasing merchandiser, Purchasing officer\nRelated occupation classified elsewhere: Commodities broker - 3324","version":"2022","source_id":635,"level":4,"normalized_name":"buyers"},{"code":"3324","parent_code":"332","title":"TRADE BROKERS","description":"Trade brokers buy and sell commodities and shipping services, usually in bulk, on behalf of their own company or for customers on a commission basis.\nTheir tasks include: a) establishing contact between buyers and sellers of commodities; b) discussing buying or selling requirements of clients and giving advice accordingly; c) buying and selling cargo space on ships; d) negotiating purchase or sale of commodities and commodity futures; e) finding cargo and/or storage space for commodities and negotiating freight, shipping and storage charges; and f) monitoring and analyzing market trends and other factors affecting the supply and demand for commodities and shipping services.\nExamples of the occupations classified here: Commodities broker, Commodity futures dealer, Shipping broker, Trade broker\nSome related occupations classified elsewhere: Finance broker - 3311, Finance dealer - 3311, Insurance dealer - 3321, Securities broker - 3311, Securities dealer - 3311","version":"2022","source_id":636,"level":4,"normalized_name":"trade brokers"},{"code":"3331","parent_code":"333","title":"CLEARING AND FORWARDING AGENTS","description":"Clearing and forwarding agents carry out customs clearing procedures and ensure that insurance, export/import licenses and other formalities are in order.\nTheir tasks include: a) carrying out customs clearing procedures for exports or imports; b) ensuring that insurance is in order; c) ensuring that export/import licenses and other formalities are in order; d) signing and issuing bills of lading; and e) checking import/export documentation to determine cargo contents, and classifying goods into different fee or tariff groups, using a tariff coding system.\nExample of occupation classified here: Shipping agent","version":"2022","source_id":637,"level":4,"normalized_name":"clearing and forwarding agents"},{"code":"3332","parent_code":"333","title":"CONFERENCE AND EVENT PLANNERS","description":"Conference and event planners organize and coordinate services for conferences, events, functions, banquets and seminars.\nTheir tasks include: a) promoting conferences, conventions and trade shows to potential customers; b) responding to inquiries concerning services provided and costs for room and equipment hire, catering and related services; c) meeting with clients to discuss their needs and outlining package options to meet these needs; d) arranging and coordinating services, such as, conference facilities, catering, signage, displays, audiovisual and computer equipment, accommodation, transport and social events, for participants, logistical arrangements for presenters; e) organizing registration of participants; f) negotiating the type and costs of services to be provided within budget; and g) overseeing work by contractors and reporting on variations to work orders.\nExamples of the occupations classified here: Conference and event organizer, Conference planner, Events coordinator, Wedding planner","version":"2022","source_id":638,"level":4,"normalized_name":"conference and event planners"},{"code":"3333","parent_code":"333","title":"EMPLOYMENT AGENTS AND CONTRACTORS","description":"Employment agents and contractors match jobseekers with vacancies, find workers for employers and contract labor for particular projects at the request of enterprises and other organizations including government, institutions, or find places for jobseekers for a commission.\nTheir tasks include: a) matching jobseekers with vacancies; b) finding workers for vacant posts against a commission from the employer or worker; c) discussing with enterprises/organizations the needed skills and other characteristics of the workers to be employed or contracted; d) finding workers with appropriate skills, etc., and undertaking the necessary formalities according to national or international regulations and requirements; e) ensuring that the employment contracts meet legal requirements and signing them; and f) advising on training schemes.\nExamples of the occupations classified here: Employment agent, Job placement officer, Labor contractor\nSome related occupations classified elsewhere: Careers adviser - 2423, Literacy agent - 3339, Musical performance agent - 3339, Occupational analyst - 2423, Sports agent -3339, Theatrical agent - 3339","version":"2022","source_id":639,"level":4,"normalized_name":"employment agents and contractors"},{"code":"3334","parent_code":"333","title":"REAL ESTATE AGENTS AND PROPERTY MANAGERS","description":"Real estate agents and property managers arrange the sale, purchase, rental and lease of real property, usually on behalf of clients and on a commission basis.\nTheir tasks include: a) obtaining information about properties to be sold or leased, the circumstances of their owner and the needs of prospective buyers or tenants; b) showing properties to be sold or leased to prospective buyers or tenants and explaining terms of sale or conditions of rent or lease; c) facilitating negotiations with tenants and owners on rents and fees; d) drawing up leasing and sale agreements and estimating costs; e) arranging signing of lease agreements and transfer of property rights; f) collecting rent and bond monies on behalf of owner and inspecting properties before, during and after tenancies; and g) ensuring the availability of workers to perform maintenance of the properties.\nExamples of the occupations classified here: Property manager, Real estate broker, Real estate salesperson, Realtor\nRelated occupation classified elsewhere: Mortgage clerk - 4312","version":"2022","source_id":640,"level":4,"normalized_name":"real estate agents and property managers"},{"code":"3339","parent_code":"333","title":"BUSINESS SERVICES AGENTS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers business services agents not classified elsewhere in Minor group 333, Business services agents. For instance, the group includes those who establish business contacts, sell business services such as advertising space in the media, arrange contracts for performances of athletes, entertainers and artists, for the publication of books, the production of plays, or the recording, performance and sale of music and who sell property and goods by auction.\nTheir tasks include: a) obtaining information about services to be sold and needs of prospective buyers; b) negotiating contracts on behalf of seller or buyer and explaining terms of sale and payment to client; c) signing agreements on behalf of seller or buyer and ensuring that contract is honored; d) making sure that the business service purchased is made available to the buyer in the agreed format at the agreed time; and e) selling by auction various kinds of property, cars, commodities, livestock, art, jewelry and other objects.\nExamples of the occupations classified here: Advertising salesperson, Auctioneer, Business services salesperson, Literary agent, Musical performance agent, Sports agent, Theatrical agent, Tour operator","version":"2022","source_id":641,"level":4,"normalized_name":"business services agents not elsewhere classified"},{"code":"3341","parent_code":"334","title":"OFFICE SUPERVISORS","description":"Office supervisors supervise and coordinate the activities of workers in major group 4, Clerical support workers.\nTheir tasks include: a) coordinating, assigning and reviewing the work of clerks engaged in the following duties: word processing, record keeping and filing, operating telephones and switchboards; data entry, desktop publishing and other activities involving general office and administrative skills; b) establishing work schedules and procedures and co-coordinating activities with other work units or departments; c) resolving work-related problems and preparing and submitting progress and other reports; d) training and instructingemployees in job duties, safety procedures and company policies, or arranging for training to be provided; e) evaluating employees’ job performance and conformance to regulations, and recommending appropriate personnel action; and f) assisting in recruitment, interviewing, and selection of employees.\nExamples of the occupations classified here: Clerical supervisor, Data entry supervisor, Filing clerks supervisor, Personnel clerks supervisor\nRelated occupation classified elsewhere: Medical records unit supervisor - 3252","version":"2022","source_id":642,"level":4,"normalized_name":"office supervisors"},{"code":"3342","parent_code":"334","title":"LEGAL SECRETARIES","description":"Legal secretaries apply specialized knowledge of legal terminology and procedures in providing support to legal professionals with communication, documentation and internal managerial coordination activities, in law offices, legal departments of large firms and governments.\nTheir tasks include: a) preparing and processing legal documents and papers, such as deeds, wills, affidavits and briefs; b) reviewing and proofreading documents and correspondence to ensure compliance with legal procedures; c) mailing, faxing, or arranging for delivery of legal correspondence to clients, witnesses, and court officials; d) organizing and maintaining documents, case files and law libraries; e) screening requests for meetings, scheduling and organizing meetings; f) assisting in the preparation of budgets, monitoring of expenditures, drafting of contracts and purchasing or acquisition orders; and g) supervising the work of office support workers.\nExamples of the occupations classified here: Legal practice manager, Legal secretary\nRelated occupation classified elsewhere: Legal assistant - 3411","version":"2022","source_id":643,"level":4,"normalized_name":"legal secretaries"},{"code":"3343","parent_code":"334","title":"ADMINISTRATIVE AND EXECUTIVE SECRETARIES","description":"Administrative and executive secretaries perform liaison, coordination and organizational tasks in support of managers and professionals and/or prepare correspondence, reports and records of proceedings and other specialized documentation.\nTheir tasks include: a) drafting administrative correspondence and minutes; b) obtaining, proposing and monitoring deadlines and follow-up dates; c) screening requests for meetings, scheduling and organizing meetings and travel arrangements; d) assisting in the preparation of budgets, monitoring of expenditures, drafting of contracts and purchasing or acquisition orders; e) liaising with other staff about a range of matters relating to the organization’s operations; f) writing and answering business or technical letters and other similar correspondence; g) preparing verbatim reports of proceedings in legislative assemblies, courts of law or other places using shorthand or specialized office equipment; h) supervising the work of clerical support workers.\nExamples of the occupations classified here: Administrative assistant, Administrative secretary, Committee secretary, Correspondence assistant, Court reporter, Executive assistant, Executive secretary, Personal assistant\nSome related occupations classified elsewhere: Medical transcriptionist - 3344, Secretary (general) - 4120","version":"2022","source_id":644,"level":4,"normalized_name":"administrative and executive secretaries"},{"code":"3344","parent_code":"334","title":"MEDICAL SECRETARIES","description":"Medical secretaries, using specialized knowledge of medical terminology and health care delivery procedures, assist health professionals and other workers by performing a variety of communication, documentation, administrative and internal coordination functions, to support health workers in medical facilities and other health-care related organizations.\nTheir tasks include: a) scheduling and confirming medical appointments and communicating messages for medical staff; and patients; b) compiling, recording and reviewing medical charts, reports, documents and correspondence; c) interviewing patients to complete forms, documents and case histories; d) completing insurance and other claims forms; e) maintaining medical files and records and technical library; f) preparing financial statements and billing procedures; g) assisting in the preparation of budgets, drafting of contracts and purchasing or acquisition orders; and h) supervising the work of office support workers and other office staff.\nExamples of the occupations classified here: Dental secretary, Hospital ward secretary, Medical insurance billing secretary, Medical office administrative assistant, Medical practice manager, Medical secretary, Medical stenographer, Medical transcriptionist, Pathology secretary, Patient care secretary\nSome related occupations classified elsewhere: Medical assistant - 3256, Medical office receptionist - 4226, Medical records technician - 3252, Secretary (general) - 4120","version":"2022","source_id":645,"level":4,"normalized_name":"medical secretaries"},{"code":"3351","parent_code":"335","title":"CUSTOMS AND BORDER INSPECTORS","description":"Customs and border inspectors check persons and vehicles crossing national borders to administer and enforce relevant government rules and regulations.\nTheir tasks include: a) patrolling national borders and coastal waters to stop persons from illegally entering or leaving the country and from illegally importing or exporting currency or goods; b) checking travel documents of persons crossing national borders to ensure that they have the necessary authorizations and certificates; c) inspecting the luggage of persons crossing national borders to ensure that it conforms to government rules and regulations concerning import or export of goods and currencies; d) examining transport documents and freight of vehicles crossing national borders to ensure conformity with government rules and regulations concerning goods in transit and the import and export of goods, and to verify that necessary payments have been made; e) detaining persons and seizing prohibited and undeclared goods found to be in violation of immigration and customs laws; f) coordinating and cooperating with other agencies involved in law enforcement, deportation and prosecution; g) performing related administrative tasks to record findings, transactions, violations and determinations; and h) when necessary, testifying in a court of law about the circumstances and results of investigations carried out.\nExamples of the occupations classified here: Border inspector, Customs inspector, Customs officer, Immigration officer, Passport checking officer","version":"2022","source_id":646,"level":4,"normalized_name":"customs and border inspectors"},{"code":"3352","parent_code":"335","title":"GOVERNMENT TAX AND EXCISE OFFICIALS","description":"Government tax and excise officials examine tax returns, bills of sale and other documents to determine the type and amount of taxes, duties and other types of fees to be paid by individuals or businesses, referring exceptional or important cases to accountants, senior government officials or Managers. \nTheir tasks include: a) advising organizations, enterprises and the public on government laws, rules and regulations concerning the determination and payment of taxes, duties and other government fees, and on the public’s rights and obligations; b) examining tax returns, bills of sale and other relevant documents to determine type and amount of taxes, duties and other types of fees to be paid; c) investigating filed tax returns and accounting records, systems and internal controls of organizations to ensure compliance with taxation laws and regulations; and d) performing related administrative tasks to document findings, maintain records and report on actions taken for cases.\nExamples of the occupations classified here: Excise officer, Tax collector, Tax examiner, Tax officer, Taxation inspector\nSome related occupations classified elsewhere: Accountant - 2411, Auditor - 2411","version":"2022","source_id":647,"level":4,"normalized_name":"government tax and excise officials"},{"code":"3353","parent_code":"335","title":"GOVERNMENT SOCIAL BENEFITS OFFICIALS","description":"Government social benefits officials examine applications for government, financial or service programs to determine eligibility and amount of benefit or appropriate services, referring exceptional or important cases to senior government officials or managers.\nTheir tasks include: a) advising individuals and organizations on government laws, rules and regulations concerning government benefit programs and the determination and disbursement of payments or referral to services, as well as on the public’s rights and obligations; b) examining applications and other relevant documents to determine type and amount of benefit which individuals are eligible to receive; c) assessing documentation and interviewing benefit recipients to ensure eligibility for continuing benefits or services; and d) performing related administrative tasks to maintain client records and prepare reports on determinations regarding eligibility, referral decisions, termination of benefits and abuse or fraud.\nExamples of the occupations classified here: Pensions officer, Social benefits officer, Social insurance officer, Social security claims officer\nSome related occupations classified elsewhere: Counseling professionals - 2635, Social worker - 2635","version":"2022","source_id":648,"level":4,"normalized_name":"government social benefits officials"},{"code":"3354","parent_code":"335","title":"GOVERNMENT LICENSING OFFICIALS","description":"Government licensing officials examine applications for licenses to export or import goods, set up businesses, build houses or other structures, or to obtain passports, determine eligibility of applications for issuing licenses or passports, and identify specific conditions or restrictions to be attached to licenses issued, referring exceptional or important cases to Senior government officials or Managers.\nTheir tasks include: a) advising individuals on government laws and regulations concerning the type of license required and the conditions attached to such licenses, and on the public's rights and obligations; b) examining applications and relevant documents and determining whether a license can be granted and the conditions which should be attached; c) examining applications and approving the issue of passports; d) performing related administrative tasks to process applications, document activities, evaluations and determinations, and to prepare correspondence to inform applicants of licensing decisions; and e) administering and scoring tests required to license applicants.\nExamples of the occupations classified here: Building permit licensing officer, Business permit licensing officer, Licensing officer, Passport issuing officer\nSome related occupations classified elsewhere: Building inspector - 3112, Fire inspector - 3112","version":"2022","source_id":649,"level":4,"normalized_name":"government licensing officials"},{"code":"3355","parent_code":"335","title":"POLICE INSPECTORS AND DETECTIVES","description":"Police inspectors and detectives investigate facts and circumstances relating to crimes committed in order to identify suspected offenders and obtain information not readily available or apparent concerning establishments or the circumstances and behavior of persons, mostly in order to prevent crimes.\nTheir tasks include: a) establishing contacts and sources of information about crimes planned or committed, in order to prevent crimes or identify suspected offenders; b) obtaining and verifying evidence by examining crime and accident scenes for clues and physical evidence, interviewing witnesses and suspects and analyzing documents and computer files; c) analyzing evidence in order to solve crimes, identify criminal activity and gather information for court cases; d) establishing contacts and sources of information not readily available or apparent concerning establishments or the circumstances and behavior of persons, usually with the aim of preventing a crime; e) making arrests; and f) testifying in courts of law or reporting to superiors about circumstances and results of investigations.\nExamples of the occupations classified here: Police detective, Police inquiry agent, Police inspector, Police intelligence agent, Police investigator\nSome related occupations classified elsewhere: Police commissioner - 1112, Police inspector-general - 1112, Police officer - 5412, Police superintendent - 1349, Private detective - 3411","version":"2022","source_id":650,"level":4,"normalized_name":"police inspectors and detectives"},{"code":"3359","parent_code":"335","title":"GOVERNMENT REGULATORY ASSOCIATE PROFESSIONALS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers government regulatory associate professionals not classified elsewhere in Major group 3, Technicians and associate professionals. For instance the group includes agricultural, fisheries, forestry, prices, wages and weights and measures inspectors.\nTheir tasks include: a) examining places of business to ensure the use of correct weights and measures in trade; b) monitoring price regulations to assess appropriateness of costs for goods and services to protect consumer interests; c) monitoring wage regulations to ensure appropriate levels of pay for work performed and to assess compliance with employment standards legislation; and d) performing related investigative and administrative tasks to record findings, document compliance problems or inappropriate business practices and to prepare reports and correspondence.\nExamples of the occupations classified here: Agricultural inspector, Fisheries inspector, Forest concession guard, Forestry inspector, Land management inspector, Market inspector, Prices inspector, Public services inspector, Wage inspector, Weights and measures inspector\nSome related occupations classified elsewhere: Fire inspector - 3112, Health inspector - 3257, Occupational health and safety inspector - 3257, Pollution inspector - 3257, Sanitary inspector - 3257","version":"2022","source_id":651,"level":4,"normalized_name":"government regulatory associate professionals not elsewhere classified"},{"code":"3411","parent_code":"341","title":"LEGAL AND RELATED ASSOCIATE PROFESSIONALS","description":"Legal and related associate professionals perform support functions in courts of law or in law offices, provide services related to such legal matters as insurance contracts, the transferring of property and the granting of loans and other financial transactions or conduct investigations for clients.\nTheir tasks include: a) documenting court proceedings and judgements; b) serving statements of claims, summonses, warrants, subpoenas and other court orders; c) maintaining order in court and hearing rooms; d) preparing legal documents including trial briefs, pleadings, appeals, wills and contracts and preparing, papers summarizing legal positions, or setting out conditions of loans or insurance; e) investigating facts, assembling evidence and researching relevant statutes, decisions and other legal documents to prepare cases; f) advising clients on legal matters; g) examining documentation such as mortgages, liens, judgements, easements, contracts and maps in order to verify properties’ legal descriptions and ownership; h) preparing documents relating to transfer of real estate, stocks or other matters requiring formal registration; i) investigating possible cases of theft of goods, money or information from business establishments and of other possible cases of unlawful behavior by customers or employees; and j) investigating establishments or the circumstances and behavior of persons on behalf of clients.\nExamples of the occupations classified here: Bailiff, Clerk of court/judge/law, Court clerk, Judge's clerk, Justice of the peace, Law clerk, Legal assistant, Paralegal, Private detective, Private investigator, Title searcher\nSome related occupations classified elsewhere: Judge - 2612, Lawyer - 2611, Legal secretary - 3342, Notary - 2619","version":"2022","source_id":652,"level":4,"normalized_name":"legal and related associate professionals"},{"code":"3412","parent_code":"341","title":"SOCIAL WORK ASSOCIATE PROFESSIONALS","description":"Social work associate professionals administer and implement social assistance programs and community services and assist clients to deal with personal and social problems.\nTheir tasks include: a) collecting information relevant to clients’ needs and assessing their relevant skills, strengths and deficits; b) helping persons with disabilities or the elderly to obtain services and to improve their ability to function in society; c) assisting clients to identify options and develop plans of action while providing necessary support and assistance; d) assisting clients to identify and access community resources including legal, medical and financial assistance, housing, employment, transportation, assistance with moves, day care and other referral services; e) counselling clients living in group homes and half-way houses, supervising their activities and assisting in pre-release and release planning; f) participating in the selection and admission of clients to appropriate programs; g) providing crisis intervention and emergency shelter services; h) implementing life skills workshops, substance abuse treatment programs, behavior management programs, youth services programs and other community and social service programs under the supervision of social work or health care professionals; i) assisting in evaluating the effectiveness of interventions and programs by monitoring and reporting on clients' progress; and j) maintaining contact with other social service agencies, schools and health care providers involved with clients to provide information and obtain feedback on clients' overall situation and progress.\nExamples of the occupations classified here: Barangay affairs worker, Community development worker, Community service worker, Crisis intervention worker, Culture center worker assistant, Daycare worker, Disability services officer, Family service worker, Life skills instructor, Mental health support worker, Outreach project worker, Relief and rehabilitation worker, Social welfare aide, Social welfare assistant, Welfare support worker, Welfare worker, Women's shelter supervisor, Youth development assistant, Youth services worker\nSome related occupations classified elsewhere: Marriage counsellor - 2635, Parole officer - 2635, Probation officer - 2635, Social worker - 2635","version":"2022","source_id":653,"level":4,"normalized_name":"social work associate professionals"},{"code":"3413","parent_code":"341","title":"RELIGIOUS ASSOCIATE PROFESSIONALS","description":"Religious associate professionals provide support to ministers of religion or to a religious community, undertake religious works, preach and propagate the teachings of a particular religion and endeavor to improve well-being through the power of faith and spiritual advice.\nTheir tasks include: a) undertaking religious works; b) preaching and propagating the teachings of a particular religious faith; c) assisting at services of public worship and religious rites; d) providing religious education, spiritual guidance and moral support to individuals and communities; e) administering and participating in programs to provide food, clothing and shelter to those in need; and f) advising communities and individuals on proper behavior and faith to preserve or improve well-being.\nExamples of the occupations classified here: Catechist, Faith healer, Lay evangelist, Lay minister, Lay preacher, Monk, Nun, Parish workers, Religious workers, Tribal Ritualists (e.g. Mambunong, Mumbaki, Mabaki, Mensapo and Anituwan in Cordilleras)\nSome related occupations classified elsewhere: Bonze - 2636, Healer of indigenous people - 3230, Herbalist - 3230, Imam - 2636, Pastor - 2636, Poojari - 2636, Priest - 2636, Rabbi - 2636, Religion minister - 2636, Village healer - 3230, Witch doctor - 3230","version":"2022","source_id":654,"level":4,"normalized_name":"religious associate professionals"},{"code":"3421","parent_code":"342","title":"ATHLETES AND SPORTS PLAYERS","description":"Athletes and sport players participate in competitive sporting events. They train and compete, either individually or as part of a team, in their chosen sport.\nTheir tasks include: a) participating in competitive sporting events; b) participating in regular practice and training sessions and undertaking private training to maintain the required standard of fitness and skill; c) undertaking sports promotional activities and media interviews; d) maintaining a high degree of expertise in a particular sport; e) deciding on strategies in consultation with coaches; f) assessing other competitors and conditions at venues; g) competing in sporting events; and h) adhering to the rules and regulations associated with a specific sport.\nExample of occupation classified here: Athletes, all sports","version":"2022","source_id":655,"level":4,"normalized_name":"athletes and sports players"},{"code":"3422","parent_code":"342","title":"SPORTS COACHES, INSTRUCTORS AND OFFICIALS","description":"Sports coaches, instructors and officials work with amateur and professional sportspersons to enhance performance, encourage greater participation in sport, and organize and officiate in sporting events according to established rules.\nTheir tasks include: a) identifying strengths and weaknesses of athletes or teams; b) planning, developing and implementing training and practice sessions; c) developing, planning and coordinating competitive schedules and programs; d) motivating and preparing athletes or teams for competitive events or games; e) formulating competitive strategy, developing game plans and directing athletes and players during games or athletic events; f) analyzing and evaluating athletes' or teams' performances and modifying training programs; g) monitoring and analyzing technique and performance, and determining how future improvements can be made; h) officiating at sporting events or athletic competitions to maintain standards of play and to ensure that game rules and safety regulations are observed; i) recording lapsed time and keeping scores during events or competitions; j) judging the performance of competitors, awarding points, imposing penalties for infractions and determining results; and k) compiling scores and other athletic records.\nExamples of the occupations classified here: Referee, Sports coach, Sports instructor, Sports official, Sports trainer\nSome related occupations classified elsewhere: Fitness instructor - 3423, Horse riding instructor - 3423, Personal trainer - 3423","version":"2022","source_id":656,"level":4,"normalized_name":"sports coaches instructors and officials"},{"code":"3423","parent_code":"342","title":"FITNESS AND RECREATION INSTRUCTORS AND PROGRAM LEADERS","description":"Fitness and recreation instructors and program leaders lead, guide and instruct groups and individuals in recreational, fitness or outdoor adventure activities.\nTheir tasks include: a) planning and carrying out recreational and fitness activities; b) monitoring recreational, sports or fitness activities to ensure safety and provide emergency or first aid assistance when required; c) evaluating and monitoring clients’ abilities and fitness and recommending activities; d) demonstrating and teaching body movements, concepts and skills used in fitness routines and recreational activities; e) instructing in the use of equipment; and f) explaining and enforcing safety procedures, rules and regulations.\nExamples of the occupations classified here: Aerobics instructor, Fitness instructor, Horse riding instructor, Outdoor adventure guide, Personal trainer, Pilates instructor, Sailing instructor, Underwater diving instructor, Zumba instructor\nRelated occupation classified elsewhere: Sports instructor - 3422","version":"2022","source_id":657,"level":4,"normalized_name":"fitness and recreation instructors and program leaders"},{"code":"3424","parent_code":"342","title":"ESPORTS PLAYERS AND COACHES","description":"Esports players and athletes participate in competitive esport tournaments, events and leagues. They train and compete, either individually or as part of a team, in their chosen esports tournaments, events and leagues.\nTheir tasks include: a) participating in competitive e-sports tournaments, events and leagues; b) participating in regular practice and training sessions and undertaking private training to maintain the required skill; c) undertaking promotional activities; d) maintaining a high degree of expertise in a particular e-sport; e) deciding on strategies in consultation with coaches; f) assessing other competitors and conditions at venues; g) competing in esports tournaments, events and leagues; and h) adhering to the rules and regulations associated with a specific esport.\nExamples of the occupations classified here: Esport coaches, Esport players","version":"2022","source_id":658,"level":4,"normalized_name":"esports players and coaches"},{"code":"3431","parent_code":"343","title":"PHOTOGRAPHERS","description":"Photographers operate still cameras to photograph people, events, scenes, materials, products and other subjects.\nTheir tasks include: a) taking photographs for advertising, or other commercial, industrial or scientific purposes and to illustrate stories and articles in newspapers, magazines and other publications; b) taking portrait photographs of persons and groups of persons; c) studying requirements of a particular assignment and decide on type of camera, film, lighting and background accessories to be used; d) determining picture composition, making technical adjustments to equipment and photograph subject; e) operating scanners to transfer photographic images to computers; f) operating computers to manipulate photographic images; g) adapting existing photographic images to create new digitized images to be included in multimedia products; and h) using airbrush, computer or other techniques to create the desired visual effect.\nExamples of the occupations classified here: Aerial photographer, Commercial photographer, Industrial photographer, News photographer, Photojournalist, Portrait photographer, Scientific photographer\nSome related occupations classified elsewhere: Electronics mechanic - 7421, Film camera operator - 3521, Photographic equipment repairer - 7311, Photogravure photographer - 7321, Photolithographer - 7321, Video camera operator - 3521","version":"2022","source_id":659,"level":4,"normalized_name":"photographers"},{"code":"3432","parent_code":"343","title":"INTERIOR DESIGNERS AND DECORATORS","description":"Interior designers and decorators plan and design commercial, industrial, public, retail and residential building interiors to produce an environment tailored to a purpose, taking into consideration factors that enhance living and working environments and sales promotion. They coordinate and participate in their construction and decoration.\nTheir tasks include: a) determining the objectives and constraints of the design brief by consulting with clients and stakeholders; b) researching and analyzing spatial, functional, efficiency, safety and aesthetic requirements; c) formulating design concepts for the interiors of buildings; d) preparing sketches, diagrams, illustrations and plans to communicate design concepts; e) negotiating design solutions with clients, management, suppliers and construction staff; f) selecting, specifying and recommending functional and aesthetic materials, furniture and products for interiors; g) detailing and documenting selected design for construction; h) coordinating the construction and the decoration of interiors; i) designing and painting stage scenery; and j) designing and decorating show windows and other display areas to promote products and services.\nExamples of the occupations classified here: Building designer and decorator, Display decorator, Display designer, Interior decorator, Interior designer, Set designer, Visual merchandiser, Window dresser\nRelated occupation classified elsewhere: Interior architect - 2161","version":"2022","source_id":660,"level":4,"normalized_name":"interior designers and decorators"},{"code":"3433","parent_code":"343","title":"GALLERY, MUSEUM AND LIBRARY TECHNICIANS","description":"Gallery, museum and library technicians prepare artworks, specimens and artefacts for collections, arrange and construct gallery exhibits, and assist librarians to organize and operate systems for handling recorded material and files.\nTheir tasks include: a) mounting and preparing objects for display; b) designing and arranging exhibit furnishings, display cases and display areas; c) assisting in setting up lighting and display equipment; d) receiving, shipping, packing and unpacking exhibits; e) ordering new library materials and maintaining library records and circulation systems; f) cataloguing printed and recorded material; g) entering data into databases and editing computer records; h) operating audiovisual and reprographic equipment; and i) searching and verifying bibliographic data.\nExamples of the occupations classified here: Curatorial technician, Gallery technician, Library technician, Museum technician, Taxidermist","version":"2022","source_id":661,"level":4,"normalized_name":"gallery museum and library technicians"},{"code":"3434","parent_code":"343","title":"CHEFS","description":"Chefs design menus, create dishes and oversee the planning, organization preparation and cooking of meals in hotels, restaurants and other eating places, on board ships, on passenger trains and in private households.\nTheir tasks include: a) planning and developing recipes and menus, estimating food and labor costs, and ordering food supplies; b) monitoring quality of dishes at all stages of preparation and presentation; c) discussing food preparation issues with managers, dieticians, kitchen and waiting staff; d) supervising and coordinating the activities of cooks and other workers engaged in food preparation; e) inspecting supplies, equipment, and work areas to ensure conformance to established standards; f) determining how food should be presented, and creating decorative food displays; g) instructing cooks and other workers in the preparation, cooking, garnishing, and presentation of food; h) participating on the recruitment of kitchen staff and monitoring their performance; i) preparing, seasoning and cooking specialty foods and complex dishes; and j) explaining and enforcing hygiene and food safety regulations.\nExamples of the occupations classified here: Executive chef, Head chef, Pastry chef (pâtissier), Saucier, Sous-chef\nSome related occupations classified elsewhere: Cook - 5120, Fast food preparer - 9411","version":"2022","source_id":662,"level":4,"normalized_name":"chefs"},{"code":"3435","parent_code":"343","title":"ARTISTIC AND CULTURAL ASSOCIATE PROFESSIONAL NOT ELSEWHERE CLASSIFIED","description":"This unit group covers artistic and cultural associate professionals not classified elsewhere in Minor Group 344, Artistic, cultural and culinary associate professionals. For instance those who assist directors or actors with staging of theatrical, motion picture, television or commercial productions are classified here.\nExamples of the occupations classified here: Body artist, Broadcasting floor manager, Broadcasting program coordinator, Broadcasting property master, Extra, Lighting technician, Prompter, Special effects technician, Stage manager, Stage technician, Stunt artist, Stunt coordinator, Tattoo artist, Theater technician, Theatrical dresser","version":"2022","source_id":663,"level":4,"normalized_name":"artistic and cultural associate professional not elsewhere classified"},{"code":"3511","parent_code":"351","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY OPERATIONS TECHNICIANS","description":"Information and communications technology operations technicians support the day-to-day processing, operation and monitoring of information and communications technology systems, peripherals, hardware, software and related computer equipment to ensure optimal performance, and identify any problems.\nTheir tasks include: a) operating and controlling peripheral and related computer equipment; b) entering commands, using computer terminal, and activating controls on computer and peripheral equipment to integrate and operate equipment; c) monitoring systems for equipment failure or errors in performance; d) notifying supervisor or maintenance technician of equipment malfunctions;e) responding to program error messages by finding and correcting problems, escalating the problem to other staff or terminating the program; f) reading job set-up instructions to determine equipment to be used, order of use, material such as disks and paper to be loaded, and control settings; g) retrieving, separating and sorting program output as needed, and sending data to specified users; and h) loading peripheral equipment, such as printers, with selected materials for operating runs, or oversee loading of peripheral equipment by peripheral equipment operators.\nExamples of the occupations classified here: Computer aided design (CAD) operator, Computer maintenance specialist, Computer maintenance technologist, Computer operator, Computer peripheral equipment operator, Electronic data processing operator, High-speed computer printer operator\nRelated occupation classified elsewhere: Computer network technician - 3513","version":"2022","source_id":664,"level":4,"normalized_name":"information and communications technology operations technicians"},{"code":"3512","parent_code":"351","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY USER SUPPORT TECHNICIANS","description":"Information and communications technology user support technicians provide technical assistance to users, either directly or by telephone, e-mail or other electronic means, including diagnosing and resolving issues and problems with software, hardware, computer peripheral equipment, networks, databases and the Internet, and providing guidance and support in the deployment, installation and maintenance of systems.\nTheir tasks include: a) answering user inquiries regarding software or hardware operation to resolve problems; b) entering commands and observing system functioning to verify correct operations and detect errors; c) installing and performing minor repairs to hardware, software, or peripheral equipment, following design or installation specifications; d) overseeing the daily performance of communications and computer systems; e) setting up equipment for employee use, performing or ensuring proper installation of cables, operating systems, or appropriate software; f) maintaining records of daily data communication transactions, problems and remedial actions taken, or installation activities; g) emulating or reproducing technical problems encountered by users; and h) consulting user guides, technical manuals and other documents to research and implement solutions.\nExamples of the occupations classified here: Computer database assistant, Computer engineering assistant, Computer help desk operator, Computer programming assistant, Computer systems analysis assistant, Electronic data processing assistant, ICT communications assistant","version":"2022","source_id":665,"level":4,"normalized_name":"information and communications technology user support technicians"},{"code":"3513","parent_code":"351","title":"COMPUTER NETWORK AND SYSTEMS TECHNICIANS","description":"Computer network and systems technicians establish, operate and maintain network and other data communications systems.\nTheir tasks include: a) operating, maintaining and troubleshooting network systems; b) operating and maintaining data communications systems other than networks; c) assisting users with network and data communications problems; d) identifying areas needing upgraded equipment and software; e) installing computer hardware, network software, operating system software and applications software; and f) performing start up and close down as well as backup and disaster recovery operations for computer networks.\nExamples of the occupations classified here: Computer network technician, Network support technician\nSome related occupations classified elsewhere: Computer operator - 3511, Network administrator - 2522, Network analyst - 2511, Web technician - 3514","version":"2022","source_id":666,"level":4,"normalized_name":"computer network and systems technicians"},{"code":"3514","parent_code":"351","title":"WEB TECHNICIANS","description":"Web technicians maintain, monitor and support the optimal functioning of Internet and Intranet websites and web server hardware and software.\nTheir tasks include: a) installing, monitoring and supporting the reliability and usability of Internet and Intranet websites or web server hardware or software; b) developing and maintaining documentation, policies and instructions, recording operational procedures and system logs; c) developing, coordinating, implementing and monitoring security measures; d) analyzing and making recommendations to enhance performance, including upgrading and acquiring new systems; e) liaising with, and providing guidance to, clients and users; f) modifying web pages; and g) performing web server backup and recovery operations.\nExamples of the occupations classified here: Webmaster, Website administrator, Website technician\nSome related occupations classified elsewhere: Computer games designer - 2166, Computer software designer - 2512, Computer systems administrator - 2522, Network administrator - 2522, System administrator - 2522, Systems analyst - 2511, Website designer - 2166, Website developer - 2513","version":"2022","source_id":667,"level":4,"normalized_name":"web technicians"},{"code":"3521","parent_code":"352","title":"BROADCASTING AND AUDIO-VISUAL TECHNICIANS","description":"Broadcasting and audio-visual technicians control technical functioning of equipment to record and edit images and sound and for transmitting radio and television broadcasts of images and sounds, as well as other types of telecommunication signals on land, sea or in aircraft.\nTheir tasks include: a) controlling equipment to record sound; b) controlling equipment to edit and mix image and sound recordings to ensure satisfactory quality and to create special image and sound effects; c) applying knowledge of principles and practices of image and sound recording and editing in order to identify and solve problems; d) controlling transmitting and broadcast systems and satellite systems for radio and television programmes; e) controlling radio communications systems, satellite services, and multiplex systems on land, sea or in aircraft; f) applying knowledge of principles and practices of broadcasting, telecommunications terminals and transmissions systems, in order to identify and solve problems; and g) making emergency repairs to equipment.\nExamples of the occupations classified here: Audiovisual operator, Broadcasting equipment operator, Broadcasting technician, Camera control unit technician, Camera operator, CCTV operator, Cinema projectionist, Media production assistant, Motion picture camera operator, Radio broadcasting equipment operator, Radio communication technician, Radio operator, Radio production technician, Sound technician, Transmitting equipment operator, TV broadcasting equipment operator, Video camera operator, Video camera technician\nRelated occupation classified elsewhere: Photographer - 3431","version":"2022","source_id":668,"level":4,"normalized_name":"broadcasting and audio-visual technicians"},{"code":"3522","parent_code":"352","title":"TELECOMMUNICATIONS ENGINEERING TECHNICIANS","description":"Telecommunications engineering technicians perform technical tasks connected with telecommunications engineering research, as well as with the design, manufacture, assembly, construction, operation, maintenance and repair of telecommunications systems.\nTheir tasks include: a) providing technical assistance connected with research and the development of telecommunications equipment, or testing prototypes; b) studying technical material such as blue prints and sketches to determine the method of work to be adopted; c) preparing detailed estimates of quantities and costs of materials and labor required for the manufacture and installation of telecommunications equipment, according to the specifications given; d) providing technical supervision of the manufacture, utilization, maintenance and repair of telecommunications systems to ensure satisfactory performance and compliance with specifications and regulations; and e) applying technical knowledge of telecommunications engineering principles and practices in order to identify and solve problems arising in the course of their work.\nExamples of the occupations classified here: Satellite communication engineering technician, Telecommunications engineering technician, Telephone engineering technician\nSome related occupations classified elsewhere: Computer hardware installer - 7422, Electronics engineering technician - 3114, Telecommunications equipment repairer - 7422, Telephone installer - 7422","version":"2022","source_id":669,"level":4,"normalized_name":"telecommunications engineering technicians"},{"code":"4110","parent_code":"411","title":"GENERAL OFFICE CLERKS","description":"General office clerks perform a range of clerical and administrative tasks according to established procedures.\nTheir tasks include: a) recording, preparing, sorting, classifying and filing information; b) sorting, opening and sending mail; c) photocopying and sending documents; d) preparing reports and correspondence of a routine nature; e) recording issue of equipment to staff; f) responding to telephone or electronic enquiries or forwarding to appropriate person; g) checking figures, preparing invoices and recording details of financial transactions made; and h) transcribing information into computers, and proof-reading and correcting copy.\nExamples of the occupations classified here: Document receiving clerk, Laboratory office clerk, Livelihood office clerk, Office clerk, Office maintenance clerk, Office record clerk, Office records filing clerk, Registrar clerk","version":"2022","source_id":670,"level":4,"normalized_name":"general office clerks"},{"code":"4120","parent_code":"412","title":"SECRETARIES (GENERAL)","description":"Secretaries (general) use typewriters, personal computers or other word-processing equipment to transcribe correspondence and other documents; check and format documents prepared by other staff; deal with incoming and outgoing mail; screen requests for meetings or appointments; and perform a variety of administrative support tasks. \nTheir tasks include: a) checking, formatting and transcribing correspondence, minutes and reports from dictation, electronic documents or written drafts to conform to office standards, using typewriter, personal computer or other word processing equipment; b) using various computer software packages, including spreadsheets, to provide administrative support; c) dealing with incoming or outgoing mail; d) scanning, recording and distributing mail, correspondence and documents; e) screening requests for meetings or appointments and helping to organize meetings; f) screening and recording leave and other staff-members' entitlements; g) organizing and supervising filing systems; and h) dealing with routine correspondence on their own initiative.\nExamples of the occupations classified here: Marketing secretary, Office secretary, Parish secretary, Sales secretary, Secretary, Typing secretary, Word processing secretary\nSome related occupations classified elsewhere: Administrative secretary - 3343, Executive assistant - 3343, Legal secretary - 3342, Medical secretary - 3344","version":"2022","source_id":671,"level":4,"normalized_name":"secretaries general"},{"code":"4131","parent_code":"413","title":"TYPISTS AND WORD PROCESSING OPERATORS","description":"Typists and word processing operators type, edit and print using typewriter, personal computer or word processor; and record oral or written matter in shorthand.\nTheir tasks include: a) typing written material from rough drafts, corrected copies, voice recordings, or shorthand using a computer, word processor or typewriter; b) checking completed work for proper spelling, grammar, punctuation and formatting; c) gathering and arranging the material to be typed, following instructions; d) filing and storing completed documents on computer hard drive or disk, or maintaining a computer filing system to store, retrieve or update documents; e) taking dictation and recording other matter in shorthand; f) reproducing the spoken word, environmental sounds and song lyrics as captions for cinema and television programming; and g) transcribing information recorded in shorthand and on sound recording equipment.\nExamples of the occupations classified here: Shorthand typist, Stenographer, Typing stenographer, Typist, Word processing clerk, Word processor\nSome related occupations classified elsewhere: Court reporter - 3343, Medical transcriptionist - 3344","version":"2022","source_id":672,"level":4,"normalized_name":"typists and word processing operators"},{"code":"4132","parent_code":"413","title":"DATA ENTRY CLERKS","description":"Data entry clerks enter coded, statistical, financial and other numerical data into electronic equipment, computerized databases, spreadsheets or other data repositories using a keyboard, mouse, or optical scanner, speech recognition software or other data entry tools. They enter data into mechanical and electronic devices to perform mathematical calculations.\nTheir tasks include: a) receiving and registering invoices, forms, records and other documents for data capture; b) entering numerical data, codes and text from source material into computer-compatible storage and processing devices; c) verifying accuracy and completeness of data and correcting entered data, if needed; d) operating bookkeeping and calculating machines; and e) importing and exporting data between different database systems and software.\nExamples of the occupations classified here: Computer clerk, Computer data encoder, Data encoder, Data encoder clerk, Data entry operator, Data input clerk, Encoder clerk, Payment entry clerk","version":"2022","source_id":673,"level":4,"normalized_name":"data entry clerks"},{"code":"4211","parent_code":"421","title":"BANK TELLERS AND RELATED CLERKS","description":"Bank tellers and related clerks deal directly with clients of banks or post offices in connection with receiving, changing and paying out money; or providing mail services.\nTheir tasks include: a) processing customer cash deposits and withdrawals, cheques, transfers, bills, credit card payments, money orders, certified cheques and other related banking transactions; b) crediting and debiting clients' accounts; c) paying bills and making money transfers on clients' behalf; d) receiving mail, selling postage stamps and conducting other post office counter business such as bill payments, money transfers and related business; e) changing money from one currency to another, as requested by clients; and f) making records of all transactions and reconciling them with cash balance.\nExamples of the occupations classified here: Bank cashier, Bank clerk, Bank teller, Money changer, Post office counter clerk \nRelated occupation classified elsewhere: Cashier - 5230","version":"2022","source_id":674,"level":4,"normalized_name":"bank tellers and related clerks"},{"code":"4212","parent_code":"421","title":"BOOKMAKERS, CROUPIERS/DEALERS AND RELATED GAMING WORKERS","description":"Bookmakers, croupiers/dealers and related gaming workers determine odds and receive and pay off bets on results of sporting or other events; or conduct games of chance in gambling establishments.\nTheir tasks include: a) determining risks to decide odds and to hedge or refuse bets; b) preparing and issuing lists of approximate odds; c) distributing cards, rolling dice or spinning a roulette wheel; d) explaining and interpreting operating rules of a gambling establishment; and e) announcing winning numbers, paying winners and collecting payments from losers.\nExamples of the occupations classified here: Bet collector, Bookmaker, Card dealer, Croupier, Gaming dealer","version":"2022","source_id":675,"level":4,"normalized_name":"bookmakers croupiers/dealers and related gaming workers"},{"code":"4213","parent_code":"421","title":"PAWNBROKERS AND MONEY-LENDERS","description":"Pawnbrokers and money lenders lend money against articles deposited as pledges, or against property or other security.\nTheir tasks include: a) evaluating articles offered as pledges, calculating interest, and lending money; b) returning articles when the loan is paid or, in the event of non-payment, selling pledged articles; c) lending money as personal loans against success of future harvest and other similar undertakings; d) collecting loans when the pledge involved the success of future harvest and other similar undertakings; and e) keeping a record of items received and money distributed and received.\nExamples of the occupations classified here: Loan clerk, Loan processor, Mortgage clerk","version":"2022","source_id":676,"level":4,"normalized_name":"pawnbrokers and money-lenders"},{"code":"4214","parent_code":"421","title":"DEBT COLLECTORS AND RELATED WORKERS","description":"Debt collectors and related workers collect payments on overdue accounts and bad cheques and collect charity payments. \nTheir tasks include: a) tracing and locating debtors; b) telephoning, visiting, or writing to customers to collect money or arrange for later payments; c) preparing reports including amounts collected and maintain records and files related to collection work; d) recommending legal action or discontinuation of service when payment cannot be otherwise obtained; and e) asking for and collecting charity payments.\nExamples of the occupations classified here: Bill and account collector, Charity collector, Credit collection clerk, Credit collector, Debt collector, Lending collector, Payment collection agent, Rent collector","version":"2022","source_id":677,"level":4,"normalized_name":"debt collectors and related workers"},{"code":"4221","parent_code":"422","title":"TRAVEL CONSULTANTS AND CLERKS","description":"Travel consultants and clerks provide information about travel destinations, arrange travel itineraries, obtain travel and accommodation reservations and register passengers at check-in and departure.\nTheir tasks include: a) obtaining information about the availability, cost and convenience of different types of transport and accommodation, ascertaining customer’s requirements and advising them on travel arrangements; b) providing information about local and regional attractions, sightseeing tours, restaurants, arts and entertainment, and providing maps and brochures; c) preparing itineraries; d) making and confirming reservations for travel, tours and accommodation; \ne) issuing tickets, boarding passes and vouchers; g) verifying travel documentation and registering passengers and luggage at check-in and departure; f) helping customers in obtaining necessary travel documents such as visas; h) preparing bills and receiving payments; and i) organizing group tours for business or vacation travel and selling them to groups or individuals.\nExamples of the occupations classified here: Airline ticket agent, Check-in attendant, Tourism information clerk, Tourism information counselor, Travel agency clerk, Travel agent, Travel clerk, Travel consultant, Travel counselor, Travel desk clerk, Travel ticket issuing clerk\nSome related occupations classified elsewhere: Conference and event planner - 3332, Entertainment and sporting events ticket issuing clerk - 5230, Tour escort -5113, Tour operator - 3339, Tourist guide - 5113, Travel agency manager - 1439","version":"2022","source_id":678,"level":4,"normalized_name":"travel consultants and clerks"},{"code":"4222","parent_code":"422","title":"CONTACT CENTER INFORMATION CLERKS","description":"Contact center information clerks provide advice and information to clients; respond to queries regarding a company’s or an organization’s goods, services or policies; and process financial transactions using the telephone or electronic communications media, such as email. They are located in premises that may be remote from clients or other operations of the organizations or companies about whom information is provided.\nTheir tasks include: a) dealing with incoming calls and messages from clients, whether to answer queries, handle calls for service or sort out complaints; b) identifying requirements and entering events into a computer system; c) dispatching tasks to other units, when relevant; d) invoicing or handling payments, where necessary; e) sending letters, information sheets and other documents to clients; and f) advising clients of additional products or services.\nExamples of the occupations classified here: Call center agent, Call center assistant, Call center representative, Chat support agent, Chat support representatives, Customer contact center information clerk, Customer service call center assistant, Customer service call center associate, Customer service representative, Telephone service representative\nSome related occupations classified elsewhere: Call center salesperson - 5244, Customer contact center salesperson - 5244, Market research interviewer - 4227, Telemarketing salesperson - 5244, Telephone operator - 4223","version":"2022","source_id":679,"level":4,"normalized_name":"contact center information clerks"},{"code":"4223","parent_code":"422","title":"TELEPHONE SWITCHBOARD OPERATORS","description":"Telephone switchboard operators operate telephone communications switchboards and consoles to establish telephone connections; receive caller inquiries and service problem reports; and record and relay messages to staff or clients. \nTheir tasks include: a) operating switchboards and consoles to connect, hold, transfer, and disconnect telephone calls; b) making connections for outgoing calls; c) dealing with telephone inquiries and recording messages; d) forwarding messages to staff or clients; and e) investigating operating system problems and informing repair services.\nExamples of the occupations classified here: Answering service operator, Communication telephone operator, Telephone operator, Telephone switchboard operator","version":"2022","source_id":680,"level":4,"normalized_name":"telephone switchboard operators"},{"code":"4224","parent_code":"422","title":"HOTEL RECEPTIONISTS","description":"Hotel receptionists register guests; assign rooms; issue keys; provide information concerning the hotel services; make room reservations; keep a record of rooms available for occupancy; and present statements of charges to departing guests and receive payment.\nTheir tasks include: a) maintaining an inventory of rooms available for occupancy, reservations and room assignments; b) registering arriving guests, assigning rooms; verifying customer’s credit and issuing room keys; c) providing information regarding hotel services and services available in the community; d) providing information about availability of accommodation and making room reservations; e) responding to guests’ requests for housekeeping and maintenance services as well as complaints; f) contacting housekeeping or maintenance services when guests report problems; g) compiling and checking guest accounts for charges using computerized or manual systems; h) receiving and forwarding messages in person or using telephone or telephone switchboard; and i) reviewing statements of charges to departing guests and receiving payment.\nExample of occupation classified here: Hotel front desk clerk","version":"2022","source_id":681,"level":4,"normalized_name":"hotel receptionists"},{"code":"4225","parent_code":"422","title":"INQUIRY CLERKS","description":"Inquiry clerks respond to personal, written, electronic mail, and telephone inquiries and complaints about the organization’s goods, services and policies, provide information and refer people to other sources. They are employed in locations which put them in direct contact with clients or with the production of the goods and services provided.\nTheir tasks include: a) answering inquiries about goods, services and policies, and providing information about their availability, location, price and related issues; b) responding to enquiries about problems and providing advice, information and assistance; c) recording information about inquiries and complaints; d) referring complex enquiries to team leaders or expert advisers; and e) issuing relevant forms, information kits and brochures to interested parties.\nExamples of the occupations classified here: Counter inquiries clerk, Information clerk, Reservation inquiries clerk","version":"2022","source_id":682,"level":4,"normalized_name":"inquiry clerks"},{"code":"4226","parent_code":"422","title":"RECEPTIONISTS (GENERAL)","description":"Receptionists (general) receive and welcome visitors, clients, or guests; and respond to inquiries and requests, including arranging for appointments. \nTheir tasks include: a) receiving and welcoming visitors, guests or clients; b) making appointments for clients; c) dealing with telephone requests for information or appointments; d) directing clients to appropriate location or person; and e) supplying information pamphlets, brochures or forms.\nExamples of the occupations classified here: Medical office receptionist, Medical receptionist, Receptionist \nSome related occupations classified elsewhere: Hotel receptionist - 4224, Medical secretary - 3344","version":"2022","source_id":683,"level":4,"normalized_name":"receptionists general"},{"code":"4227","parent_code":"422","title":"SURVEY AND MARKET RESEARCH INTERVIEWERS","description":"Survey and market research interviewers interview people and record their responses to survey and market research questions on a range of topics.\nTheir tasks include: a) contacting individuals by telephone or in person and explaining the purpose of the interview; b) asking questions following the outlines of questionnaires and surveys; c) recording responses on paper or entering responses directly into a computer database through computer-assisted interviewing systems; d) identifying and resolving inconsistencies in responses; and e) providing feedback to survey sponsors concerning problems in obtaining valid data.\nExamples of the occupations classified here: Data enumerator clerk, Enumerator, Enumerator clerk, Market research interviewer, Public opinion interviewer, Survey interviewer","version":"2022","source_id":684,"level":4,"normalized_name":"survey and market research interviewers"},{"code":"4229","parent_code":"422","title":"CLIENT INFORMATION WORKERS NOT ELSEWHERE CLASSIFIED","description":"This Unit Group includes client information workers not elsewhere classified in Minor Group 422. Client information workers. For instance, it includes workers who obtain and process information from clients needed to determine eligibility for services.\nIn such cases, tasks would include: a) interviewing patients to obtain and process information required to provide hospital services; b) interviewing applicants for public assistance to gather information pertinent to their application; c) verifying the accuracy of information provided; d) initiating procedures to grant, modify, deny or terminate assistance; e) providing information and answering questions concerning benefits and claims procedures; and f) referring patient or applicant to other organizations if they are ineligible for services.\nExamples of the occupations classified here: Admissions clerk, Eligibility interviewer, Eligibility specialist, Hospital admissions clerk","version":"2022","source_id":685,"level":4,"normalized_name":"client information workers not elsewhere classified"},{"code":"4311","parent_code":"431","title":"ACCOUNTING AND BOOKEEPING CLERKS","description":"Accounting and bookkeeping clerks compute, classify and record numerical data to keep financial records complete. They perform any combination of routine calculating, posting and verifying duties to obtain primary financial data for use in maintaining accounting records.\nTheir tasks include: a) checking figures, postings and documents for correct entry, mathematical accuracy and proper codes; b) operating computers programmed with accounting software to record, store and analyze information; c) classifying, recording and summarizing numerical and financial data to compile and keep financial records using journals and ledgers or computers; d) calculating, preparing and issuing bills, invoices, account statements and other financial statements according to established procedures; and e) compiling statistical, financial, accounting or auditing reports and tables pertaining to such matters as cash receipts, expenditures, accounts payable and receivable, and profits and losses.\nExamples of the occupations classified here: Account-information clerk, Accounting clerk, Accounting sales clerk, Accounting staff, Accounts clerk, Bookkeeping clerk, Cost computing clerk \nSome related occupations classified elsewhere: Accounting assistant - 3313, Bookkeeper - 3313","version":"2022","source_id":686,"level":4,"normalized_name":"accounting and bookeeping clerks"},{"code":"4312","parent_code":"431","title":"STATISTICAL, FINANCE AND INSURANCE CLERKS","description":"Statistical, finance and insurance clerks obtain, compile and compute statistical or actuarial data or perform clerical tasks relating to the transactions of insurance establishments, banks and other financial establishments.\nTheir tasks include: a) processing insurance enrolments, cancellations, claims transactions, policy changes and payments; b) obtaining and compiling statistical or actuarial data based on routine or special sources of information; c) calculating totals, averages, percentages and other details and presenting them in the required tabular form; d) preparing financial documents, and calculating interest or brokerage charges and stamp duties payable; and e) maintaining records of bonds, shares and other securities bought or sold on behalf of clients or employer.\nExamples of the occupations classified here: Actuarial clerk, Brokerage clerk, Finance clerk, Insurance clerk, Mortgage clerk, Securities clerk, Statistical clerk, Statistician aide,Tax clerk, Treasury clerk\nSome related occupations classified elsewhere: Accounting assistant - 3313, Accounts clerk - 4311, Bookkeeping clerk - 4311, Statistical assistant - 3314, Stocks and shares broker - 3311, Trade broker - 3324","version":"2022","source_id":687,"level":4,"normalized_name":"statistical finance and insurance clerks"},{"code":"4313","parent_code":"431","title":"PAYROLL CLERKS","description":"Payroll clerks collect, verify and process payroll information and compute pay and benefit entitlements for employees within a department, company or other establishment.\nTheir tasks include: a) maintaining records of employee attendance, leave and overtime to calculate pay and benefit entitlements, using manual or computerized systems; b) preparing and verifying statements of earnings for employees, indicating gross and net salaries and deductions such as taxes, union dues, garnishments and insurance and pension plans; c) preparing employee payments and benefit payments by cheque or electronic transfer; d) reviewing time sheets, work charts, wage computation and other information to detect and reconcile payroll discrepancies; and e) verifying attendance, hours worked and pay adjustments, and posting information onto designated records.\nExamples of the occupations classified here: Payroll and timekeeping specialist, Payroll clerk, Wages clerk \nSome related occupations classified elsewhere: Accounting assistant - 3313, Accounts clerk - 4311, Bookkeeper - 3313, Bookkeeping clerk - 4311","version":"2022","source_id":688,"level":4,"normalized_name":"payroll clerks"},{"code":"4321","parent_code":"432","title":"STOCK CLERKS","description":"Stock clerks maintain records of goods produced and production materials received, weighed, issued, dispatched or put into stock.\nTheir tasks include: a) arranging and controlling receipt and dispatch of goods and keeping relevant records; b) maintaining stock records, verifying issue of goods, estimating needs and making requisitions of new stocks; c) receiving, storing and issuing tools, spare parts, or various equipment and maintaining relevant records; d) weighing goods received, issued, produced, or dispatched and maintaining relevant records; and e) compiling inventories of furniture and other items received for storage.\nExamples of the occupations classified here: Cargo clerk, Demurrage clerk, Freight clerk, Inventory clerk, Stock checker clerk, Stock controller clerk, Stock custodian, Stock dispatch clerk, Storekeeper clerk, Storeroom clerk, Supply checker clerk, Warehouse checker, \nWarehouse clerk, Warehouse dispatcher, Warehouse man, Weighing clerk","version":"2022","source_id":689,"level":4,"normalized_name":"stock clerks"},{"code":"4322","parent_code":"432","title":"PRODUCTION CLERKS","description":"Production clerks compute quantities of materials required at specified dates for manufacturing, construction and similar production programmes; and prepare and check production operation schedules.\nTheir tasks include: a) computing quantities, qualities and types of materials required by production programme; b) preparing production requirements schedules, ensuring that materials are available when needed, and keeping relevant records; c) preparing or assisting in the preparation of production operation schedules on the basis of customers' orders and production capacity and performance; d) verifying stocks, arranging deliveries and investigating delays; and e) recording and coordinating the flow of work and materials between departments.\nExamples of the occupations classified here: Material control and handling clerk, Materials order clerk, Materials processing and control clerk, Materials schedule clerk, Production clerk","version":"2022","source_id":690,"level":4,"normalized_name":"production clerks"},{"code":"4323","parent_code":"432","title":"TRANSPORT CLERKS","description":"Transport clerks keep records of operational aspects and coordinate the timing of train, road and air passenger and freight transport; and prepare reports for management.\nTheir tasks include: a) keeping records of operational aspects and coordinating the timing of passenger and freight transport; b) directing train routings within a division or zone of a railway system and keeping related records; c) directing, controlling and keeping records of freight handling at a railway yard; d) coordinating and keeping records of operational activities concerning road transport, such as allocation and scheduling of vehicles and drivers, loading and unloading of vehicles and storage of goods in transit; e) coordinating and keeping records of operational activities concerning air transport of passengers and freight, such as passenger lists and freight manifests; and f) preparing reports for management.\nExamples of the occupations classified here: Aircraft clerical dispatcher, Incoming-freight clerk, Ship boarding clerical inspector, Train clerical dispatcher, Transport service clerical controller, Transport service clerical dispatcher","version":"2022","source_id":691,"level":4,"normalized_name":"transport clerks"},{"code":"4411","parent_code":"441","title":"LIBRARY CLERKS","description":"Library clerks issue and receive library materials; sort and shelve books, sound and vision recordings, periodicals, journals, magazines and newspapers; and provide general library information to library users.\nTheir tasks include: a) issuing and receiving library books and other materials; b) reshelving books and other library materials; c) performing clerical activities such as manual and electronic filing, word processing and occasional typing; d) maintaining journal subscriptions; e) assisting library users in accessing basic library materials and making inter-library loans; and f) maintaining library records relating to the acquisition, issue and return of books and other materials.\nExamples of the occupations classified here: Librarian aide, Library assistant, Library clerk, Library filer","version":"2022","source_id":692,"level":4,"normalized_name":"library clerks"},{"code":"4412","parent_code":"441","title":"MAIL CARRIERS AND SORTING CLERKS","description":"Mail carriers and sorting clerks perform sorting, recording, delivery and other duties in connection with mail services from post offices or related organizations, as well as from or within an establishment. \nTheir tasks include: a) performing mail-handling duties in public post offices or privately-owned delivery establishments; b) sorting and delivering mail to private houses and businesses; c) providing delivery confirmation records when requested by the client; and d) sorting and keeping simple records of incoming and outgoing correspondence and dispatching outgoing mail in various establishments. \nExamples of the occupations classified here: Mail clerk, Mail courier, Mail dispatch clerk, Mail messenger, Mail sorting clerk, Post carrier, Postal clerk, Postman","version":"2022","source_id":693,"level":4,"normalized_name":"mail carriers and sorting clerks"},{"code":"4413","parent_code":"441","title":"CODING, PROOF-READING AND RELATED CLERKS","description":"Coding, proof-reading and related clerks convert information into codes; verify and correct proofs; and perform a number of miscellaneous clerical duties.\nTheir tasks include: a) converting information into codes and classifying information by codes for data-processing purposes; b) comparing proofs of texts and related material prepared for printing with original material; correcting errors; and marking texts for printer according to the established rules; c) sorting forms and marking them with identification numbers; d) sorting documents for filing or to collate sets of pages; and e) addressing circulars and envelopes by hand.\nExamples of the occupations classified here: Coding clerk, Proofreading clerk","version":"2022","source_id":694,"level":4,"normalized_name":"coding proof-reading and related clerks"},{"code":"4414","parent_code":"441","title":"SCRIBES AND RELATED WORKERS","description":"Scribes and related workers write letters and complete forms on behalf of persons who are unable to read and write, e.g., illiterate persons, not physically present, etc. \nTheir tasks include: a) reading letters and other written matter to persons who are unable to read or write and providing necessary interpretation and information; b) writing letters and completing forms on behalf of others; and c) offering advice to individuals and interpreting and helping with the completion of government and other official forms.\nExample of occupation classified here: Scribe \nRelated occupation classified elsewhere: Medical transcriptionist - 3344","version":"2022","source_id":695,"level":4,"normalized_name":"scribes and related workers"},{"code":"4415","parent_code":"441","title":"FILING AND COPYING CLERKS","description":"Filing and copying clerks file correspondence, cards, invoices, receipts and other records in alphabetical or numerical order or according to the filing system used. They locate and remove material from file when requested; and photocopy, scan or fax documents.\nTheir tasks include: a) sorting or classifying materials according to guidelines such as content, purpose, user criteria, or chronological, alphabetical, or numerical order; b) filing material in drawers, cabinets and storage boxes; c) locating and removing materials from files when requested; d) keeping records of materials filed and removed; and e) photocopying, scanning or faxing documents.\nExamples of the occupations classified here: Copying clerk, Filing clerk","version":"2022","source_id":696,"level":4,"normalized_name":"filing and copying clerks"},{"code":"4416","parent_code":"441","title":"PERSONNEL CLERK","description":"Personnel clerks maintain and update personnel records such as information on transfers and promotions, performance evaluations, employee leave taken and accumulated, salaries, qualifications and training.\nTheir tasks include: a) updating information on employment history, salaries, performance evaluations, qualifications and training, and leave taken and accumulated; b) initiating records for newly-appointed workers and checking records for completeness; c) processing applications for employment and promotions and advising applicants of results; d) receiving and answering inquiries about employment entitlements and conditions; e) sending out job applications and announcements of job openings and job examinations; f) maintaining and updating manual and computerized filing and registration systems; and compiling and preparing reports and documents relating to personnel activities; and g) storing and retrieving personnel records and files on request.\nExamples of the occupations classified here: Employee benefits service clerk, Employee data management clerk, Employment clerk, Human resource assistant, Human resource clerk, Recruitment clerk","version":"2022","source_id":697,"level":4,"normalized_name":"personnel clerk"},{"code":"4419","parent_code":"441","title":"CLERICAL SUPPORT WORKERS NOT ELSEWHERE CLASSIFIED","description":"This Unit Group covers clerical support workers not classified elsewhere in Major Group 4. Clerical support workers. For instance, the group includes correspondence clerks, press clippers and publication clerks.\nIn such cases, tasks would include: a) receiving customers' orders for classified advertising; writing and editing copy; calculating advertising rates; and billing customers; b) writing business and government correspondence such as replies to requests for information and assistance, damage claims, credit and billing enquiries and service complaints;c) assisting in the preparation of periodicals, advertisements, catalogues, directories and other material for publication; and d) reading newspapers, magazines, press releases and other publications to locate and file articles of interest to staff and clients.\nExamples of the occupations classified here: Advertising clerk, Correspondence clerk, Directory compiler, Press clipper, Publication clerk","version":"2022","source_id":698,"level":4,"normalized_name":"clerical support workers not elsewhere classified"},{"code":"5111","parent_code":"511","title":"TRAVEL ATTENDANTS AND TRAVEL STEWARDS","description":"Travel attendants and travel stewards ensure the comfort and safety of passengers; serve meals and beverages; and render personal services, usually on aircraft and on board ships. They may plan and coordinate housekeeping and social activities on ships.\nTheir tasks include: a) greeting passengers entering aircraft or ship; checking tickets or boarding passes; and directing them to their seats or berths; b) announcing, explaining and demonstrating safety and emergency procedures, such as the use of oxygen masks, seat belts, and life jackets; c) assembling and serving pre-prepared meals and beverages; d) selling duty-free and other goods; e) taking care of general needs and comfort of passengers, answering inquiries, and keeping cabins clean and tidy; f) directing and assisting passengers and following prescribed procedures in the event of an emergency, such as evacuating a plane following an emergency landing; g) verifying that first aid kits and other emergency equipment are in working order; h) administering first aid to passengers in distress; i) attending pre-flight briefings concerning weather, altitudes, routes, emergency procedures, crew coordination, lengths of flights, food and beverage services offered, and numbers of passengers; j) preparing passengers and aircraft for take-off and landing; and k) determining special assistance needs of passengers such as small children, the elderly, or disabled persons.\nExamples of the occupations classified here: Aircraft cabin attendant, Airline steward, Cabin attendant, Flight attendant, Flight steward, Ship's steward","version":"2022","source_id":699,"level":4,"normalized_name":"travel attendants and travel stewards"},{"code":"5112","parent_code":"511","title":"TRANSPORT CONDUCTORS","description":"Transport conductors check and issue tickets; and ensure the safety and comfort of passengers on trains, trams, buses and other public transport vehicles.\nTheir tasks include: a) collecting and issuing tickets, passes or fares, and checking the validity of tickets issued previously; b) attending to sleeping-cars and their occupants on passenger trains; c) providing assistance with boarding, seating and luggage as required, especially to elderly, sick, or injured people; d) opening and closing doors for passengers; e) performing equipment safety checks prior to departure; f) signaling to drivers to stop or proceed; g) greeting passengers, boarding transportation equipment, and announcing routes and stops; h) ensuring that safety regulations are respected; i) responding to passengers requests and complaints and providing information about stops and connections; and j) taking appropriate action in case of emergencies or accidents.\nExamples of the occupations classified here: Bus conductor, Cable car conductor, Jeepney conductor, Passenger car conductor, Public transport ticket inspector, Train conductor","version":"2022","source_id":700,"level":4,"normalized_name":"transport conductors"},{"code":"5113","parent_code":"511","title":"TRAVEL GUIDES","description":"Travel guides accompany individuals or groups on trips, sightseeing tours and excursions and on tours of places of interest such as historical sites, industrial establishments and theme parks. They describe points of interest and provide background information on interesting features.\nTheir tasks include: a) escorting and guiding tourists on cruises and sightseeing tours; b) escorting visitors through places of interest such as museums, exhibitions, theme parks, factories and other industrial establishments; c) describing and providing information on points of interest and exhibits, and responding to questions; d) conducting educational activities for school children; e) monitoring visitors' activities to ensure compliance with establishment or tour regulations and safety practices; f) greeting and registering visitors and tour participants, and issuing any required identification badges or safety devices; g) distributing brochures, showing audio-visual presentations, and explaining procedures and operations at tour sites; h) providing for physical safety of groups, and performing activities such as providing first aid and directing emergency evacuations; and i) resolving any problems with tour itineraries, service, or accommodation.\nExamples of the occupations classified here: Art gallery guide, Mountaineering guide, Museum guide, Recreational attendant, Sightseeing guide, Tour escort, Tourist guide","version":"2022","source_id":701,"level":4,"normalized_name":"travel guides"},{"code":"5120","parent_code":"512","title":"COOKS","description":"Cooks plan, organize, prepare and cook meals in hotels, restaurants and other eating places, on board ships, on passenger trains and in private households.\nTheir tasks include: a) planning meals, preparing and cooking foodstuffs; b) planning, supervising and coordinating the work of kitchen helpers; c) checking the quality of food; d) weighing, measuring and mixing ingredients according to recipes and personal judgement; e) regulating the temperature of ovens, grills, roasters and other cooking equipment; inspecting and cleaning the kitchen, kitchen equipment, serving areas, etc. to ensure safe and sanitary food handling practices; andf) operating large-volume cooking equipment such as grills, deep-fat fryers, or griddles.\nExamples of the occupations classified here: Cook, Head cook, Preserving cook, Private service cook, Shipcook\nSome related occupations classified elsewhere: Cafe manager - 1412, Chef - 3434, Fastfood preparer - 9411, Restaurant manager - 1412","version":"2022","source_id":702,"level":4,"normalized_name":"cooks"},{"code":"5131","parent_code":"513","title":"WAITERS","description":"Waiters serve food and beverages at tables in dining and drinking places, clubs, institutions and canteens, on board ships and on passenger trains.\nTheir tasks include: a) setting tables with clean linen, cutlery, crockery and glassware; b) greeting customers and presenting them with menus and beverage lists; c) advising on food and beverage choices; d) taking orders for food and drinks and passing order to kitchen or bar staff; e) serving food and beverages to clients at tables; f) clearing tables and returning dishes and cutlery to kitchen; and g) presenting bills, accepting payment and operating point of sales machines and cash registers.\nExamples of the occupations classified here: Back waiter, Food attendant, Food server, General waiter, Sommelier, Waitress\nSome related occupations classified elsewhere: Bartender - 5132, Café manager - 1412, Restaurant manager - 1412","version":"2022","source_id":703,"level":4,"normalized_name":"waiters"},{"code":"5132","parent_code":"513","title":"BARTENDERS","description":"Bartenders prepare, mix and serve alcoholic and non-alcoholic drinks directly to customers over a bar or counter, or through waiters.\nTheir tasks include: a) taking beverage orders from serving staff or directly from patrons; b) preparing and serving alcoholic and non-alcoholic drinks at a bar; c) washing used glassware, cleaning and maintaining bar service areas, tea and coffee-making areas and equipment such as espresso machines; d) collecting payment for sales, operating cash registers and balancing cash receipts; e) tapping kegs and attaching supply lines; f) assisting in keeping bar properly stocked and arranging bottles and glasses; g) checking identification of customers to verify age requirements for purchase of alcohol; h) taking steps to limit problems related to excessive drinking such, as persuading customers to stop drinking, declining further service and ordering transportation; i) mixing ingredients to prepare cocktails and other drinks; and j) serving snacks or other food items to customers at the bar.\nExamples of the occupations classified here: Barista, Barkeeper, Barmaid\nSome related occupations classified elsewhere: Café manager - 1412, Restaurant manager - 1412, Waiter - 5131","version":"2022","source_id":704,"level":4,"normalized_name":"bartenders"},{"code":"5141","parent_code":"514","title":"HAIRDRESSERS","description":"Hairdressers cut, style, color, straighten and permanently wave hair; shave or trim facial hair; and treat scalp conditions.\nTheir tasks include: a) cutting, washing, tinting and waving hair; b) shaving or trimming beards and moustaches; c) giving scalp treatment; d) fitting wigs according to customers’ requirements; e) providing advice on hair care, beauty products and hairstyles; f) styling hair into dreadlocks and braids and adding hair extensions; g) arranging appointments and collecting payments; and h) cleaning work areas and sanitizing instruments.\nExamples of the occupations classified here: Barber, Hair care specialist, Hair beautician, Hair colorist, Hair preparer, Hairstylist","version":"2022","source_id":705,"level":4,"normalized_name":"hairdressers"},{"code":"5142","parent_code":"514","title":"BEAUTICIANS AND RELATED WORKERS","description":"Beauticians and related workers give facial and body beauty treatments; apply cosmetics and make-up; and give other kinds of treatment to individuals in order to improve their appearance.\nTheir tasks include: a) cleaning and applying creams, lotions and related products to face and parts of body; b) giving facial and body massage; c) applying make-up to clients of a beauty parlor or to actors and other performers; d) cleaning, shaping and polishing finger- and toe-nails; and treating minor ailments of the human foot such as corns, calluses or deformed toe-nails; e) attending to clients taking bath and administering elementary massage; f) using waxing, sugaring and depilation techniques to remove unwanted bodily hair; g) advising clients on diet and exercise to assist in weight loss and slimming; and h) arranging appointments and collecting payments.\nExamples of the occupations classified here: Assistant beautician, Bath attendant, Beautician, Beauty consultant, Cosmetologist, Make-up artist, Manicurist, Mortuary beautician, Nail technician, Pedicurist, Slimming consultant","version":"2022","source_id":706,"level":4,"normalized_name":"beauticians and related workers"},{"code":"5151","parent_code":"515","title":"CLEANING AND HOUSEKEEPING SUPERVISORS IN OFFICES, HOTELS AND OTHER ESTABLISHMENTS","description":"Cleaning and housekeeping supervisors in offices, hotels and other establishments organize, supervise and carry out housekeeping functions in order to keep clean and tidy the interiors, fixtures and facilities in these establishments.\nTheir tasks include: a) engaging, training, discharging, organizing and supervising helpers, cleaners and other housekeeping staff; b) purchasing or controlling the purchase of supplies; c) controlling storage and issue of supplies; d) supervising general welfare and conduct of individuals in institutions; e) sweeping or vacuum-cleaning, washing and polishing floors, furniture and other fixtures; f) making beds, cleaning bathrooms, supplying towels, soap and related items; g) cleaning kitchens and generally helping with kitchen work, including dishwashing; and h) restocking mini-bars and replenishing items such as drinking glasses and writing equipment.\nExamples of the occupations classified here: Cleaning supervisor, Hospital housekeeper, Hotel housekeeper, Hotel housekeeping attendant, Housekeeping matron, Housekeeping supervisor\nSome related occupations classified elsewhere: Bed and breakfast operator - 5152, Building caretaker - 5153, Domestic cleaner - 9111, Domestic housekeeper - 5152, Hotel manager - 1411","version":"2022","source_id":707,"level":4,"normalized_name":"cleaning and housekeeping supervisors in offices hotels and other establishments"},{"code":"5152","parent_code":"515","title":"HOUSEHOLD SERVICE PROVIDERS","description":"Household service providers organize, supervise and carry out housekeeping functions in private households with or without the support of subordinate staff.\nTheir tasks include: a) supervising workers employed in households as domestic staff; b) purchasing or controlling the purchase of supplies; c) controlling storage and issue of supplies; d) assisting in cases of minor injury or illness by performing tasks such as taking temperature, giving medicine, putting on bandages; e) sweeping or vacuum-cleaning, washing and polishing floors, furniture and other fixtures; f) making beds, cleaning bathrooms, supplying towels, soap and related items; g) taking care of household pets and plants, receiving visitors, answering telephones, delivering messages and shopping for groceries; h) preparing and cooking meals, setting and clearing tables and serving food and beverages; and i) cleaning kitchens and generally helping with kitchen work, including dishwashing.\nExamples of the occupations classified here: Bed and breakfast operator, Butler, Domestic housekeeper, House steward\nSome related occupations classified elsewhere: Domestic helper - 9111, Hotel manager - 1411","version":"2022","source_id":708,"level":4,"normalized_name":"household service providers"},{"code":"5153","parent_code":"515","title":"BUILDING CARETAKERS","description":"Building caretakers take care of apartment houses, hotels, offices, churches and other buildings and maintain them and associated grounds in a clean and orderly condition. They may supervise other workers and contractors depending on the size and nature of the building concerned.\nTheir tasks include: a) supervising the work of cleaning, housekeeping and building maintenance staff and contractors; b) participating in cleaning, simple repairs and maintenance of building interiors; c) tending furnaces and boilers to ensure provision of heat and hot water; d) regulating conduct of tenants and visitors in such matters as noise abatement or misuse of property; e) providing small services to absent tenants such as accepting deliveries on their behalf or providing requested information to callers; f) notifying management and owners of buildings of the need for major repairs; g) patrolling buildings to ensure security is maintained; and h) filling out registration forms and providing tenants with copies of rules.\nExamples of the occupations classified here: Caretaker, Building concierge, Dorm caretaker, Lighthouse keeper, Property caretaker, Resort caretaker, Skilled janitor","version":"2022","source_id":709,"level":4,"normalized_name":"building caretakers"},{"code":"5161","parent_code":"516","title":"ASTROLOGERS, FORTUNE-TELLERS AND RELATED WORKERS","description":"Astrologers, fortune-tellers and related workers recount past and predict future events in persons’ lives by practicing astrology, on the basis of characteristics of the clients’ palms, samples of playing cards drawn or other techniques.\nTheir tasks include:a) casting horoscopes of individuals at birth or later to recount past and forecast future events and conditions of their lives; b) interpreting characteristics of clients’ palms, samples of playing cards, position of tea leaves or coffee remnants in a cup, shapes and patterns of bones of dead animals, etc.; c) forecasting future events on the basis of these interpretations; d) determining auspicious times for various human activities such as inaugurations, marriages, journeys and religious and other ceremonies; e) giving warnings and advice on possible courses of action; and f) advising individuals on precautions to be taken to avoid evil influences.\nExamples of the occupations classified here: Astrologer, Feng shui master, Fortune teller, Numerologist, Palmist, Paranormal expert, Psychic reader, Tarot reader\nSome related occupations classified elsewhere: Faith healer - 3413, Village healer - 3230, Witch doctor - 3230","version":"2022","source_id":710,"level":4,"normalized_name":"astrologers fortune-tellers and related workers"},{"code":"5162","parent_code":"516","title":"COMPANIONS AND VALETS","description":"Companions and valets provide companionship and attend to various needs of the employer.\nTheir tasks include: a) providing companionship to employer by accompanying him/her to various places, reading, conversing and participating in activities such as sports; b) assisting in entertaining visitors in employer's home; and c) keeping wardrobe and personal effects of the employer in good order.\nExamples of the occupations classified here: Chaperon, Companion, Personal maid, Resident care companion, Valet\nSome related occupations classified elsewhere: Butler - 5152, Dancing partner - 5169, Social escort - 5169","version":"2022","source_id":711,"level":4,"normalized_name":"companions and valets"},{"code":"5163","parent_code":"516","title":"UNDERTAKERS AND EMBALMERS","description":"Undertakers and embalmers perform various tasks in the disposal of dead human bodies.\nTheir tasks include: a) making arrangements for, and conducting, funerals, cremations and burials; b) embalming human bodies to retard or arrest the process of decay; c) conforming to health and sanitation and ensuring that legal requirements concerning embalming are met; d) incising and closing incisions on various parts of the body and reshaping or reconstructing disfigured or maimed bodies when necessary; e) dressing bodies and placing them in caskets; and f) conducting interviews to arrange for preparation of obituary notices, to assist with the selection of caskets or urns, and to determine the location and time of burials or cremations.\nExamples of the occupations classified here: Cremator, Funeral undertaker, Grave digger, Sepulturero","version":"2022","source_id":712,"level":4,"normalized_name":"undertakers and embalmers"},{"code":"5164","parent_code":"516","title":"PET GROOMERS AND ANIMAL CARE WORKERS","description":"Pet groomers and animal care workers feed, handle, train and groom animals; and assist veterinarians, animal health technologists and technicians in veterinary facilities, animal shelters, breeding and boarding kennels, zoos, laboratories, retail pet shops, riding schools, dog training schools, pet grooming and similar establishments.\nTheir tasks include: a) bathing and feeding animals; b) leading or carrying animals to treatment room and holding them during treatment; c) cleaning and sterilizing veterinary surgical instruments; d) labelling drugs, chemicals and other pharmaceutical preparations and replenishing stock; e) sterilizing bottles, beakers and other equipment; f) cleaning, organizing, and disinfecting animal quarters such as pens, stables, cages, and yards, and animal equipment such as saddles and bridles; g) collecting and recording animal information such as weight, size, physical condition and treatments received, medications given, and food intake; h) training animals to develop and maintain desired animal behaviors for competition, entertainment, obedience, security, riding and other activities; and i) grooming animals by performing tasks such as washing, brushing, clipping, and trimming coats, cutting nails and cleaning ears.\nExamples of the occupations classified here: Animal attendant, Animal keeper, Animal trainer, Dog breeder, Dog trainer, Horse breaker, Veterinary aide, Zookeeper","version":"2022","source_id":713,"level":4,"normalized_name":"pet groomers and animal care workers"},{"code":"5165","parent_code":"516","title":"DRIVING INSTRUCTORS","description":"Driving instructors teach people how to drive motor vehicles.\nTheir tasks include: a) instructing students under actual driving conditions; and explaining and demonstrating the operation of brakes, clutch, gear selection, automatic transmission, signals and lights; b) teaching road traffic regulations; c) teaching road craft and road safety; d) advising students when they are ready to undergo driving examination; e) advising on and teaching advanced driving techniques required for emergency situations; and f) illustrating and explaining handling and mechanical operation of motor vehicles and driving techniques using blackboard diagrams and audio-visual aids.\nExamples of the occupations classified here: Driving instructor, Motorcycle driving instructor\nRelated occupation classified elsewhere: Flying instructor - 3153","version":"2022","source_id":714,"level":4,"normalized_name":"driving instructors"},{"code":"5169","parent_code":"516","title":"PERSONAL SERVICES WORKERS NOT ELSEWHERE CLASSIFIED","description":"This Unit Group covers personal services workers not elsewhere classified in Sub-Major Group 51. Personal Services Workers. For instance, those who provide services and companionship as dancing partners, social escorts, and night club hostesses or hosts are classified here.\nExamples of the occupations classified here: Club hostess, Dancing partner, Escort, Hostess, Social escort, Usher, Usherette\nRelated occupation classified elsewhere: Companion - 5162","version":"2022","source_id":715,"level":4,"normalized_name":"personal services workers not elsewhere classified"},{"code":"5211","parent_code":"521","title":"STALL AND MARKET SALESPERSONS","description":"Stall and market salespersons sell various goods from stalls on open-air or covered markets or from stalls in streets or other open spaces.\nTheir tasks include: a) obtaining permission to set up a stand at a particular place in streets, markets or other open spaces; b) determining product mix, stock and price levels for goods to be sold; c) buying or contracting a regular supply of goods to be sold from wholesale suppliers or directly from producers; d) erecting and dismantling stalls and stands; and transporting, storing, loading and unloading goods for sale; e) demonstrating and selling goods and accepting payment; f) stacking and displaying goods for sale; and wrapping and packing goods sold; and g) keeping accounts and maintaining a record of stock levels.\nExamples of the occupations classified here: Kiosk salesperson, Market salesperson, Market stallholder, Market vendor, Stall salesperson, Street stall sales assistant, Street stall salesperson\nSome related occupations classified elsewhere: Food service counter attendant - 5246, Shop sales assistant - 5223, Shopkeeper - 5221, Street food vendor - 5212, Street vendor (excluding food) - 9520","version":"2022","source_id":716,"level":4,"normalized_name":"stall and market salespersons"},{"code":"5212","parent_code":"521","title":"STREET FOOD SALESPERSONS","description":"Street food salespersons prepare and sell, or sell previously prepared, hot or cold food and beverages ready for immediate consumption in streets and public places such as stations, cinemas, or theaters.\nTheir tasks include: a) obtaining permission or a license, where required, to sell food and drinks on the street or in a public place; b) obtaining food and drinks for sale; c) preparing, either beforehand or on the spot, food and drinks for sale; d) loading and unloading, pushing, pedaling or carrying hand-cart, truck, tray or basket to bring food and drinks to the desired place in the streets, or to public places such as stations or cinemas; and e) displaying and selling food and drinks and accepting payment.\nExamples of the occupations classified here: Food hawker, Street food vendor\nSome related occupations classified elsewhere: Cook - 5120, Fast food preparer - 9411, Food service counter attendant - 5246, Street vendor (excluding food) - 9520","version":"2022","source_id":717,"level":4,"normalized_name":"street food salespersons"},{"code":"5221","parent_code":"522","title":"SHOPKEEPERS","description":"Shopkeepers operate small retail shops either independently or with support from a small number of others.\nTheir tasks include: a) determining product mix, stock and price levels for goods to be sold; b) purchasing and ordering goods for sale from markets, wholesalers and other suppliers; c) budgeting and maintaining records of stock levels and financial transactions; d) determining prices and displaying goods for sale; e) selling goods to customers and advising them on product use; f) examining returned goods and deciding on appropriate action; and g) taking inventory of goods in stock.\nExamples of the occupations classified here: Grocer, Newsagent, Shopkeeper, Store keeper\nSome related occupations classified elsewhere: Market stall holder - 5211, Shop manager - 1420","version":"2022","source_id":718,"level":4,"normalized_name":"shopkeepers"},{"code":"5222","parent_code":"522","title":"SHOP SUPERVISORS","description":"Shop supervisors supervise and coordinate the activities of shop sales assistants, checkout operators and other workers in retail and wholesale shops such as supermarkets and department stores.\nTheir tasks include: a) planning and preparing work schedules and assigning staff to specific duties; b) instructing staff on sales procedures, including how to handle difficult or complex cases; c) ensuring that customers receive prompt service; d) participating in and providing advice to managers on interviewing, hiring, training, evaluating, promoting and dismissing staff, and resolving staff grievances; e) examining returned goods and deciding on appropriate action; f) taking inventory of goods for sale and ordering new stock; g) ensuring that goods and services are correctly priced and displayed; and h) ensuring that safety procedures are enforced.\nExamples of the occupations classified here: Checkout supervisor, Shop supervisor, Store supervisor, Supermarket supervisor\nSome related occupations classified elsewhere: Shop managers - 1420, Shopkeepers - 5221, Street stall salesperson - 5211","version":"2022","source_id":719,"level":4,"normalized_name":"shop supervisors"},{"code":"5223","parent_code":"522","title":"SHOP SALES ASSISTANTS","description":"Shop sales assistants sell a range of goods and services directly to the public or on behalf of retail and wholesale establishments, and explain the functions and qualities of these goods and services.\nTheir tasks include: a) determining customer requirements and advising on product range, price, delivery, warranties and product use and care; b) demonstrating and explaining to customers the establishment's goods and services; c) selling goods and services; accepting payment by a variety of payment methods; preparing sales invoices; and recording sales using cash registers; d) assisting with the ongoing management of stock such as product inventories and participating in stock takes; and e) stacking and displaying goods for sale, and wrapping and packing goods sold.\nExamples of the occupations classified here: Retail establishment salesperson, Sales clerk, Shop assistant, Store sales clerk, Wholesale establishment salesperson\nSome related occupations classified elsewhere: Checkout operator - 5230, Food service counter attendant - 5246, Kiosk salesperson - 5211, Market salesperson - 5211, Shop manager - 1420, Shopkeeper - 5221, Street food vendor - 5212, Street stall salesperson - 5211","version":"2022","source_id":720,"level":4,"normalized_name":"shop sales assistants"},{"code":"5230","parent_code":"523","title":"CASHIERS AND TICKET CLERKS","description":"Cashiers and ticket clerks operate cash registers, optical price scanners, computers or other equipment to record and accept payment for the purchase of goods, services and admissions in settings such as stores, restaurants and ticket offices.\nTheir tasks include: a) receiving and verifying payment by cash, check, credit card or automatic debit in stores, ticket offices, or similar establishments; b) giving change and issuing receipts; c) issuing tickets for attendance at sporting and cultural events; d) counting and recording money received or paid out and balancing against cash register sales records; e) receiving incoming cash, checking it against sales slips and other documents, and preparing it for deposit at bank; f) operating cash register to calculate total to be paid from or to clients; g) scanning, weighing and recording prices of goods; and h) wrapping and placing merchandise in bags.\nExamples of the occupations classified here: Cash clerk, Cash register clerk, Cashier, Checkout operator, Service station cashier, Store cashier, Entertainment and sporting event ticket issuing clerk, Toll collector\nSome related occupations classified elsewhere: Checkout supervisor - 5222, Service station attendant - 5245, Shop sales assistant - 5223, Travel ticket issuing clerk - 4221","version":"2022","source_id":721,"level":4,"normalized_name":"cashiers and ticket clerks"},{"code":"5241","parent_code":"524","title":"FASHION AND OTHER MODELS","description":"Fashion and other models wear and display clothing and accessories and pose for photographs, film and video, advertising, still photography or for artistic creation.\nTheir tasks include: a) dressing in sample apparel of new or current styles or of type wanted by customer; b) walking, turning and posing to demonstrate style and characteristics of garments, fashion accessories and other merchandise to best advantage; c) posing as subject for sculpture, painting and other types of visual art; d) posing for still photography for magazines and other advertising media; and e) posing for television, video and cinema commercials and other productions.\nExamples of the occupations classified here: Advertising model, Artist's model, Fashion model\nRelated occupation classified elsewhere: Actor/Actress - 2655","version":"2022","source_id":722,"level":4,"normalized_name":"fashion and other models"},{"code":"5242","parent_code":"524","title":"SALES DEMONSTRATORS","description":"Sales demonstrators demonstrate goods at commercial premises, exhibitions and private homes.\nTheir tasks include: a) setting up displays and demonstrating articles for sale to inform customers about their characteristics and mode of use, as well as to stimulate buying interest; b) answering questions and offering advice on the use of goods; c) selling goods or directing customers to sales staff; d) taking orders and making arrangements for payment, delivery and collection of goods; and e) offering sample goods and distributing catalogues and advertising material.\nExamples of the occupations classified here: Demonstrator, Product demonstrator, Promodizer, Sales merchandiser\nSome related occupations classified elsewhere: Door-to-door salesperson - 5243, Market salesperson - 5211, Street stall salesperson - 5211","version":"2022","source_id":723,"level":4,"normalized_name":"sales demonstrators"},{"code":"5243","parent_code":"524","title":"DOOR-TO-DOOR SALESPERSONS","description":"Door-to-door salespersons sell goods and services and solicit business for an establishment, by approaching or visiting potential customers, usually residents in private homes, by going from door to door.\nTheir tasks include: a) giving details of various goods or services and of terms of sale by visiting clients and potential clients door-to-door; b) demonstrating or describing goods or services on offer; c) recording orders and transactions and placing orders received with suppliers; d) preparing invoices and sales contracts and accepting payment; e) distributing letters, information sheets and other documents to clients; f) compiling lists of prospective clients and calling on them to obtain new business; and g) travelling between sales areas and clients and transporting samples or goods for sale.\nExamples of the occupations classified here: Door-to-door sales representative, Party plan salesperson\nSome related occupations classified elsewhere: Commercial sales representative - 3322, Street vendor - 9520","version":"2022","source_id":724,"level":4,"normalized_name":"door-to-door salespersons"},{"code":"5244","parent_code":"524","title":"CONTACT CENTER SALESPERSONS","description":"Contact center salespersons contact existing and prospective customers, using the telephone or other electronic communications media, to promote goods and services, obtain sales and arrange sales visits. They may work from a customer contact center or from non-centralized premises.\nTheir tasks include: a) promoting goods and services by telephone or electronic mail, following scripts and working form lists of contacts; b) creating interest in goods and services, and seeking a sale or agreement to see sales representatives; c) arranging processing and dispatch of goods and services, information kits and brochures to customers; d) arranging appointments for sales representatives; e) recording notes for follow up action and updating marketing databases to reflect changes to the status of each customer; f) reporting competitor activities and issues raised by contacts for attention by managers; g) maintaining statistics of calls made and successes achieved; and h) submitting periodic reports on telemarketing activities and results.\nExamples of the occupations classified here: Call center salesperson, Customer contact center salesperson, Sales and marketing call center agent, Telemarketer, Telemarketing agent, Telemarketing sales representative, Telemarketing salesperson, Telephone salesperson \nSome related occupations classified elsewhere: Contact center information clerk - 4222, Customer service representative - 4222","version":"2022","source_id":725,"level":4,"normalized_name":"contact center salespersons"},{"code":"5245","parent_code":"524","title":"SERVICE STATION ATTENDANTS","description":"Service station attendants sell fuel, lubricants and other automotive products; and provide services such as fueling, cleaning, lubricating; and performing minor repairs to motor vehicles.\nTheir tasks include: a) filling fuel tanks and containers to level specified by customer; b) checking and replenishing air pressure in vehicle tires, and oil and other vehicle fluid levels; c) washing vehicle windscreens and windows; d) performing minor repair work to vehicles such as replacing tires, light bulbs and windscreen wiper blades; e) maintaining and operating automatic car wash facilities; f) collecting payments from customers for purchases; g) cleaning petrol pumps and surrounding driveway, shop and facilities; and h) undertaking stock control; and preparing reports on fuel, oil, accessories and other items sold.\nExamples of the occupations classified here: Electric vehicle (EV) charging service attendant, Gas station attendant, Marina attendant, Service station attendant\nSome related occupations classified elsewhere: Food service counter assistant - 5246, Service station cashier - 5230, Shop sales assistant - 5223","version":"2022","source_id":726,"level":4,"normalized_name":"service station attendants"},{"code":"5246","parent_code":"524","title":"FOOD SERVICE COUNTER ATTENDANTS","description":"Food service counter attendants serve customers at food counters and finish preparation of simple food items in restaurants, cafes, hotels, fastfood outlets, cafeterias, hospitals and other settings. \nTheir tasks include: preparing simple food items and reheating prepared meals; e) portioning and wrapping food or placing it directly on plates for service to patrons; f) packaging take-away food; g) stocking refrigerators, salad and buffet bars and keeping records of the quantities of food used; and h) receiving payment for food items purchased.\nExamples of the occupations classified here: Cafeteria counter attendant, Food counter attendant, Food service assistant, Salad bar attendant\nSome related occupations classified elsewhere: Bartender - 5132, Cook - 5120, Fast food preparer - 9411, Kiosk salesperson - 5211, Market salesperson - 5211, Street stall salesperson - 5211, Waiter - 5131","version":"2022","source_id":727,"level":4,"normalized_name":"food service counter attendants"},{"code":"5247","parent_code":"524","title":"ONLINE-SELLING SALESPERSONS","description":"Online-selling salespersons sell goods and services via internet. They fill orders and document for shipping to customers. They work for companies that typically sell their products online.\nTheir tasks include: a) filling customer orders by packaging sold items and documentation for shipping to customers; b) building relationship with clients or customers in order to convince them to buy the products; c) purchasing and ordering goods for sale from markets, wholesalers and other suppliers; d) budgeting and maintaining records of stock levels and financial transactions; e) composing description of products, determining their prices and shipping costs; f) advertising products on different social media platforms to attract customers; g) examining returned goods and deciding on appropriate action; and h) taking inventory of goods in stock.\nExamples of the occupations included here: Online seller, Online seller assistant, Online store merchant, Online store worker\nSome related occupations classified elsewhere: Shop sales assistant - 5223, Shop supervisor - 5222, Shopkeepers - 5221","version":"2022","source_id":728,"level":4,"normalized_name":"online-selling salespersons"},{"code":"5249","parent_code":"524","title":"SALES WORKERS NOT ELSEWHERE CLASSIFIED","description":"This Unit Group includes sales workers not classified elsewhere in Sub-Major Group 52. Sales Workers.\nExamples of the occupations classified here: Rental salesperson","version":"2022","source_id":729,"level":4,"normalized_name":"sales workers not elsewhere classified"},{"code":"5311","parent_code":"531","title":"CHILD CARE WORKERS","description":"Child care workers provide care and supervision for children in residential homes and in before-school, after-school, vacation and day care centers.\nTheir tasks include: a) assisting children to wash, dress and feed themselves; b) taking children to and from school or outdoors for recreation; c) playing games with children, or entertaining them by reading or storytelling; d) assisting in the preparation of materials and equipment for children's education and recreational activities; e) managing children's behavior and guiding their social development; f) disciplining children and recommending or initiating other measures to control behavior, such as caring for own clothing and picking up toys and books; g) observing and monitoring children's play activities; and h) keeping records on individual children, including daily observations and information about activities, meals served, and medications administered.\nExamples of the occupations classified here: Babysitter, Child care attendant, Child care provider, Child care staff, Child care worker, Creche ayah, Family day care worker, Nanny\nRelated occupation classified elsewhere: Early childhood educator - 2342","version":"2022","source_id":730,"level":4,"normalized_name":"child care workers"},{"code":"5312","parent_code":"531","title":"TEACHERS' AIDES","description":"Teachers' aides perform non-teaching duties to assist teaching staff, and provide care and supervision for children in schools and pre-schools. \nTheir tasks include: a) demonstrating, supervising and participating in activities that enhance the physical, social, emotional and intellectual development of children in schools and preschools; b) preparing indoor and outdoor areas for learning and recreational activities; c) assisting children with intellectual, physical, behavioral and other learning difficulties with their studies; d) assisting children individually to learn social skills; e) assisting with preparing teaching materials, and copying and collating written and printed material; f) operating audio-visual equipment, computers and other teaching aides; and g) distributing and collecting lesson material.\nExamples of the occupations classified here: Pre-school assistant, Teacher's assistant","version":"2022","source_id":731,"level":4,"normalized_name":"teachers aides"},{"code":"5321","parent_code":"532","title":"HEALTH CARE ASSISTANTS","description":"Health care assistants provide direct personal care and assistance with activities of daily living to patients and residents in a variety of health care settings such as hospitals, clinics, and residential nursing care facilities. They generally work in implementation of established care plans and practices, and under the direct supervision of medical, nursing or other health professionals or associate professionals.\nTheir tasks include: a) providing care, support and treatment to patients and residents of medical, rehabilitative and residential care facilities as per treatment plans established by medical, nursing and other health professionals; b) assisting patients with personal and therapeutic care needs such as personal hygiene, feeding, dressing, physical mobility and exercise, communication; taking oral medications; and changing dressings; c) positioning, lifting and turning patients and transporting them in wheelchairs or on movable beds; maintaining patients' environmental hygiene standards, such as cleaning patient rooms and changing bed-linen; d) providing massage and other non-pharmacological pain relief measures, such as during pregnancy and labor; and e) observing patients’ condition, responses and behavior and reporting changes to a health professional.\nExamples of the occupations classified here: Barangay health aide, Clinic or hospital birth assistant, Clinic or hospital nursing aide, Hospital attendant, Hospital nursing aide, Institution-based caregiver, Nursing attendant, Patient care assistant, Psychiatric aide\nSome related occupations classified elsewhere: Ambulance worker - 3258, Associate professional nurse - 3221, Home nursing aide - 5322, Professional nurse - 2221","version":"2022","source_id":732,"level":4,"normalized_name":"health care assistants"},{"code":"5322","parent_code":"532","title":"HOME-BASED PERSONAL CARE WORKERS","description":"Home-based personal care workers provide routine personal care and assistance with activities of daily living to persons who are in need of such care due to effects of ageing, illness, injury, or other physical or mental condition in private homes and other independent residential settings.\nTheir tasks include: a) assisting clients with personal and therapeutic care needs such as personal hygiene, feeding, dressing, physical mobility and exercise, communication, taking oral medications and changing dressings, usually as per care plans established by a health professional; b) maintaining records of client care, changes in condition and responses to care and treatment, and reporting concerns or providing referrals to a health or social services professional; c) positioning and lifting clients with physical mobility challenges, and helping transport them in wheelchairs and motor vehicles; d) providing clients and families with emotional support and information and advice on topics such as nutrition, hygiene, exercise, caring for infants, or adapting to disability or illness; e) maintaining clients' environmental hygiene standards, such as changing bed linen, washing clothes and dishes, and cleaning living quarters; f) providing psychological support to clients such as through conversation or reading aloud; g) planning, purchasing, preparing, or serving meals to meet nutritional requirements and prescribed diet; h) providing support to parents and care for newborns during the post-partum period; and i) scheduling and accompanying clients for appointments with medical doctors and other health professionals; or performing other errands.\nExamples of the occupations classified here: Home birth assistant, Home care aide, Home nursing aide, Home-based caregiver, Personal care provider\nSome related occupations classified elsewhere: Associate professional nurse - 3221, Associate professional social worker - 3412, Clinic or hospital nursing aide - 5321, Professional nurse - 2221, Professional social worker - 2635","version":"2022","source_id":733,"level":4,"normalized_name":"home-based personal care workers"},{"code":"5329","parent_code":"532","title":"PERSONAL CARE WORKERS IN HEALTH SERVICES NOT ELSEWHERE CLASSIFIED","description":"This Unit Group covers personal care workers in health services not elsewhere classified in Minor Group 532. Personal Care Workers in Health Services. For instance the group includes occupations such as dental aid, sterilization aid, hospital orderly, medical imaging assistant, and pharmacy aide.\nTheir tasks include: a) cleaning and sterilizing surgical, dental and pharmaceutical instruments, bottles, beakers and other equipment; b) labelling drugs, chemicals and other pharmaceutical preparations and replenishing stock on shelves; c) lifting, turning, and moving patients and transporting them in wheelchairs or on moveable beds; d) preparing patients for examination or treatment; e) setting up instrument trays, preparing materials, and assisting dentists or radiographers during procedures; and f) exposing diagnostic X-rays.\nExamples of the occupations classified here: Dental aide, First aid assistant, First aid attendant, Hospital orderly, Medical imaging assistant, Pharmacy aide, Phlebotomist, Sterilization aide\nSome related occupations classified elsewhere: Dental assistant - 3251, Dental technician - 3214, Pharmaceutical assistant - 3213","version":"2022","source_id":734,"level":4,"normalized_name":"personal care workers in health services not elsewhere classified"},{"code":"5411","parent_code":"541","title":"FIREFIGHTERS","description":"Firefighters prevent, fight and extinguish fires and assist in other emergencies; protect life and property; and conduct rescue efforts.\nTheir tasks include: a) responding to fire alarms and other calls for assistance, such as automobile and industrial accidents, bomb threats and other emergencies; b) controlling and extinguishing fires using manual and power equipment and firefighting chemicals; c) fighting special types of fires and using special equipment in industrial establishments; d) rescuing people from burning buildings and accident sites and those trapped in dangerous situations; e) preventing or limiting the spread of dangerous substances in case of fires or accidents; and f) informing the public about fire prevention.\nExamples of the occupations classified here: Aircraft accidents firefighter, Firefighter, Fireman, Forest firefighter\nSome related occupations classified elsewhere: Fire inspector - 3112, Fire investigator - 3119, Fire prevention specialist - 3112","version":"2022","source_id":735,"level":4,"normalized_name":"firefighters"},{"code":"5412","parent_code":"541","title":"POLICE OFFICERS","description":"Police officers maintain law and order; patrolling public areas; enforcing laws and regulations; and arresting suspected offenders.\nTheir tasks include: a) patrolling a specific area to maintain public order; respond to emergencies; protect people and property; and enforce laws and regulations; b) identifying, pursuing and arresting suspects and perpetrators of criminal acts; c) directing traffic and assuming authority in the event of accidents; and d) providing emergency assistance to victims of accidents, crimes and natural disasters.\nExamples of the occupations classified here: Constable, Police patrol officer, Police patrolman, Policeman\nSome related occupations classified elsewhere: Police chief constable - 1112, Police commissioner - 1112, Police detective - 3355, Police inspector - 3355, Police inspector-general - 1112","version":"2022","source_id":736,"level":4,"normalized_name":"police officers"},{"code":"5413","parent_code":"541","title":"PRISON GUARDS","description":"Prison guards watch over and maintain order among inmates of prisons, reformatories or penitentiaries.\nTheir tasks include: a) searching arriving prisoners, putting their valuables in safekeeping, escorting prisoners to cells and locking them in; b) making periodic inspection tours of cells; and inspecting and maintaining the security of locks, windows, doors and gates; c) supervising prisoners at work, meals, or during recreation periods; d) observing the conduct and behavior of prisoners to prevent disturbances and escapes; e) patrolling prison areas to prevent escape; f) assisting with the implementation of rehabilitation programs; and g) escorting prisoners in transit and during temporary leaves.\nExamples of the occupations classified here: Correctional guard, Jail guard, Prison guard, Prison warden","version":"2022","source_id":737,"level":4,"normalized_name":"prison guards"},{"code":"5414","parent_code":"541","title":"SECURITY GUARDS","description":"Security guards patrol or monitor premises to guard property against theft and vandalism. They control access to establishments and maintain order; and enforce regulations at public events and within establishments.\nTheir tasks include: b) controlling access to establishments; monitoring and authorizing the entrance or departure of employees and visitors; checking identification; and issuing security passes; c) circulating among visitors, patrons, or employees to preserve order; protect property from theft or vandalism; and enforce the regulations of the establishment; d) responding to alarms; investigating disturbances; and contacting superiors, police or firefighters as appropriate; e) performing security checks of passengers and luggage at airports; and f) picking up and ensuring the safe delivery of cash and valuables to banks, automated teller machines and retail establishments.\nExamples of the occupations classified here: Aviation security guard, Bodyguard, Bouncer, Civilian guard, Customs gatekeeper, Doorkeeper, Gatekeeper, Guard patrol, Harbor patrol, Museum guard, Roving guard, Security agent, Security guard, Security officer, Security patrolman, Surveillance officer, Watchman\nSome related occupations classified elsewhere: Beach patrolman/patrolwoman - 5419, Lifeguard - 5419, Private detective - 3411, Private inquiry agent - 3411, Private investigator - 3411","version":"2022","source_id":738,"level":4,"normalized_name":"security guards"},{"code":"5419","parent_code":"541","title":"PROTECTIVE SERVICES WORKERS NOT ELSEWHERE CLASSIFIED","description":"This Unit Group covers protective services workers not elsewhere classified in Minor Group 541. Protective Services Workers. For instance, the group includes lifeguards, crossing guards and animal control officers.\nTheir tasks include: a) patrolling beaches and swimming pools to prevent accidents; and to rescue bathers from drowning; b) monitoring traffic flow to locate safe gaps through which pedestrians can cross streets; c) responding to citizen complaints concerning stray domestic animals, livestock and wildlife; issuing warnings and citations to owners; and impounding lost, homeless and dangerous animals; d) patrolling an assigned area to enforce parking regulations; and e) directing traffic.\nExamples of the occupations classified here: Animal control officer, Beach patrolman/patrolwoman, Coastguard, Crossing guard, Forest protection officer, Game warden, Lifeguard, Rescue service personnel, Traffic aide, Traffic enforcer, Traffic warden\nSome related occupations classified elsewhere: Doorkeeper - 5414, Museum guard - 5414, Watchman/Watchwoman - 5414","version":"2022","source_id":739,"level":4,"normalized_name":"protective services workers not elsewhere classified"},{"code":"6111","parent_code":"611","title":"RICE FARMERS","description":"Workers in this unit group plan and carry out the necessary operations to grow and harvest rice for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets. They may grow other secondary crops.\nTheir tasks include: a) determining the kinds and amounts of rice to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements, buildings, working animals, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting, cultivating and harvesting rice; e) storing and carrying out some basic processing of rice; f) tending working animals and maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.\nExamples of the occupations classified here: Irrigated, rice farmer, Lowland, rice farmer, Rainfed, rice farmer, Upland, rice farmer\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Crop farm laborer - 9211","version":"2022","source_id":740,"level":4,"normalized_name":"rice farmers"},{"code":"6112","parent_code":"611","title":"CORN FARMERS","description":"Workers in this unit group plan and carry out the necessary operations to grow and harvest corn for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets. They may grow other secondary crops.\nTheir tasks include: a) determining the kinds and amounts of corn to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements, buildings, working animals, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting cultivating and harvesting corn; e) storing and carrying out some basic processing of corn; f) tending working animals and maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.\nExample of occupation classified here: Corn farmer\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Crop farm laborer - 9211","version":"2022","source_id":741,"level":4,"normalized_name":"corn farmers"},{"code":"6113","parent_code":"611","title":"VEGETABLE, LEGUMES AND ROOT CROPS FARMERS","description":"Workers in this unit group plan and carry out the necessary operations to grow and harvest vegetable, field legumes and root crops for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of vegetables, field legumes and root crops to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements buildings, working animals, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting, cultivating and harvesting vegetables, legumes and fiber crops; e) storing and carrying out some basic processing of vegetables, legumes and root crops f) tending working animals and maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.\nExamples of the occupations classified here: Cabbage farmer, Cassava farmer, Eggplant farmer, Gabi farmer, Mongo beans farmer, Peanut farmer, Pechay farmer, Roots vegetable farmer, Soybeans farmer, Sweet potato farmer, Tomato farmer, Ubi farmer, White potato (Irish potato) farmer\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Crop farm laborer - 9211","version":"2022","source_id":742,"level":4,"normalized_name":"vegetable legumes and root crops farmers"},{"code":"6114","parent_code":"611","title":"SUGARCANE FARMERS","description":"Workers in this unit group plan and carry out the necessary operations to grow and harvest sugarcane for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the variety and amounts of sugarcane to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements, buildings, working animals, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting cultivating and harvesting sugarcane; e) storing and carrying out some basic processing of sugarcane; f) tending working animals and maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.\nExample of occupation classified here: Sugarcane farmers\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Crop farm laborer - 9211","version":"2022","source_id":743,"level":4,"normalized_name":"sugarcane farmers"},{"code":"6115","parent_code":"611","title":"COCONUT FARMERS","description":"Workers in this unit group plan and carry out the necessary operations to grow and harvest coconuts for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets. They may grow other secondary crops.\nTheir tasks include: a) determining the kinds and amounts of coconut to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements, buildings, working animals, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting, cultivating and harvesting coconut and other secondary crops; e) storing and carrying out some basic processing of coconut; f) tending working animals and maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.\nExample of occupation classified here: Coconut farmers\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Crop farm laborer - 9211","version":"2022","source_id":744,"level":4,"normalized_name":"coconut farmers"},{"code":"6116","parent_code":"611","title":"OTHER FIELD CROP FARMERS","description":"Workers in this unit group plan and carry out the necessary operations to grow and harvest crops other than rice, corn, sugarcane, vegetables, field legumes, root crops, sugarcane and coconut for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of other crops to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements, buildings, working animals, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting, cultivating and harvesting fiber crops; e) storing and carrying out some basic processing of fiber crops; f) tending working animals and maintaining farm buildings, machinery and equipment; g) delivering or marketing farm products.\nExamples of the occupations classified here: Abaca farmer, Achuete farmer, Black pepper farmer, Cotton farmer, Garlic/onion (and other spices) farmer, Jute farmer, Laurel farmer, Ramie farmer, Sisal farmer, Tobacco farmer\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Crop farm laborer - 9211","version":"2022","source_id":745,"level":4,"normalized_name":"other field crop farmers"},{"code":"6117","parent_code":"611","title":"TREE AND SHRUB CROP GROWERS","description":"Tree and shrub crop growers plan organize and perform farming operations to grow and harvest trees and shrubs, such as fruit trees, tree nuts, coffee and cacao and other tree and shrub crop growers for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) monitoring market activity and conditions, determining types and quantities of crops to be grown, and planning and coordinating production accordingly; b) preparing soil by hand or machine, and spreading fertilizers and manure; c) selecting and sowing seeds, and planting seedlings; d) maintaining crops by cultivating soil, by transplanting, pruning or thinning trees and shrubs, and by setting up and operating irrigation equipment; e) controlling weeds, pests and diseases, by applying herbicides and pesticides; f) tending trees or bushes, collecting sap and harvesting crops; g) inspecting, cleaning, grading, packaging, storing and loading crops for sale or delivery to market; h) tending working animals and maintaining farm buildings, structures, equipment and water supply systems; i) inspecting, cleaning, grading, packaging, storing and loading crops for sale or delivery to market; j) storing and carrying out some processing of produce; k) promoting and marketing products, arranging the sale, purchase and transportation of produce and supplies and maintaining and evaluating records of farm activities and transactions; and l) training and supervising workers in crop production, maintenance duties, and health and safety precautions and hiring and discharging workers and contractors.\nExamples of the occupations classified here: Banana farmer, Cacao farmer, Cashew nut farmer, Castañas farmer, Citrus farmer, Coffee farmer, Fruit farmer, Mango farmer, Pili nut farmer, Pineapple farmer, Rubber tapper, Rubber tree farmer, Tea farmer, Viticulturist\nSome related occupations classified elsewhere: Fruit picker - 9211, Plantation manager - 1311","version":"2022","source_id":746,"level":4,"normalized_name":"tree and shrub crop growers"},{"code":"6118","parent_code":"611","title":"GARDENERS, HORTICULTURAL AND NURSERY GROWERS","description":"Gardeners, horticultural and nursery growers plan organize and perform operations to cultivate and maintain trees, shrubs, flowers and other plants in parks and private gardens, and to produce saplings, bulbs and seeds, or grow vegetables and flowers by intensive cultivation techniques, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) monitoring market activity and conditions determining kinds and amounts of vegetables, horticultural and nursery products to be grown and planning and coordinating production accordingly; b) preparing land by conditioning soil, levelling ground and installing and operating irrigation and drainage systems; c) planting trees, hedges, garden plants, grass; d) pruning and trimming trees, shrubs and hedges, installing plant supports and protection, and rolling, mowing aerating and edging lawns; e) constructing features and facilities within gardens, such as paths or paved areas, walls, rockeries, garden beds ponds and water features, sheds and fences; f) checking the health of plants and trees, identifying and treating weeds, pests and diseases, and applying mulch and fertilizers; g) producing saplings, bulbs and seeds and raising plants from seeds or cuttings; h) harvesting crops inspecting, cleaning, grading, packaging, storing and loading products for sale or delivery to market; i) maintaining buildings, greenhouses and other structures, equipment and water supply systems; j) storing and carrying out some processing of produce; k) promoting and marketing products, arranging the sale, purchase and transportation of produce and supplies and maintaining and evaluating records of activities and transactions; and l) training and supervising workers in production, maintenance duties, and health and safety precautions and hiring and discharging workers and contractors.\nExamples of the occupations classified here: Bamboo shoot grower, Foliage propagator, Horticulturist, Landscape gardener, Market gardener, Mushroom cultivator, Orchid plant grower, Rose grower \nSome related occupations classified elsewhere: Garden laborer - 9214, Horticultural laborer - 9214, Horticultural scientist - 2132","version":"2022","source_id":747,"level":4,"normalized_name":"gardeners horticultural and nursery growers"},{"code":"6119","parent_code":"611","title":"OTHER MARKET GARDENERS AND CROP GROWERS, NOT ELSEWHERE CLASSIFIED","description":"Workers in this unit group plan, organize and perform farming operations to grow and harvest specific combinations of field crops, field vegetables, tree and shrub crops, and garden, horticultural and nursery products, for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of plants to be grown; b) purchasing seeds, fertilizer and other supplies; c) renting or investing in land and land improvements, buildings, equipment and machinery; d) performing farm operations such as land preparation, sowing, planting cultivating plants and trees and harvesting their products; e) storing and carrying out some basic processing of other plants; f) maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.","version":"2022","source_id":748,"level":4,"normalized_name":"other market gardeners and crop growers not elsewhere classified"},{"code":"6121","parent_code":"612","title":"LIVESTOCK FARMER","description":"Livestock producers plan, organize and perform farming operations to breed and raise domesticated animals (excluding poultry), such as cattle, sheep, pigs, goats, horses and camels, for the production of meat, skins, and wool or for use as working, sporting or recreational animals for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) monitoring market activity and conditions, determining kinds and amounts of stock to produce, planning and coordinating production accordingly; b) cultivating pastures and providing and monitoring fodder and water supplies to maintain appropriate nutritional levels and condition of livestock; c) monitoring and examining animals to detect illness, injury, or disease, and to check physical condition such as rate of weight gain; d) grooming , marking, clipping, trimming, drenching and/or castrating animals and shearing coats to collect hair or wool; e) herding livestock to pastures for grazing or to scales, sheds, vehicles, or other enclosures; f) mixing feed, additives, and medicines in prescribed portions and distributing or hand-feeding to animals for consumption; g) performing duties related to livestock reproduction, such as breeding, artificial insemination, and helping with animal births; h) maintaining and cleaning farm buildings, machinery, equipment, and structures; i) slaughtering and skinning animals and preparing them for market; j) storing and carrying out some processing of animal produce; k) promoting and marketing products, arranging the sale, purchase and transportation of livestock, produce and supplies and maintaining and evaluating records of farm activities and transactions; and l) training and supervising workers in animal care procedures, maintenance duties, and health and safety precautions and hiring and discharging workers and contractors.\nExamples of the occupations classified here: Carabao farmer, Cattle farmer, Cattle herder, Drover, Goat farmer, Horse breeder, Livestock stockman\nSome related occupations classified elsewhere: Agricultural production manager - 1311, Ranch manager - 1311","version":"2022","source_id":749,"level":4,"normalized_name":"livestock farmer"},{"code":"6122","parent_code":"612","title":"DAIRY FARMER","description":"Workers in this unit group plan and carry out the necessary operations on dairy products and deliver or sell these on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts dairy products to be produced; b) renting or investing in grazing land, buildings, equipment and machinery; c) milking animals by hand or using milking machines; d) milking, and preparing dairy products for market; e) storing and carrying out some basic processing of dairy produce; f) maintaining farm buildings, machinery and equipment; and g) delivering or marketing farm products.","version":"2022","source_id":750,"level":4,"normalized_name":"dairy farmer"},{"code":"6123","parent_code":"612","title":"EGGS PRODUCERS","description":"Workers in this unit group plan and carry out the necessary operations for sale or delivery of eggs on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of eggs to be produced; b) hatching of eggs; c) collecting and storing eggs and packaging them for sale or delivery to market.\nExamples of the occupations classified here: Egg collector, Egg hatcher","version":"2022","source_id":751,"level":4,"normalized_name":"eggs producers"},{"code":"6124","parent_code":"612","title":"CHICKEN FARMER","description":"Workers in this unit group plan and carry out the necessary operations to breed, raise and tend chicken for sale or delivery of meat or feathers on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of chicken to be produced; b) purchasing and raising chicks, c) purchasing chicken feeds and other supplies; d) renting or investing in chicken farm buildings, equipment and machinery; e) raising and tending chicken; f) determining sex of chicks and facilitating breeding; g) slaughtering, dressing and packing chicken for shipment; h) storing and carrying out some basic processing of their produce; i) maintaining chicken farm buildings, machinery and equipment; and j) delivering or marketing live chicken and chicken meat products.\nExamples of the occupations classified here: Chicken breeder, Chicken farmer, Chicken meat producer, Poultry tender, chicken","version":"2022","source_id":752,"level":4,"normalized_name":"chicken farmer"},{"code":"6125","parent_code":"612","title":"DUCK RAISERS","description":"Workers in this unit group plan and carry out the necessary operations to breed, raise and tend ducks for sale or delivery of meat or feathers on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of ducks and eggs to be produced; b) purchasing and raising ducklings; c) purchasing duck feeds and other supplies; d) renting or investing in duck farm buildings, equipment and machinery; e) raising and tending ducks; f) determining sex of ducklings and facilitating breeding; g) killing, dressing and packing ducks for shipment; h) storing and carrying out some basic processing of their produce; i) maintaining duck farm buildings, machinery and equipment; and j) delivering or marketing live duck and duck meat products.\nExamples of the occupations classified here: Duck meat producer, Duck breeder, Duck farmer, Poultry tender, duck","version":"2022","source_id":753,"level":4,"normalized_name":"duck raisers"},{"code":"6126","parent_code":"612","title":"POULTRY PRODUCERS","description":"Workers in this unit group plan and carry out the necessary operations to breed, raise and tend poultry other than chicken and ducks for sale or delivery of meat or feathers on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of poultry other than chicken and ducks; b) purchasing and raising other than chicks and ducklings; c) purchasing poultry feeds and other supplies; d) renting or investing in poultry farm buildings, equipment and machinery; e) raising and tending poultry other than chicken and ducks; f) determining sex of other than chicks and ducklings and facilitating breeding; g) slaughtering, dressing and packing poultry other than chicken and ducks for shipment; h) storing and carrying out some basic processing of their produce; i) maintaining poultry farm buildings, machinery and equipment; and j) delivering or marketing poultry farm products other than those of chicken and duck.\nExamples of the occupations classified here: Poultry breeder (other than chicken and duck), Poultry farmer (other than chicken and duck), Poultry tender (other than chicken and duck), Quail farmer, Turkey farmer","version":"2022","source_id":754,"level":4,"normalized_name":"poultry producers"},{"code":"6127","parent_code":"612","title":"HOG RAISING PRODUCERS","description":"Workers in this unit group plan and carry out the necessary operations to breed, raise and tend hogs for meat and deliver or sell these on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) determining the kinds and amounts of hogs to be produced; b) purchasing hogs, producing and purchasing fodder and other supplies; c) renting or investing in hog farm buildings, equipment and machinery; d) breeding, raising and tending hogs; e) slaughtering, skinning and preparing hogs for market; f) storing and carrying out some basic processing of their produce; g) maintaining hog farm buildings, machinery and equipment; and h) delivering or marketing live hog and hog meat products.\nExamples of the occupations classified here: Hog farmer, Hog raiser, Pig farmer\nRelated occupation classified elsewhere: Farm managers and overseers - 1231","version":"2022","source_id":755,"level":4,"normalized_name":"hog raising producers"},{"code":"6128","parent_code":"612","title":"APIARISTS AND SERICULTURISTS","description":"Apiarists and sericulturists plan, organize and perform operations to breed, raise and tend insects such as honey bees, silkworms, and other species to produce honey, beeswax, silk and other products for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) monitoring market activity, planning and coordinating production accordingly, monitoring market activity and conditions, determining kinds and amounts of insect products to produce, planning and coordinating production accordingly; b) purchasing insects and growing or purchasing feed and other supplies; c) breeding, raising and tending insects and collecting their products; d) renting or investing in and maintaining and cleaning buildings, machinery, equipment, and structures; e) storing and carrying out some processing of produce; f) arranging the sale, purchase and transportation of stock, produce and supplies and maintaining and evaluating records of farming activities; and g) training and supervising workers in production procedures, maintenance duties, and health and safety precautions, and hiring and discharging workers and contractors.\nExamples of the occupations classified here: Apiary farmer (apiarist), Beekeeper, Beekeeping farmer, Silkworm farmer (sericulturist)\nRelated occupation classified elsewhere: Wild honey and beeswax gatherer - 6214","version":"2022","source_id":756,"level":4,"normalized_name":"apiarists and sericulturists"},{"code":"6129","parent_code":"612","title":"ANIMAL PRODUCERS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers market-oriented animal producers not classified elsewhere in Minor group 612, Animal producers. For instance, the group includes those engaged in breeding, raising and tending non-domesticated mammals, game and other birds (except poultry), snails, snakes and other reptiles, as well as various insects and animals used for laboratory tests, for sale or delivery on a regular basis to wholesale buyers, marketing organizations, zoos and circuses, or at markets.\nTheir tasks include: a) monitoring market activity and conditions, determining kinds and amounts of products to produce, planning and coordinating production accordingly; b) raising, feeding and tending animals; c) killing and skinning animals, and preparing animals or animal products for market; d) monitoring and examining animals to detect illness, injury, or disease, and to check physical condition such as rate of weight gain; e) performing duties related to animal reproduction, such as breeding, artificial insemination, and helping with animal births; f) renting or investing in and maintaining and cleaning buildings, machinery, equipment, and structures; g) slaughtering and skinning animals and preparing them for market; h) storing and carrying out some processing of produce; i) promoting and marketing products, arranging the sale, purchase and transportation of stock, produce and supplies and maintaining and evaluating records of activities and transactions; and j) training and supervising workers in animal care procedures, maintenance duties, and health and safety precautions.\nExamples of the occupations classified here: Crocodile farmer, Earthworm farmer (vermiculturist), Fur farmer (non-domesticated animals), Game bird breeder, Game fowl raiser, Ostrich farmer, Reptile farmer, Snail breeder\nSome related occupations classified elsewhere: Game warden - 5419, Pet groomer - 5164, Poultry breeder - 6122, Zoo keeper - 5164","version":"2022","source_id":757,"level":4,"normalized_name":"animal producers not elsewhere classified"},{"code":"6130","parent_code":"613","title":"MIXED CROP AND ANIMAL PRODUCERS","description":"Mixed crop and animal producers plan, organize and perform farming operations to grow and harvest field, tree and various other crops, as well as to breed, raise and tend animals and to produce a variety of animal husbandry products, for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) monitoring market activity and conditions, determining kinds and amounts of crops to be grown and animals to be raised, and planning and coordinating production accordingly; b) purchasing seeds, fertilizer, and other supplies; c) performing operations such as land preparation, sowing, planting, cultivating and harvesting crops; d) producing or buying fodder and other food supplies; e) breeding, raising and tending animals; f) killing and skinning animals, and preparing animals or animal products for market; g) renting or investing in and maintaining and cleaning farm buildings, machinery, equipment, and structures; h) storing and carrying out some processing of produce; i) promoting and marketing products, arranging the sale, purchase and transportation of livestock, produce and supplies and maintaining and evaluating records of farm activities and transactions; and j) training and supervising workers in animal care procedures, maintenance duties, and health and safety precautions and hiring and discharging workers and contractors.\nExamples of the occupations classified here: Farmer (mixed farming), Skilled farm worker (mixed farming)\nSome related occupations classified elsewhere: Agricultural production manager – 1311, Mixed farming laborer - 9213, Plantation manager - 1311","version":"2022","source_id":758,"level":4,"normalized_name":"mixed crop and animal producers"},{"code":"6211","parent_code":"621","title":"FOREST TREE PLANTERS","description":"Workers in this unit group plan and manage the necessary operations to cultivate trees for sale or delivery of forest products on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) assessing sites for reforestation, selecting seedlings and planting trees using manual planting tools and establishing and caring for forest stands; b) planting forest seeds or seedlings; and c) maintaining, establishing and caring of forestrial tree farms for timber, for pulp and paper or for environmental use.\nExamples of the occupations classified here: Forest ranger, Watershed forester\nSome related occupations classified elsewhere: Forest protection officer - 5419, Forestry laborer - 9215, Forestry technician - 3143, Silviculturist - 2132","version":"2022","source_id":759,"level":4,"normalized_name":"forest tree planters"},{"code":"6212","parent_code":"621","title":"CONCESSIONAIRES AND LOGGERS","description":"Workers in this minor group plan and manage the necessary operations to log trees for sale or delivery of forest products to wholesale buyers, marketing organizations or at markets at a sustainable basis.\nTheir tasks include: a) marking merchantible trees to be felled and estimating volume of timber; b) marking trees to be cut; c) operating chainsaw and other power saws to thin young forest stands, trim, top and fell trees and saw them into logs; d) scaling and rescaling of felled trees; e) cutting trees into logs; f) cutting and processing logs into timber; g) loading and unloading out timbers, other semi-finished or finished forest products; h) replanting and replacing cut trees; and i) establishing and maintaining processing plants.\nExample of occupations classified here: Log marker, Log scaler, Logger, Logging climber, Lumber grader, Lumberjacks, Rafter, Timber cruiser, Timber inspector, Tree feller, Tree marker\nRelated occupation classified elsewhere: Tree faller operator - 8341","version":"2022","source_id":760,"level":4,"normalized_name":"concessionaires and loggers"},{"code":"6213","parent_code":"621","title":"CHARCOAL MAKERS AND RELATED WORKERS","description":"Workers in this unit group plan and manage the necessary operations to convert wood into charcoal or to obtain rude turpentine from wood using traditional techniques.\nTheir tasks include: a) operating simple kiln to convert wood into charcoal by slow burning process; b) operating simple digester or still to obtain or distill crude wood turpentine; and c) performing other related tasks.\nExamples of the occupations classified here: Charcoal burner, Charcoal maker","version":"2022","source_id":761,"level":4,"normalized_name":"charcoal makers and related workers"},{"code":"6214","parent_code":"621","title":"MINOR FOREST PRODUCT GATHERERS","description":"Workers in this unit group are directly concerned with gathering one or more of a variety of wild or semi-cultivated forest products such as rattan, bamboo, mushrooms, herbs, and other medicinally or commercially valuable plants, reeds ferns and orchids and other wild flowers and plants for domestication.\nTheir tasks include: a) locating and collecting of forest products; b) delivering and marketing products; and c) performing other related tasks.\nExamples of the occupations classified here: Rattan gatherer, Wild honey and beeswax gatherer, Wild mushroom gatherer, Wild orchids gatherer\nSome related occupations classified elsewhere: Beekeeper - 6128, Beekeeping farmer - 6128, Mushroom cultivator - 6118","version":"2022","source_id":762,"level":4,"normalized_name":"minor forest product gatherers"},{"code":"6221","parent_code":"622","title":"MILKFISH AND TILAPIA PRODUCERS","description":"Workers in this unit group breed and raise milkfish and tilapia for sale or delivery on a regular basis to buyers, marketing organizations or at markets.\nTheir tasks include: a) purchasing feeds and other supplies; b) renting or investing in fish farm facilities; c) breeding, raising and cultivating fish; d) harvesting, sorting, cleaning, freezing, icing fish for market; e) constructing and maintaining fish farm facilities; and f) delivering or marketing products.\nExamples of the occupations classified here: Bangus farm producer, Bangus farmer, Tilapia farm producer, Tilapia farmer\nSome related occupations classified elsewhere: Aquaculture laborer - 9216, Aquaculture production manager - 1312","version":"2022","source_id":763,"level":4,"normalized_name":"milkfish and tilapia producers"},{"code":"6222","parent_code":"622","title":"SEAWEEDS PRODUCERS","description":"Workers in this unit group cultivate seaweeds for sale or delivery on a regular basis to buyers, marketing organizations or at markets.\nTheir tasks include: a) purchasing supplies; b) renting or investing in farm facilities; c) cultivating and harvesting seaweeds; d) drying and bailing of seaweeds; e) constructing and maintaining farm facilities; and f) delivering or marketing products.\nExamples of the occupations classified here: Agar-agar producers, Carrageenan producers, Seaweed cultivator\nSome related occupations classified elsewhere: Aquaculture laborer - 9216, Aquaculture production manager - 1312","version":"2022","source_id":764,"level":4,"normalized_name":"seaweeds producers"},{"code":"6223","parent_code":"622","title":"PRAWN PRODUCERS","description":"Workers in this unit group breed and raise prawns and shrimps for sale or delivery on a regular basis to buyers, marketing organizations or at markets.\nTheir tasks include: a) purchasing feeds and other supplies; b) renting or investing in prawn farm facilities; c) breeding, raising and cultivating prawns and shrimps; d) preparing prawns and shrimps for market; e) cleaning, sorting, freezing, or icing prawns and shrimps; f) constructing and maintaining prawn facilities; and g) delivering or marketing products.\nExample of occupation classified here: Prawn farm cultivator\nSome related occupations classified elsewhere: Aquaculture laborer - 9216, Aquaculture production manager - 1312","version":"2022","source_id":765,"level":4,"normalized_name":"prawn producers"},{"code":"6224","parent_code":"622","title":"OYSTERS AND MUSSELS PRODUCERS","description":"Workers in this unit group raise and cultivate oysters and mussels for sale or delivery on a regular basis to buyers, marketing organizations or at markets.\nTheir tasks include: a) purchasing feeds and other supplies; b) renting or investing in farm facilities; c) raising, cultivating and harvesting oysters and mussels; d) preparing oysters and mussels for market; e) cleaning, sorting, freezing or icing oysters and mussels; f) constructing and maintaining farm facilities; and g) delivering or marketing products.\nExamples of the occupations classified here: Mussel cultivator, Mussel farmer, Oyster cultivator, Oyster farmer\nRelated occupation classified elsewhere: Oyster diver - 6229","version":"2022","source_id":766,"level":4,"normalized_name":"oysters and mussels producers"},{"code":"6225","parent_code":"622","title":"OTHER AQUA PRODUCTS PRODUCERS","description":"Workers in this unit group breed and raise other aqua products other than milkfish, tilapia, prawn and shrimps, oysters and mussels, and seaweeds for sale or delivery on a regular basis to buyers, marketing organizations or at markets.\nTheir tasks include: a) purchasing feeds and other supplies; b) renting or investing fish farm/pond facilities; c) breeding, raising and cultivating aqua products other than milkfish, tilapia, prawn and shrimps, oysters and mussels, and seaweeds and preparing them for market; d) cleaning, sorting, freezing, icing or salting other aqua products; e) constructing and maintaining fish farm/pond facilities; and f) delivering or marketing products.\nExamples of the occupations classified here: Algae cultivator, Aquarium fish farm operator (goldfish, corals, etc.), Fish hatchery/nursery farm operator, Frog raiser, Pearl cultivator\nRelated occupation classified elsewhere: Fishery laborer - 9216","version":"2022","source_id":767,"level":4,"normalized_name":"other aqua products producers"},{"code":"6226","parent_code":"622","title":"INLAND AND COASTAL WATERS FISHERY WORKERS","description":"Inland and coastal waters fishery workers, alone or as members of fishing-vessel crews, catch fish or gather other forms of aquatic life in inland or coastal waters, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) preparing and repairing nets and other fishing gear and equipment; b) selecting area for fishing, plotting courses and computing navigational positions using compass, charts and other aids; c) operating fishing vessels to, from and at fishing grounds; d) baiting, setting, operating and hauling in fishing gear by hand or using hoisting equipment; e) gathering various forms of aquatic life from shores and shallow waters; f) maintaining engine fishing gear and other on-board equipment; g) keeping records of transactions, fishing activities, weather and sea conditions and estimating costs and budgets; h) sorting, and storing catch in holds with salt and ice; i) removing catches from fishing equipment, measuring them to ensure compliance with legal size and returning undesirable or illegal catches to the water. j) direct fishing operations, and supervising fishing crew members; and\nExamples of the occupations classified here: Coastal fishery skipper, Coastal water fishery workers, Coastal waters fisher, Coastal waters fishing vessel skipper, Inland water fishery workers, Inland waters fisher\nSome related occupations classified elsewhere: Bangus/tilapia farmers - 6221, Deep-sea fisher - 6227, Fishing laborer - 9216, Fishing operations manager - 1312, Oyster diver - 6229","version":"2022","source_id":768,"level":4,"normalized_name":"inland and coastal waters fishery workers"},{"code":"6227","parent_code":"622","title":"DEEP-SEA FISHERY WORKERS","description":"Deep-sea fishery workers, as skippers or members of fishing vessel crews, catch deep-sea fish, for sale or delivery to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) preparing and repairing nets and other fishing gear and equipment; b) commanding and operating fishing vessels to from and at deep-sea fishing grounds; c) determining areas for fishing, plotting courses and computing navigational positions using compass, charts, tables and other aids; d) steering vessels and operating navigational instruments and electronic fishing aids; e) directing fishing operations and supervising crew activities; g) recording fishing progress, activities, weather and sea conditions on ship's log; h) baiting, setting and hauling in fishing gear; i) cleaning, freezing, icing or salting catch on or offshore; and j) selecting and training vessel crews\nExamples of the occupations classified here: Deep-sea fisher, Trawler skipper\nSome related occupations classified elsewhere: Coastal fishery skipper - 6226, Coastal waters fisher - 6226, Fishery laborer - 9216, Fishing operations manager - 1312, Inland waters fisher - 6226","version":"2022","source_id":769,"level":4,"normalized_name":"deep-sea fishery workers"},{"code":"6228","parent_code":"622","title":"HUNTERS AND TRAPPERS","description":"Hunters and trappers catch and kill mammals, birds or reptiles mainly for meat, skin, feathers and other products, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.\nTheir tasks include: a) setting traps to catch mammals, birds or reptiles; b) killing trapped or free mammals, birds or reptiles with firearms or other weapons; c) skinning and otherwise treating killed mammals, birds or reptiles to obtain desired products for sale or delivery; d) delivering or selling trapped live mammals, birds or reptiles; and e) repairing and maintaining equipment.","version":"2022","source_id":770,"level":4,"normalized_name":"hunters and trappers"},{"code":"6229","parent_code":"622","title":"FISHERMEN NOT ELSEWHERE CLASSIFIED","description":"Workers in this unit group perform a variety of fishing tasks not elsewhere classified.\nTheir tasks include: a) gathering clams, oysters, crabs, lobster and other inland and coastal mollusks and crustaceans by digging, trapping, or by operation of special tonging or dredging devices; b) gathering sea mosses, turtle eggs or shells; c) diving to sea bed to gather corals or sponges or harvest pearl oysters; and d) catching and/or breeding fish and other sea creatures for aquariums and museums.\nExamples of the occupations classified here: Fish catcher for aquarium, Oyster diver, Pearl diver, Sea moss gatherer\nRelated occupation classified elsewhere: Subsistence diver - 6340","version":"2022","source_id":771,"level":4,"normalized_name":"fishermen not elsewhere classified"},{"code":"6310","parent_code":"631","title":"SUBSISTENCE CROP FARMERS","description":"Subsistence crop farmers grow and harvest field or tree and shrub crops, vegetables and fruit, in order to provide food, shelter and a minimum of cash income for themselves and their households.\nTheir tasks include: a) preparing the soil, sowing, planting, tending and harvesting field crops; b) growing vegetables, fruit and other tree and shrub crops; c) fetching water and gathering firewood; d) storing for later use and carrying out some processing of produce; e) building and maintaining makeshift houses and other shelters for own use; f) making tools, clothes and utensils for use by the household; and g) selling or bartering some products at local markets.\nExample of the occupations classified elsewhere: Subsistence crop farmer, Subsistence gardener, Subsistence vegetable grower\nSome related occupations classified elsewhere: Crop farm laborer - 9211, Firewood collector- 9624, Water collector- 9624","version":"2022","source_id":772,"level":4,"normalized_name":"subsistence crop farmers"},{"code":"6320","parent_code":"632","title":"SUBSISTENCE LIVESTOCK FARMERS","description":"Subsistence livestock farmers breed, raise and tend livestock in order to provide food, shelter and a minimum of cash income for themselves and their households.\nTheir tasks include: a) cultivating pastures, or managing grazing lands, and monitoring feed and water supplies needed to maintain condition of livestock; b) monitoring and examining animals to detect illness, injury, or disease, and to check physical condition; c) grooming and marking animals and shearing coats to collect hair or wool; d) herding or leading livestock to pastures, grazing land and water supplies; e) raising, tending, feeding and milking animals or draining blood from them; f) breeding animals and helping with animal births; g) slaughtering and skinning animals and preparing them and their products for consumption or sale; h) carrying out some processing of animal products; i) building and maintaining makeshift houses and other shelters for own use; j) making tools, clothes and utensils for use by the household; k) fetching water and gathering firewood; and l) buying, bartering and selling animals and some products.\nExample of occupation classified here: Subsistence cattle farmer\nSome related occupations classified elsewhere: Livestock farm laborer - 9212, Mixed crop and livestock farm laborers - 9213, Water and firewood collector – 9624","version":"2022","source_id":773,"level":4,"normalized_name":"subsistence livestock farmers"},{"code":"6330","parent_code":"633","title":"SUBSISTENCE MIXED CROP AND LIVESTOCK FARMERS","description":"Subsistence mixed crop and livestock farmers grow and harvest field or tree and shrub crops, vegetables and fruit, gather wild fruits, medicinal and other plants, tend or hunt animals, and/or catch fish and gather various forms of aquatic life in order to provide food, shelter and a minimum of cash income for themselves and their households.\nTheir tasks include: a) preparing the soil, sowing, planting, tending and harvesting field crops; b) growing vegetables, fruit and other tree and shrub crops; c) gathering wild fruits, medicinal and other plants; d) breeding, tending and feeding animals and poultry mainly to obtain meat, eggs, milk, hair, skin or other products; e) fetching water and gathering firewood; f) storing produce for later use and carrying out some processing of produce; g) building and maintaining makeshift houses and other shelters for own use; h) making tools, clothes and utensils for use by the household; i) selling or bartering some products at local markets.\nExample of occupation classified here: Mixed subsistence farmer","version":"2022","source_id":774,"level":4,"normalized_name":"subsistence mixed crop and livestock farmers"},{"code":"6340","parent_code":"634","title":"SUBSISTENCE FISHERS, HUNTERS, TRAPPERS AND GATHERERS","description":"Subsistence fishers, hunters, trappers and gatherers gather wild fruits medicinal and other plants; hunt and trap animals; and catch fish and gather various forms of aquatic life in order to provide food, shelter, and a minimum of cash income for themselves and their households.\nTheir tasks include: a) gathering wild fruits, roots, medicinal and other plants; b) hunting or trapping animals mainly to obtain meat, milk, hair, skin or other products; c) fetching water and gathering firewood; d) catching fish and gathering other forms of aquatic life; e) storing or carrying out some processing of their produce; f) building and maintaining houses and other shelters; g) making tools, clothes and utensils for use by the household; and h) selling or bartering some products at local markets.\nExamples of the occupations classified here: Subsistence collector, Subsistence diver, Subsistence fisher, Subsistence gatherer\nSome related occupations classified elsewhere: Livestock farm laborer – 9212, Subsistence crop farmer - 6310, Subsistence livestock farmer - 6320, Water and firewood collector – 9624","version":"2022","source_id":775,"level":4,"normalized_name":"subsistence fishers hunters trappers and gatherers"},{"code":"7111","parent_code":"711","title":"HOUSE BUILDERS","description":"House builders erect, maintain and repair houses and similar small buildings using either traditional or modern techniques and materials.\nTheir tasks include: a) preparing ground for erecting building or other structures; b) erecting structures to support roof, and building and covering walls with appropriate materials; c) fixing rafters to roof and covering with roofing material; d) levelling floor to make it smooth and serviceable; e) maintaining and repairing existing structures; f) arranging for specialized work such as bricklaying, painting, plumbing and electrical wiring to be done by subcontractors; and g) coordinating and supervising the activities of subcontractors, laborers and other workers.\nExample of occupation classified here: House builder\nSome related occupations classified elsewhere: Construction project manager - 1323, Construction supervisor - 3123, Project builder - 1323","version":"2022","source_id":776,"level":4,"normalized_name":"house builders"},{"code":"7112","parent_code":"711","title":"BRICKLAYERS AND RELATED WORKERS","description":"Bricklayers and related workers lay bricks, pre-cut stones and other types of building blocks in mortar to construct and repair walls, partitions, arches and other structures.\nTheir tasks include: a) laying stone, brick and similar building blocks to construct or repair walls, partitions, fireplaces and other structures such as smokestacks, furnaces, converters, kilns and ovens, piers and abutments; b) laying footpaths, kerbs and pavements; and c) laying bricks or other masonry to build patios, garden walls and other decorative installations.\nExamples of the occupations classified here: Block layer, Bricklayer, Chimney builder, Paver, Refractory bricklayer\nRelated occupation classified elsewhere: Stonemason - 7113","version":"2022","source_id":777,"level":4,"normalized_name":"bricklayers and related workers"},{"code":"7113","parent_code":"711","title":"STONEMASONS, STONE CUTTERS, SPLITTERS AND CARVERS","description":"Stonemasons, stone cutters, splitters and carvers cut and shape hard and soft stone blocks and slabs for the construction and maintenance of stone structures and monumental masonry, and carve designs and figures in stone.\nTheir tasks include: a) driving wedges into quarried stone to break it into slabs or blocks; b) selecting and grading slabs and blocks of granite, marble, and other stone; c) cutting, shaping and finishing building and monumental stone such as granite or marble by using hand or hand-powered tools; d) making patterns and marking shapes on stone for subsequent sawing, planing, drilling and other dressing and cutting operations; e) cutting and carving characters, figures or designs on stone blocks used for monuments or memorials; f) setting stone in the erection of monuments and memorials; and g) repairing and replacing stonework on old buildings, churches and monuments.\nExamples of the occupations classified here: Granite cutter, Monument mason, Stone carver, Stone cutter, Stone lathe operator, Stone polisher, Stonemason\nSome related occupations classified elsewhere: Stone cutting or processing machine operator - 8112, Wall and floor tiler - 7122","version":"2022","source_id":778,"level":4,"normalized_name":"stonemasons stone cutters splitters and carvers"},{"code":"7114","parent_code":"711","title":"CONCRETE PLACERS, CONCRETE FINISHERS AND RELATED WORKERS","description":"Concrete placers, concrete finishers and related workers erect reinforced concrete frameworks and structures, make forms for molding concrete, reinforce concrete surfaces, cement openings in walls or casings for wells, finish and repair cement surfaces and carry out terrazzo work. \nTheir tasks include: a) constructing and repairing reinforced concrete floors, walls, tanks, silos and other concrete structures; b) making shuttering or assembling prefabricated forms for molding concrete; c) cementing openings in walls or casings for wells; d) finishing and smoothing surfaces of concrete structures; and e) applying a durable, smooth surfacing composed of cement, sand pigment and marble particles to floors, known as a terrazzo finish.\nExamples of the occupations classified here: Cement finisher, Concrete finisher, Concrete placer, Concrete shutterer, Reinforced concreter, Terrazzo worker\nSome related occupations classified elsewhere: Concrete finishing machine operator - 8114, Road surface laying machinery operator - 8342","version":"2022","source_id":779,"level":4,"normalized_name":"concrete placers concrete finishers and related workers"},{"code":"7115","parent_code":"711","title":"CARPENTERS AND JOINERS","description":"Carpenters and joiners cut, shape, assemble, erect, maintain and repair various types of structures and fittings made from wood and other materials.\nTheir tasks include: a) making, altering and repairing structural and other woodwork at a work-bench and on a construction site; b) constructing, erecting and installing heavy-framed wooden structures on building sites; c) fitting, assembling and altering internal and external fixtures of buildings, such as walls, doors, door and window frames, facings and paneling; d) making, repairing and fitting scenic equipment for theatrical performances, motion picture or television productions; and e) constructing, assembling, altering and repairing wooden fixtures and fittings in train coaches, aircraft, ships, boats, floats, and other vehicles.\nExamples of the occupations classified here: Carpenter, Door installer, Finish carpenter, Framer, Joiner, Wood shipwright\nSome related occupations classified elsewhere: Furniture and cabinet maker - 7522, Wheel-wright - 7522","version":"2022","source_id":780,"level":4,"normalized_name":"carpenters and joiners"},{"code":"7119","parent_code":"711","title":"BUILDING FRAME AND RELATED TRADES WORKERS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers building frame and related trades workers not classified elsewhere in Minor group 711, Building frame and related trades workers. For instance the group includes steeplejacks, scaffolders and demolition workers.\nTheir tasks would include: a) climbing and performing miscellaneous construction and building maintenance work on tall structures such as towers, chimneys and spires; b) erecting temporary metal or wooden scaffolding on building sites; and c) demolishing buildings and other structures.\nExamples of the occupations classified here: Building wrecker, Prefabricated building assembler, Scaffolder, Skilled demolition worker, Steeplejack\nSome related occupations classified elsewhere: Building work construction laborer - 9313, Demolition laborer - 9313","version":"2022","source_id":781,"level":4,"normalized_name":"building frame and related trades workers not elsewhere classified"},{"code":"7121","parent_code":"712","title":"ROOFERS","description":"Roofers build and repair roofs on all types of buildings using one or more kinds of materials.\nTheir tasks include: a) studying drawings, specifications and construction sites to determine materials required; b) covering roof frameworks with slate and pre-fabricated tiles to cover pitched roofs; c) laying a waterproof shield and fixing metallic or synthetic materials to a building’s frame; d) sizing and cutting roofing materials to fit around edges corners and protuberances such as chimney; e) using natural materials such as thatching to provide roof coverings; and f) creating temporary structures such as scaffolding and ladders.\nExamples of the occupations classified here: Asphalt roofer, Composite materials roofer, Metal roofer, Roof fixer, Slate roofer, Thatcher, Tile roofer","version":"2022","source_id":782,"level":4,"normalized_name":"roofers"},{"code":"7122","parent_code":"712","title":"FLOOR LAYERS AND TILE SETTERS","description":"Floor layers and tile setters install, maintain and repair flooring, and cover floors, walls and other surfaces with tiles or mosaic panels for decorative or other purposes.\nTheir tasks include: a) preparing floor areas for covering with a variety of materials; b) assembling carpet, tiles or other materials and laying them on floors according to design and other specifications; c) preparing wall areas for covering with tiles or other materials for decorative or other purposes such as acoustic insulation; and d) setting tiles and constructing and laying mosaic panels to walls, floors and other surfaces.\nExamples of the occupations classified here: Carpet layer, Floor layer, Floor tiler, Marble setter, Parquetry worker, Tile setter, Wall tiler","version":"2022","source_id":783,"level":4,"normalized_name":"floor layers and tile setters"},{"code":"7123","parent_code":"712","title":"PLASTERERS","description":"Plasterers install, maintain and repair plasterboard in buildings, and apply decorative and protective coverings of plaster, cement and similar material to the interiors and exteriors of structures.\nTheir tasks include: a) applying one or more coats of plaster to interior walls and ceilings of buildings to produce finished surface; b) measuring, marking and installing ornamental plaster panels, and casting and trimming ornamental plaster cornices; c) applying protective and decorative covering of cement, plaster and similar materials to exterior building surfaces; and d) making and installing decorative plaster fixtures of fibrous plaster.\nExamples of the occupations classified here: Dry wall plasterer, Fibrous plasterer, Ornamental plasterer, Plasterer, Solid plasterer, Stucco plasterer","version":"2022","source_id":784,"level":4,"normalized_name":"plasterers"},{"code":"7124","parent_code":"712","title":"INSULATION WORKERS","description":"Insulation workers apply and repair insulating materials to buildings, boilers, pipes or refrigeration and air-conditioning equipment.\nTheir tasks include: a) cutting insulation material by size and shape; b) applying slabs and sheets of insulating or sound-absorbing materials to walls, floors and ceilings of buildings; c) blow and pack insulating or sound-absorbing materials into cavities between walls, floors and ceilings of buildings with power-driven machines; d) examining plans, specifications and work sites to determine the type, quality and quantity of insulation material required; e) applying insulating materials to exposed surfaces of equipment such as boilers, pipes and tanks; and f) insulating refrigeration and air-conditioning equipment.\nExamples of the occupations classified here: Acoustic insulation worker, Boiler and pipe insulation worker, Insulation installer, Insulation worker, Refrigeration and air-conditioning equipment insulation worker","version":"2022","source_id":785,"level":4,"normalized_name":"insulation workers"},{"code":"7125","parent_code":"712","title":"GLAZIERS","description":"Glaziers measure, cut, finish, fit and install flat glass and mirrors.\nTheir tasks include: a) selecting the type of glass to be used, cutting to right size and shape and installing in windows, doors, showers and partitions of buildings; b) installing glass and mirrors in skylights, display cases, interior walls and ceilings; c) installing or replacing windscreens in vehicles or boats; and d) creating decorative glass features such as glass walls, staircases, balustrades and stained-glass windows.\nExamples of the occupations classified here: Autoglazier, Building glazier, Glass decorator, Glazier fabricator, Leaded-glass glazier, Plate-glass fitter, Roofing glazier, Vehicle glazier \nSome related occupations classified elsewhere: Glass cutter - 7315, Glass finisher - 7315","version":"2022","source_id":786,"level":4,"normalized_name":"glaziers"},{"code":"7126","parent_code":"712","title":"PLUMBERS AND PIPE FITTERS","description":"Plumbers and pipe fitters assemble, install, repair and maintain pipe systems, fittings and fixtures for water, gas, drainage, sewerage systems, and hydraulic and pneumatic equipment.\nTheir tasks include: a) measuring, cutting, threading, bending, jointing, assembling, installing, maintaining and repairing pipes, fittings and fixtures of drainage, heating, water supply and sewerage systems; b) installing gas appliances, dishwashers and water heaters, sinks and toilets using hand and power tools; c) laying clay, concrete or cast-iron pipes in ditches to form sewers, drains or water mains, or for other purposes; and d) inspecting, examining and testing installed systems and pipes, using pressure gauge, hydrostatic testing, observation or other methods.\nExamples of the occupations classified here: Aircraft pipe and tube fitter, Drain technician, Gas fitter, Gas pipe fitter, Marine pipe fitter, Pipe fitter, Pipe layer, Pipeline inspector, Plumber, Ventilation pipe fitter\nRelated occupation classified elsewhere: Air conditioning and refrigeration mechanics - 7127","version":"2022","source_id":787,"level":4,"normalized_name":"plumbers and pipe fitters"},{"code":"7127","parent_code":"712","title":"AIR CONDITIONING AND REFRIGERATION MECHANICS","description":"Air conditioning and refrigeration mechanics assemble, install, maintain and repair air conditioning and refrigeration systems and equipment.\nTheir tasks include: a) interpreting blueprints, drawings or other specifications; b) assembling, installing and repairing components such as compressors, motors, condensers, evaporators, switches and gauges for air conditioning and refrigeration systems; c) connecting piping and equipment by bolting, riveting, welding or brazing; and d) testing systems, diagnosing faults and performing routine maintenance or servicing.\nExamples of the occupations classified here: Air conditioning equipment mechanic, Air duct installer, Refrigeration mechanic\nSome related occupations classified elsewhere: Plumbers and pipe filters - 7126, Ventilation pipe fitter - 7126","version":"2022","source_id":788,"level":4,"normalized_name":"air conditioning and refrigeration mechanics"},{"code":"7131","parent_code":"713","title":"PAINTERS AND RELATED WORKERS","description":"Painters and related workers prepare surfaces of buildings and other structures for painting, apply protective and decorative coats of paint or similar materials, or cover interior walls and ceilings of buildings with wallpaper or other finishes.\nTheir tasks include: a) cleaning and preparing walls and other surfaces of buildings for painting or wallpapering; b) selecting and preparing paints to required colors by mixing pigments and additives; c) applying or spraying paint, varnish, and similar materials to surfaces, fixtures and fittings of buildings; d) measuring and hanging wallpaper or other fabrics on interior walls and ceilings; and e) applying paints, varnishes and stains to surfaces using brushes, rollers and sprays.\nExamples of the occupations classified here: Building painter, Construction painter, House painter, Paperhanger","version":"2022","source_id":789,"level":4,"normalized_name":"painters and related workers"},{"code":"7132","parent_code":"713","title":"SPRAY PAINTERS AND VARNISHERS","description":"Spray painters and varnishers operate spray painting and varnishing equipment to apply protective coatings to manufactured items or structures.\nTheir tasks include: a) preparing surfaces to be coated using a variety of methods to remove grease, dirt and rust; b) painting cars, buses, trucks and other vehicles, and applying varnish and other protective coatings; and c) applying paint as well as protective coatings of enamel or varnish on metal, wooden and other manufactured products, usually with a hand-spraying device.\nExamples of the occupations classified here: Aircraft painter, Car painter, Furniture spray painter, Manufactured articles painter, Manufactured articles varnisher, Upholstery painter, Varnisher, Vehicle painter\nSome related occupations classified elsewhere: Building painter - 7131, Decorative painter - 7316, Metal coating machine operator - 8122, Signwriter - 7316, Wood treater - 7521","version":"2022","source_id":790,"level":4,"normalized_name":"spray painters and varnishers"},{"code":"7133","parent_code":"713","title":"BUILDING STRUCTURE CLEANERS","description":"Building structure cleaners clean exterior surfaces of buildings and other structures, and remove soot from chimneys.\nTheir tasks include: a) cleaning exterior surfaces of stone, brick, metal or similar materials by means of chemicals, or a jet of steam or sand applied under high pressure; b) removing soot from flues, chimneys and connecting pipes; and c) removing asbestos, mold and fire damaged surfaces from buildings.\nExamples of the occupations classified here: Building exteriors cleaner, Building exteriors sandblasters\nSome related occupations classified elsewhere: Graffiti cleaner - 9129, Water blaster - 9129","version":"2022","source_id":791,"level":4,"normalized_name":"building structure cleaners"},{"code":"7211","parent_code":"721","title":"METAL MOLDERS AND COREMAKERS","description":"Metal molders and coremakers make molds and cores for casting metal.\nTheir tasks include: a) making molds by hand or using auxiliary machines on a bench for small metal castings, on the foundry floor, or in a pit for large castings; b) making cores for use in metal molds; c) cleaning and smoothing molds, core boxes, and repairing surface imperfections; d) moving and positioning work pieces such as mold sections, patterns, and bottom boards, using cranes, or signaling others to move work pieces; e) positioning patterns inside mold sections and clamping sections together; f) cutting spouts, runner holes and sprue holes into molds; and g) lifting upper mold sections from lower sections and remove molded patterns.\nExamples of the occupations classified here: Car parts molder, Coremaker, Filler metal molder, Metal bench molder, Metal castings molder, Metal mold maker","version":"2022","source_id":792,"level":4,"normalized_name":"metal molders and coremakers"},{"code":"7212","parent_code":"721","title":"WELDERS AND FLAME CUTTERS","description":"Welders and flame cutters weld and cut metal parts using gas flame, electric arc and other sources of heat to melt and cut, or to melt and fuse metal.\nTheir tasks include: a) welding metal parts using gas flame, or an electric arc, thermite compound or other methods; b) operating resistance-welding machines; c) using blowtorch to make and repair lead linings, pipes, floors and other lead fixtures; d) brazing metal parts together; e) cutting metal pieces using gas flame or an electric arc; f) joining metal parts by hand soldering; g) monitoring the fitting, burning, and welding processes to avoid overheating of parts or warping, shrinking, distortion, or expansion of material; and h) examining work pieces for defects and measuring work pieces with straight edges or templates to ensure conformance with specifications.\nExamples of the occupations classified here: Auto body welder, Brazier, Construction welder, Electric arc welder, machine, Electric welder, Flux-cored arc welder, Gas tungsten arc welder, Orbital welder, Pipe welder, Resistance welder, Shielded metal arc welder, Thermite welder","version":"2022","source_id":793,"level":4,"normalized_name":"welders and flame cutters"},{"code":"7213","parent_code":"721","title":"SHEET METAL WORKERS","description":"Sheet metal workers make, install and repair articles and parts of articles made out of sheet metal such as sheet steel, copper, tin, brass, aluminum, zinc or galvanized iron.\nTheir tasks include: a) marking sheet metal for cutting and shaping; b) making and repairing household utensils and other articles in tin, copper and light alloys, or ornamental articles and fittings; c) making and repairing boilers, tanks, vats and similar containers; d) installing and repairing sheet-metal parts of vehicles and aircraft; e) converting blueprints into shop drawings to be followed in the construction and assembly of sheet metal products; f) determining project requirements, including scope, assembly sequences, and required methods and materials, according to blueprints, drawings, and written or verbal instructions; and g) inspecting product quality and installation to ensure conformance to specifications.\nExamples of the occupations classified here: Aircraft sheet metal worker, Boilersmith, Coppersmith, Ornamental sheet metal worker, Panel beater, Plate metal worker , Sheet metal marker, Tinsmith, Vehicle sheet metal worker","version":"2022","source_id":794,"level":4,"normalized_name":"sheet metal workers"},{"code":"7214","parent_code":"721","title":"STRUCTURAL METAL PREPARERS AND ERECTORS","description":"Structural metal preparers and erectors assemble, erect and dismantle structural metal frames of buildings and other structures.\nTheir tasks include: a) marking metal framework as a guide when drilling, cutting, and shaping them for use in buildings, ships and other structures; b) drilling, cutting and shaping structural steel in a workshop; c) erecting steel framework for buildings, bridges and other constructions; d) assembling and erecting the framework and other metal parts of ships' structures; e) shaping and fitting structural-steel plates of ships under construction or repair; and f) riveting structural-metal members by hand, machine or pneumatic riveter.\nExamples of the occupations classified here: Constructional steel erector, Iron works fabricator, Metal shipwright, Pneumatic riveter, Reinforcing iron worker, Riveter, Ship plater, Structural metal erector, Structural metal marker, Structural metal preparer\nRelated occupation classified elsewhere: Rivet production machine operator - 7223","version":"2022","source_id":795,"level":4,"normalized_name":"structural metal preparers and erectors"},{"code":"7215","parent_code":"721","title":"RIGGERS AND CABLE SPLICERS","description":"Riggers and cable splicers assemble rigging gear to move and position equipment and structural components, or install and maintain cables, ropes and wires on construction sites, buildings or other structures.\nTheir tasks include: a) estimating the size, shape and weight of objects to be moved and deciding on the type of equipment to move them; b) installing and repairing cables, ropes, wires, pulleys and other tackle; c) joining, repairing and fitting attachments to wires, ropes and cables; d) working as member of crew erecting and repairing derricks for drilling water, gas and oil-wells; e) lifting and mounting scenery, lighting and other equipment in theatres and on film sets; and f) installing and maintaining communication towers, aerial cableways, funicular railways, ski lifts and similar infrastructure.\nExamples of the occupations classified here: Aircraft rigger, Cable and rope splicer, Gas-drilling rigger, Hoisting equipment rigger, Oil-drilling rigger, Ship rigger, Suspension bridge cable worker, Theatrical rigger, Tower rigger\nSome related occupations classified elsewhere: Cable and rope splicing machine operator -8189, Crane, hoist and related plant operators - 8343","version":"2022","source_id":796,"level":4,"normalized_name":"riggers and cable splicers"},{"code":"7221","parent_code":"722","title":"BLACKSMITHS, HAMMERSMITHS AND FORGING PRESS WORKERS","description":"Blacksmiths, hammersmiths and forging press workers hammer and forge bars, rods, ingots and plates of iron, steel or other metals, and draw wire to make and repair various kinds of tools, metal articles, pieces of equipment, and agricultural and related implements.\nTheir tasks include: a) heating metal in forge furnace and manufacturing and repairing articles by drawing, bending; b) cutting, hammering metal on an anvil, punching, shearing, joining and hardening or tempering; c) shaping heated metal into forgings on power hammer equipped with open dies; d) operating closed-die drop hammer to forge metal articles; e) operating a power-press machine equipped with closed dies to forge metal articles; f) drawing wire; g) reading work orders or blueprints to determine specified tolerances and sequences of operations for machine setup; and h) measuring and inspecting machine parts to ensure conformance to product specifications.\nExamples of the occupations classified here: Blacksmith, Drop-hammer worker, Forging press worker, Hammersmith, Metal former, Wire drawer\nSome related occupations classified elsewhere: Casting machine operator - 7223, Machine tool operator - 7223","version":"2022","source_id":797,"level":4,"normalized_name":"blacksmiths hammersmiths and forging press workers"},{"code":"7222","parent_code":"722","title":"TOOLMAKERS AND RELATED WORKERS","description":"Toolmakers and related workers make and repair custom made and specialized tools, sports guns, locks, dies, patterns machinery components and other metal articles using hand and machine tools to work metal to fine tolerances.\nTheir tasks include: a) reading and interpreting engineering drawings and specifications of tools, dies, prototypes or models; b) preparing templates and sketches, and determining work processes; c) visualizing and computing dimensions, sizes, shapes, and tolerances of assemblies, based on specifications; d) positioning, securing and measuring metal stock or castings to lay out for machining; e) setting up, operating and maintaining conventional and computer numerically controlled machine tools to cut, turn, mill, plane, drill, bore, grind or otherwise shape workpiece to prescribed dimensions and finish; f) fitting and assembling parts to make and repair jigs, fixtures and gauges; g) repairing and modifying sports guns and other small arms; h) making, fitting, assembling, repairing and installing lock parts and locks; i) making and repairing metal patterns for preparation of foundry molds; j) laying out lines and reference points on metal stock to guide other workers who cut, turn, mill, grind or otherwise shape metal; and k) verifying dimensions, alignments, and clearances of finished parts for conformance to specifications, using precision measuring instruments and testing completed items for proper operation.\nExamples of the occupations classified here: Die maker, Gauge maker, Gunsmith, Jig maker, Locksmith, Metal marker, Metal patternmaker, Patternmaker, Toolmaker\nRelated occupation classified elsewhere: Tool production machine operator - 7223","version":"2022","source_id":798,"level":4,"normalized_name":"toolmakers and related workers"},{"code":"7223","parent_code":"722","title":"METAL WORKING MACHINE TOOL SETTERS AND OPERATORS","description":"Metal working machine tool setters and operators set and/or operate, various machine tools working to fine tolerances.\nTheir tasks include: a) setting one or more types of machine tool for production of metal articles in standardized series; b) operating and monitoring metalworking machines, such as lathes, milling, planing, boring, drilling, grinding or honing machines, including multi-purpose numerically controlled metalworking machines; c) performing similar tasks when machining plastics and other metal substitutes; d) observing machine operations to detect work piece defects or machine malfunctions, adjusting machines as necessary; e) inspecting work pieces for defects, and measuring work pieces to determine accuracy of machine operation, using rules, templates, or other measuring instruments; and f) changing worn machine accessories, such as cutting tools and brushes, using hand tools.\nExamples of the occupations classified here: Boring machine operator, Casting machine operator, Machine tool operator, Machine tool setter, Machine tool setter-operator, Metal turner, Metal working drilling machine setter-operator, Metal working honing machine setter-operator, Metal working lathe setter-operator, Metal working machine setter-operator, Metal working milling machine setter-operator, Metal working numerical control machine setter-operator, Metal working planning machine setter-operator, Metal working precision grinding-machine setter-operator, Rivet production machine operator, Tool production machine operator\nSome related occupations classified elsewhere: Machine-operator, drilling/metal - 8211, Machine-operator, grinding/metal - 8211, Machine-operator, machine tool - 8211","version":"2022","source_id":799,"level":4,"normalized_name":"metal working machine tool setters and operators"},{"code":"7224","parent_code":"722","title":"METAL POLISHERS, WHEEL GRINDERS AND TOOL SHARPENERS","description":"Metal polishers, wheel grinders and tool sharpeners polish and grind metal surfaces and sharpen tools.\nTheir tasks include: a) operating fixed or portable buffing and polishing machines; b) sharpening cutting tools and instruments using grinding wheels or mechanically operated grinding machines; c) repairing, adjusting and sharpening saw blades and metal teeth of cylinders in textile carding machines; d) dressing grinding wheels, according to specifications; e) monitoring machine operations to determine whether adjustments are necessary; stop machines when problems occur; f) inspecting, feeling, and measuring work pieces to ensure that surfaces and dimensions meet specifications; and g) selecting and mounting grinding wheels on machines, according to specifications, using hand tools and applying knowledge of abrasives and grinding procedures.\nExamples of the occupations classified here: Cutting instrument sharpener, Knife sharpener, Metal buffer, Metal finisher, Metal grinder, Metal polisher, Metal wheel-grinder, Saw repairer, Saw sharpener, Textile carding machine grinder, Tool grinder, Tool sharpener\nSome related occupations classified elsewhere: Metal finishing machine operator - 8122, Metal polishing machine operator - 8122","version":"2022","source_id":800,"level":4,"normalized_name":"metal polishers wheel grinders and tool sharpeners"},{"code":"7231","parent_code":"723","title":"MOTOR VEHICLE MECHANICS AND REPAIRERS","description":"Motor vehicle mechanics and repairers fit, install, maintain, service and repair engines and the mechanical and related equipment of passenger cars, delivery trucks, motorcycles and other motor vehicles.\nTheir tasks include: a) detecting and diagnosing faults in engines and parts; b) fitting, examining, testing and servicing motor vehicle and motorcycle engines; c) replacing engine components or complete engines; d) fitting, examining, adjusting, dismantling, rebuilding and replacing defective parts of motor vehicles; e) installing or adjusting motors and brakes, and adjusting steering or other parts of motor vehicles; f) installing, adjusting, servicing and replacing mechatronics components of motor vehicles; g) performing scheduled maintenance services, such as oil changes, lubrications and engine tune-ups, to achieve smoother running of vehicles and ensure compliance with pollution regulations; and h) reassembling engines and parts after being repaired.\nExamples of the occupations classified here: Automotive brakes systems service technician, Automotive mechanic, Moped repairer, Motor truck mechanic, Motor vehicle engine and fuel systems service technician, Motor vehicle engine fitter, Motor vehicle mechanic, Motor vehicle mechatronics service technician, Motor vehicle repairer, Motor vehicle service technician, Motorcycle mechanic, Motorized rickshaw mechanic, Road transport diesel fitter, Small engine mechanic, Train mechanic\nSome related occupations classified elsewhere: Automotive electrician - 7412, Bicycle repairer - 7234, Electrical mechanic - 7412, Motor vehicle engine assembler - 8211","version":"2022","source_id":801,"level":4,"normalized_name":"motor vehicle mechanics and repairers"},{"code":"7232","parent_code":"723","title":"AIRCRAFT ENGINE MECHANICS AND REPAIRERS","description":"Aircraft engine repairers and mechanics fit, service, repair and overhaul aircraft engines and assemblies, such as airframes, hydraulic, and pneumatic systems.\nTheir tasks include: a) fitting, examining, testing and servicing aircraft engines; b) replacing engine components or complete engines; c) examining and inspecting airframes and aircraft components, including landing gear, hydraulic systems, and de-icers to detect wear, cracks, breaks, leaks, or other problems; d) maintaining, repairing, overhauling, modifying and testing aircraft structural, mechanical and hydraulic systems; e) reading and interpreting manuals, service bulletins, and other specifications to determine the feasibility and method of repairing or replacing malfunctioning or damaged components; f) maintaining, repairing, and rebuilding aircraft structures, functional components, and parts such as wings and fuselage, rigging, hydraulic units, oxygen systems, fuel systems, electrical systems, gaskets, and seals; g) inspecting completed work to certify that maintenance meets standards and the aircraft is ready for operation; h) maintaining repair logs, documenting all preventive and corrective aircraft maintenance; i) installing and testing electrical and electronic components, assemblies, and systems in aircraft; and j) connecting components to assemblies such as radio systems, instruments, magnetos, inverters, and in-flight refueling systems.\nExamples of the occupations classified here: Aeromechanic, Aircraft airframes maintenance engineer, Aircraft engine fitter, Aircraft engines maintenance engineer, Aircraft maintenance assistant, Aircraft maintenance supervisor, Aircraft mechanic, Aircraft pneudraulic systems mechanic, Aircraft powerplant mechanic, Aircraft restorer, Aircraft service technician, Airframe and power plant mechanic, Airframe mechanic, Aviation maintenance technician, Helicopter mechanic, Jet engine mechanic, Rocket engine component mechanic\nSome related occupations classified elsewhere: Aeronautical engineer - 2144, Aircraft engine assembler - 8211, Avionics aircraft maintenance engineer - 7421, Avionics technician - 7421","version":"2022","source_id":802,"level":4,"normalized_name":"aircraft engine mechanics and repairers"},{"code":"7233","parent_code":"723","title":"AGRICULTURAL AND INDUSTRIAL MACHINERY MECHANICS AND REPAIRERS","description":"Agricultural and industrial machinery mechanics and repairers fit, install, examine, service and repair engines, agricultural and industrial machinery and mechanical equipment, except motor vehicle, aircraft and electric motors.\nTheir tasks include: a) fitting, installing, examining, servicing and repairing engines, machinery and mechanical equipment; b) oiling and greasing stationary engines and machinery; c) inspecting and testing new machinery and mechanical equipment for conformity with standards and specifications; d) disassembling machinery and equipment to remove parts and make repairs; e) examining parts for defects such as breakage and excessive wear; f) operating newly repaired machinery and equipment to verify the adequacy of repairs; and g) recording repairs and maintenance performed.\nExamples of the occupations classified here: Agricultural machinery erector-installer, Agricultural machinery fitter, Agricultural machinery greaser, Agricultural machinery mechanic, Agricultural machinery oiler, Construction machinery mechanic, Construction machinery repairer, Diesel engine mechanic (except motor vehicle), Earth-moving equipment fitter, Farm machinery mechanic, Farm machinery repairer, Farm tractor mechanic, Heavy equipment mechanic, Hydraulic mechanic, Industrial machinery erector-installer, Industrial machinery fitter, Industrial machinery greaser, Industrial machinery oiler, Industrial plant mechanic, Industrial sewing machine mechanic, Loomfixers, Marine craft mechanic, Marine engine fitter, Marine machinery mechanic, Metalworking machine-tool fitter, Metalworking machine-tool mechanic, Mining machinery fitter, Mining machinery mechanic, Mining machinery repairer, Plant maintenance mechanic, Power plant mechanic, Printing machinery fitter, Printing machinery mechanic, Ship fitter, Stationary engine fitter, Stationary engine repairer, Steam-engine mechanic, Textile machinery fitter, Train engine fitter, Train engine repairer, Turbine fitter, Turbine mechanic, Woodworking machinery fitter, Woodworking machinery mechanic\nSome related occupations classified elsewhere: Air conditioning equipment mechanic - 7127, Electrical mechanic - 7412, Mechanical machinery assembler - 8211","version":"2022","source_id":803,"level":4,"normalized_name":"agricultural and industrial machinery mechanics and repairers"},{"code":"7234","parent_code":"723","title":"BICYCLE AND RELATED REPAIRERS","description":"Bicycle and related repairers fit, maintain, service and repair the mechanical and related equipment of bicycles, rickshaws, baby carriages, wheelchairs and similar non-motorized transport equipment.\nTheir tasks include: a) examining, servicing and repairing bicycles and other non-motorized transport equipment; b) cleaning and lubricating bearings and other moving parts; c) replacing and repairing components and accessories, such as brakes, driving chain mechanism, wheels, handle bars etc.; d) changing tires and controlling air pressure; e) spray painting frames; and f) assembling new bicycles, wheelchairs and similar non-motorized equipment.\nExamples of the occupations classified here: Bicycle mechanic, Bicycle repairer, Perambulator repairer, Wheelchair repairer\nSome related occupations classified elsewhere: Moped repairer - 7231, Motorized rickshaw mechanic - 7231","version":"2022","source_id":804,"level":4,"normalized_name":"bicycle and related repairers"},{"code":"7311","parent_code":"731","title":"PRECISION-INSTRUMENT MAKERS AND REPAIRERS","description":"Precision-instrument makers and repairers make, calibrate, repair, maintain, adjust and install mechanical watches, clocks, nautical, meteorological, optical, orthopedic and other precision instruments and equipment and set them for correct performance.\nTheir tasks include: a) repairing, cleaning, and adjusting mechanisms of timing instruments, such as watches and clocks; b) adjusting timing regulators, using calipers, watch-rate recorders, and tweezers; c) cleaning, rinsing, and drying timepiece parts, using solutions and ultrasonic or mechanical watch-cleaning machines; d) testing timepiece accuracy and performance, using meters and other electronic instruments; e) testing accuracy of meters, gauges, indicators, or other recording or controlling instruments to locate defective components and for conformance to standards; f) calibrating instruments or scales, using hand tools, computer, or electronic devices; g) inspecting components, connections, and drive mechanisms to detect defects; h) assembling instruments and devices, such as barometers, control valves, gyroscopes, hygrometers, speedometers, tachometers, and thermostats; i) testing, calibrating, and adjusting electronic, mercurial, aneroid, and other types of meteorological instruments for compliance with printed specifications and schematic diagrams, using voltmeters, oscilloscopes, tube testers, and other test instruments; j) adjusting and repairing masts, supporting structures, clearance lights, control panels, control cabling and wiring, and other electrical and mechanical devices; k) repairing and setting optical instruments such as microscopes, telescopes, theodolites, sextants; and l) checking whether assembled units conform to specifications and ensuring stipulated performance and sensitivity by standard tests.\nExamples of the occupations classified here: Cannon-pinion adjuster, Instrument/meteorological maker, Maker and repairer, instrument/surgical, Optical instrument maker, Optical instrument repairer, Photographic equipment repairer, Precision instrument assembler, Precision instrument maker, Precision instrument repairer, Surgical instrument maker, Watch and clock assembler, Watch and clock repairer, Watchmaker\nSome related occupations classified elsewhere: Locksmith - 7222, Machine tool operator - 7223, Orthopedic appliance maker - 3214, Watch assembler - 8212","version":"2022","source_id":805,"level":4,"normalized_name":"precision-instrument makers and repairers"},{"code":"7312","parent_code":"731","title":"MUSICAL INSTRUMENT MAKERS AND TUNERS","description":"Musical-instrument makers and tuners make, assemble, repair, adjust, restore musical instruments and tune them to the required pitch with hand or power tools. They usually specialize in one type of instrument, such as string instruments, brass instruments pianos, reed instruments or percussion instruments.\nTheir tasks include: a) fabricating and assembling musical instruments and instrument parts of wood, ebonite, metal, leather and other materials; b) repairing or replacing musical instrument parts and components, such as strings, bridges, felts, and keys, using hand and power tools; c) playing and inspecting instruments to evaluate their sound quality and to locate any defects; d) adjusting string tensions to achieve proper tone or pitch of stringed instruments; e) adjusting lips, reeds, or toe hole of organ pipes, using hand tools, to regulate airflow and loudness of sound; f) tuning and servicing pipe organs by adjusting pitch of organ A pipes to conform with pitch of tuning fork and adjusting pitch of other pipes with references to pitch of tuned pipes; g) installing new drumheads in percussion instruments; h) tuning accordions by aurally comparing pitch of reeds with master reeds and filing reeds to obtain standard pitch; i) aligning pads and keys on reed or wind instruments; j) tuning percussion instruments to required pitch by tightening or loosening cords holding leather pieces fixed atop or at both ends of instrument; and k) assembling and installing new pipe organs and pianos in buildings.\nExamples of the occupations classified here: Accordion maker, Brass instrument maker, Brass instrument repairer, Metal wind instrument maker, Musical instrument tuner, Organ builder, Piano maker, Piano tuner, Stringed instrument maker, Woodwind instrument maker","version":"2022","source_id":806,"level":4,"normalized_name":"musical instrument makers and tuners"},{"code":"7313","parent_code":"731","title":"JEWELLERY AND PRECIOUS METAL WORKERS","description":"Jewelry and precious metal workers design, fabricate, adjust, repair, or appraise jewelry, ceremonial or religious items, gold, silver, other precious metals, or gems. They cut, file, polish and set precious and semiprecious stones including gems and diamonds and engrave designs on jewelry and precious metal articles. They cut and polish diamonds for industrial purposes.\nTheir tasks include: a) casting jewelry and other non-ferrous metal articles by hand; b) creating new jewelry designs and modifying existing designs, using computers as necessary; c) cutting designs in molds or other materials to be used as models in the fabrication of metal and jewelry products; d) altering existing jewelry mountings in order to reposition jewels or to adjust mountings; e) repairing, reshaping and restyling old jewelry or precious metal ware following designs or instructions; f) making complete jewelry articles such as rings, necklaces, bangles, brooches and bracelets from materials such as gold, silver, platinum, and precious or semiprecious stones; g) examining gem surfaces and internal structures, using polariscopes, refractometers, microscopes, and other optical instruments, to differentiate between stones, to identify rare specimens, or to detect flaws, defects, or peculiarities affecting gem values; h) cutting and polishing gems and setting them in jewelry articles; i) engraving or embossing letters, designs or decorative lines on jewelry and precious metal ware; j) grinding, drilling and finishing jewel bearings for use in precision instruments such as compasses and chronometers; and k) examining assembled or finished products to ensure conformance to specifications, using magnifying glasses or precision measuring instruments.\nExamples of the occupations classified here: Jewelry enameller, Gem cutter/faceter, Gem setter, Gold cutter, Gold reclaimer, Goldbeater, Goldsmith, Jeweler, Jewelry caster, by hand and machine, Jewelry engraver, Jewelry finishers, by hand and machine, Jewelry polisher, Jewelry repairer, Precious metal leaf maker, Precious metal roller, Silversmith","version":"2022","source_id":807,"level":4,"normalized_name":"jewellery and precious metal workers"},{"code":"7314","parent_code":"731","title":"POTTERS AND RELATED WORKERS","description":"Potters and related workers prepare pottery, porcelain ware, sanitary ware, bricks, tiles and abrasive wheels by hand or by machine.\nTheir tasks include: a) making articles of pottery and porcelain; b) making clay or plaster of Paris molds; c) reading technical drawings to know customer’s requirements; d) forming articles on potter's wheel by pressing thumbs into centers of revolving clay to form hollows, and press on the inside and outside of emerging clay cylinders with hands and fingers, gradually raising and shaping clay to desired forms and sizes; e) adjusting wheel speeds according to the feel of the clay as pieces enlarge and walls become thinner; f) operating jigger machines to form ceramic ware, such as bowls, cups, plates, and saucers; g) adjusting and setting controls of pug mill that mixes, extrudes, cuts, and deposits clay charges in or over molds as specified; h) smoothening surfaces of finished pieces, using rubber scrapers and wet sponges; i) forming abrasive wheels by molding and pressing an abrasive mixture by hand or by machine; j) examining finished ware for defects, verifying accuracy of shapes and sizes of objects, using calipers and templates; and k) preparing work for sale or exhibition, and maintaining relationships with retail, pottery, art, and resource networks that can facilitate sale or exhibition of work.\nExamples of the occupations classified here: Abrasive wheel molder, Brick and tile molder, Clay extruding-press operator, Decorators/lazers, Potter, Pottery and porcelain caster, Pottery and porcelain die-presser, Pottery and porcelain jiggerman, Pottery and porcelain maker, Pottery and porcelain modeler, Pottery and porcelain presser, hand, Pottery and porcelain thrower\nSome related occupations classified elsewhere: Brick and tile kiln operator - 8181, Ceramic artist - 2651, Pottery and porcelain kiln operator - 8181","version":"2022","source_id":808,"level":4,"normalized_name":"potters and related workers"},{"code":"7315","parent_code":"731","title":"GLASS MAKERS, CUTTERS, GRINDERS AND FINISHERS","description":"Glass makers, cutters, grinders and finishers blow, mold, press, cut, trim, grind and polish glass, shape molten glass according to patterns.\nTheir tasks include: a) heating glass to pliable stage, using gas flames or ovens, and rotating glass to heat it uniformly; b) blowing and bending glass tubing into specified shapes to form scientific apparatus like flasks, retorts, pipettes; c) grinding and polishing glass objects or parts to correct defects or to prepare surfaces for further finishing and smoothening and polishing rough edges, using belt sander or polishing wheels; d) examining glass stock and finished products and marking or discarding items with defects such as spots, stains, scars, snags, chips, scratches, or unacceptable shapes or finishes; e) reading work orders to determine dimensions, cutting locations, and quantities to cut; f) observing gauges, computer printouts and video monitors to verify specified processing conditions and make adjustments as necessary; g) positioning pattern or drawing on glass, measuring dimensions, and marking cutting lines, using glass cutting tools and cutting glass along marked outlines or around pattern; h) setting up, operating and adjusting computerized or robotic glass cutting equipment; i) inspecting, weighing, and measuring products to verify conformance to specifications, using instruments such as micrometers, calipers, magnifiers, and rulers; j) regulating oven temperatures according to glass types to be processed; k) transferring pattern for individual stained glass parts from full size drawing to pattern paper, using stylus to trace drawings; l) spraying silver solution on glass to provide mirrored surface, using spray gun; and m) laying out cutting and grinding optical and other glass to specified dimensions and weight for molding into lens blanks and for use as watch crystals.\nExamples of the occupations classified here: Glass blower, Glass cutter, Glass edge grinder, Glass finisher, Glass grinder, Glass lens molder, Glass polisher, Glass scientific blower, Glass tinter, Glass tube bender, Optical glass cutter\nRelated occupation classified elsewhere: Glass production furnace operator - 8181","version":"2022","source_id":809,"level":4,"normalized_name":"glass makers cutters grinders and finishers"},{"code":"7316","parent_code":"731","title":"SIGN WRITERS, DECORATIVE PAINTERS, ENGRAVERS AND ETCHERS","description":"Sign writers, decorative painters, engravers and etchers decorate articles made of wood, metal, textiles, glass, ceramics and other materials. They plan, lay out and paint letters, figures, monograms and designs to make signs and engrave and etch ornamental and floral designs on glass and other articles.\nTheir tasks include: a) painting decorative free-hand designs on objects, such as pottery, glass, cigarette cases, lampshades; b) transferring from paper transfers decorative or ornamental designs on articles; c) integrating and developing visual elements, such as line, space, mass, color, and perspective, in order to produce desired effects such as the illustration of ideas, emotions, or moods; d) laying out and painting in one or more languages letters, figures, monograms and designs to make signs; e) sketching or tracing design or lettering onto work piece or pattern material to prepare pattern or stencil; f) designing pattern or lettering to paint work pieces, such as signs, glassware, pottery, or zinc plates; g) using software and routing equipment to produce 3D Carved images for application onto larger signage as well as engraved and inlaid signs; h) designing and producing normal flat cut lettering or lettering that is shadowed with applied vinyl or lettering that is ready cut for application; i) writing, painting, or printing signs or show cards used for display or other purposes; j) cutting out letters and signs for display purposes from wallboard or cardboard, by hand or machines, such as electrically powered jigsaw or bandsaw; k) examining sketches, diagrams, samples, blueprints, or photographs to decide how designs are to be etched, cut, or engraved onto work pieces; l) measuring and computing dimensions of lettering, designs, or patterns to be engraved; m) engraving and printing patterns, ornamental designs, etchings, trademarks, figures or lettering onto flat or curved surfaces of a wide variety of metal, glass, plastic, or ceramic items; and n) etching decorative designs, calibration markings and other figures on glass articles.\nExamples of the occupations classified here: Brush painter, Ceramics decorator, Ceramics dipper, Ceramics painter, Ceramics spray painter, Decorative painter, Glass enameller, Glass engraver, Glass etcher, Glass painter, Glass sandblaster, Hand dipper, Linoleum block engraver, hand, Lithographic stone engraver, Metal engraving etcher, Metal printing die engraver, hand, Metal printing plate engraver, hand, Metal printing roller engraver, hand/machine, Mirror silverer, Photoengraver, Printing engraver, Printing plate retoucher, Rubber and wood engraver, hand, Sign-maker, Signwriter\nSome related occupations classified elsewhere: Building painter - 7131, Ceramics painting machine operator - 8181, Glass painting machine operator - 8181, Manufactured articles painter - 7132, Vehicle painter - 7132","version":"2022","source_id":810,"level":4,"normalized_name":"sign writers decorative painters engravers and etchers"},{"code":"7317","parent_code":"731","title":"HANDICRAFT WORKERS IN WOOD, BASKETRY AND RELATED MATERIALS","description":"Handicraft workers in wood and related materials apply traditional techniques like seasoning, impregnation to prepare wood, straw, rattan, reeds, clay, shells, and other materials, and carve, mold, assemble, weave, or paint and decorate various articles for personal or household use, or for decorative purposes. Basketry weavers, brush makers and related workers select and prepare materials like bristles, nylon, fiber, bass, whisker and wire to make wicker furniture, brushes and brooms and weave various kinds of baskets.\nTheir tasks include: a) preparing wood, straw, rattan, reeds, shells, or similar materials; b) carving floral and artistic designs on wooden surfaces for decorative purposes; c) painting free hand decorative designs on glass and pottery or porcelain ware; d) carving, assembling, weaving, painting and decorating various articles for personal or household use such as salad bowls, serving-spoons, cutting-boards, trays, vases, jugs, baskets, straw hats, straw mats and similar objects; e) carving, assembling, weaving and painting various decorative articles such as statues and other sculptures, chess pieces, jewelry, and similar objects; f) making wicker furniture from peeled and softened rattan, reeds, rushes, willow branches and similar materials; g) making various kinds of baskets by interlacing osier, rattan, reeds, rushes or similar materials; h) forming bottom of basket by interlacing strips of rattan, wood veneer or other material with framework of rods of material such as willow; i) inserting rods around edge of bottom between woven sections of bottom and bending them upright to serve as framework for sides; j) selecting and preparing brush materials, such as bristles, nylon, fibers and wire, and setting them in brush base; and k) selecting and preparing materials, such as broom corn, bass, whisker and fiber, and fastening them to broom handles;\nExamples of the occupations classified here: Basket maker, Basketry weaver, Broom maker, hand, Brush maker, Handicraft designer, Handicraft model maker, Paper box maker, hand, Paper handicraft worker, Rattan binder, Reed weaving handicraft worker, Wicker furniture maker, Wood carver, Wood cottage industry worker, Wooden articles handicraft worker\nSome related occupations classified elsewhere: Stone products machine operator - 8114, Wood products machine operator - 7523","version":"2022","source_id":811,"level":4,"normalized_name":"handicraft workers in wood basketry and related materials"},{"code":"7318","parent_code":"731","title":"HANDICRAFT WORKERS IN TEXTILE, LEATHER AND RELATED MATERIALS","description":"Their tasks include: a) spinning and dyeing with natural dyestuffs, wool, cotton and other fibers; b) lace-making and weaving, knitting, or embroidering various garments and articles for household use; c) preparing and dyeing hides with natural dyestuffs and making traditional footwear or handbags, belts and other accessories; d) spinning and winding yarn by hand; e) drawing warp threads into loom by hand; f) weaving plain or figured cloth, tapestry, lace, carpet or other fabrics on hand looms; g) making carpets by using a knotting technique; h) knitting garments and other articles on hand-operated machine or by hand; i) crocheting or making braid by hand; j) making nets by hand; k) grading and classifying natural textile fibers; l) washing wool fibers; m) cleaning and fluffing textile fibers; and n) forming fibers into sliver, combing them, combining sliver into sliver laps or forming sliver into rove.\nExamples of the occupations classified here: Carpet handicraft worker, Carpet weaver, Cloth weaver, Fabric examiner, Fiber aide, Fiber blender, Fiber carder, Fiber classer, Fiber grader, Fiber lapper, Fiber mixer, Fiber picker, Fiber preparer, Hand braid maker, Hand crocheter, Hand-operated machine knitter, Jacquard loom cloth weaver, Knitter, Leather handicraft worker, Loom threader, Net maker, hand, Tapestry maker, hand, Textiles fiber comber, Textiles fiber drawer, Textiles fiber rover, Textiles handicraft worker, Thread and yarn spinner, Tie dye maker, Weaver, Wool dryer, Wool scourer, Wool washer\nSome related occupations classified elsewhere: Knitting machine operator - 8152, Textile fiber combing machine operator - 8151, Weaving machine operator - 8152","version":"2022","source_id":812,"level":4,"normalized_name":"handicraft workers in textile leather and related materials"},{"code":"7319","parent_code":"731","title":"HANDICRAFT WORKERS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers handicraft workers who perform traditional handicrafts not classified elsewhere. For instance, the group includes traditional handicraft workers in non-precious metals and stone.\nExamples of the occupations classified here: Bar shampoo maker, Handicraft candle-maker, Metal toymaker, Soap maker, Stone articles handicraft worker, Toymaker (except metal)","version":"2022","source_id":813,"level":4,"normalized_name":"handicraft workers not elsewhere classified"},{"code":"7321","parent_code":"732","title":"PRE-PRESS TECHNICIANS","description":"Pre-press technicians proof, format, set and compose text and graphics into a form suitable for use in various printing processes and representation in other visual media.\nTheir tasks include: a) operating graphic cameras and other photographic equipment to reproduce camera-ready copy onto films, plates and digital output devices; b) using computer applications to generate images, text, layouts and impositions for print and other visual media displays; c) operating plate making equipment to reproduce images from film to printing plates, digital output devices and presses; d) operating computer screen-based equipment for scanning, color separation, color correction, masking, creative design, combining, imposing, retouching, and other processes used to transfer copy to film and produce film for plate, digital output and cylinder productions; e) carrying out digital and chemical proofing from digital systems, and negative and positive films; f) evaluating printed proofs, checking and correcting them for quality; and g) preparing and exposing carbon tissue for laying on cylinders by transfer method, and developing images.\nExamples of the occupations classified here: Compositor, Data scanner, Desktop publishing operator, Digitizer, Electronic pre-press technician, Linotype operator, Monotype keyboard operator, Photogravurist, Photolithographer, Printing plate maker, Screen maker, Screen printing plate mounter, Typesetter","version":"2022","source_id":814,"level":4,"normalized_name":"pre-press technicians"},{"code":"7322","parent_code":"732","title":"PRINTERS","description":"Printers set up and operate digital, letterpress, lithographic, flexographic, gravure, newspaper and other printing presses.\nTheir tasks include: a) setting, adjusting and monitoring substrate-feed mechanisms, delivery mechanisms, inking systems and other printing machine functions; b) mixing ink and solvents to standard, and regulating paper and ink supply during print runs; c) monitoring, evaluating and determining press to check print quality standards against proofs and detect malfunctions; d) producing a variety of printed products using relief, lithographic, flexographic and gravure printing presses, and in-line finishing systems; e) preparing plates, blankets and impression cylinders on small offset lithographic printing presses; f) loading paper into feeding mechanisms; g) monitoring machine operations and quality of printing; h) maintaining, adjusting, repairing and cleaning machines; and i) producing digital print images, and transferring and outputting images.\nExamples of the occupations classified here: Block printer, Developer, black and white, Developer, color, Digital press operator, Digital printing operator, Flexographic press operator, Gravure press operator, Large sheet-fed press operator, Offset Pressman, Offset printing press operator, Press roller maker, Printing feeder operator, Printing machine operator, Printing quality inspector, Rotogravure pressman, Screen printer, Screen printing press operator, Silk-screen printer, Silk-screen stencil cutter, Small press operator, Tarpaulin printer, Textile printer, Wallpaper printer, Web press operator","version":"2022","source_id":815,"level":4,"normalized_name":"printers"},{"code":"7323","parent_code":"732","title":"PRINT FINISHING AND BINDING WORKERS","description":"Print finishing and binding workers bind books and other publications, and finish printed products by hand or machine.\nTheir tasks include: a) setting up and supervising the operation of automatic binding and finishing equipment; b) binding full, half and limp-bound books, and repairing bindings; c) folding, collating and sewing signatures by machine and hand; d) operating paper guillotines for pre-press and post-press paper cutting and trimming, and programming electronically operated units; e) operating systems to insert printed material into newspapers, magazines and envelopes; f) embellishing printed products automatically and manually; and g) operating photographic and electronic reproduction devices.\nExamples of the occupations classified here: Binding bench worker, Book binder, Collator operator, Cutter operator, Foil Stamp operator, Folder operator, Gatherer operator, Multibinder operator, Perfect binder operator, Saddle stitch operator, Small machine bindery worker","version":"2022","source_id":816,"level":4,"normalized_name":"print finishing and binding workers"},{"code":"7411","parent_code":"741","title":"BUILDING AND RELATED ELECTRICIANS","description":"Building and related electricians install, maintain and repair electrical wiring systems and related equipment and fixtures.\nTheir tasks include: a) installing, maintaining and repairing electrical wiring systems and related equipment in various buildings such as schools, hospitals, commercial establishments, residential buildings and other structures; b) examining blueprints, wiring diagrams and specifications to determine sequences and methods of operation; c) planning layout and installation of electrical wiring, equipment and fixtures, based on job specifications and relevant standards; d) inspecting electrical systems, equipment, and components to identify hazards, defects, and the need for adjustment or repair; e) selecting, cutting and connecting wire and cable to terminals and connectors; f) measuring and laying out installation reference points; g) positioning and installing electrical switchboards; and h) testing continuity of circuit.\nExamples of the occupations classified here: Building electrician, Building repairs electrician, Building wiring electrician, Electrical inspector, Electrician, Industrial electrician, Industrial wiring electrician, Maintenance electrician\nSome related occupations classified elsewhere: Electrical fitter - 7412, Electrical line installer - 7413, Electrical mechanic - 7412","version":"2022","source_id":817,"level":4,"normalized_name":"building and related electricians"},{"code":"7412","parent_code":"741","title":"ELECTRICAL MECHANICS AND FITTERS","description":"Electrical mechanics and fitters fit, adjust, install and repair electrical machinery and other electrical apparatus and equipment in buildings, factories, workshops, or other places.\nTheir tasks include: a) fitting, adjusting and repairing various kinds of electrical machinery and motors, generators, switchgear and control apparatus, instruments, or electrical parts of elevators and related equipment; b) fitting, adjusting and repairing electrical parts in domestic appliances, industrial machines and other appliances; c) inspecting and testing manufactured electrical products; d) installing, testing, connecting, commissioning, maintaining and modifying electrical equipment, wiring and control systems; e) designing, installing, maintaining, servicing and repairing electric and hydraulic passenger and freight lifts, escalators, moving walkways and other lift equipment; f) connecting electrical systems to power supply; and g) replacing and repairing defective parts.\nExamples of the occupations classified here: Armature builder, Auto electrician, Automotive electrician, Electric meter repairman, Electric motor and generator fitter, Electric motor repairman, Electrical tester, Electrical fitter (general), Electrical generator fitter, Electrical inspector, Electrical mechanic, Industrial electrician, Lift mechanic, Plant electrician, Transformer repairman\nSome related occupations classified elsewhere: Electrical equipment assembler - 8212, Electronics mechanic - 7421","version":"2022","source_id":818,"level":4,"normalized_name":"electrical mechanics and fitters"},{"code":"7413","parent_code":"741","title":"ELECTRICAL LINE INSTALLERS AND REPAIRERS","description":"Electrical line installers and repairers install, repair and join electrical transmission and supply cables and related equipment.\nTheir tasks include: a) installing and repairing overhead and underground electrical power and electrical traction lines; b) making joints in overhead and underground cables; c) adhering to safety practices and procedures, such as checking equipment regularly and erecting barriers around work areas; d) opening switches or attaching grounding devices to remove electrical hazards from disturbed or fallen lines or to facilitate repairs; e) climbing poles or using truck-mounted buckets to access equipment; and f) identifying defective sectionalizing devices, circuit breakers, fuses, voltage regulators, transformers, switches, relays, or wiring, using wiring diagrams and electrical-testing instruments.\nExamples of the occupations classified here: Cable jointers, Cable puller, Electric cable and line installer, Electric cable jointer, Electric power line worker, Electrical line installer, Lineman/electric power, Ride maintenance mechanic\nSome related occupations classified elsewhere: Data and telecommunications cabler - 7422, Telecommunications line worker - 7422","version":"2022","source_id":819,"level":4,"normalized_name":"electrical line installers and repairers"},{"code":"7414","parent_code":"741","title":"ELECTRIC VEHICLE MECHANICS AND REPAIRERS","description":"Electric vehicle mechanics and repairers are responsible for inspections, maintenance and repair of electric vehicles.\nTheir task include: a) maintenance and repair, including troubleshooting of power line, as needed; and b) diagnose, service and repair high voltage EVs and commercial charging stations.\nExamples of the occupations classified here: Electric Vehicle (EV) mechanic, Electric Vehicle (EV) repairer\nSome related occupations classified elsewhere: Electric vehicle (EV) charging service personnel/attendant - 5245, Electric vehicle (EV) electrical service technician - 3113, Electric vehicle (EV) fleet and depot safety officer - 3257, Electric vehicle (EV) mechanical service technician - 3115, Electric vehicle (EV) test technician - 3119, Electric vehicle supply equipment (EVSE) installation technician - 3113, Motor vehicle inspection system (MVIS) electric vehicle (EV) testing specialist - 3119","version":"2022","source_id":820,"level":4,"normalized_name":"electric vehicle mechanics and repairers"},{"code":"7421","parent_code":"742","title":"ELECTRONICS MECHANICS AND SERVICERS","description":"Electronics mechanics and servicers fit, maintain, adjust and repair electronic equipment such as commercial and office machines and electronic instruments and control systems.\nTheir tasks include: a) examining and testing machines, instruments, components, other equipment, instruments and control systems to identify faults; b) adjusting, repairing, and replacing worn and defective parts and wiring, and maintaining machines, equipment and instruments; c) reassembling, test operating and adjusting equipment; d) installing electronic instruments and control systems; e) coordinating work with that of engineers, technicians, and other maintenance personnel; f) interpreting test data to diagnose malfunctions and systemic performance problems; g) installing, adjusting, repairing or replacing electrical and electronic components, assemblies, and systems using hand tools, power tools, or soldering irons; h) connecting components to assemblies such as radio systems, instruments, magnetos, inverters, and in-flight refueling systems; and i) keeping records of maintenance and repair work.\nExamples of the occupations classified here: Automated teller machines mechanic, Avionics aircraft maintenance engineer, Avionics technician, Electronic equipment servicer, Electronic mechanic, Office equipment technician, Office machinery fitter, Office machines mechanic, Photocopy machine technician, Radio mechanic, Reprographic equipment technician, Television repairer, Video electronics service/repairer\nRelated occupation classified elsewhere: Air traffic safety technician - 3155","version":"2022","source_id":821,"level":4,"normalized_name":"electronics mechanics and servicers"},{"code":"7422","parent_code":"742","title":"INFORMATION AND COMMUNICATIONS TECHNOLOGY INSTALLERS AND SERVICERS","description":"Information and communications technology (ICT) installers and servicers install, repair and maintain telecommunications equipment, data transmission equipment, cables, antennae and conduits and repair, fit and maintain computers.\nTheir tasks include: a) maintaining, troubleshooting, testing and repairing computers, data transmission equipment and computer peripherals; b) fitting and adjusting computer hardware; c) installing, maintaining, repairing, and diagnosing malfunctions of microwave, telemetry, multiplexing, satellite and other radio and electromagnetic wave communications systems; d) providing technical advice and information, and monitoring the performance of complex telecommunications networks and equipment; e) installing and repairing cabling for computer, radio, telephone and television transmission; f) joining telecommunications and data cables and sealing sheathes; and g) installing, maintaining and repairing antennae used in communications.\nExamples of the occupations classified here: Communication rigger, Communications technician, Communications technology servicer, Computer equipment fitter, Computer hardware installer, Computer servicer/repairer, Data and telecommunications cabler, Electronic products inspector, Electronic products tester, Hardware technician, Private Automatic Branch Exchange (PABX) technician, Radio equipment installer, Telecommunication equipment installer, Telecommunication equipment repairer, Telecommunications line worker, Telephone installer, Telephone mechanic\nRelated occupation classified elsewhere: Telecommunications engineering technician - 3522","version":"2022","source_id":822,"level":4,"normalized_name":"information and communications technology installers and servicers"},{"code":"7511","parent_code":"751","title":"BUTCHERS, FISHMONGERS AND RELATED FOOD PREPARERS","description":"Butchers, fishmongers and related food preparers slaughter animals, clean, cut and dress meat and fish, remove bones and prepare related food items or preserve meat, fish and other foods and food products by drying, salting or smoking.\nTheir tasks include: a) slaughtering animals; b) flaying and trimming carcasses; c) boning, cutting and dressing meat and fish for sale or further processing; d) preparing ingredients and making sausages and similar products using chopping, mixing and shaping machines; e) curing meat, fish and other foods; f) operating smokehouses or ovens to smoke meat, fish and other foodstuffs; g) cooking or in other ways preparing meat, fish and related food items for sale; h) selling meat or fish to customers, including wrapping, weighing and labelling products, and receiving payment.\nExamples of the occupations classified here: Butcher, Fish deboner, Fish filleter, Fish processing worker, Fishmonger, Meat cutter, Slaughterer\nSome related occupations classified elsewhere: Fish processing machine operator - 8160, Meat processing machine operator - 8160, Shop keeper - 5221","version":"2022","source_id":823,"level":4,"normalized_name":"butchers fishmongers and related food preparers"},{"code":"7512","parent_code":"751","title":"BAKERS, PASTRY-COOKS AND CONFECTIONERY MAKERS","description":"Bakers, pastry-cooks and confectionery makers make various kinds of bread, cakes, and other flour products, as well as handmade chocolate and sugar confectionery.\nTheir tasks include: a) making bread, cakes, biscuits, pastries, pies and other flour products; b) making handmade confectionery from mixtures of sugar, chocolate and other ingredients using hand tools and some machines; c) combining measured ingredients in bowls of mixing, blending, or cooking machinery; d) checking the quality of raw materials to ensure that standards and specifications are met; e) applying glazes, icings, or other toppings to baked goods, using spatulas or brushes; f) checking the cleanliness of equipment and operation of premises before production runs to ensure compliance with occupational health and safety regulations; g) monitoring oven temperatures and product appearance to determine baking times; and h) coordinating the forming, loading, baking, unloading, de-panning and cooling of batches of bread, rolls, pastry and confectionary products.\nExamples of the occupations classified here: Baker, Bread baker, Cake decorator, Chocolate maker, Confectioner, Kakanin maker, Noodle maker, Pastry maker, Pastry-cook\nSome related occupations classified elsewhere: Bakery products machine operator - 8160, Bread production machine operator - 8160, Chocolate production machine operator - 8160, Cook - 5120","version":"2022","source_id":824,"level":4,"normalized_name":"bakers pastry-cooks and confectionery makers"},{"code":"7513","parent_code":"751","title":"DAIRY PRODUCTS MAKERS","description":"Dairy products makers process butter and various types of cheese, cream or other dairy products.\nTheir tasks include: a) boiling or pasteurizing milk to achieve specified butter fat content; b) separating cream from milk and churning cream into butter; c) dumping measured amounts of starter and other ingredients into milk; d) curdling milk, heating curd until it reaches desired firmness, draining curd and placing cheese into molds to press it into shape; e) salting cheese and piercing or smearing cheese with cultured wash to develop mold growth; f) placing and turning cheese blocks on shelves to cure cheese; g) monitoring product quality before packaging by inspecting, taking samples and adjusting treatment conditions when necessary; and h) recording amounts of ingredients used, test results, and time cycles.\nExamples of the occupations classified here: Butter maker, Cheese maker, Ice cream maker\nSome related occupations classified elsewhere: Dairy products machine operator - 8160, Milk processing machine operator - 8160","version":"2022","source_id":825,"level":4,"normalized_name":"dairy products makers"},{"code":"7514","parent_code":"751","title":"FRUIT, VEGETABLE AND RELATED PRESERVERS","description":"Fruit, vegetable and related preservers process or preserve fruit, nuts and related foods in various ways including cooking, drying, salting, or juice or oil extraction.\nTheir tasks include: a) extracting juices from various fruits; b) extracting oils from oil-bearing seeds, nuts or fruits; c) cooking, salting or drying fruit, vegetables and related foods; d) mixing and adding ingredients such as pectin, sugar, spices and vinegar to assist preservation and enhance texture, appearance and flavor; and e) transferring preserved foods to sterile jars, bottles or other containers.\nExamples of the occupations classified here: Chutney maker, Food preserver, Fruit pickler, Fruit preserver, Jam maker, Oil expeller, Vegetable pickler, Vegetable preserver\nRelated occupation classified elsewhere: Canning machine operator - 8160","version":"2022","source_id":826,"level":4,"normalized_name":"fruit vegetable and related preservers"},{"code":"7515","parent_code":"751","title":"FOOD AND BEVERAGE TASTERS AND GRADERS","description":"Food and beverage tasters and graders inspect, taste and grade various types of agricultural products, food and beverages.\nTheir tasks include: a) inspecting, testing, tasting and smelling agricultural products, food and beverages at various stages of processing; b) determining quality, acceptability to consumer tastes and approximate value of products and grading them into appropriate classes; c) discarding inferior products; d) recording the grade and/or identification numbers on tags, receiving, or sales sheets; and e) weighing and measuring products.\nExamples of the occupations classified here: Coffee taster, Food grader, Food taster, Fruit grader, Liquor taster, Tea taster, Vegetable grader, Wine taster","version":"2022","source_id":827,"level":4,"normalized_name":"food and beverage tasters and graders"},{"code":"7516","parent_code":"751","title":"TOBACCO PREPARERS AND TOBACCO PRODUCTS MAKERS","description":"Tobacco preparers and tobacco products makers prepare tobacco leaves and make various tobacco products.\nTheir tasks include: a) grading cured tobacco leaves by type, quality and locality where grown; b) mixing tobacco leaves according to formula to obtain a blend of distinct flavor; c) tending vacuum container which moistens tobacco for further processing; d) removing midribs and stalks from tobacco leaves and shredding tobacco; and e) making cigars, cigarettes, snuff and other tobacco products by hand or with simple machines.\nExamples of the occupations classified here: Cigar maker, Cigarettes maker, Snuff maker, Tobacco blender, Tobacco grader, Tobacco stripper\nSome related occupations classified elsewhere: Cigar production machine operator - 8160, Cigarette production machine operator - 8160","version":"2022","source_id":828,"level":4,"normalized_name":"tobacco preparers and tobacco products makers"},{"code":"7521","parent_code":"752","title":"WOOD TREATERS","description":"Wood treaters operate and tend wood treatment processing equipment and machines to remove bark from logs, produce wood chips, season, preserve and treat wood, and produce waferboards, particleboards, hardboards, insulation boards, plywood, veneers and similar wood products.\nTheir tasks include: a) operating and tending kilns, treating tanks and other equipment to dry lumber, prepare and season wood and other wood products, and to treat chemically and impregnate wood products with preservatives; b) monitoring equipment operation, gauges, and panel lights in order to detect deviations from standards and to ensure that processes are operating according to specifications; c) assisting in maintaining processing equipment and machines as required; d) cleaning, lubricating and adjusting equipment; e) transporting materials and products to and from work areas, manually or using carts, handtrucks, or hoists; and f) completing and maintaining production reports.\nExamples of the occupations classified here: Dry kiln operator, Lumber kiln operator, Timber treating tank operator, Veneer applier, Veneer dryer tender, Wood seasoner\nRelated occupation classified elsewhere: Wood processing plant operator - 8172","version":"2022","source_id":829,"level":4,"normalized_name":"wood treaters"},{"code":"7522","parent_code":"752","title":"CABINET-MAKERS AND RELATED WORKERS","description":"Cabinet-makers and related workers make, decorate and repair wooden furniture, carts and other vehicles, wheels, parts, fittings, patterns, models and other wooden products using woodworking machines, machine tools and specialized hand tools.\nTheir tasks include: a) operating woodworking machines, such as power saws, jointers, mortisers and shapers, and using hand tools to cut, shape and form parts and components; b) studying plans, verifying dimensions of articles to be made, or preparing specifications and checking the quality and fit of pieces in order to ensure adherence to specifications; c) trimming joints and fitting parts and subassemblies together to form complete units using glue and clamps, and reinforcing joints using nails, screws or other fasteners; d) making, restyling and repairing various wooden articles, such as cabinets, furniture, vehicles, scale models, sports equipment and other parts or products; e) decorating furniture and fixtures by inlaying wood, applying veneer and carving designs; and f) finishing surfaces of wooden articles or furniture.\nExamples of the occupations classified here: Cabinet-maker, Cartwright, Cooper, Furniture cabinet-maker, Marquetry inlayer, Smoking wood pipe maker, Wheelwright, Wood patternmaker, Wooden furniture finisher, Wooden model maker\nSome related occupations classified elsewhere: Carpenters - 7115, Joiner - 7115, Wood and related products assemblers - 8219","version":"2022","source_id":830,"level":4,"normalized_name":"cabinet-makers and related workers"},{"code":"7523","parent_code":"752","title":"WOODWORKING MACHINE TOOL SETTERS AND OPERATORS","description":"Woodworking machine tool setters and operators set-up or operate and monitor automatic or semi-automatic woodworking machines, such as precision sawing, shaping, planning, boring, turning and woodcarving machines to fabricate or repair wooden parts for furniture, fixtures and other wooden products.\nTheir tasks include: a) setting-up, programming, operating and monitoring several types of woodworking machines for sawing, shaping, boring, drilling, planing, pressing, turning, sanding or carving to fabricate or repair wooden parts for furniture, fixtures and other wooden products; b) operating preset special-purpose woodworking machines to fabricate wooden products such as coat hangers, mop handles, clothes pins and other products; c) selecting knives, saws, blades, cutter heads, cams, bits, or belts according to workpiece, machine functions and product specifications; d) installing and adjusting blades, cutter heads, boring-bits and sanding-belts, and using hand tools and rules; e) setting and adjusting various kinds of woodworking machines for operation by others; and f) reading and interpreting specifications or following verbal instructions.\nExamples of the occupations classified here: Furniture production machine operator, Precision woodworking sawyer, Wood carving machine operator, Wood production machine operator, Wood products machine operator, Wood turner, Wood-planing machine setter-operator, Wood-shaping machine setter-operator, Woodworking lathe operator, Woodworking machine setter, Woodworking machine setter-operator, Woodworking machine set-up operator\nRelated occupation classified elsewhere: Wood and related products assemblers - 8219","version":"2022","source_id":831,"level":4,"normalized_name":"woodworking machine tool setters and operators"},{"code":"7531","parent_code":"753","title":"TAILORS, DRESSMAKERS, FURRIERS AND HATTERS","description":"Tailors, dressmakers, furriers and hatters fabricate, fit, alter and repair tailored or hand-made clothing; They produce made-to-measure clothing such as suits, overcoats, and dresses from textile fabrics, light leather, fur and other material, or make hats or wigs according to customer’s and clothing manufacturer’s specifications.\nTheir tasks include: a) making overcoats, suits, skirts, shirts, blouses, lingerie, corsetry, hats, wigs and similar garments often to clients' individual requirements; b) selecting textile fabrics, leather or fur pelts matching the desired size, color, texture, and quality of the garment; cutting to shape them to garment pattern and arranging them on pattern according to the design of the garment; c) making garment style changes, such as tapering trouser legs, narrowing lapels, and adding or removing padding; d) selecting and modifying commercial patterns to customers' and clothing manufacturers' specifications and fit; e) fitting, altering and repairing tailored clothing, dresses, coats and other made-to-measure garments according to customers' requests; f) making and caring for costumes used in theatrical, television and motion picture productions; g) folding, twisting, and draping material, such as satin or silk, or sewing ribbon or cloth in the form of artificial flowers or bows around crown and brim to shape and decorate hats; h) sewing, and fastening together materials and hair strands to make wigs; i) blending shades of hair to give natural appearance to wigs and arranging woven hair in specified position and sewing hair together to form hairpiece; j) making, altering, restyling and repairing fur garments and other fur articles; and k) reclaiming furs or skins from old coats, gluing fabric to interior of fur coats and trimming fur garments.\nExamples of the occupations classified here: Dressmaker, Fur grader, Fur trimmer, Furrier, Hatter, Milliner, Tailor\nSome related occupations classified elsewhere: Sewing machine operator - 8153, Textile handicraft worker - 7318","version":"2022","source_id":832,"level":4,"normalized_name":"tailors dressmakers furriers and hatters"},{"code":"7532","parent_code":"753","title":"GARMENT AND RELATED PATTERNMAKERS AND CUTTERS","description":"Textile, leather and related patternmakers and cutters create precision master patterns for production of garments, other textile, and leather or fur products. They mark, cut, shape and trim textile, light leather and other materials according to blueprints or specifications in the manufacture of garments, hats and caps, gloves and miscellaneous products.\nTheir tasks include: a) creating a master pattern for each size within a range of garment sizes, using charts, drafting instruments, computers, and/or grading devices; b) creating the “blueprint” or pattern pieces for a particular apparel design with the aid of a computer; c) calculating dimensions of patterns according to sizes, considering stretching of material; d) drawing details on outlined parts to indicate where parts are to be joined, as well as the positions of pleats, pockets, buttonholes on garments, decorative stitching on shoe parts or eyelets on canvas products using computers or drafting instruments; e) positioning templates or measuring materials to locate specified points of cuts or to obtain maximum yields and mark fabric accordingly; f) laying out master pattern on fabric and cutting sample pattern; g) testing patterns by making and fitting sample garments; h) placing patterns on top of layers of fabric and cutting fabric following patterns, using electric or manual knives, cutters or computer numerically controlled cutting devices; i) cutting fabric or fur pelts to make parts for garments and other fur articles; j) trimming excess material or cutting threads off finished products, such as cutting loose ends of a finished product; k) positioning leather on cutting bed of machine, maximizing usage according to skin grain, skin flaws and skin stretch; and l) performing pattern-making, marking and cutting tasks in the manufacture of other products such as soft furnishings and canvas goods.\nExamples of the occupations classified here: Fur patternmaker, Garment cutter, Garment marker, Garment patternmaker, Glove cutter, Hat and cap patternmaker, Leather cutter, Leather patternmaker, Textile cutter, Textile patternmaker\nRelated occupation classified elsewhere: Textile patternmaking machine operator - 8159","version":"2022","source_id":833,"level":4,"normalized_name":"garment and related patternmakers and cutters"},{"code":"7533","parent_code":"753","title":"SEWING, EMBROIDERY AND RELATED WORKERS","description":"Sewing, embroidery and related workers sew together, repair, renovate and decorate garments, gloves and other products of textile, fur, light leather and other materials and fabricate tents sails, awnings and tarpaulins. They work mainly by hand using a needle and thread but may perform some tasks using a sewing machine.\nTheir tasks include: a) repairing defective or damaged portion of cloth or garment by hand, using matching thread and needle; b) removing stitches from garments to be altered, using rippers or razor blades; c) selecting thread according to specifications or color of parts or dying thread to match color and shade of cloth to be darned; d) patching holes, sewing tears and ripped seams, or darning defects in items, using needles and thread; e) pulling knots to the wrong sides of garments, using hooks; f) trimming ends with scissors to make mended portion look uniform with pattern of cloth; g) sewing ornamental designs by hand over stamped, printed or stenciled patterns on fabric using needle and colored thread; h) embroidering ornamental designs on cloth by hand or machine using needle and colored threads; i) softening leather or shoe material with water to prepare it for sewing; j) sewing or gluing decorative trimmings to articles, such as hats, caps, or millinery; k) hand sewing umbrella covers to frames, tacking cover to ribs along seams and sewing corners to tip of rib and sewing ties to outside of cover to hold umbrella when folded; and l) fabricating and assembling thick cloth, canvas and like materials into sails, awning, tarpaulins and tents.\nExamples of the occupations classified here: Doormat maker, Embroiderer, Fur sewer, hand, Glove sewer, Rug maker, Stitcher, Stuffed toy maker, Umbrella maker\nSome related occupations classified elsewhere: Dressmaker - 7531, Sewing machine operator - 8153, Textiles handicraft worker - 7318","version":"2022","source_id":834,"level":4,"normalized_name":"sewing embroidery and related workers"},{"code":"7534","parent_code":"753","title":"UPHOLSTERERS AND RELATED WORKERS","description":"Upholsterers and related workers install, repair and replace upholstery of furniture, fixtures, orthopedic appliances; seats, panels, convertible and vinyl tops and other furnishings of automobiles, railway coaches, aircraft, ships and similar items with fabric, leather, rexine or other upholstery material. They also make and repair cushions, quilts and mattresses.\nTheir tasks include: a) discussing upholstery fabric, color, and style with customers and providing cost estimate for upholstering furniture or other items; b) making upholstery patterns from sketches, customer descriptions or blueprints; c) laying out, measuring and cutting upholstery materials following patterns, templates, sketches, or design specifications; d) installing, arranging and securing springs, padding and covering material to furniture frames; e) sewing upholstery materials by hand to seam cushions and joining sections of covering materials; f) sewing rips or tears in material, or creating tufting, using needle and thread; g) tacking, gluing or sewing ornamental trims, buckles, braids, buttons and other accessories to covers or frames on upholstered items; h) laying out, cutting, fabricating and installing upholstery in aircrafts, motor vehicles, railway cars, boats and ships; i) repairing raw hide covering of artificial limbs; j) renovating antique furniture using a variety of tools including ripping chisels, magnetic hammers and long needles; k) collaborating with interior designers to decorate rooms and coordinate furnishing fabrics; and l) making quilts, cushions and mattresses.\nExamples of the occupations classified here: Furniture upholsterer, Mattress maker, Orthopedic upholsterer, Vehicle upholsterer\nRelated occupation classified elsewhere: Sewing machine operator - 8153","version":"2022","source_id":835,"level":4,"normalized_name":"upholsterers and related workers"},{"code":"7535","parent_code":"753","title":"PELT DRESSERS, TANNERS AND FELLMONGERS","description":"Pelt dressers, tanners and fellmongers trim, scrape, clean, tan, buff and dye animal hides, pelts or skins to produce leather stock and finished furs for making garments and other products.\nTheir tasks include: a) sorting and grading pelts, hides and skins according to color, shading, size and density; b) scraping particles of flesh, fat, or protective tissue from skins or pelts to clean and soften them; c) removing hair from skin or hides soaked in lime water; d) preparing hides by curing them with salt; e) removing long, coarse hair from pelts and trimming underlying hair to even length; f) tanning and dressing pelts to improve luster and beauty or restore natural appearance of pelts; g) preparing bark and myrobalan liquor for treating hides or skins; h) treating hides and skins in tanning solution to convert them into leather; i) tinting or dyeing furs to enhance natural shades of fur; j) removing wrinkles and setting grains on wet hide or skin; k) dressing and applying dyes and stains to leather; l) stretching and smoothing dressed pelts; and m) seasoning leather by applying chemical solution or oil evenly on surface by hand brush and allowing it to dry in open air.\nExamples of the occupations classified here: Fellmonger, Hide grader, Hide splitter, Leather currier, Leather stainer, Pelt dyer, Pelt grader, Skin grader, Tanner\nRelated occupation classified elsewhere: Tanning machine operator - 8155","version":"2022","source_id":836,"level":4,"normalized_name":"pelt dressers tanners and fellmongers"},{"code":"7536","parent_code":"753","title":"SHOEMAKERS AND RELATED WORKERS","description":"Shoemakers and related workers make, modify and repair standard, custom or orthopedic footwear and natural or synthetic leather articles, such as luggage, handbags and belts, (except for leather garments, hats and gloves), or participate in the manufacture of shoes and related goods. They decorate, reinforce or finish shoes, luggage, handbags and belts.\nTheir tasks include: a) making, modifying and repairing standard footwear to meet individual requirements; b) making, modifying and repairing orthopedic or therapeutic footwear according to doctors' prescriptions, or modifying existing footwear for people with foot problems and special needs; c) repairing belts, luggage, purses and similar products; d) taking plaster casts of deformed legs or foot to prepare drawings; e) preparing inserts, heel pads, and lifts from casts of customers' feet; f) studying drawings and other specifications to make footwear according to customer’s needs; g) studying work orders and/or shoe part tags to obtain information about workloads, specifications, and the types of materials to be used; h) checking the texture, color, and strength of leather to ensure that it is adequate for a particular purpose; i) cutting out, shaping and padding parts for making leather articles; j) sewing rips or patching holes to repair articles, such as purses, belts, shoes, and luggage; k) removing and examining shoes, shoe parts, and designs to verify conformance to specifications such as proper embedding of stitches in channels; l) attaching accessories or ornamentation to decorate or protect products; and m) making and repairing articles such as saddles and harnesses for animals, luggage, handbags, brief-cases, leather bags, belts and other accessories.\nExamples of the occupations classified here: Cobbler, Footwear cutter, Footwear finisher, Footwear laster, Footwear patternmaker, Footwear repairer, Leather goods maker, Leather shoemaker, Orthopedic footwear maker, Orthopedic shoemaker, Saddle and harness maker, Saddler, Shoemaker\nSome related occupations classified elsewhere: Furrier - 7531, Hatter - 7531, Shoe production machine operator - 8156","version":"2022","source_id":837,"level":4,"normalized_name":"shoemakers and related workers"},{"code":"7541","parent_code":"754","title":"UNDERWATER DIVERS","description":"Underwater divers work under the surface of water, using underwater breathing apparatus to inspect, install, repair, and remove equipment and structures, conduct tests or experiments, rig explosives, photograph structures or marine life or find and recover missing items and persons. \nTheir tasks include: a) taking safety precautions, such as monitoring dive lengths and depths, and registering with authorities before diving expeditions begin; b) checking and maintaining diving equipment such as helmets, masks, air tanks, diving suits, harnesses and gauges; c) descending into water with the aid of diver helpers, using scuba gear or diving suits; d) working under water to lay and repair bridges, piers and harbor-wall foundations; e) inspecting for suspected damage and making minor repairs to ships' hulls and underwater installations; f) reporting on condition of wrecked ships; g) removing underwater obstructions; h) drilling holes for underwater blasting; i) performing various underwater tasks connected with salvage work or recovering dead bodies; j) gathering of shellfish, sponges, and other aquatic life forms for research purposes; k) communicating with workers on the surface while underwater, using signal lines or telephones; l) obtaining information about diving tasks and environmental conditions.\nExamples of the occupations classified here: Salvage frogman, Underwater welder, Underwater worker\nSome related occupations classified elsewhere: Commercial diver - 6229, Subsistence diver - 6340","version":"2022","source_id":838,"level":4,"normalized_name":"underwater divers"},{"code":"7542","parent_code":"754","title":"SHOTFIRERS AND BLASTERS","description":"Shot firers and blasters, position, assemble, and detonate explosives at mining, quarrying and demolition sites.\nTheir tasks include: a) ensuring workplace safety and explosives handling, storage and transport procedures and regulations are followed; b) planning and giving instructions for the lay out, depth and diameter of blast holes; c) checking depth and cleanliness of blast holes; d) determining quantity and type of explosives to be used; e) loading explosives into blast holes; f) assembling, or directing other workers to assemble, primer charges using detonators and explosive cartridges, and attaching electrical wires, fuses and detonating cords to primers; g) connecting wires, fuses and detonator cords into series, testing electrical circuits and repairing malfunctions, and connecting series to blasting machines; h) covering charges, filling blast holes with rock dust, sand and other materials, and tamping material to compact charges; i) ensuring all explosives are detonated, and reporting and attending to misfires; j) declaring blast areas safe before and after detonation of explosives; and k) compiling and maintaining records about usage of explosives in compliance with laws and regulations.\nExamples of the occupations classified here: Blaster, Powder monkey, Powderman, Shotfirer\nSome related occupations classified elsewhere: Mining driller - 8111, Mining laborer - 9311, Mining Supervisor - 3121, Oil and gas well driller - 8113, Quarry laborer - 9311","version":"2022","source_id":839,"level":4,"normalized_name":"shotfirers and blasters"},{"code":"7543","parent_code":"754","title":"PRODUCT GRADERS AND TESTERS (EXCEPT FOODS AND BEVERAGES)","description":"Product graders and testers (except foods and beverages) inspect , test, sort, sample, and weigh raw materials, manufactured components and non-comestible goods produced or sold, to ensure compliance with quality standards and to identify defects, wear, and deviations from specifications, and to grade and classify them according to their quality.\nTheir tasks include: a) inspecting and testing products, parts and materials for conformity with specifications and standards; b) grading and classifying natural textile fibers for spinning and winding; c) discarding or rejecting products, materials, and equipment not meeting specifications; d) analyzing and interpreting blueprints, data, manuals, and other materials to determine specifications, inspection and testing procedures; e) notifying supervisors and other personnel of production problems, and assisting in identifying and correcting these problems; f) recording inspection or test data, such as weights, temperatures, grades, or moisture content, and quantities inspected or graded; g) marking items with details such as grade and acceptance or rejection status; h) measuring dimensions of products using instruments such as rulers, calipers, gauges, or micrometers; and i) analyzing test data and making computations as necessary to determine test results.\nExamples of the occupations classified here: Product grader, Quality inspector, Wool classer\nSome related occupations classified elsewhere: Food grader - 7515, Fruit grader - 7515, Fur grader - 7531, Pelt grader - 7535, Product safety inspector - 3257, Vegetable grader - 7515","version":"2022","source_id":840,"level":4,"normalized_name":"product graders and testers except foods and beverages"},{"code":"7544","parent_code":"754","title":"FUMIGATORS AND OTHER PEST AND WEED CONTROLLERS","description":"Fumigators and other pest and weed controllers use chemicals to remove harmful insects, small animals, wild plants and other unwanted organisms to prevent damage to crops and to buildings and other structures and their surroundings and to prevent health risks.\nTheir tasks include: a) operating and monitoring equipment for spraying pests and weeds; b) mixing chemicals according to instructions; c) covering areas to specified depths with pesticides, applying knowledge of weather conditions, droplet sizes, elevation-to-distance ratios, and obstructions; d) spraying or releasing chemical solutions or toxic gases and setting traps to kill pests and vermin, such as mice, termites, and roaches; e) lifting, pushing, and swinging nozzles, hoses, and tubes in order to direct spray over designated areas; f) filling sprayer tanks with water and chemicals; and g) cleaning and servicing machinery to ensure operating efficiency.\nExamples of the occupations classified here: Fumigator, Pest controller, Weed controller\nRelated occupation classified elsewhere: Aerial crop sprayer - 3153","version":"2022","source_id":841,"level":4,"normalized_name":"fumigators and other pest and weed controllers"},{"code":"7549","parent_code":"754","title":"CRAFT AND RELATED WORKERS NOT ELSEWHERE CLASSIFIED","description":"This group covers craft and trade occupations not classified elsewhere in major group 7, Craft and related trades workers. For instance, the group includes those who mold, slice, grind and polish optical lenses. \nTheir tasks would include: a) heating, molding and pressing optical glass to make lens blanks; and b) grinding and polishing lens blanks.\nExamples of the occupations classified here: Flower arranger, Optical lens finisher, Optical lens molder","version":"2022","source_id":842,"level":4,"normalized_name":"craft and related workers not elsewhere classified"},{"code":"8111","parent_code":"811","title":"MINERS AND QUARRIERS","description":"Miners and quarriers operate plant, machinery and hand tools to extract rock, minerals and non-metallic deposits from underground and surface mines and quarries.\nTheir tasks include: a) positioning, operating and monitoring the performance of a variety of underground and surface mining equipment including continuous mining, cutting and channeling plant; b) setting up and operating drilling equipment in underground and surface mines and quarries; c) operating machinery and using tools to remove loosened rock, ore, coal and other deposits; d) preparing, fitting and installing supports in underground workings including rock bolts; e) operating machinery to open new shafts, drives, air vents and rises; f) operating auxiliary plant such as pumps to expel air, water and mud; g) performing minor maintenance and repairs and lubricating and cleaning plant, machines and tools; h) completing records detailing operations completed during shifts; and i) collecting mineral samples for laboratory analysis.\nExamples of the occupations classified here: Bogger operator, Continuous miner operator, Drilling machine operator, Jumbo operator, Mining dragline operator, Mining driller, Mining plant operator, Mining roof bolter\nSome related occupations classified elsewhere: Blaster - 7542, Mining laborer - 9311, Mining supervisor - 3121, Oil and gas well driller - 8113, Quarry laborer - 9311, Shotfirer - 7542","version":"2022","source_id":843,"level":4,"normalized_name":"miners and quarriers"},{"code":"8112","parent_code":"811","title":"MINERAL AND STONE PROCESSING PLANT OPERATORS","description":"Mineral and stone processing plant operators operate and monitor machinery and equipment for processing rocks, minerals and stone to recover refined products for immediate use or further processing.\nTheir tasks include: a) setting up and operating stationary plant and machinery which grind, crush, cut, saw and slice rocks, minerals and stones according to the specifications for the job; b) positioning blocks and slabs of stone onto machines for sawing, cutting and further working; c) monitoring and maintaining the flow of unprocessed rocks, minerals and stones from conveyors into machines; d) operating washing, separating, leaching, precipitating, filtering, extracting and combining equipment to remove waste material and recover minerals; e) combining mineral ores with solvents to facilitate further processing; f) separating metal and mineral concentrates from ore and alluvial deposits by thickening, flotation, gravity separation, filtration, and or magnetic and electrostatic separation; g) observing meters, gauges and control panels, and adjusting valves and controls to ensure the safe and efficient operation of equipment, and detecting malfunctions, and assisting with plant and machinery maintenance and repair; h) examining processed materials visually or with hands to ensure compliance with established standards and job specifications, and may collect samples for testing in laboratories; i) recording information about processing completed during shifts, such as quantities, types and dimensions of materials produced; and j) sorting, stacking and moving processed minerals and stone for packaging, further processing or shipping.\nExamples of the occupations classified here: Coal washer, Crushing machine operator, Cutting machine operator, Gold precipitator, Gold precipitator, Grinding machine operator, Mineral machine operator, Mineral or stone processing crusher operator, Mineral processing flotation worker, Mineral-processing operator, Minerals milling machine operator, Silver precipitator, Splitting machine operator, Stone cutting or processing machine operator, Stone machine operator\nSome related occupations classified elsewhere: Cast stone production machine operator - 8114, Stone cutter using hand or hand-powered tools - 7113, Stone polisher using hand or hand-powered tools - 7113, Stone polishing machine operator - 8114, Stone splitter using hand or hand-powered tools - 7113, Stonemason - 7113","version":"2022","source_id":844,"level":4,"normalized_name":"mineral and stone processing plant operators"},{"code":"8113","parent_code":"811","title":"WELL DRILLERS AND BORERS AND RELATED WORKERS","description":"Well drillers and borers and related workers position, assemble and operate drilling machinery and related equipment to sink wells, extract ore, liquids and gases or for a variety of other purposes.\nTheir tasks include: a) dismantling, moving and assembling drilling rigs and auxiliary equipment; b) assembling and dismantling pipes, casings and drill heads, and replacing dysfunctional equipment; c) operating controls to lower and raise drill pipes and casings in and out of wells, regulate pressure in the well and control the speed of tools; d) preparing drilling fluid and checking the operation of pumps to ensure adequate circulation of fluid in drill pipe and well; e) monitoring gauges and other indicators and listening to equipment to detect malfunctions and unusual well conditions, and determining the need to change drilling or equipment; f) maintaining, adjusting, repairing and cleaning drilling rigs, hoisting and other machinery; g) maintaining records of drilling and servicing operations; h) operating machines and tools to extract dust, cuttings and lost and broken drilling equipment from holes and wells; i) closing and sealing wells no longer in use; and j) may supervise and train crew members.\nExamples of the occupations classified here: Artesian well driller, Bore sinker, Boring equipment operator, Derrick operator, Derrickman, Developmental driller, Directional driller, Drilling plant operator, Drilling rig operator, Oil or gas well driller, Power-tong operator, Toolpusher, Tourpusher, Well sinker\nSome related occupations classified elsewhere: Blaster - 7542, Miner - 8111, Quarrier - 8111","version":"2022","source_id":845,"level":4,"normalized_name":"well drillers and borers and related workers"},{"code":"8114","parent_code":"811","title":"CEMENT, STONE AND OTHER MINERAL PRODUCTS MACHINE OPERATORS","description":"Cement, stone and other mineral products machine operators operate and monitor machines for manufacturing and finishing precast concrete, bitumen, and stone products, and making cast stone for building purposes. \nTheir tasks include: a) operating extrusion, molding, mixing, pumping, compacting, grinding and cutting machinery to manufacture and finish precast concrete and stone products; b) operating plant to produce cement, lime and clinker, including loading and unloading ingredients and operating continuous feed equipment such as pumps and conveyors; c) operating plant and machines which weigh and mix sand, gravel, cement, water and other ingredients to make concrete; d) operating plant and machinery which assembles and fills molds with concrete and artificial stone mixtures, removes castings from molds and finishes surfaces of precast products; e) cutting, grinding, drilling, sandblasting and polishing concrete products and stone blocks, slabs and products to the specifications for the job; f) checking production plans and specifications to determine and select materials, ingredients, procedures, components, settings and adjustments for extrusion, molding, mixing and compacting machines; g) monitoring plant and machines during operation by observing instruments such as temperature and pressure gauges, and adjusting controls and reporting malfunctions as necessary; h) collecting and examining samples of mixtures and finished products for conformity to specifications and adjusting machine settings accordingly; i) checking and maintaining production records, including information about quantities, dimensions and types of materials and goods produced; and j) arranging and assisting with plant and machinery maintenance and repair.\nExamples of the occupations classified here: Cast-concrete products machine operator, Cast-stone products machine operator, Cement production plant operator, Concrete finishing machine operator, Concrete production machine operator, Concrete stone fabricator, Industrial diamond polishing machine operator, Mineral ore processing plant operator, Stone polishing machine operator, Stone products machine operator\nSome related occupations classified elsewhere: Brick, pottery or tiles kiln operator - 8181, Extruding clay press operator - 8181, Stone polisher using hand or hand-powered tools - 7113, Stone processing machine operator - 8112","version":"2022","source_id":846,"level":4,"normalized_name":"cement stone and other mineral products machine operators"},{"code":"8121","parent_code":"812","title":"METAL PROCESSING PLANT OPERATORS","description":"Metal processing plant operators, operate, monitor, adjust and maintain, single process machinery and equipment to process and convert mineral ores and refine, harden, roll and extrude metals.\nTheir tasks include: a) setting up, preparing and adjusting mineral ore and metal processing machinery to carry out one step in the overall mineral ore or metal processing operation; b) operating single-function machinery to grind, separate, filter, mix, treat, cast, roll, refine or otherwise process metals and mineral ores; c) observing gauges, meters, computer printouts, video monitors and products to ensure correct operation of machine and verify specified processing conditions; d) adjusting equipment, valves, pumps, controls and process equipment; e) controlling the preparation, measuring and feeding of raw materials and processing agents into plant; f) controlling process start-up and shut-down, troubleshooting and monitoring outside process equipment; g) verifying equipment for malfunctions, carrying out routine operating tests and arranging for maintenance; and h) analyzing sample products, performing tests, recording data and writing production logs.\nExamples of the occupations classified here: Aluminum cutting machine operator, Annealer, Ladle pourer, Metal drawing machine operator, Metal extruding machine operator, Metal extrusion plant operator, Metal hardening furnace operator, Metal heat treating operator, Steel roller\nSome related occupations classified elsewhere: Blast furnace operator - 3135, Central control caster - 3135, Metal coating machine operator - 8122, Rolling mill control operator - 3135","version":"2022","source_id":847,"level":4,"normalized_name":"metal processing plant operators"},{"code":"8122","parent_code":"812","title":"METAL FINISHING, PLATING AND COATING MACHINE OPERATORS","description":"Metal finishing-, plating and coating-machine operators operate and monitor equipment which finishes, plates and coats metal articles or parts, in order to give them improved resistance to corrosion and abrasion, for decorative purposes, or to impart electrical or magnetic properties.\nTheir tasks include: a) operating and monitoring equipment which cleans metal articles in preparation for electroplating, galvanizing, enameling or similar processes; b) operating and monitoring electroplating equipment; c) operating and monitoring hot-dip equipment used to coat iron and steel products; d) operating and monitoring machines which automatically coat wire with non ferrous metal; e) operating and monitoring equipment used to spray molten metal or other substances on metal products to provide a protective or decorative coating or to build up worn or damaged surfaces; f) operating and monitoring equipment used to impart a rust-resistant finish to metal articles by treating them with chemicals and heating them; g) checking proper thickness of plating using micrometers, calipers or other devices recording data and writing production logs; and h) preparing and mixing metalizing solutions according to formulas or specifications.\nExamples of the occupations classified here: Metal coating machine operator, Metal finishing machine operator, Metal painting machine operator, Metal plating machine operator, Metal polishing machine operator\nSome related occupations classified elsewhere: Metal processing control operator - 3135, Metal production process controller - 3135, Vehicle painter - 7132","version":"2022","source_id":848,"level":4,"normalized_name":"metal finishing plating and coating machine operators"},{"code":"8131","parent_code":"813","title":"CHEMICAL PRODUCTS PLANT AND MACHINE OPERATORS","description":"Chemical products plant and machine operators monitor and operate units and machinery to blend, mix, process and package a wide range of chemical products.\nTheir tasks include: a) setting up, starting, controlling, adjusting and stopping machines and plant; b) monitoring reaction processes and transfers of products in conformance with safety procedures; c) monitoring meters, gauges and electronic instrumentation on one or more chemical or formulation units, such as mixers, kettles, blenders, dryers, tableting, encapsulation, granulation and coating machines; d) measuring, weighing and loading chemical ingredients following formulation cards; e) taking samples and performing routine chemical and physical tests of products and recording production data; and f) cleaning and performing minor repairs to machines and plant.\nExamples of the occupations classified here: Candle production machine operator, Chemical and related processes kiln operator, Explosive products machine operator, Pharmaceutical and toiletry products machine operators\nSome related occupations classified elsewhere: Chemical processing plant controllers - 3133, Petroleum and natural gas refining plant operators - 3134","version":"2022","source_id":849,"level":4,"normalized_name":"chemical products plant and machine operators"},{"code":"8132","parent_code":"813","title":"PHOTOGRAPHIC PRODUCTS MACHINE OPERATORS","description":"Photographic products machine operators operate and monitor equipment which makes photographic film and paper, and which processes exposed photographic film and makes prints.\nTheir tasks include: a) operating and monitoring equipment which makes photographic film and paper; b) operating, monitoring and testing photographic processing and printing equipment, and maintaining operational standards; c) preparing exposed film for different processing batches in dark rooms and dark chambers; d) inspecting images, films, prints and adjusting settings on print-making equipment to produce required color, brightness, contrast, number, size and type of prints; e) adjusting settings and running automatic developing equipment; f) operating equipment to transfer film to video tape or other electronic media; g) performing photographic processing related tasks; and h) operating automatic equipment (in retail establishments) to develop color negatives, prints and slides;\nExamples of the occupations classified here: Colored film developer, Darkroom technician, Enlarging machine operator, Photograph developing machine operator, Photograph enlarger, Photograph printer, Photographic film machine operator, Photographic film printer, Photographic plate production machine operator, Photographic processor\nSome related occupations classified elsewhere: Photographer - 3431, Photolithographer - 7321","version":"2022","source_id":850,"level":4,"normalized_name":"photographic products machine operators"},{"code":"8141","parent_code":"814","title":"RUBBER PRODUCTS MACHINE OPERATORS","description":"Rubber-products machine operators operate and monitor machines which knead and blend rubber and rubber compounds, and produce various components and products from natural and synthetic rubber, such as molded footwear, domestic articles, insulating materials, industrial accessories, or tires.\nTheir tasks include: a) operating and monitoring machines which knead, mix and blend rubber and rubber compounds for further processing; b) operating and monitoring machines which produce sheets of rubber or rubberized fabric by a rolling process; c) operating and monitoring machines which extrude compounded rubber or shape vulcanized rubber by molding; d) operating and monitoring machines which build up tires on a form, vulcanize tires and mold or rebuild used tires; e) examining outputs for defects and conformity to specifications; and f) locating defects and repairing worn and faulty tires by vulcanizing or other processes.\nExamples of the occupations classified here: Latex worker, Rubber extruding machine operator, Rubber milling machine operator, Rubber molder, Rubber products machine operator, Tire maker, Tire production machine operator, Tire repairer, Vulcanizer","version":"2022","source_id":851,"level":4,"normalized_name":"rubber products machine operators"},{"code":"8142","parent_code":"814","title":"PLASTIC PRODUCTS MACHINE OPERATORS","description":"Products machine operators operate and monitor machines which knead and blend compounds to obtain plastic materials and which make various plastic components and articles. \nTheir tasks include: a) operating and monitoring machines which knead and blend compounds to obtain plastic materials; b) operating and monitoring machines which shape plastic materials by molding, extrusion, blowing, cutting and other means; c) operating and monitoring machines which laminate plastics and plastic impregnated materials or produce fiberglass; d) encasing uncoated wire, cord, cable and optic fiber in plastic; e) examining outputs for defects and conformity to specifications; f) recycling waste plastic materials; and g) making artificial eyes and contact lens discs, making and repairing spectacle frames and plastic parts of orthopedic appliances.\nExamples of the occupations classified here: Optic fiber drawer, Plastic cable making machine operator, Plastic extrusion machine operator, Plastic grinding machine operator, Plastic molder, Plastic products machine operator, Plastics boat builder, Plastics bottle blowing machine operator, Plastics laminated press operator, Plastics molding machine operator","version":"2022","source_id":852,"level":4,"normalized_name":"plastic products machine operators"},{"code":"8143","parent_code":"814","title":"PAPER PRODUCTS MACHINE OPERATORS","description":"Paper products machine operators operate and monitor machines which produce boxes, envelopes, bags and other goods from paper, paperboard, cardboard and similar materials.\nTheir tasks include: a) operating and monitoring machines which glue paper to cardboard, cut it to the required length or cut and crease cardboard or paperboard to form box blanks; b) operating and monitoring pressing machines which form drinking cups or other containers from paper, paperboard or cardboard; and c) operating and monitoring machines which cut, fold and glue paper to make envelopes and paper bags, or which form bags from other similar materials.\nExamples of the occupations classified here: Cardboard products machine operator, Envelope and paper bag production machine operator, Paper box production machine operator, Paper maché molder, Paper products machine operator","version":"2022","source_id":853,"level":4,"normalized_name":"paper products machine operators"},{"code":"8151","parent_code":"815","title":"FIBRE PREPARING, SPINNING AND WINDING MACHINE OPERATORS","description":"Fiber-preparing, spinning and winding machine operators operate and monitor machines which prepare fibers, and spin, double, twist and wind yarn and thread from natural textile fibers. They twist two or more strands of yarn to prepare single stronger, smoother, uniform and heavier strands and treat textiles to make them stiff and water resistant.\nTheir tasks include: a) operating and monitoring machines for tearing woolen rags into fiber; b) operating and monitoring machines for cleaning and turning woolen yarn waste into fluffed wool; c) operating and monitoring machines which combine textile fibers into uniform blends; d) operating and monitoring machines which clean and fluff textile fibers, transform them into sliver, comb them into sliver for first drawing, combine slivers into sliver lap or sliver laps into ribbon lap; e) operating draw frame machine) having number of drawing sets, each set combining several slivers into one of nearly same weight and thickness as any of original sliver; f) operating and monitoring machines which spin thread and yarn from roving, wind two or more threads onto bobbin, twist two or more strands of yarn or thread into single strands of yarn to increase strength, smoothness and/or uniformity of yarn, or wind yarn or thread from one package to another; g) operating and monitoring spinning frame that draws out and twists roving or sliver into yarn; h) operating and monitoring machines for drawing slivers received from drawing machine into loosely twisted strands; i) preparing sizing for use in stiffening and finishing cloth and yarn by mixing ingredients such as starch, tallow, resins, soaps and water and boiling mixture for specified time in steam; j) treating textiles with chemicals to make them water resistant; k) cleaning rollers and cylinders of carding machines to remove wool waste; and l) operating and resurfacing metal drawing rolls of various spinning, combing and lapping machines with new rubber or leather covers.\nExamples of the occupations classified here: Fiber combining machine operator, Fiber preparing machine operator, Synthetic fiber spinning machine operator, Textile fiber drawing-frame machine operator, Thread and yarn spinning machine operator, Thread and yarn twisting machine operator, Thread and yarn winding machine operator","version":"2022","source_id":854,"level":4,"normalized_name":"fibre preparing spinning and winding machine operators"},{"code":"8152","parent_code":"815","title":"WEAVING AND KNITTING MACHINE OPERATORS","description":"Weaving and knitting machine operators set up, operate and monitor weaving and knitting machines which process yarn or thread into woven, non-woven and knitted products such as cloth, lace, carpets, rope, industrial fabric, hosiery and knitted garments or to quilt and embroider fabric.\nTheir tasks include: a) setting up and operating batteries of automatic, link-type knitting machines to knit garments of specified pattern and design; b) threading yarn, thread, and fabric through guides, needles, and rollers of machines for weaving, knitting, or other processing; c) tending automatic looms that simultaneously weave pile yarn, filling yarn, and warp yarn material to produce carpets and rugs with various colored designs; d) operating and monitoring loom on which yarn or twist is intersected and knotted at regular intervals to form mesh; e) operating and monitoring large automatic multi-needle machines to embroider material or to sew lengths of several layers of material to make yard goods, quilts or mattress coverings; f) tending circular knitting machines with automatic pattern controls that knit seamless hose; g) operating and monitoring knitting machines to knit hosiery to shape of foot and leg; h) operating and monitoring machine for knitting heel and toes of socks into ribs or tops cut from circular fabric; i) operating and monitoring machine which seams openings in toes of socks; j) operating and monitoring crocheter machine to knit lace, trimming etc. of desired pattern or design; k) examining looms to determine causes of loom stoppage, such as warp filling, harness breaks, or mechanical defects; l) repairing or replacing worn or defective needles and other components; and m) cleaning, oiling, and lubricating machines, using air hoses, cleaning solutions, rags, oil cans, and/or grease guns.\nExamples of the occupations classified here: Carpet weaving machine operator, Crocheting machine operator, Jacquard card cutter, Knitting machine operator, Knitting-machine setter, Lace production machine operator, Loom threading machine operator, Net production machine operator, Warping beam machine operator, Weaving machine operator\nSome related occupations classified elsewhere: Carpet weaver - 7318, Cloth weaver - 7318, Knitter - 7318","version":"2022","source_id":855,"level":4,"normalized_name":"weaving and knitting machine operators"},{"code":"8153","parent_code":"815","title":"SEWING MACHINE OPERATORS","description":"Sewing machine operators operate and monitor sewing machines to make, repair, darn and renovate textile, fur, synthetic or leather garments or embroider ornamental designs on garments or other materials. They operate button hole making and eyelet holing machines to cut holes, stitch around holes, stitch buttons and fix eyelets to garments.\nTheir tasks include: a) operating or tending sewing machines to perform garment sewing operations, such as joining, reinforcing, seaming or decorating garments or garment parts; b) attaching buttons, hooks, zippers, fasteners, or other accessories to fabric, using feeding hoppers or clamp holders; c) tending semiautomatic sewing machines with multiple-sewing heads controlled by pattern chain that embroiders various designs on garments; d) operating machines, such as single or double needle sergers and flat-bed felling machines, to automatically join, reinforce, or decorate material or articles; e) operating fur sewing machines to join fur pelt strips to required size and shape and join pelts into garment sections or shells; f) operating stitching machines to sew leather parts together for leather garments, handbags, gloves; g) monitoring machine operation to detect problems such as defective stitching, breaks in thread, or machine malfunctions; and h) performing equipment maintenance tasks such as replacing needles.\nExamples of the occupations classified here: Embroidery machine operator, Sewing machine operator\nSome related occupations classified elsewhere: Embroiderer - 7533, Furrier - 7531, Sewer - 7533, Tailor - 7531, Textiles handicraft worker - 7318","version":"2022","source_id":856,"level":4,"normalized_name":"sewing machine operators"},{"code":"8154","parent_code":"815","title":"BLEACHING, DYEING AND FABRIC CLEANING MACHINE OPERATORS","description":"Bleaching, dyeing and fabric cleaning machine operators operate and monitor machines that bleach, shrink, dye, and otherwise treat fibers, yarn or cloth.\nTheir tasks include: a) starting and controlling machines and equipment to bleach, dye, or otherwise process and finish fabric, yarn, thread, and/or other textile goods; b) tending machines that shrink woven or knitted cloth to predetermined size or strengthen the weave by interlocking the fibers; c) tending a variety of automatic machines that comb and polish furs; d) operating and monitoring machines that treat silk to give it body and weight; e) operating and monitoring machines that impregnate textiles with chemicals to render them waterproof; f) dyeing articles to change or restore their colors; g) operating and monitoring machines that stretch, or impart luster, or other type of finish to textiles; h) tending and regulating equipment that fumigates and removes foreign matter from furs; i) operating machines that comb, dry and polish furs, clean, sterilize and fluff feathers and blankets; j) keying in processing instructions to program electronic equipment; k) observing display screens, control panels, equipment, and cloth entering or exiting processes to determine if equipment is operating correctly; and l) cleaning machine filters and lubricating equipment.\nExamples of the occupations classified here: Bleaching machine operator, Dyeing machine operator, Fabric bleaching machine operator, Textile dyeing machine operator, Textile fulling-mill operator, Textile shrinking machine operator\nSome related occupations classified elsewhere: Hand launderer - 9121, Hand presser - 9121, Laundry machine operator - 8157, Textile printer - 7322","version":"2022","source_id":857,"level":4,"normalized_name":"bleaching dyeing and fabric cleaning machine operators"},{"code":"8155","parent_code":"815","title":"FUR AND LEATHER PREPARING MACHINE OPERATORS","description":"Fur and leather preparing machine operators operate and monitor various machines that prepare leather or treat fur or wool-bearing pelts. They trim, scrape, clean, tan, buff and dye animal hides, pelts or skins to produce leather stock and finished furs.\nTheir tasks include: a) operating and monitoring machines which remove flesh and fat from hides or pelts to clean and soften them prior to processing; b) operating and monitoring machines which remove long coarse hair from fur pelts, trim hair to even length and dye, stretch and smooth dressed pelts; c) operating and monitoring machines to remove epidermis hair roots, pigment cells and lime salts from grain side of skin; d) operating and monitoring machines to reduce thickness of hide or skin to uniform size; e) operating and monitoring machines to polish or roughen hides or skins to specified finish; f) operating and monitoring machines which separate residual wool from skins, or flesh and hair from hides; g) operating and monitoring machines in which hides are split edgeways to form two or more pieces or to give uniform thickness; h) operating and monitoring machines which treat hides and skins in solutions to convert them into leather; i) treating surface of leather with oil and operating glazing machine to give glossy finish to leather; j) operating and monitoring machines which apply dyes and stains to leather; and k) maintaining and repairing vats and other machinery.\nExamples of the occupations classified here: Hide dehairing machine operator, Leather staining machine operator, Tanning machine operator\nSome related occupations classified elsewhere: Pelt dresser - 7535, Tanner - 7535","version":"2022","source_id":858,"level":4,"normalized_name":"fur and leather preparing machine operators"},{"code":"8156","parent_code":"815","title":"SHOEMAKING AND RELATED MACHINE OPERATORS","description":"Shoemaking and related machine operators operate and monitor machines which produce and repair standard or special footwear, handbags and other accessories, mainly made of leather.\nTheir tasks include: a) operating and monitoring machines which mark patterns and cut shoe parts; b) operating and monitoring machines which sew shoe parts together, or edge, polish, or apply ornaments and perform finishing tasks; and c) operating and monitoring machines which produce luggage, handbags, belts and other accessories, as well as other items such as saddles, collars or harnesses.\nExamples of the occupations classified here: Footwear production machine operator, Leather goods production machine operator, Shoe production machine operator\nSome related occupations classified elsewhere: Cobbler - 7536, Leather handicraft worker - 7318","version":"2022","source_id":859,"level":4,"normalized_name":"shoemaking and related machine operators"},{"code":"8157","parent_code":"815","title":"LAUNDRY MACHINE OPERATORS","description":"Laundry machine operators operate laundry, dry cleaning, pressing and fabric treatment machines in laundries and dry-cleaning establishments.\nTheir tasks include: a) sorting articles for cleaning according to the type color, fabric and cleaning treatment required; b) placing sorted articles into receptacles and onto conveyor belts for moving to repair and cleaning areas; c) checking and removing stains from garments, and replacing buttons and making minor repairs; d) loading and unloading washing machines, driers and extractors; e) adding cleaning agents and starches to articles; f) smoothing articles and guiding them through cleaning and pressing machines; g) stopping and starting machines to untangle, straighten and remove articles; h) placing articles on shelves and hanging articles for delivery and collection; and i) packaging articles and preparing orders for dispatch.\nExamples of the occupations classified here: Dry-cleaning machine operator, Laundry machine operator, Laundry pressing machine operator\nSome related occupations classified elsewhere: Hand launderer - 9121, Hand presser - 9121","version":"2022","source_id":860,"level":4,"normalized_name":"laundry machine operators"},{"code":"8159","parent_code":"815","title":"TEXTILE, FUR AND LEATHER PRODUCTS MACHINE OPERATORS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers textile, fur and leather products machine operators not classified elsewhere in Minor group 815, Textile, fur and leather products machine operators. For instance, the group includes those engaged in operating and monitoring machines which make hats, tents, mattresses or miscellaneous articles such as braids or other trimmings.\nTheir tasks include: a) operating and monitoring machines which form and make hats out of textiles, fur or leather; b) operating and monitoring machines which make miscellaneous articles such as braids or other trimmings; c) operating and monitoring machines that fold cloth into measured length; d) operating and monitoring machines that wind thread, twine, or yarn into balls preparatory to shipping or further processing; and e) operating and monitoring machines to measure size of pieces of leather.\nExamples of the occupations classified here: Braid making machine operator, Fur patternmaking machine operator, Hat blocking machine operator, Hat making machine operator, Tent making machine operator, Textile patternmaking machine operator","version":"2022","source_id":861,"level":4,"normalized_name":"textile fur and leather products machine operators not elsewhere classified"},{"code":"8160","parent_code":"816","title":"FOOD AND RELATED PRODUCTS MACHINE OPERATORS","description":"Food and related machine operators set, operate and attend machinery used to slaughter animals, trim meat from carcasses; bake, freeze, heat, crush, mix, blend and otherwise process foodstuffs, beverages and tobacco leaves.\nTheir tasks include: a) operating and monitoring machinery used to restrain, stun, slaughter animals and trim carcasses into standard meat and fish cuts; b) setting, operating and attending machinery and ovens to mix, bake and otherwise prepare bread and flour confectionery products; c) operating machinery to crush, mix, malt, cook and ferment grains and fruits to produce beer, wines, malt liquors, vinegar, yeast and related products; d) attending equipment to make jam, toffee, cheese, processed cheese, margarine, syrup, ice, pasta, ice-cream, sausages, chocolate, maize starch, edible fats and dextrin; e) operating equipment to cool, heat, dry, roast, blanch, pasteurize, smoke, sterilize, freeze, evaporate and concentrate foodstuffs and liquids used in food processing; f) mixing, pulping, grinding, blending and separating foodstuffs and liquids with churning, pressing, sieving, grinding and filtering equipment; and g) processing tobacco leaves by machine to make cigarettes, cigars, pipe and other tobacco products.\nExamples of the occupations classified here: Bakery products machine operator, Bread production machine operator, Chocolate production machine operator, Cigar production machine operator, Cigarettes production machine operator, Dairy products machine operator, Fish processing machine operator, Meat processing machine operator, Milk processing machine operator, Noodle production machine operator, Sugarcane processing machine operator, Tobacco processing machine operator\nRelated occupation classified elsewhere: Bottling machine operator - 8183","version":"2022","source_id":862,"level":4,"normalized_name":"food and related products machine operators"},{"code":"8171","parent_code":"817","title":"PULP AND PAPERMAKING PLANT OPERATORS","description":"Pulp and papermaking plant operators operate and monitor multi-function process control machinery and processing equipment to control the processing of wood, scrap pulp and other cellulose materials in the production of pulp.\nTheir tasks include: a) coordinating and monitoring the operation of screening equipment, washing equipment, digesters, mixing tanks and other pulp processing equipment from automated panel boards in central control room to control the processing of wood, scrap pulp, recyclable paper and other cellulose materials; b) operating and monitoring screening equipment, bleaching equipment, digesters, mixing tanks, washers and other pulp processing machinery and equipment to carry out one or more cellulose processing steps; c) controlling start-up and shut-down of process machinery and equipment, and observing equipment and machinery panel indicators, gauges, level indicators and other equipment instruments to detect machinery and equipment malfunctions and ensure process steps are carried out according to specifications; d) analyzing instrument readings and production test samples and making adjustments to pulp production process and equipment as required; and e) completing and maintaining production reports.\nExamples of the occupations classified here: Paper pulp beater operator, Paper pulp digester operator, Papermaking plant operator, Pulp and paper calendar operator, Pulp and paper grinder operator, Pulp and paper sheeter operator, Repulper operator, Wood grinding machine operator\nRelated occupation classified elsewhere: Paper pulp refinery operator - 3139","version":"2022","source_id":863,"level":4,"normalized_name":"pulp and papermaking plant operators"},{"code":"8172","parent_code":"817","title":"WOOD PROCESSING PLANT OPERATORS","description":"Wood processing plant operators monitor, operate, and control automated lumber mill equipment for sawing timber logs into rough lumber, cutting veneer, making plywood and particle board, and otherwise preparing wood for further use.\nTheir tasks include: a) examining logs and rough lumber to determine size, condition, quality and other characteristics to decide best lumber cuts to carry out, or operating automated equipment to convey logs through laser scanners which determine the most productive and profitable cutting patterns; b) operating and monitoring log in-feed and conveyor systems; c) operating and monitoring automated lumber mill equipment from control rooms or equipment consoles head saws, resaws and multiblade saws to saw logs, cants, flitches, slabs or wings and remove rough edges from sawn timber into dressed lumber of various sizes, and saw or split shingles and shakes; d) operating and monitoring plywood core-laying machines and hot-plate plywood presses and machines which cut veneer; and e) cleaning and lubricating sawmill equipment.\nExamples of the occupations classified here: Circular saw operator, Edge sawyer, Log cut-off operator, Plywood core laying machine operator, Plywood press operator, Sawmill operator, Sawmill planer operator, Sawmill sawyer, Sawmill trimmer operator, Veneer cutting lathe operator, Veneer lathe operator, Wood processing plant sawyer\nSome related occupations classified elsewhere: Timber treating tank operator - 7521, Veneer dryer tender - 7521, Wood treater - 7521, Woodworking machine operator - 7523","version":"2022","source_id":864,"level":4,"normalized_name":"wood processing plant operators"},{"code":"8181","parent_code":"818","title":"GLASS AND CERAMICS PLANT OPERATORS","description":"Glass and ceramics plant operators operate and monitor kilns, furnaces and other machinery and equipment used in the manufacture of glass, ceramics, porcelain, tiles or bricks. They operate machines to anneal, harden or decorate glass and ceramics.\nTheir tasks include: a) operating and monitoring glass-making furnaces to make glass by melting and fusing pre-mixed ingredients; b) tending hot or cold-end spray equipment used to coat glassware with surface hardener; c) operating and maintaining machines that press or blow molten glass in molds to form or shape containers, such as bottles, jars and drinking glasses; d) operating hand press to mold glass into required shape; e) operating drawing kiln to process molten glass into continuous sheet of flat glass; f) operating and monitoring floating-glass production plant; g) operating and maintaining finishing machines to grind, drill, sand, bevel, decorate, wash or polish glass or glass products; h) setting and operating press machines to mold ceramic articles from moist clay; i) operating machines to mix clay with water to knead it into a suitable plastic condition or semi-liquid form for making ceramic products; j) operating and monitoring kilns which bake pottery, porcelain ware and bake bricks and tiles; k) operating and monitoring machines for making glaze or abrasives; l) operating and monitoring machines which extrude molten glass to form fiberglass filaments; and m) observing finished products to identify splits, cracks, breaks, color and other imperfections.\nExamples of the occupations classified here: Brick kiln operator, Ceramics kiln operator, Ceramics painting machine operator, Ceramics production machine operator, Clay mixing machine operator, Clay slips production machine operator, Extruding clay press operator, Float-glass bath kiln operator, Glass blowing machine operator, Glass cutting machine operator, Glass finishing machine operator, Glass mixing machine operator, Glass production furnace operator, Glass production furnace operator, Glass-fiber production machine operator, Glaze production machine operator, Plate-glass rolling machine operator, Pottery kiln operator, Tile kiln operator\nSome related occupations classified elsewhere: Brick and tile molder - 7314, Glass blower - 7315, Glass cutter - 7315","version":"2022","source_id":865,"level":4,"normalized_name":"glass and ceramics plant operators"},{"code":"8182","parent_code":"818","title":"STEAM ENGINE AND BOILER OPERATORS","description":"Steam engine and boiler operators maintain and operate various types of steam engines, boilers, turbines and auxiliary equipment to provide power and other utility services for commercial, industrial and institutional buildings, at work sites and aboard ships or self-propelled vessels.\nTheir tasks include: a) operating, cleaning, lubricating and monitoring steam engines, boilers and auxiliary equipment such as pumps, compressors and air-conditioning equipment to supply and maintain steam and power for buildings, marine vessels or pneumatic tools; b) analyzing and recording instrument readings, troubleshooting and performing minor repairs to prevent equipment or system failure; c) monitoring and inspecting performance of equipment for efficient operation and ensuring boiler water, chemical, and fuel levels are maintained at required levels; d) firing coal furnaces by hand or with stokers and gas or oil-fed boilers, using automatic gas feeds or oil pumps; e) testing boiler water quality or arrange for testing, adjusting and taking necessary corrective action, such as adding chemicals to prevent corrosion and harmful deposits; f) monitoring ship’s engine, machinery and equipment indicators, recording variables and reporting abnormalities to ship engineer officer on watch; and g) operating and maintaining off-loading liquid pumps and valves.\nExamples of the occupations classified here: Boiler plant fireman, Boiler tender, Ships' boiler operator, Stationary engineer, Steam boiler plant operator, Steam engine operator, Stoker\nSome related occupations classified elsewhere: Ships' engineer - 3151, Stationary engine fitter - 7233","version":"2022","source_id":866,"level":4,"normalized_name":"steam engine and boiler operators"},{"code":"8183","parent_code":"818","title":"PACKING, BOTTLING AND LABELLING MACHINE OPERATORS","description":"Packing, bottling and labelling machine operators operate and monitor machines which weigh, pack and label various products, or fill different containers with products.\nTheir tasks include: a) operating and monitoring machines that weigh, wrap, seal and pack various products; b) operating and monitoring machines that fill and seal tubes, bottles, cans, boxes, bags and other containers with products, such as food, beverages, paints, oils and lotions; and c) operating and monitoring machines that, by gluing or other methods, label products, packages and various containers.\nExamples of the occupations classified here: Bottle filler, Bottling machine operator, Canning machine operator, Labelling machine operator, Packing machine operator, Wrapping machine operator\nRelated occupation classified elsewhere: Hand packer - 9321","version":"2022","source_id":867,"level":4,"normalized_name":"packing bottling and labelling machine operators"},{"code":"8189","parent_code":"818","title":"STATIONARY PLANT AND MACHINE OPERATORS NOT ELSEWHERE CLASSIFIED","description":"This unit group includes stationary plant and machine operators not classified elsewhere in sub-major group 81, Stationary plant and machine operators. The group includes, for instance, operators of machines which make silicon chips and splice cables and ropes.\nExamples of the occupations classified here: Cable and rope splicing machine operator, Silicon chip production machine operator","version":"2022","source_id":868,"level":4,"normalized_name":"stationary plant and machine operators not elsewhere classified"},{"code":"8211","parent_code":"821","title":"MECHANICAL MACHINERY ASSEMBLERS","description":"Mechanical machinery assemblers assemble, according to strictly laid down procedures, component parts of mechanical machinery such as engines, motor vehicles, turbines and aircraft.\nTheir tasks include: a) assembling and installing prefabricated parts or components to form subassemblies, mechanical machinery, engines and finished motor vehicles; b) reviewing work orders, specifications, diagrams and drawings to determine materials needed and assembly instructions; c) recording production and operational data on specified forms; d) inspecting and testing completed components and assemblies; and e) rejecting faulty assemblies and components;\nExamples of the occupations classified here: Agricultural machinery assembler, Aircraft assembler, Aircraft assembly-line machine operator, Automotive assembly-line machine operator, Engine assembler, Engine installer, Gearbox assembler, Industrial machinery assembler, Truck bench fitter, Turbine assembler, Vehicle assembler\nSome related occupations classified elsewhere: Bicycle assembler - 8219, Electromechanical equipment assembler - 8212, Motor vehicle mechanic - 7231","version":"2022","source_id":869,"level":4,"normalized_name":"mechanical machinery assemblers"},{"code":"8212","parent_code":"821","title":"ELECTRICAL AND ELECTRONIC EQUIPMENT ASSEMBLERS","description":"Electrical and electronic equipment assemblers assemble or modify, according to strictly laid down procedures, components of electrical, electro-mechanical and electronic equipment.\nTheir tasks include: a) assembling component parts and electrical and electronic systems and positioning, aligning and fastening units to assemblies, sub-assemblies, or frames using hand or power tools, soldering and micro-welding equipment.; b) reviewing work orders, specifications, diagrams and drawings to determine materials needed and assembly instructions: c) recording production and operational data on specified forms; d) operating wire-coiling machines to wind wire coils used in electrical equipment and components such as registers, transformers, armature wires, electric motors and generators; and e) inspecting and testing completed components and assemblies, wiring installations and circuits and rejecting faulty assembly components;\nExamples of the occupations classified here: Armature assembler, Coil winding machine operator, Electrical assembler, Electrical equipment assembler, Electromechanical equipment assembler, Electronic equipment assembler, Printed circuit board etcher, Telephone assembler, Television assembler, Watch assembler\nSome related occupations classified elsewhere: Electronics mechanic and servicer - 7421, Precision-instrument maker - 7311","version":"2022","source_id":870,"level":4,"normalized_name":"electrical and electronic equipment assemblers"},{"code":"8219","parent_code":"821","title":"ASSEMBLERS NOT ELSEWHERE CLASSIFIED","description":"Assemblers not elsewhere classified assemble, according to strictly laid down procedures various products that do not include electronic, electrical, or mechanical components.\nTheir tasks include: a) assembling component parts and positioning, aligning and fastening units to assemblies, sub-assemblies, or frames using hand or power tools, soldering and micro-welding equipment; b) reviewing work orders, specifications, diagrams and drawings to determine materials needed and assembly instructions; c) recording production and operational data on specified forms; d) inspecting and testing components and completed assemblies; and e) rejecting faulty products.\nExamples of the occupations classified here: Ammunition assembler, Bicycle assembler, Box builder, Door assembler, Eyeglass frame assembler, Faucets assembler, Jewelry assembler, Knife assembler, Leather products assembler, Luggage finisher, Metal products assembler (except mechanical), Musical instruments assembler, Paperboard products assembler, Pen and pencil assembler, Photographic equipment assembler, Plastic products assembler, Plastic toy assembler, Rubber products assembler, Sun-blinds assembler, Textile products assembler, Thermos bottle assembler, Wood furniture finisher, Wood products assembler","version":"2022","source_id":871,"level":4,"normalized_name":"assemblers not elsewhere classified"},{"code":"8311","parent_code":"831","title":"LOCOMOTIVE ENGINE DRIVERS","description":"Locomotive-engine drivers drive, or assist in driving, locomotive engines to transport passengers and freight.\nTheir tasks include: a) driving or assisting in driving a steam, electric or diesel-electric locomotive engine; b) driving an underground or elevated passenger train; c) driving a locomotive to haul carriages underground or on the surface of a mine or quarry; d) watching for track hazards, observing signals and indicator gauges; and e) operating communications systems to communicate with train crews and traffic controllers to ensure safe operation and scheduling of trains.\nExamples of the occupations classified here: Locomotive engine driver, Metropolitan railway driver, Train driver\nRelated occupation classified elsewhere: Tram driver - 8331","version":"2022","source_id":872,"level":4,"normalized_name":"locomotive engine drivers"},{"code":"8312","parent_code":"831","title":"RAILWAY BRAKE, SIGNAL AND SWITCH OPERATORS","description":"Railway brakers, signalers and shunters take charge of and safeguard railway freight trains during runs, control the movement of railway traffic by operating signals, switch rolling stock and make up trains in railway yards, make up trains for hauling in mines and control their movement.\nTheir tasks include: a) taking charge of and safeguarding freight train during run; b) controlling flow of railway traffic over section of line by operating signals and switches from control panel or signal box; c) switching and coupling rolling stock in railway yards and sidings in accordance with orders about loading, unloading and make-up of trains; d) making up trains for hauling by locomotive or cable and directing their movement along haulage ways in a mine or quarry; and e) checking train systems and equipment such as air conditioning and heating systems, brakes and brake hoses prior to train run.\nExamples of the occupations classified here: Railway braker, Railway shunter, Railway signaler","version":"2022","source_id":873,"level":4,"normalized_name":"railway brake signal and switch operators"},{"code":"8321","parent_code":"832","title":"MOTORCYCLE DRIVERS","description":"Motor-cycle drivers drive and tend motor cycles or motorized tricycles equipped to transport materials, goods or passengers.\nTheir tasks include: a) driving and tending motor cycle or motorized tricycle to transport materials, goods and passengers; b) observing traffic rules and signals; c) cleaning and washing vehicle as well as performing maintenance and minor repairs; d) keeping a record of journeys; and e) delivering messages.\nExamples of the occupations classified here: Dispatch rider, Electric tricycle (e-trike) driver, Habal-habal driver, Motorcycle rider, Motorcyclist, Motorized rickshaw driver, Motorized tricycle driver\nRelated occupation classified elsewhere: Pedal vehicle driver - 9331","version":"2022","source_id":874,"level":4,"normalized_name":"motorcycle drivers"},{"code":"8322","parent_code":"832","title":"CAR, TAXI AND VAN DRIVERS","description":"Car, taxi and van drivers drive and tend motor cars and vans to transport passengers, mail or goods.\nTheir tasks include: a) driving and tending passenger vans, cars or taxis; b) driving and tending cars, vans or small trucks to deliver mail or goods; c) assisting passengers with handling of luggage; d) collecting fares, payments for deliveries, or documents certifying deliveries; e) operating telecommunications equipment to report location and availability and follow directions of control center; f) determining most appropriate route; g) assisting physically challenged passengers; and h) operating equipment to facilitate the loading and unloading of physically challenged passengers.\nExamples of the occupations classified here: Ambulance driver, Company driver, Family driver, Jeepney driver, Multicab driver, Parking valet, Personal driver, School van driver\nSome related occupations classified elsewhere: Animal-drawn vehicle driver - 9332, Bus driver - 8331, Heavy truck driver - 8332, Motorized rickshaw driver - 8321, Pedal vehicle driver - 9331, Rickshaw puller - 9331","version":"2022","source_id":875,"level":4,"normalized_name":"car taxi and van drivers"},{"code":"8323","parent_code":"832","title":"TRANSPORT NETWORK VEHICLE SERVICE MOTORCYCLE DRIVERS","description":"Transport Network Vehicle Service (TNVS) motorcycle drivers drive and tend motor cycles or motorized tricycles equipped to transport goods or passengers. But unlike conventional drivers, TNVS motorcycle and tricycle drivers use a mobile application for booking rides and navigation.\nTheir tasks include: a) driving and tending motorcycle or motorized tricycle; b) booking rides using a mobile application; c) picking up and dropping off goods or passengers at designated locations; d) assisting passengers with handling of luggage; e) observing traffic rules and signals; f) cleaning and washing vehicle as well as performing maintenance and minor repairs; g) keeping a record of journeys; and h) delivering messages to passengers or clients.\nExamples of the occupations classified here: TNVS motorcycle driver, TNVS tricycle driver\nSome related occupations classified elsewhere: Motorcycle rider (conventional) - 8321, Tricycle driver (conventional) - 8321","version":"2022","source_id":876,"level":4,"normalized_name":"transport network vehicle service motorcycle drivers"},{"code":"8324","parent_code":"832","title":"TRANSPORT NETWORK VEHICLE SERVICE CAR DRIVERS","description":"TNVS car drivers drive and tend motor cars to transport passengers or goods. But unlike conventional drivers, TNVS car drivers use a mobile application for booking rides and navigation.\nTheir tasks include: a) driving and tending cars; b) booking rides using a mobile application; c) picking up and dropping off goods or passengers at designated locations; d) assisting passengers with handling of luggage; e) observing traffic rules and signals; f) cleaning and washing vehicle as well as performing maintenance and minor repairs; g) keeping a record of journeys; and h) delivering messages to passengers or clients.\nSome related occupations classified elsewhere: Company driver - 8322, Taxi driver (conventional) - 8322","version":"2022","source_id":877,"level":4,"normalized_name":"transport network vehicle service car drivers"},{"code":"8325","parent_code":"832","title":"TRANSPORT NETWORK VEHICLE SERVICE TAXI DRIVERS","description":"TNVS taxi drivers drive and tend taxis to transport passengers. But unlike conventional drivers, TNVS taxi drivers use a mobile application for booking rides and navigation.\nTheir tasks include: a) driving and tending taxis; b) booking rides using a mobile application; c) picking up and dropping off passengers at designated locations; d) assisting passengers with handling of luggage; e) observing traffic rules and signals; f) cleaning and washing vehicle as well as performing maintenance and minor repairs; g) keeping a record of journeys; and h) delivering messages to passengers or clients.\nSome related occupations classified elsewhere: Taxi driver (conventional) - 8322, TNVS car drivers - 8324","version":"2022","source_id":878,"level":4,"normalized_name":"transport network vehicle service taxi drivers"},{"code":"8326","parent_code":"832","title":"TRANSPORT NETWORK VEHICLE SERVICE VAN DRIVERS","description":"TNVS van drivers drive and tend motor vans to transport passengers, mail or goods. But unlike conventional drivers, TNVS van drivers use a mobile application for booking rides and navigation.\nTheir tasks include: a) driving and tending vans; b) booking rides using a mobile application; c) picking up and dropping off goods or passengers at designated locations; d) assisting passengers with handling of luggage; e) observing traffic rules and signals; f) cleaning and washing vehicle as well as performing maintenance and minor repairs; g) keeping a record of journeys; and h) delivering messages to passengers or clients.\nSome related occupations classified elsewhere: Jeepney driver - 8322, Van driver (conventional) - 8322","version":"2022","source_id":879,"level":4,"normalized_name":"transport network vehicle service van drivers"},{"code":"8331","parent_code":"833","title":"BUS AND TRAM DRIVERS","description":"Bus and tram drivers drive and tend buses or street tramcars to transport passengers, mail or goods.\nTheir tasks include: a) driving and tending motor bus, trolley bus or motor coach to transport local or long mail or goods; b) driving and tending street tramcar transporting passengers; c) opening and closing doors before or after passengers board or alight; d) assisting passengers with luggage; e) controlling lighting, heating and ventilation on buses and trams; f) observing traffic to ensure safe progress; and g) collecting fares or verifying passenger has necessary ticket.\nExamples of the occupations classified here: Bus driver, Motor coach driver, School bus driver, Tram driver, Truck driver","version":"2022","source_id":880,"level":4,"normalized_name":"bus and tram drivers"},{"code":"8332","parent_code":"833","title":"HEAVY TRUCK AND LORRY DRIVERS","description":"Heavy-truck and lorry drivers drive and tend heavy motor vehicles to transport goods, liquids and heavy materials over short or long distances.\nTheir tasks include: a) driving and tending a heavy motor vehicle, such as a lorry with or without trailer or a dump-truck, to transport goods, liquids or heavy materials over short or long distances; b) determining the most appropriate routes; c) ensuring goods are stowed and securely covered, to prevent loss and damage; d) assisting with or carrying out loading or unloading operations, using various lifting or tipping devices; e) carrying out minor maintenance to vehicles, and arranges major maintenance and repairs; and f) estimating weights to comply with load limitations, and ensuring the safe distribution of weights.\nExamples of the occupations classified here: Concrete mixer driver, Dump truck driver, Fire truck driver, Garbage truck driver, Heavy truck driver, Road train driver, Trailer truck driver\nRelated occupation classified elsewhere: Van driver - 8322","version":"2022","source_id":881,"level":4,"normalized_name":"heavy truck and lorry drivers"},{"code":"8341","parent_code":"834","title":"MOBILE FARM AND FORESTRY PLANT OPERATORS","description":"Mobile farm and forestry plant operators drive, tend, operate and monitor one or more types of special purpose motorized, mobile machinery or equipment used in agricultural, horticultural and forestry operations.\nTheir tasks include: a) driving and tending tractor drawn or self-propelled special -purpose farm machinery to plough land and sow, fertilize, cultivate and harvest crops; b) driving and tending tractor-drawn or self-propelled special -purpose forestry machinery to clear land, plant, harvest and carry trees and timber or perform other forestry operations; c) preparing and positioning plant for operation; d) adjusting speed, height and depth of implements; e) operating plant to hold, lift and cut trees; f) operating attachments to lift, swing, release and sort trees and logs, and operating auxiliary plant such as chipping machines and log splitting machines; g) feeding felled trees into processors to strip limbs and cut into logs and loading logs onto stockpiles and into trucks; and h) servicing machinery and performing minor repairs.\nExamples of the occupations classified here: Agricultural machinery operator, Harvester operator, Logging plant operator, Motorized farm equipment operator, Motorized forestry equipment operator, Timber carrier driver, Tractor driver, Tree faller operator\nSome related occupations classified elsewhere: Bulldozer operator - 8342","version":"2022","source_id":882,"level":4,"normalized_name":"mobile farm and forestry plant operators"},{"code":"8342","parent_code":"834","title":"EARTHMOVING AND RELATED PLANT OPERATORS","description":"Earthmoving and related plant operators operate machines to excavate, grade, level, smooth and compact earth or similar materials.\nTheir tasks include: a) operating and monitoring excavating machinery equipped with moveable shovel, grab-bucket or dragline bucket, to excavate and move earth, rock, sand, gravel or similar materials; b) operating and monitoring machinery for digging trenches for sewers, drainage, water, oil, gas or similar pipelines; c) operating and monitoring machinery equipped with concave steel blade to move, distribute and level earth, sand, snow and other materials; d) operating and monitoring equipment to remove sand, gravel and mud from bottom of body of water; e) operating and monitoring machines for hammering wooden, concrete or steel piles into ground; f) operating and monitoring power roller to compact and smooth layers of materials in making roads, pavements and similar work; and g) operating and monitoring machines which spread and smooth concrete or bituminous or tar preparations to construct roadways, roads or similar surfaces.\nExamples of the occupations classified here: Backhoe operator, Bulldozer operator, Construction grader and scraper operator, Excavator operator, Front-end loader operator, Pile-driver operator, Road surface laying machinery operator, Road-roller operator","version":"2022","source_id":883,"level":4,"normalized_name":"earthmoving and related plant operators"},{"code":"8343","parent_code":"834","title":"CRANE, HOIST AND RELATED PLANT OPERATORS","description":"Crane, hoist and related plant operators operate and monitor stationary and mobile cranes and other hoisting equipment.\nTheir tasks include: a) operating and monitoring stationary or mobile cranes by raising and lowering jibs and booms, to lift, move, position or place equipment and materials; b) operating and monitoring equipment for hoisting, lowering or raising workers and materials on construction sites or in mines; c) operating and monitoring ski-lifts and similar equipment; d) operating and monitoring machinery used to haul ferry or barge with goods, passengers and vehicles across short stretches of water; e) operating and monitoring machinery to open and close bridge for the passage of road and water traffic; f) operating and monitoring cranes equipped with dredging attachments to dredge waterways and other areas; and g) operating cranes mounted on boats or barges to lift, move and place equipment and materials.\nExamples of the occupations classified here: Cable car operator, Chair-lift operator, Crane operator, Funicular driver, Hoist operator, Mine cage operator, Ski-lift operator, Winch operator","version":"2022","source_id":884,"level":4,"normalized_name":"crane hoist and related plant operators"},{"code":"8344","parent_code":"834","title":"LIFTING TRUCK OPERATORS","description":"Lifting-truck operators drive, operate and monitor lifting-truck or similar vehicle to transport, lift and stack pallets with goods.\nTheir tasks include: a) operating and monitoring lifting-truck and similar equipment to load and unload, transport, lift and stack goods and pallets in terminals, harbors, warehouses, factories and other establishments; b) positioning lifting devices under, over, or around loaded pallets, skids and boxes, and securing material or products for transport to designated areas; c) inspecting equipment to identify wear and damage; d) performing routine maintenance on vehicles and equipment; and e) keeping records of work undertaken and breakdowns of vehicles.\nExamples of the occupations classified here: Forklift truck driver, Forklift truck operator","version":"2022","source_id":885,"level":4,"normalized_name":"lifting truck operators"},{"code":"8350","parent_code":"835","title":"SHIPS' DECK CREWS AND RELATED WORKERS","description":"Ship’s deck crews and related workers carry out deck duties on board ship and similar duties on board other water-borne craft.\nTheir tasks include: a) standing look-out watches at sea and when entering or leaving harbor or other narrow waters; b) steering ship according to instructions; c) handling ropes and wires, and operates mooring equipment; d) maintaining and, in some cases, operating ship’s equipment, cargo gear, rigging, life-saving and firefighting appliances; e) performing deck and hull cleaning, scraping, painting and other maintenance duties as required; and f) breaking out, rigging and stowing cargo-handling gear, stationary rigging and running gear.\nExamples of the occupations classified here: Bargeman, Boatman, Boatswain Deck cadet, Ferry hand, Lifeboat coxswain, Reefer repairman, Sailor, Seaman, Tug hand, Yacht crew","version":"2022","source_id":886,"level":4,"normalized_name":"ships deck crews and related workers"},{"code":"9111","parent_code":"911","title":"DOMESTIC CLEANERS AND HELPERS","description":"Domestic cleaners and helpers sweep, vacuum clean, wash and polish, take care of household linen, purchase household supplies, prepare food, serve meals and perform various other domestic duties.\nTheir tasks include: a) sweeping, vacuum-cleaning, polishing and washing floors and furniture, or washing windows and other fixtures; b) washing, ironing and mending linen and other textiles; c) washing dishes; d) helping with preparation, cooking and serving of meals and refreshments; e) purchasing food and various other household supplies; f) cleaning, disinfecting and deodorizing kitchens, bathrooms and toilets; and g) cleaning windows and other glass surfaces.\nExamples of the occupations classified here: Domestic charworker, Domestic cleaner, Domestic helper or domestic worker (kasambahay)\nSome related occupations classified elsewhere: Domestic housekeeper - 5152, Hand launderer - 9121, Hotel cleaner - 9112, Street sweeper - 9613","version":"2022","source_id":887,"level":4,"normalized_name":"domestic cleaners and helpers"},{"code":"9112","parent_code":"911","title":"CLEANERS AND HELPERS IN OFFICES, HOTELS AND OTHER ESTABLISHMENTS","description":"Cleaners and helpers in offices, hotels and other establishments perform various cleaning tasks in order to keep clean and tidy the interiors and fixtures of hotels, offices and other establishments, as well as of aircraft, trains, buses and similar vehicles.\nTheir tasks include: a) sweeping or vacuum-cleaning, washing and polishing floors, furniture and other fixtures in buildings, coaches, buses, trams, trains and aircraft; b) making beds, cleaning bathrooms, supplying towels, soap and related items; c) cleaning kitchens and generally helping with kitchen work, including dishwashing; and d) picking up rubbish, emptying garbage containers and taking contents to waste areas to removal.\nExamples of the occupations classified here: Aircraft cleaner, Hotel cleaner, Janitor (unskilled), Lavatory attendant, Office cleaner, Office utility worker, Restaurant and food chain cleaner, Room attendant, Train and bus cleaner\nSome related occupations classified elsewhere: Building caretaker - 5153, Dishwasher - 9412, Domestic cleaner - 9111, Domestic housekeeper- 5152, Kitchen helper - 9412, Street sweeper - 9613","version":"2022","source_id":888,"level":4,"normalized_name":"cleaners and helpers in offices hotels and other establishments"},{"code":"9121","parent_code":"912","title":"HAND LAUNDERERS AND PRESSERS","description":"Hand launderers and pressers launder, press or dry-clean garments, linen and other textiles by hand.\nTheir tasks include: a) laundering and pressing linen, clothing, fabrics and similar articles by hand in a laundry or other establishment; b) cleaning, by hand and with chemical solutions, clothing, fabrics, leather goods and similar articles, in a dry-cleaning or other establishment; c) replacing buttons and making minor repairs; and d) placing articles on shelves and hanging articles for delivery and collection.\nExamples of the occupations classified here: Dry-cleaner, hand, Dry-cleaning spotter, Hand launderer, Hand presser, Ironer or presser\nSome related occupations classified elsewhere: Dry-cleaning machine operator - 8157, Laundry machine operator - 8157, Laundry pressing machine operator - 8157","version":"2022","source_id":889,"level":4,"normalized_name":"hand launderers and pressers"},{"code":"9122","parent_code":"912","title":"VEHICLE CLEANERS","description":"Vehicle cleaners, wash, clean and polish vehicles.\nTheir tasks include: a) cleaning, washing and polishing cars and other vehicles, by hand or using hand-held power tools; b) vacuuming vehicle interiors and dry cleaning carpets and upholstery; c) applying cleaning agents to remove stains from vehicle exteriors and interiors; d) washing tires and wheel arches and blackening tires; e) washing and polishing vehicle windows; and f) emptying and cleaning compartments in vehicles.\nExamples of the occupations classified here: Car detailer, Vehicle washer, hand","version":"2022","source_id":890,"level":4,"normalized_name":"vehicle cleaners"},{"code":"9123","parent_code":"912","title":"WINDOW CLEANERS","description":"Window cleaners wash and polish windows and other glass fittings.\nTheir tasks include: a) washing windows or other glass surfaces with water or various solutions, drying and polishing them; b) using ladders, swinging scaffolds, bosun's chairs, hydraulic bucket trucks and other equipment to reach and clean windows in multi – story buildings; and c) selecting appropriate cleaning or polishing implement.\nExample of occupation classified here: Window cleaner","version":"2022","source_id":891,"level":4,"normalized_name":"window cleaners"},{"code":"9129","parent_code":"912","title":"OTHER CLEANING WORKERS","description":"Other cleaning workers clean surface, materials and objects, such as carpets, walls, swimming pools and cooling towers, using specialized cleaning equipment and chemicals.\nTheir tasks include: a) cleaning carpets and upholstered furniture using cleaning machines and their attachments; b) selecting and applying cleaning agents to remove stains from carpets; c) treating carpets with soil-repellent chemicals and deodorants, and treating for pests; d) cleaning stone walls, metal surfaces and fascias using high pressure water cleaners and solvents; and e) applying chemicals and high pressure cleaning methods to remove micro-organisms from water and filtration systems and using wet vacuums and other suction equipment to remove scale, accumulated dirt and other deposits from swimming pools, cooling tower components and drains.\nExamples of the occupations classified here: Carpet cleaner, Cooling tower cleaner, Graffiti cleaner, Swimming pool cleaner, Water blaster","version":"2022","source_id":892,"level":4,"normalized_name":"other cleaning workers"},{"code":"9211","parent_code":"921","title":"CROP FARM LABORERS","description":"Crop farm laborers perform simple and routine tasks in the production of crops such as fruit, nuts, grains and vegetables on farms.\nTheir tasks include: a) digging and shoveling to clear ditches or for other purposes; b) loading and unloading supplies, produce and other materials; c) raking, pitching and stacking straw, hay and similar material; d) watering, thinning, and weeding crops by hand or using hand tools; e) picking fruit, nuts, vegetables and other crops; f) planting and harvesting field crops, such as rice, by hand; g) grading, sorting, bunching and packing produce into containers; and h) performing minor repairs on fixtures, buildings and fences.\nExamples of the occupations classified here: Cane planter, Coconut farm laborer, Fruit picker, Rice farm laborer, Vegetable picker\nSome related occupations classified elsewhere: Building work construction laborer - 9313, Rice farmers - 6111, Corn farmers - 6112, Firewood collector - 9624, Water collector - 9624","version":"2022","source_id":893,"level":4,"normalized_name":"crop farm laborers"},{"code":"9212","parent_code":"921","title":"LIVESTOCK FARM LABORERS","description":"Livestock farm laborers perform simple and routine tasks in farm production of animals, including poultry and insects.\nTheir tasks include: a) digging and shoveling to clear ditches or for other purposes; b) loading and unloading supplies, produce and other materials; c) feeding, watering, and cleaning animals and keeping their quarters clean; d) monitoring livestock and reporting on their condition; e) assisting with maintaining the health and welfare of livestock; f) assisting with herding, droving and separating livestock for milking, shearing, transportation or slaughter and between pastures; g) collecting eggs and placing in incubators; h) raking, pitching, stacking and storing hay, straw and other types of animal feed and bedding grading, sorting, packing produce into containers; and i) performing minor repairs on fixtures, buildings and fences.\nExample of occupation classified here: Livestock farm laborer\nSome related occupations classified elsewhere: Drover - 6121, Firewood collector - 9624, Livestock farmer - 6121, Shepherd – 6121, Water collector - 9624","version":"2022","source_id":894,"level":4,"normalized_name":"livestock farm laborers"},{"code":"9213","parent_code":"921","title":"MIXED CROP AND LIVESTOCK FARM LABORERS","description":"Mixed crop and livestock farm laborers perform simple and routine tasks in farm production of both crops and animals.\nTheir tasks include: a) digging and shoveling to clear ditches or for other purposes; b) loading and unloading supplies, produce and other materials; c) raking, pitching and stacking straw, hay and similar material; d) watering, thinning, and weeding crops by hand or using hand tools; e) picking fruit, nuts, vegetables and other crops and collecting eggs; f) planting and harvesting field crops, such as rice, by hand; g) feeding, watering, and cleaning animals and keeping their quarters clean; h) monitoring livestock, reporting on their condition; i) assisting with herding, droving and separating livestock for milking, shearing, transportation or slaughter and between pastures; j) grading, sorting, bunching and packing produce into containers; and k) performing minor repairs on fixtures, buildings and fences.\nExample of occupation classified here: Farm laborer\nSome related occupations classified elsewhere: Firewood collector - 9624, Skilled farm worker (mixed crop and livestock) - 6130, Water collector - 9624","version":"2022","source_id":895,"level":4,"normalized_name":"mixed crop and livestock farm laborers"},{"code":"9214","parent_code":"921","title":"GARDEN AND HORTICULTURAL LABORERS","description":"Garden and horticultural laborers perform simple and routine tasks in operations to cultivate and maintain trees, shrubs, flowers and other plants in parks and private gardens, to produce saplings, bulbs and seeds, or grow vegetables and flowers by intensive cultivation techniques.\nTheir tasks include: a) loading, unloading and moving supplies, produce and equipment; b) preparing garden sites and plots using hand tools and simple machines; c) assisting with planting and transplanting flowers, shrubs, trees and lawns; d) maintaining gardens by watering, weeding and mowing lawns; e) cleaning gardens and removing rubbish; f) assisting with propagating, planting and potting seeds, bulbs and cuttings; g) tending plants by hand watering and weeding; h) harvesting and packaging plants for sale and transport; and i) performing minor repairs on fixtures, buildings and fences.\nExamples of the occupations classified here: Garden laborer, Horticultural laborer, Lawn mower, Nursery laborer\nSome related occupations classified elsewhere: Crop farm laborer - 9211, Horticulturist - 6118, Landscape gardener - 6118, Market gardener - 6118","version":"2022","source_id":896,"level":4,"normalized_name":"garden and horticultural laborers"},{"code":"9215","parent_code":"921","title":"FORESTRY LABORERS","description":"Forestry laborers perform simple and routine tasks to cultivate and maintain natural and plantation forests, and logging, felling and sawing trees.\nTheir tasks include: a) digging holes for tree planting; b) stacking and loading logs and timber; c) clearing undergrowth in forest stands and thinning young plantations; d) maintaining look-out for fires in forests; e) removing major branches and tree tops, trimming branches and sawing trunks into logs; f) operating and maintaining manual and hand held machine saws to fell trees and cut felled trees and branches into logs; g) collecting seeds, and planting seedlings; and h) performing minor repairs and maintenance of forest roads, buildings, facilities, and equipment.\nExamples of the occupations classified here: Axeman/woman, Forestry laborer, Tree planter\nSome related occupations classified elsewhere: Charcoal makers and related workers - 6213, Concessionaires and loggers - 6212, Forest tree planters - 6211, Minor forest product gatherers - 6214","version":"2022","source_id":897,"level":4,"normalized_name":"forestry laborers"},{"code":"9216","parent_code":"921","title":"FISHERY AND AQUACULTURE LABORERS","description":"Fishery and aquaculture laborers, perform simple and routine tasks to cultivate, catch and harvest fish and seafood in aquaculture and inland, coastal and deep sea fishing operations.\nTheir tasks include: a) cleaning the sea-bed and feeding fish and mollusks that are being cultivated; b) gathering seaweed, sea mosses, clams and other mollusks; c) preparing nets, lines and other fishing tackle and other deck equipment; d) operating fishing gear to catch fish and other marine life; e) cleaning, sorting and packing fish and seafood in ice and salt and stowing catch in hold; f) cleaning deck surfaces and fish hold; and g) handling mooring lines during docking.\nExamples of the occupations classified here: Aquaculture laborer, Fishery laborer, Fishpond laborer, Prawn hatchery worker\nSome related occupations classified elsewhere: Coastal waters fisher - 6226, Deep-sea fisher - 6227, Inland waters fisher - 6226, Milkfish and tilapia producers - 6221","version":"2022","source_id":898,"level":4,"normalized_name":"fishery and aquaculture laborers"},{"code":"9311","parent_code":"931","title":"MINING AND QUARRYING LABORERS","description":"Mining and quarrying laborers perform routine tasks in mining and quarrying operations.\nTheir tasks include: a) assisting miners and quarriers in maintaining machinery, equipment, and mine and quarry installations; b) assembling and dismantling mining equipment; c) removing tunnel supports from disused workings in mines and quarries; d) removing dangerous projections from mine and quarry workings; e) removing waste and serviceable materials and equipment from work areas after extraction activities have been completed, and clearing rock and mineral spills; f) cleaning machinery, equipment, tools, roadways and haulage tracks; and g) sorting, loading, unloading, stacking and storing tools, materials and supplies used by other mine workers.\nExamples of the occupations classified here: Gold panner, Mining laborer, Quarry laborer\nSome related occupations classified elsewhere: Drilling plant operator - 8113, Miner - 8111, Mining driller - 8111, Mining plant operator - 8111, Oil and gas well driller - 8113, Quarrier - 8111","version":"2022","source_id":899,"level":4,"normalized_name":"mining and quarrying laborers"},{"code":"9312","parent_code":"931","title":"CIVIL ENGINEERING LABORERS","description":"Civil engineering laborers perform routine tasks in connection with the building and maintenance of roads, railways, dams and other civil engineering projects.\nTheir tasks include: a) digging and filling holes and trenches using hand held tools; b) shoveling and spreading gravel and related materials; c) trimming and cutting rocks and concrete and bitumen surfaces using jack-hammers; d) loading and unloading construction materials, excavated material and equipment and transporting them around construction sites using wheelbarrows and hand trucks; and e) cleaning worksites and removing obstructions.\nExamples of the occupations classified here: Civil engineering construction laborer, Dams maintenance laborer, Earthmoving laborer","version":"2022","source_id":900,"level":4,"normalized_name":"civil engineering laborers"},{"code":"9313","parent_code":"931","title":"BUILDING CONSTRUCTION LABORERS","description":"Building construction laborers perform routine tasks in connection with building construction and demolition work.\nTheir tasks include: a) cleaning used building bricks and doing other simple work on demolition sites; b) mixing pouring and spreading materials such as concrete, plaster and mortar digging and filling holes and trenches using hand held tools; c) spreading sand, soil, gravel and similar materials; d) loading and unloading construction materials, excavated material and equipment and transporting them around construction sites using wheelbarrows, hods and hand trucks; and e) cleaning work sites and removing obstructions.\nExamples of the occupations classified here: Bricklayer's assistant, Building work construction laborer, Demolition laborer, Hod carrier\nSome related occupations classified elsewhere: Bricklayer - 7112, Building wrecker - 7119, House builder - 7111","version":"2022","source_id":901,"level":4,"normalized_name":"building construction laborers"},{"code":"9321","parent_code":"932","title":"HAND PACKERS","description":"Hand packers weigh, pack and label materials and products by hand.\nTheir tasks include: a) weighing, wrapping, sealing and packing material and various products by hand; b) filling bottles, cans, boxes, bags and other containers with products by hand; and c) labelling products, packages and various containers by hand.\nExamples of the occupations classified here: Food packer, Hand labeler, Hand packer, Hand wrapper\nSome related occupations classified elsewhere: Labelling machine operator - 8183, Packing machine operator - 8183, Wrapping machine operator - 8183","version":"2022","source_id":902,"level":4,"normalized_name":"hand packers"},{"code":"9329","parent_code":"932","title":"MANUFACTURING LABORERS NOT ELSEWHERE CLASSIFIED","description":"Manufacturing laborers not elsewhere classified assist the work of machine operators and assemblers and perform a variety of manual tasks in manufacturing, excluding packing and labelling finished products.\nTheir tasks include: a) conveying goods, material, equipment, etc. to work area, removing finished pieces; b) loading and unloading vehicles, trucks and trolleys; c) clearing machine blockages, cleaning machinery, equipment and tools; and d) carrying out manual sorting of products or components.\nExamples of the occupations classified here: Bottle sorter, Factory hand, Material handler, Stacker\nSome related occupations classified elsewhere: Electrical equipment assembler - 8212, Electronic equipment assembler - 8212, Hand packer - 9321, Leather products assembler - 8219, Rubber products assembler - 8219","version":"2022","source_id":903,"level":4,"normalized_name":"manufacturing laborers not elsewhere classified"},{"code":"9331","parent_code":"933","title":"HAND AND PEDAL VEHICLE DRIVERS","description":"Hand or pedal vehicle drivers propel cycles and similar vehicles to transport passengers or goods.\nTheir tasks include: a) loading or unloading goods, or assisting passengers in getting on or off a vehicle; b) moving vehicle in the desired direction with due regard to other traffic and traffic regulations; c) inspecting vehicle components to identify wear and damage; d) maintaining vehicle, making minor repairs and installing replacement parts; and e) collecting fares or charges.\nExamples of the occupations classified here: Bicycle courier, Cycle rickshaw driver, Padyak driver, Pedal vehicle driver, Pedicab driver, Rickshaw puller, Sikad driver\nSome related occupations classified elsewhere: Bicycle racer - 3421, Motorcycle rider - 8321, Motorcyclist - 8321","version":"2022","source_id":904,"level":4,"normalized_name":"hand and pedal vehicle drivers"},{"code":"9332","parent_code":"933","title":"DRIVERS OF ANIMAL-DRAWN VEHICLES AND MACHINERY","description":"Drivers of animal-drawn vehicles and machinery drive animal-drawn vehicles to transport passengers or goods, as well as animal-drawn machinery usually in connection with farming.\nTheir tasks include: a) harnessing animals and hitching them to vehicles or machinery; b) loading or unloading goods, or assisting passengers in getting on or off a vehicle; c) driving animals in the desired direction with due regard to other traffic and traffic regulations; d) collecting fares or charges; e) driving animals to haul wagons in mines or quarries; f) driving animals hitched to farm or other machinery; g) driving working animals; h) maintaining vehicle or machinery, making minor repairs and installing replacement parts; and i) grooming and feeding animals.\nExamples of the occupations classified here: Animal-drawn vehicle driver, Animal train driver, Kalesa driver (kutsero)\nRelated occupation classified elsewhere: Jockey - 3421","version":"2022","source_id":905,"level":4,"normalized_name":"drivers of animal-drawn vehicles and machinery"},{"code":"9333","parent_code":"933","title":"FREIGHT HANDLERS","description":"Freight handlers carry out tasks such as packing, carrying, loading and unloading furniture and other household items, or loading and unloading ship and aircraft cargoes and other freight, or carrying and stacking goods in various warehouses.\nTheir tasks include: a) carrying goods to be loaded on or unloaded from vans, trucks, wagons, ships, or aircraft; b) loading and unloading grain, coal, sand and similar goods by placing them on conveyor-belts, pipes, etc.; c) connecting hoses between main shore installation pipes and tanks of barges, tankers and other ships to load and unload petroleum, liquefied gases and other liquids; d) carrying and stacking goods in warehouses and similar establishments; and e) sorting cargo prior to loading and unloading.\nExamples of the occupations classified here: Baggage handler, Boat loader, Freight handler, Railway vehicle loader, Road vehicle loader, Stevedore (kargador), Warehouse porter\nSome related occupations classified elsewhere: Crane operator - 8343, Forklift operator - 8344, Hotel porter - 9621, Luggage porter - 9621","version":"2022","source_id":906,"level":4,"normalized_name":"freight handlers"},{"code":"9334","parent_code":"933","title":"SHELF FILLERS","description":"Shelf fillers stock shelves and display areas and keep stock clean and in order in supermarkets and other retail and wholesale shops.\nTheir tasks include: a) placing goods neatly in bins and on racks, and stacking bulky goods on floors; b) filling shelves with goods ensuring goods with the earliest use-by dates are at the front of shelves; c) removing goods with past due use-by dates; d) maintaining shelf order by removing stock belonging in a different location; e) noting what has been sold and collecting goods needed from the stockroom; f) obtaining articles for customers from shelf or stockroom; g) directing customers to location of articles sought; and h) receiving, opening, unpacking, and inspecting for damage merchandise from manufacturer or distributor.\nExamples of the occupations classified here: Night filler, Stock filler, Stock handler","version":"2022","source_id":907,"level":4,"normalized_name":"shelf fillers"},{"code":"9335","parent_code":"933","title":"TRANSPORT NETWORK VEHICLE SERVICE BICYCLE DRIVERS","description":"TNVS bicycle drivers propel cycles and similar vehicles to transport goods.\na) driving and tending bicycles; b) booking rides using a mobile application; c) picking up and dropping off goods at designated locations; d) observing traffic rules and signals; e) cleaning and washing vehicle as well as performing maintenance and minor repairs; f) keeping a record of journeys; and g) delivering messages to passengers or clients.\nSome related occupations classified elsewhere: Bicycle rider (conventional) - 9331, Pedal vehicle driver (conventional) - 9331","version":"2022","source_id":908,"level":4,"normalized_name":"transport network vehicle service bicycle drivers"},{"code":"9411","parent_code":"941","title":"FAST FOOD PREPARERS","description":"Fast food preparers prepare and cook to order a limited range of foods or beverages that involve simple preparation processes and a small number of ingredients. They may take orders from customers and serve at counters or tables.\nTheir tasks include: a) preparing simple or pre-prepared foods and beverages such as sandwiches, hamburgers, pizzas, fish and chips, salads, and coffee; b) washing, cutting, measuring and mixing foods for cooking; c) operating large-volume single-process cooking equipment such as grills, deep-fat fryers or griddles; d) re-heating pre-prepared food, cleaning food preparation areas, cooking surfaces and utensils; e) taking and serving food and beverage orders in eating places that specialize in fast service and carry-out food; f) ordering and taking delivery of fast food ingredients; g) maintaining sanitation, health, and safety standards in work areas; h) operating large-volume cooking equipment such as grills, deep-fat fryers, or griddles; and i) verifying that prepared food meets requirements for quality and quantity.\nExamples of the occupations classified here: Fast food cook, Hamburger maker, Pizza maker, Short order cook\nSome related occupations classified elsewhere: Chef - 3434, Cook - 5120, Food service counter attendant - 5246","version":"2022","source_id":909,"level":4,"normalized_name":"fast food preparers"},{"code":"9412","parent_code":"941","title":"KITCHEN HELPERS","description":"Kitchen helpers clear tables, clean kitchen areas, wash dishes, preparing ingredients and perform other duties to assist workers who prepare or serve food and beverages.\nTheir tasks include: a) cleaning kitchens, food preparation areas and service areas; b) assisting cooks and chefs in preparation of food by washing, peeling, chopping, cutting up, measuring and mixing ingredients; c) assembling dishes for service; d) unpacking and storing supplies in refrigerators, cupboards and other storage areas; e) washing dishes and cooking utensils and putting them away; f) checking, transferring, weighing and storing supplies in refrigerators, cupboards and other storage areas; and g) preparing, cooking, toasting and heating simple food items.\nExamples of the occupations classified here: Carinderia helper, Hand dishwasher, Kitchen assistant, Kitchen hand, Kitchen helper, Kitchen porter, Kitchen steward, Pantry attendant, Snack haus or bar helper\nSome related occupations classified elsewhere: Cook - 5120, Fast food preparer - 9411","version":"2022","source_id":910,"level":4,"normalized_name":"kitchen helpers"},{"code":"9510","parent_code":"951","title":"STREET AND RELATED SERVICE WORKERS","description":"Street and related service workers provide a variety of services on streets and in other public places, including cleaning shoes, washing car windows, running errands, looking after property, and providing other on-the-spot street services.\nTheir tasks include: a) obtaining the materials necessary to perform services; b) approaching people on the street to offer services; c) cleaning and polishing shoes; d) cleaning and polishing car windows; e) running errands; f) assisting drivers to find a parking place and ensuring car is not damaged during driver’s absence; g) handing out leaflets and free newspapers; and h) receiving immediate payment.\nExamples of the occupations classified here: Barker, Car guard, Car window washer, Errand boy, Leaflet distributor, Shoe polisher\nSome related occupations classified elsewhere: Leaflet and newspaper deliverer - 9621, Service station attendant - 5245","version":"2022","source_id":911,"level":4,"normalized_name":"street and related service workers"},{"code":"9520","parent_code":"952","title":"STREET VENDORS (excluding food)","description":"Street vendors (excluding food) sell a usually limited range of goods (excluding food for immediate consumption) in streets and public places such as stations, cinemas or theatres.\nTheir tasks include: a) buying or receiving items for sale, or making simple items; b) loading and unloading basket, tray, push-cart, bicycle, hand truck or other vehicle, to transport goods to the streets or public places such as stations or cinemas; c) displaying goods or calling out to attract customer’s attention; d) approaching potential customers on street and offering goods for sale; and e) receiving immediate payment.\nExamples of the occupations classified here: Ambulant non-food vendor, Cigarette ambulant vendor, Hawker, Newspaper vendor, Peddler, Rug ambulant vendor, Sampaguita ambulant vendor\nSome related occupations classified elsewhere: Door-to-door sales representative - 5243, Free newspaper distributor - 9510, Market salesperson - 5211, Street food vendor - 5212, Street stall salesperson - 5211","version":"2022","source_id":912,"level":4,"normalized_name":"street vendors excluding food"},{"code":"9611","parent_code":"961","title":"GARBAGE AND RECYCLING COLLECTORS","description":"Garbage collectors collect and remove rubbish and items for recycling from buildings, yards, streets and other places.\nTheir tasks include: a) collecting rubbish and recyclable materials and locating it into bins and garbage and recycling trucks; b) riding on or in garbage and recycling trucks; c) lifting garbage bins and emptying contents into trucks and larger containers; and d) unloading garbage and recycling trucks.\nExamples of the occupations classified here: Dustman/woman, Garbage collector, Garbage dumper, Recycling collector, Refuse collector\nSome related occupations classified elsewhere: Garbage truck driver - 8332, Waste picker - 9612","version":"2022","source_id":913,"level":4,"normalized_name":"garbage and recycling collectors"},{"code":"9612","parent_code":"961","title":"REFUSE SORTERS","description":"Refuse sorters identify, collect and sort discarded items suitable for recycling at dump sites and recycling enterprises or in buildings, streets and other public places.\nTheir tasks include: a) searching through refuse and collecting items for recycling from dump sites, domestic, commercial and industrial premises or from public places such as streets; b) sorting cardboard, paper, glass, plastic, aluminum or other recyclable materials by type; c) placing recyclable items and materials in designated compartments and containers for storage or transportation; d) identifying and setting aside items of furniture, equipment, machinery, or components that are suitable for repair or re-use; e) transporting recyclable items by hand or using non-motorized vehicles; and f) selling recyclable or reusable materials.\nExamples of the occupations classified here: Garbage sorter, Magbobote, Mangangalakal, Recycling worker, Scrap merchant, Waste picker\nSome related occupations classified elsewhere: Refuse collector - 9611, Street sweeper - 9613","version":"2022","source_id":914,"level":4,"normalized_name":"refuse sorters"},{"code":"9613","parent_code":"961","title":"SWEEPERS AND RELATED LABORERS","description":"Sweepers and related laborers sweep and clean streets, parks, airports, stations and other public places.\nTheir tasks include: a) sweeping streets, parks, airports, stations and similar public places; b) beating dust out of carpets by using a carpet-beater; and c) cleaning rubbish, leaves from driveways and grounds.\nExamples of the occupations classified here: Market sweeper, Metro aide, Park sweeper, Street sweeper","version":"2022","source_id":915,"level":4,"normalized_name":"sweepers and related laborers"},{"code":"9621","parent_code":"962","title":"MESSENGERS, PACKAGE DELIVERERS AND LUGGAGE PORTERS","description":"Messengers, package deliverers and luggage porters carry and deliver messages, packages and other items within an establishment or between establishments, to households and elsewhere, or carry luggage especially at hotels, stations and airports.\nTheir tasks include: a) delivering messages, packages and other items within an establishment or between establishments, or elsewhere; b) performing the duties of a post-runner; c) delivering various goods to and from enterprises, shops, households and other places; d) carrying and delivering luggage at hotels, stations, airports, and elsewhere; e) receiving and marking baggage by completing attaching claim checks; f) planning and following the most efficient route; and g) sorting items to be delivered according to the delivery route.\nExamples of the occupations classified here: Baggage handler, Bellboy or bellgirl, Deliverer, Delivery helper, Hotel porter, Luggage porter, Messenger, Newspaper deliverer, Package deliverer, Post-runner\nSome related occupations classified elsewhere: Mail carrier - 4412, Postman/woman - 4412","version":"2022","source_id":916,"level":4,"normalized_name":"messengers package deliverers and luggage porters"},{"code":"9622","parent_code":"962","title":"ODD JOB PERSONS","description":"Odd job persons clean, paint and maintain buildings, grounds and facilities, and undertake simple repairs.\nTheir tasks include: a) repairing broken windows, screens, doors, fences, barbecues, picnic tables, shelves, cupboards and other items; b) replacing defective items such as light bulbs; c) repairing and painting interior and exterior surfaces such as walls, ceilings and fences; d) adjusting doors and windows; e) replacing tap washers; f) putting up handrails and grab rails; and g) unloading coal or wood and putting it into cellars of private households or establishments.\nExamples of the occupations classified here: Handyperson, Odd-job person","version":"2022","source_id":917,"level":4,"normalized_name":"odd job persons"},{"code":"9623","parent_code":"962","title":"METER READERS AND VENDING-MACHINE COLLECTORS","description":"Meter readers and vending-machine collectors stock vending machines and collect money from them or from parking meters and other coin-boxes, or read electricity, gas or water meters.\nTheir tasks include: a) filling storage areas of vending machines and collecting money from their containers; b) collecting money from parking meters and similar coin-boxes; c) reading electricity, gas or water meters and recording consumption; d) keeping records of merchandise distributed and money collected; e) proceeding along established routes to take readings of meter dials; f) verifying readings in cases where consumption appears to be abnormal, and record possible reasons for fluctuations; and g) inspecting meters for unauthorized connections, defects, and damage such as broken seals.\nExamples of the occupations classified here: Meter reader, Vending-machine collector","version":"2022","source_id":918,"level":4,"normalized_name":"meter readers and vending-machine collectors"},{"code":"9624","parent_code":"962","title":"WATER AND FIREWOODS COLLECTOR","description":"Water and firewood collectors collect water and firewood and transport them on foot or using hand or animal carts.\nTheir tasks include: a) cutting and collecting wood from forests for sale in market or as fuel or for own consumption; b) visiting forests or fields to pick pieces of dried wood from ground and arranging them in heaps; c) cutting decayed branches and trunks of trees using axe and hand -saw; d) tying collected wood into small faggots and carrying them or transporting them on a cart to the market for sale or to village or household for use; e) drawing water from wells, rivers or ponds etc. for domestic use; and f) collecting water in leather bags, buckets or other containers from taps, rivers, ponds or wells and delivering the water to work sites, the houses of clients or to own household for drinking, cleaning of drains or storage in tanks.\nExamples of the occupations classified here: Firewood collector, Water collector","version":"2022","source_id":919,"level":4,"normalized_name":"water and firewoods collector"},{"code":"9629","parent_code":"962","title":"ELEMENTARY WORKERS NOT ELSEWHERE CLASSIFIED","description":"This unit group covers elementary workers not classified elsewhere in major group 9, Elementary workers. For instance, the group includes those who issue and collect parking or admission tickets, provide personal items to patrons or customers in cloak rooms and assist patrons at entertainment events. \nTheir tasks include: a) selling and collecting admission tickets and passes from patrons at entertainment events or collecting tags from patrons; b) examining tickets or passes to verify authenticity, using criteria such as color and date issued; c) guiding patrons to exits or providing other instructions or assistance in case of emergency; d) directing patrons to restroom, concession stands and telephones; e) directing vehicle drivers to parking spaces; f) patrolling parking areas in order to prevent vehicle damage and vehicle property thefts; g) calculating parking charges, and collecting fees from customers; and h) assigning dressing room facilities, locker space, or clothing containers to patrons of athletic or bathing establishments.\nExamples of the occupations classified here: Cloak room attendant, Fairground attendant, Golf caddie, Golf-range attendant, Parking attendant, Recreation facilities attendant, Ticket collector, Usher/Usherette\nRelated occupation classified elsewhere: Parking valet - 8322","version":"2022","source_id":920,"level":4,"normalized_name":"elementary workers not elsewhere classified"}]$psoc2022_3de3889be8c9ca74$;
 v_rows jsonb; v_source uuid; v_expected integer:=649; v_existing integer;
BEGIN
 IF current_user <> 'postgres' OR session_user <> 'postgres' OR current_database() <> 'postgres' THEN
  RAISE EXCEPTION 'Verified DEV management identity required' USING ERRCODE='42501';
 END IF;
 IF encode(sha256(convert_to(v_raw,'UTF8')),'hex') <> '3de3889be8c9ca74afb04ec60a0aadbbbfa134e2270477cd33fdfcf7123e7d17' THEN
  RAISE EXCEPTION 'Pinned PSOC payload hash mismatch' USING ERRCODE='22023';
 END IF;
 v_rows:=v_raw::jsonb;
 IF jsonb_array_length(v_rows)<>v_expected THEN RAISE EXCEPTION 'PSOC row count mismatch'; END IF;
 CREATE TEMP TABLE psoc_2022_stage(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,parent_code text,
  title text NOT NULL,normalized_name text NOT NULL,description text NOT NULL,level smallint NOT NULL,
  version text NOT NULL,source_id text
 ) ON COMMIT DROP;
 INSERT INTO psoc_2022_stage(code,parent_code,title,normalized_name,description,level,version,source_id)
 SELECT code,parent_code,title,normalized_name,description,level,version,source_id
 FROM jsonb_to_recordset(v_rows) AS r(code text,parent_code text,title text,normalized_name text,
  description text,level smallint,version text,source_id text);
 IF EXISTS(SELECT 1 FROM psoc_2022_stage s WHERE version<>'2022' OR level NOT BETWEEN 1 AND 4
  OR length(code)<>level OR code!~'^[0-9]+$' OR btrim(title)='' OR btrim(normalized_name)=''
  OR (level=1 AND parent_code IS NOT NULL)
  OR (level>1 AND (parent_code IS DISTINCT FROM left(code,level-1)
    OR NOT EXISTS(SELECT 1 FROM psoc_2022_stage p WHERE p.code=s.parent_code AND p.level=s.level-1))))
  OR (SELECT count(*) FROM psoc_2022_stage WHERE level=1)<>10
  OR (SELECT count(*) FROM psoc_2022_stage WHERE level=2)<>43
  OR (SELECT count(*) FROM psoc_2022_stage WHERE level=3)<>130
  OR (SELECT count(*) FROM psoc_2022_stage WHERE level=4)<>466 THEN
  RAISE EXCEPTION 'PSOC hierarchy validation failed' USING ERRCODE='22023';
 END IF;
 SELECT id INTO v_source FROM public.taxonomy_sources WHERE code='PSOC_2022' FOR UPDATE;
 IF v_source IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.taxonomy_sources WHERE id=v_source AND version='2022' AND is_active
   AND metadata->>'source_payload_sha256'='3de3889be8c9ca74afb04ec60a0aadbbbfa134e2270477cd33fdfcf7123e7d17') THEN
   RAISE EXCEPTION 'PSOC source conflicts with prepared import' USING ERRCODE='55000';
  END IF;
  SELECT count(*) INTO v_existing FROM public.taxonomy_mappings WHERE taxonomy_source_id=v_source;
  IF v_existing<>v_expected OR EXISTS(
   SELECT 1 FROM psoc_2022_stage s WHERE (
    SELECT count(*) FROM public.taxonomy_mappings m JOIN public.occupations o ON o.id=m.entity_id
    LEFT JOIN public.occupations p ON p.id=o.parent_id
    LEFT JOIN public.taxonomy_mappings pm ON pm.taxonomy_source_id=v_source AND pm.entity_id=p.id AND pm.entity_type='occupation'
    WHERE m.taxonomy_source_id=v_source AND m.entity_type='occupation' AND m.external_code=s.code
     AND m.mapping_type='exact' AND m.is_primary AND m.external_name=s.title
     AND o.canonical_name=s.title AND o.normalized_name=s.normalized_name AND o.description=s.description
     AND o.occupation_level=s.level AND o.is_active
     AND pm.external_code IS NOT DISTINCT FROM s.parent_code)<>1)
   OR (SELECT count(*) FROM public.occupation_aliases WHERE source='PSOC_2022' AND alias_type='external_code')<>466
   OR EXISTS(SELECT 1 FROM psoc_2022_stage s WHERE s.level=4 AND NOT EXISTS(
    SELECT 1 FROM public.occupation_aliases a JOIN public.taxonomy_mappings m ON m.entity_id=a.occupation_id
     AND m.taxonomy_source_id=v_source AND m.entity_type='occupation' AND m.external_code=s.code
    WHERE a.source='PSOC_2022' AND a.alias_type='external_code' AND a.alias=s.code AND a.normalized_alias=s.code AND a.is_active)) THEN
   RAISE EXCEPTION 'Existing PSOC import changed; no overwrite allowed' USING ERRCODE='55000';
  END IF;
  RETURN;
 END IF;
 IF to_regclass('public.occupations_normalized_name_level_unique') IS NULL
  OR to_regclass('public.occupations_normalized_name_unique') IS NOT NULL THEN
  RAISE EXCEPTION 'Occupation hierarchy index migration must be applied first' USING ERRCODE='55000';
 END IF;
 INSERT INTO public.taxonomy_sources(code,name,version,source_type,country_code,source_url,is_active,metadata)
 VALUES('PSOC_2022','2022 Updates to the 2012 Philippine Standard Occupational Classification (PSA API)',
  '2022','national','PH','https://classification.psa.gov.ph/psoc/2022',true,'{"namespace":"PSOC","base_classification":"2012","api_release":"2022","provenance_status":"official_api_pagination_and_hierarchy_verified","source_snapshot_sha256":"0a77f0a0816246199b51359c76b0cf7baf7393996dfe7fea9b85afcce3ca57ce","source_payload_sha256":"3de3889be8c9ca74afb04ec60a0aadbbbfa134e2270477cd33fdfcf7123e7d17","retrieved_at":"2026-10-15T07:50:02.864Z","source_documentation":"https://psa.gov.ph/classifications-api/psoc","technical_notes":"https://psa.gov.ph/classification/psoc/technical-notes","documentation_count_conflict":{"documented_units":456,"api_units":466,"status":"unresolved_published_text_difference"},"counts":{"major":10,"sub-major":43,"minor":130,"unit":466},"import_method":"additive_existing_canonical_tables_v1","mapping_basis":"same_source_entry_identity_not_inferred_job_title_equivalence","canonical_name_uniqueness":"normalized_name_within_hierarchy_level_legacy_null_equals_zero"}'::jsonb)
 RETURNING id INTO v_source;
 INSERT INTO public.occupations(id,canonical_name,normalized_name,description,occupation_level,parent_id,is_active)
 SELECT s.id,s.title,s.normalized_name,s.description,s.level,p.id,true
 FROM psoc_2022_stage s LEFT JOIN psoc_2022_stage p ON p.code=s.parent_code;
 INSERT INTO public.taxonomy_mappings(taxonomy_source_id,entity_type,entity_id,external_code,external_id,external_name,
  mapping_type,confidence,is_primary,metadata)
 SELECT v_source,'occupation',s.id,s.code,s.source_id,s.title,'exact',NULL,true,
  jsonb_build_object('namespace','PSOC','release','2022','level',s.level,'parent_code',s.parent_code,
   'source_payload_sha256','3de3889be8c9ca74afb04ec60a0aadbbbfa134e2270477cd33fdfcf7123e7d17','identity_mapping',true)
 FROM psoc_2022_stage s;
 INSERT INTO public.occupation_aliases(occupation_id,alias,normalized_alias,alias_type,language_code,source,is_active)
 SELECT id,code,code,'external_code',NULL,'PSOC_2022',true FROM psoc_2022_stage WHERE level=4;
 IF (SELECT count(*) FROM public.taxonomy_mappings WHERE taxonomy_source_id=v_source)<>649 THEN
  RAISE EXCEPTION 'PSOC import was incomplete';
 END IF;
END $import$;
